/* ÇEVİRİ sq · olay — arac/ceviri.py ile YAZILDI, elle düzenleme: py arac/ceviri.py uygula.
   Kayıt: id → [metin, kaynak_ozet] (olayda alan başına). Tasarım: denetim/CEVIRI-1103/TASARIM.md */
Ceviri.ekle("sq","olay",{
"OLAYLAR_EK2:1908-09-01:0":{"b": ["Hekurudha e Hixhazit në Medinë", "95009b9c"], "d": ["Linja prej 1464 km, e ndërtuar vetëm me dhurime të myslimanëve dhe me inxhinieri vendase, arriti në Medinë; udhëtimi i haxhit u shkurtua nga javë në ditë. Është vepra më e madhe infrastrukturore e periudhës së Abdylhamidit II.", "a1c98c4c"]},
"OLAYLAR_EK2:1909-04-13:0":{"b": ["Ngjarja e 31 Martit", "1d7c2bb2"], "d": ["Kryengritja e madhe antikushtetuese e mori Stambollin; Ushtria e Veprimit që erdhi nga Selaniku e shtypi kryengritjen dhe Abdylhamidi II u rrëzua nga froni.", "4885dfd1"]},
"OLAYLAR_EK2:1912-10-26:0":{"b": ["Filloi rrethimi i Edrenesë", "234d9b28"], "d": ["Mbrojtja pesëmujore e Shykri Pashës u bë epope e rezistencës brenda katastrofës ballkanike; qyteti ra nga uria dhe u rimor në korrik 1913.", "3c3ca395"]},
"OLAYLAR_EK2:1913-01-23:0":{"b": ["Sulmi mbi Portën e Lartë", "b304d02d"], "d": ["Qeveria, që po përgatitej të dorëzonte Edrenenë, u rrëzua me sulmin e armatosur të ittihadistëve; ministri i luftës, Nazim Pasha, u vra. Filloi periudha e pushtetit të plotë të Komitetit Bashkim e Përparim.", "a8a7af44"]},
"OLAYLAR_EK2:1915-07-11:0":{"b": ["Shfuqizimi i Mutesarrifllëkut të Malit të Libanit", "b5639051"], "d": ["Rendi i mutesarrifllëkut autonom, i krijuar me Reglement Organique të vitit 1861 dhe i mbështetur te protokolli ndërkombëtar i rinovuar në vitin 1864, u shfuqizua në mënyrë të njëanshme nga Shteti Osman gjatë Luftës së Parë Botërore; Ministria e Brendshme filloi të emëronte drejtpërdrejt në krahinë mutesarrifë myslimanë. Kështu u mbyll periudha e autonomisë 1861-1915, gjatë së cilës shërbyen tetë mutesarrifë.", "83ff35bc"]},
"OLAYLAR_EK3:1402-08-01:0":{"b": ["Ndarja e vendit midis shehzadeve", "82f26bfb"], "d": ["Pas disfatës së Ankarasë, Sulejman Çelebiu kaloi në Rumeli dhe u shpall sulltan në Edrene; Isa Çelebiu mbante Bursën, kurse Mehmet Çelebiu krahinën Amasja-Tokat-Sivas. Në hartë këto tri pjesë paraqiten me ngjyra të ndryshme.", "08baaa0b"]},
"OLAYLAR_EK3:1403-02-01:0":{"b": ["Traktati i Galipolit: bregu i Detit të Zi deri në Mesemvri iu la Bizantit", "a4164eca"], "d": ["Emiri Sulejman, që pas disfatës së Ankarasë donte të qëndronte në Rumeli, nënshkroi në Galipoli një traktat me perandorin bizantin Manuel. Ia la Bizantit Kartalin, Pendikun, Gebzen dhe disa ishuj, në Rumeli Selanikun dhe Thesalinë, si dhe në Detin e Zi brezin bregdetar deri në Mesemvri; u hoq edhe taksa që Bizanti u paguante Osmanëve. Kështu Ahtopoli, Igneada dhe Rezve në bregun e Istranxhës mbetën njëzet e një vjet nën administrimin bizantin; Murati II, me paqen e vitit 1424, rimori shumicën e këtyre vendeve.", "ad1af28a"]},
"OLAYLAR_EK3:1403-03-09:0":{"b": ["Vdekja e Bajazidit Jëlldërëm në robëri", "7e968d83"], "d": ["Padishahu, rob në duart e Timurit, vdiq në Akshehir; kufoma e tij u soll në Bursë dhe u varros. Vdekja e tij e bëri të pakthyeshme luftën për fron midis shehzadeve.", "af68bc4d"]},
"OLAYLAR_EK3:1403-06-15:0":{"b": ["Traktati i Galipolit — lëshimet ndaj Bizantit", "dfacbd00"], "d": ["Sulejman Çelebiu, që donte të siguronte pozitën e vet në Rumeli, u mor vesh me Bizantin dhe me shtetet latine dhe ua ktheu Selanikun, brigjet e Marmarasë dhe disa ishuj; pranoi madje të paguante haraç.", "0d91820c"]},
"OLAYLAR_EK3:1403-09-01:0":{"b": ["Përplasja e Ulubatit — disfata e Isa Çelebiut", "500c5d24"], "d": ["Isa Çelebiu, që mbante Bursën, u mund në Ulubat nga i vëllai, Mehmeti; edhe disa përpjekje për t'u rimëkëmbur mbetën pa rezultat.", "624072ce"]},
"OLAYLAR_EK3:1406-06-01:0":{"b": ["Zhdukja e Isa Çelebiut", "0effa11e"], "d": ["Isa Çelebiu, që me mbështetjen e Sulejman Çelebiut u kthye disa herë në Anadoll, pas disfatës së fundit u zhduk; pjesa e tij i kaloi Mehmet Çelebiut dhe në hartë zona e Mehmetit u zgjerua drejt perëndimit.", "d164b447"]},
"OLAYLAR_EK3:1406-06-18:0":{"b": ["Musa Çelebiu kaloi në Vllahi", "8441267a"], "d": ["Mehmet Çelebiu, që përballë Sulejman Çelebiut humbi Bursën dhe Ankaranë dhe u tërhoq në Tokat-Amasja, e nxiti të vëllanë, Musanë, të shkonte në Rumeli. Musa pranoi ftesën e vojvodës së Vllahisë, Mirçea, dhe arriti në Vllahi me rrugë detare; prej aty do të niste luftën që do ta linte Sulejmanin midis dy fronteve.", "e7866931"]},
"OLAYLAR_EK3:1410-05-06:0":{"b": ["Mehmet Çelebiu rimori Bursën dhe Ankaranë — pjesa e Anadollit doli nga duart e Sulejman Çelebiut", "bfb69f12"], "d": ["Pas sukseseve të Musa Çelebiut në Rumeli (Jamboll, 13 shkurt 1410), Emir Sulejman Çelebiu, që ndodhej në Anadoll, kaloi në Rumeli. Pas largimit të Sulejmanit nga Anadolli, Mehmet Çelebiu rimori krahinën e Bursës, përfshirë Ankaranë, dhe si shenjë e hipjes në fron preu monedhë me datën 813. Në hartë ana anadollake e Marmarasë kalon nga pjesa e Emir Sulejmanit në ngjyrën e Mehmet Çelebiut.", "bc148b8e"]},
"OLAYLAR_EK3:1410-06-15:0":{"b": ["Beteja e Kosmidionit", "0efc2caa"], "d": ["Në betejën e zhvilluar përpara mureve të Stambollit me mbështetjen e Bizantit, Sulejman Çelebiu e mundi të vëllanë, Musanë; por mbështetja e tij në Rumeli kishte filluar të shkrihej me shpejtësi. Vendbanime të tjera që u humbën në të njëjtën datë: Elasona (Alasonya), Ajtosi (Aydos), Bolajir (vende në Rumeli që në hartë kalojnë nga Musa te Sulejmani).", "0498cbda"]},
"OLAYLAR_EK3:1411-01-01:0":{"b": ["Rrethimi i Stambollit nga Musa Çelebiu", "4932f586"], "d": ["Musa Çelebiu, që donte të ndëshkonte Bizantin për mbështetjen ndaj Sulejmanit, rrethoi Stambollin; ky rrethim e shtyu Bizantin në aleancë me Mehmet Çelebiun.", "b52f942c"]},
"OLAYLAR_EK3:1411-02-17:0":{"b": ["Vdekja e Emir Sulejmanit — Musa zot i Rumelisë", "325c1549"], "d": ["Sulejman Çelebiu, i kapur ndërsa po ikte nga Edrenea, u vra; e gjithë Rumelia kaloi në duart e Musa Çelebiut. Në hartë Rumelia kalon nga ngjyra blu në ngjyrën vjollcë.", "48aa849a"]},
"OLAYLAR_EK3:1413-07-05:0":{"b": ["Beteja e Çamurlusë — rivendosja e bashkimit", "0b23173e"], "d": ["Mehmet Çelebiu, me mbështetjen e Bizantit, të despotatit serb dhe të bejlerëve të Rumelisë, i shkaktoi të vëllait, Musait, një disfatë vendimtare në Çamurlu; Musa u vra ndërsa po ikte. Rumelia në duart e Musait, së bashku me Edrenenë, i kaloi Mehmetit dhe Mehmet Çelebiu u shpall në Edrene sundimtari i vetëm i Shtetit Osman. Periudha njëmbëdhjetëvjeçare e Interregnumit mori fund dhe pjesët e shehzadeve në hartë u bashkuan në një trup të vetëm.", "649e53b7"]},
"OLAYLAR_EK3:1683-01-01:0":{"b": ["Vendimi për fushatën e Vjenës — paqja e Vasvárit nuk u ripërtëri, objektivi u ndryshua nga Janëkkalaja (Győr) në Vjenë", "1bf278f2"], "d": ["Perandori Leopold I kërkonte ripërtëritjen e Traktatit të Vasvárit, afati i të cilit ende nuk kishte skaduar, dhe edhe Mehmeti IV dukej në anën e paqes. Por veziri i madh Merzifonlu Kara Mustafa Pasha, duke marrë si arsye ankesat e Imre Thökölyt, të cilin e kishte shpallur mbret të Hungarisë së Mesme, nuk lejoi ripërtëritjen e paqes; duke vënë në lëvizje predikuesit, në radhë të parë Vani Mehmed Efendiun, e bindi padishahun për luftë. Në këshillin e mbajtur u vendos që padishahu të rrinte në Beograd dhe serdar-i ekremi të përparonte për të marrë Janëkkalanë; por në këshillin e Székesfehérvárit (İstolni Belgrad), megjithë kundërshtimin e hanit të Krimesë, Murad Girajit, dhe të valiut të Budës, Uzun Ibrahim Pashës, objektivi u ndryshua në rrethimin e Vjenës.", "7a572168"]},
"OLAYLAR_EK3:1683-07-14:0":{"b": ["Filloi Rrethimi i Dytë i Vjenës — ushtria përpara Vjenës", "bb542e49"], "d": ["Ushtria osmane nën komandën e vezirit të madh Kara Mustafa Pashës arriti përpara Vjenës më 14 korrik 1683. Perandori Leopold I, duke ia lënë mbrojtjen e qytetit Starhembergut, u tërhoq në brendësi të Austrisë. Ndryshe nga i pari, ky rrethim i dytë, i përgatitur me Vjenën si objektiv të drejtpërdrejtë, do të zgjaste deri më 12 shtator.", "ecea5576"]},
"OLAYLAR_EK3:1683-10-09:0":{"b": ["Disfata e Párkányt dhe humbja e Estergomit", "a7366740"], "d": ["Ushtria që po tërhiqej nga Vjena u mund për herë të dytë në Párkány; më pas ra Estergomi, një nga kalatë kyçe të Hungarisë. Tërheqja filloi të shndërrohej në shembje.", "13a860f4"]},
"OLAYLAR_EK3:1683-12-25:0":{"b": ["Ekzekutimi i Merzifonlu Kara Mustafa Pashës", "ce8b10ac"], "d": ["Veziri i madh, i konsideruar përgjegjës për disfatën e Vjenës, u mbyt me litar në Beograd; por ekzekutimi i tij as e rregulloi frontin, as e riktheu prestigjin e tronditur të shtetit.", "23449e61"]},
"OLAYLAR_EK3:1684-03-05:0":{"b": ["U krijua Lidhja e Shenjtë", "060280d0"], "d": ["Me nismën e papatit, midis Austrisë, Polonisë dhe Venedikut u krijua kundër Osmanëve Lidhja e Shenjtë; në vitin 1686 iu bashkua edhe Rusia. Kështu perandoria hyri në një luftë shumëfrontëshe që do të zgjaste gjashtëmbëdhjetë vjet.", "5f02a851"]},
"OLAYLAR_EK3:1684-07-14:0":{"b": ["Mbrojtja e parë e Budës", "ccc43630"], "d": ["Rrethimi i parë i Budës nga ushtria e Lidhjes së Shenjtë u zmbraps me mbrojtjen këmbëngulëse katërmujore të kalasë; por kalatë në Hungari vazhdonin të binin njëra pas tjetrës.", "fb62dd75"]},
"OLAYLAR_EK3:1685-08-19:0":{"b": ["Humbja e Ujvarit", "689ab78c"], "d": ["Ra Kalaja e Ujvarit, që kishte mbetur njëzet e dy vjet në duart osmane dhe ishte bërë proverbiale në Evropë; prania osmane në Hungarinë e Sipërme u shpërbë.", "559f5062"]},
"OLAYLAR_EK3:1685-10-15:0":{"b": ["Arrestimi i Thökölyt në Varad — Mbretëria e Hungarisë së Mesme u shpërbë, kalatë e Hungarisë së Sipërme u dorëzuan", "1741aaaf"], "d": ["Pas disfatës së Vjenës, osmanët kishin filluar ta shihnin edhe Thökölyn ndër ata që kishin çuar në luftë dhe në disfatë. Më 15 tetor 1685, me urdhër të serdarit Melek Ibrahim Pasha, bejlerbeu i Varadit Ahmed Pasha urdhëroi kapjen e Thökölyt, që kishte ardhur për ndihmë; shpresohej të fitoheshin kushte më të mira paqeje duke ua dorëzuar atë Habsburgëve. Kur u përhap lajmi i arrestimit, të gjitha kalatë dhe qytetet e Mbretërisë së Hungarisë së Mesme, përveç Munkácsit që mbronte gruaja e tij Ilona Zrínyi, u dorëzuan te Habsburgët; shumica e ushtarëve kuruc kaluan në ushtrinë habsburge. Kur Thököly u lirua në Beograd më 2 janar 1686, mbretëria ishte zhdukur tashmë.", "1a00b9f3"]},
"OLAYLAR_EK3:1686-09-02:0":{"b": ["Humbja e Budës — kryeqyteti hungarez 145-vjeçar", "70800e2b"], "d": ["Në fund të rrethimit shtatëdhjetë e tetëditor, ra Buda; bejlerbeu i fundit, Abdurrahman Abdi Pasha, ra shehid mbi muret. Humbja e qytetit, nën administrimin osman që nga viti 1541, konsiderohet simbol i daljes nga duart të Hungarisë. Vendbanime të tjera që u humbën në të njëjtën datë: Pesht.", "e66f909f"]},
"OLAYLAR_EK3:1687-08-12:0":{"b": ["Disfata e Mohaçit të Dytë (Harsány) — humbja e Transilvanisë dhe e Mohaçit", "a7922681"], "d": ["Në fushën ku në vitin 1526 ishte fituar fitorja e madhe, këtë herë u pësua një disfatë e rëndë; ushtria u shpërbë dhe ushtarët që u rebeluan arritën shkarkimin e vezirit të madh. Disfata çoi edhe në humbjen e Transilvanisë.", "6b95b7d0"]},
"OLAYLAR_EK3:1687-09-26:0":{"b": ["Humbja e Athinës dhe shpërthimi i Partenonit", "b6691730"], "d": ["Një predhë e hedhur nga artileria venedikase e hodhi në erë Partenonin, që osmanët e përdornin si depo municioni; tempulli dymijëvjeçar u shndërrua në rrënoja. Qyteti kaloi në duart e Venedikut (do të rimerrej në vitin 1688).", "e28ad137"]},
"OLAYLAR_EK3:1687-11-08:0":{"b": ["Rrëzimi i Mehmetit IV dhe hipja në fron e Sulejmanit II", "9f53037c"], "d": ["Për shkak të katastrofave në front dhe të kryengritjes së ushtrisë, Mehmeti IV u rrëzua pas sundimit 39-vjeçar; në vend të tij u soll i vëllai, Sulejmani II, i mbajtur dyzet vjet në kafaz.", "6a7bb845"]},
"OLAYLAR_EK3:1688-09-06:0":{"b": ["Humbja e parë e Beogradit — rrethimi i Lidhjes së Shenjtë", "c6b9b19a"], "d": ["Beogradi, në duart osmane që nga viti 1521, iu dorëzua ushtrisë së Lidhjes së Shenjtë; dyert e Serbisë u hapën për armikun dhe rreziku arriti te vija Nish-Sofje. Vendbanim tjetër që në atlas po në atë datë kalon nga Osmanët te Habsburgët: Hisarxhëk (Grocka) — ndjek zinxhirin e qendrës kryesore të lidhur me Beogradin (TDV belgrad; përafërsi e deklaruar).", "ba09a1ad"]},
"OLAYLAR_EK3:1689-08-01:0":{"b": ["Badeni kaloi Moravën përpara Pozharevcit — Pozharevci ra në duart e Austrisë", "bcf3fc59"], "d": ["Markgrafi Ludwig von Baden, në gusht 1689, kaloi Moravën në Pozharevac dhe përparoi drejt Nishit; qyteti mbeti në duart e Austrisë deri në verën e vitit 1690 (TDV suleyman-ii thotë se Pozharevci u rimor në vitin 1690). Dita dhe leximi i Röderit nuk u riverifikuan në këtë seancë.", "28e54b6c"]},
"OLAYLAR_EK3:1689-09-24:0":{"b": ["Humbja e Nishit — përparimi habsburg (kurora e Mbretërisë së Hungarisë), viti më kritik", "c5e27b3f"], "d": ["Përparimi habsburg (kurora e Mbretërisë së Hungarisë) e hoqi edhe Nishin nga administrimi osman; sulmet arritën deri në Shkup dhe Prishtinë. Kurse Vidini ra më pas, në tetor 1689 (zë më vete). Në vitin më të errët të luftës, shteti ndiente se kërcënohej edhe kryeqyteti.", "77de2b1f"]},
"OLAYLAR_EK3:1689-10-25:0":{"b": ["Orsova dhe Fethylislami (Kladova) morën garnizon austriak", "ee8dd875"], "d": ["Pas marrjes pa luftë të Vidinit (tetor 1689, TDV vidin), Badeni më 25 tetor 1689 riparoi Orsovën dhe Fethylislamin dhe vendosi garnizone në to; Orsova mbeti në duart e Austrisë deri në vjeshtën e vitit 1690. Dita mbështetet te Bánlaky/Röder dhe nuk u riverifikua në këtë seancë.", "4c6ebd2c"]},
"OLAYLAR_EK3:1690-09-27:0":{"b": ["Nishi sërish te Osmanët", "0c4f44eb"], "d": ["Fazil Mustafa Pasha doli në fushatë në korrik 1690; pasi u morën Piroti, Pozharevci dhe Golubaci (Güvercinlik), Nishi i rrethuar kaloi në duart osmane më 27 shtator 1690 (TDV semendire). Në të njëjtën kohë ishte rimarrë edhe Vidini. Vendbanime të tjera që në atlas po në atë datë kthehen nga Habsburgët te Osmanët: Jagodina (Yagodina) dhe Prokuplje (Ürküp) — meqë nuk u gjet ditë në nivel vendi, u mor dita e Nishit (TDV semendire; përafërsi e deklaruar; Röder 1842 shkruan se veziri kaloi nga Jagodina më 8-24 shtator, kundërthënia nuk u zgjidh).", "ec6a2b00"]},
"OLAYLAR_EK3:1690-10-01:0":{"b": ["Njësitë austriake në Smederevë u dorëzuan", "90da20c4"], "d": ["Pas marrjes së Nishit më 27 shtator 1690, me një rrethim katërditor u dorëzuan njësitë austriake në Smederevë (TDV semendire). Bánlaky/Röder thonë 24 shtator; burimet kundërshtohen, u mor për bazë TDV.", "9034a37d"]},
"OLAYLAR_EK3:1690-10-08:0":{"b": ["Beogradi u rimor", "ab435838"], "d": ["Veziri i madh Kyprylyzade Fazil Mustafa Pasha më 8 tetor 1690 e rimori Beogradin nga Austria; kështu qyteti i humbur në vitin 1688 iu kthye Osmanëve (TDV suleyman-ii). Vendbanim tjetër që në atlas po në atë datë kthehet nga Habsburgët te Osmanët: Hisarxhëk (Grocka) — ndjek zinxhirin e qendrës kryesore të lidhur me Beogradin (TDV suleyman-ii; përafërsi e deklaruar).", "5b889cb0"]},
"OLAYLAR_EK3:1691-08-19:0":{"b": ["Disfata e Salankamenit — Fazil Mustafa Pasha shehid", "10d626f1"], "d": ["Në një nga betejat fushore më të përgjakshme të shekullit, veziri i madh ra shehid i goditur në ballë; ushtria u shpërbë. Shpresa për rimëkëmbje u shua me këtë luftë.", "36dfe6ea"]},
"OLAYLAR_EK3:1694-09-21:0":{"b": ["Humbja e ishullit të Kiosit", "07c084f8"], "d": ["Flota venedikase pushtoi Kiosin; sundimi osman në Egje hyri nën kërcënim. Ishulli do të rimerrej vitin pasues.", "f5f59c77"]},
"OLAYLAR_EK3:1695-02-11:0":{"b": ["Vendimi i Mustafait II për të dalë vetë në fushatë", "61c3ba9c"], "d": ["Padishahu i ri, duke ndjekur rrugën e stërgjyshërve, shpalli se do të dilte në fushatë në krye të ushtrisë; ky vendim ngriti moralin në ushtri dhe nisi periudhën dyvjeçare të fushatave personale.", "2794ae0f"]},
"OLAYLAR_EK3:1695-02-22:0":{"b": ["Rimarrja e Kiosit", "6b496fca"], "d": ["Mezomorto Husein Pasha, që e mundi flotën venedikase në betejat detare të Ishujve Oinousses (Koyun Adaları), rimori Kiosin; u bë shenjë e një ringjalljeje të shkurtër të detarisë osmane.", "7638e074"]},
"OLAYLAR_EK3:1695-09-22:0":{"b": ["Fitorja e Lugojit — fushata e parë e Mustafait II kundër Austrisë", "d5ee9b34"], "d": ["Në fushatën e parë ku padishahu mori pjesë personalisht, u rimor Lipova dhe forcat austriake u mundën në Lugoj; u bë thyerja e parë në vargun shumëvjeçar të disfatave. Atlasi e konsideron edhe Karánsebesin (Caransebeş) si të kthyer në këtë fushatë nga Habsburgët te Osmanët; burimi jep vetëm shtatorin 1695 (TDV mustafa-ii), dita në atlas u mor nga regjistrimi i Lugojit (përafërsi e deklaruar).", "a6411d61"]},
"OLAYLAR_EK3:1696-07-19:0":{"b": ["Humbja e Kalasë së Azovit", "2b78b5cd"], "d": ["Pjetri I, që synonte të dilte në Detin e Zi, me rrethimin e dytë mori Azovin; Rusia për herë të parë u vendos përgjithmonë në një kala osmane dhe hodhi hapin e parë drejt shndërrimit në fuqi detare.", "b765c903"]},
"OLAYLAR_EK3:1696-08-27:0":{"b": ["Fitorja e Ulashit (Olasch)", "02ac9ca8"], "d": ["Fitorja e fituar në bregun e Danubit në fushatën e dytë të padishahut prishi planin austriak për të marrë Temeshvarin; por nuk e ndryshoi ekuilibrin e përgjithshëm të luftës.", "b6e2d27a"]},
"OLAYLAR_EK3:1697-09-11:0":{"b": ["Disfata e Zentës — u përcaktua fati i luftës", "475c4a7b"], "d": ["Ndërsa ushtria po kalonte lumin Tisa, pësoi sulmin e befasishëm të princit Eugjen; forcat e ndara në të dy brigjet e lumit u asgjësuan brenda pak orësh, vdiqën mijëra ushtarë dhe burrështetas, përfshirë vezirin e madh Elmas Mehmed Pashën. Zenta, një nga disfatat më të rënda të historisë osmane, e bëri të pashmangshme tryezën e paqes.", "ced10fdc"]},
"OLAYLAR_EK3:1698-11-13:0":{"b": ["Filluan bisedimet e paqes së Karlovcit", "1f395cf3"], "d": ["Në bisedimet që filluan me ndërmjetësimin e Anglisë dhe të Holandës, delegacioni osman për herë të parë u detyrua të pranonte parimin 'uti possidetis' (secila palë mban atë që ka në dorë); negociatat prej shtatëdhjetë e dy seancash konsiderohen lindja e diplomacisë moderne osmane.", "1d41e9e8"]},
"OLAYLAR_EK4:1801-03-08:0":{"b": ["Mehmet Ali nga Kavalla doli në Egjipt", "514c943f"], "d": ["Në ushtrinë osmane të dërguar për të rimarrë Egjiptin e pushtuar nga francezët ishte edhe njësia vullnetare e mbledhur nga Kavalla. Mehmet Aliu, në të tridhjetat, ishte komandanti i dytë i kësaj njësie; në Egjipt shkeli jo si vali, por si oficer kompanie.", "b7e3bb36"]},
"OLAYLAR_EK4:1803-05-01:0":{"b": ["Ushtarët shqiptarë rrëzuan valiun e Egjiptit", "c76a0ec2"], "d": ["Njësitë shqiptare, rrogat e të cilave nuk paguheshin, u ngritën në kryengritje dhe e detyruan valiun Hysrev Pasha të ikte nga kalaja. Në boshllëkun që lindi me tërheqjen e francezëve, bejlerët qylemenë (memlukë), odxhaku shqiptar dhe valinjtë e emëruar nga Porta e Lartë hynë në një luftë tripalëshe; Mehmet Aliu, duke krijuar ekuilibra në këtë trekëndësh, doli në plan të parë. Vendbanime të tjera që u humbën në të njëjtën datë: Taifi.", "669d61a0"]},
"OLAYLAR_EK4:1805-05:0":{"b": ["Ulemaja e Kajros e shpalli Mehmet Aliun vali", "a16752f2"], "d": ["Esnafët dhe ulemaja e Kajros, të rraskapitur nga presioni i taksave, nën udhëheqjen e nakib-ul-eshrafit Omer Mekrem, u ngritën, njoftuan se nuk e njihnin valiun Hurshid Pasha dhe e vendosën Mehmet Aliun në postin e valiut. Zgjedhja e një valiu nga populli është një ngjarje e rrallë në historinë osmane.", "1572b66f"]},
"OLAYLAR_EK4:1805-07-03:0":{"b": ["Porta e Lartë pranoi faktin e kryer: fermani për valiun e Egjiptit", "b86736a3"], "d": ["Porta e Lartë, që nuk kishte fuqi të mbante në Egjipt kandidatin e vet, i dërgoi Mehmet Aliut fermanin e valiut të Egjiptit me gradën e vezirit. Në hartë Egjipti që nga kjo datë kalon në shtresën vartëse (me ngjyrë të çelët): juridikisht tokë osmane, de fakto vendi i dinastisë së Mehmet Aliut nga Kavalla. Vendbanime të tjera që po në atë datë kalojnë në shtresën vartëse: Kajro, Aleksandria, Damieta, Asjuti, Asuani, Ibrimi, Suezi, Rashidi (Rosetta).", "e769c607"]},
"OLAYLAR_EK4:1807-03-17:0":{"b": ["Ekspedita angleze e Fraserit zbarkoi në Aleksandri", "4d6c31be"], "d": ["Në përgjigje të afrimit të Osmanëve me Francën, Anglia dërgoi në Egjipt një forcë zbarkimi. Mehmet Aliu në atë kohë merrej me qylemenët në Egjiptin e Epërm; u kthye shpejt dhe organizoi mbrojtjen.", "fd5f278f"]},
"OLAYLAR_EK4:1807-04-21:0":{"b": ["Disfata e Rashidit (Rosettës) — anglezët u zmbrapsën", "3636004c"], "d": ["Kolona angleze që hyri në qytezën e Rashidit pësoi humbje të rënda në përleshjet në rrugë; në shtator forcat e zbrazën plotësisht Egjiptin. Kjo fitore e përforcoi prestigjin e Mehmet Aliut si në Egjipt, ashtu edhe në Stamboll.", "68a2ba26"]},
"OLAYLAR_EK4:1811-03-01:0":{"b": ["Ngjarja e Kalasë: likuidimi i bejlerëve qylemenë", "84030b97"], "d": ["Bejlerët qylemenë, të ftuar në kortezhin e ceremonisë së organizuar për fushatën e Hixhazit, u zhdukën pasi u zunë në kurth në kalimin e ngushtë të Kalasë së Kajros. Kështu mori fund ndikimi pesëqindvjeçar i qylemenëve dhe në Egjipt Mehmet Aliut nuk i mbeti asnjë rival.", "1ca00e33"]},
"OLAYLAR_EK4:1811-09-03:0":{"b": ["Filloi fushata e Hixhazit — ushtria marshoi nga Suezi në Jenbo me det dhe nga rruga e haxhit me tokë", "1c05c159"], "d": ["Rimarrja e dy qyteteve të shenjta (Haremejn), nën administrimin saudito-vehabit që nga viti 1803, ishte çështja më e madhe e legjitimitetit të Mahmudit II; meqë Porta e Lartë nuk kishte fuqi, detyra iu dha valiut të Egjiptit. Mehmet Aliu dërgoi në krye të ushtrisë të birin gjashtëmbëdhjetëvjeçar, Tosunin.", "5e614d69"]},
"OLAYLAR_EK4:1811-10-01:0":{"b": ["U mor Jenboja — baza e parë bregdetare e fushatës së Hixhazit", "179bc78d"], "d": ["Rreth dy mijë këmbësorë shqiptarë, të nisur nga Suezi me anije të sapondërtuara, zbarkuan pranë Jenbos në tetor 1811; qyteza u dorëzua pas një rezistence të dobët dyditore. Kalorësit nën komandën e Tosunit, që ndiqnin me tokë rrugën e haxhit, arritën në Jenbo përmes Akabasë dhe Vexhit vetëm dy javë më vonë. Jenboja u bë baza e parë në Hixhaz e ushtrisë egjiptiane që do të marshonte drejt Medinës dhe Mekës.", "cfc2ed8a"]},
"OLAYLAR_EK4:1812-01-01:0":{"b": ["Disfata e parë në grykën Safra-Xhedide", "99ef804d"], "d": ["Pararoja egjiptiane, që ra në pritë në qafat e ngushta malore, u shpartallua. Disfata u bë mësimi taktik i fushatës: u kuptua se pa mbështetjen e fiseve beduine nuk ishte e mundur të ecej në Hixhaz.", "765dd19d"]},
"OLAYLAR_EK4:1812-12-03:0":{"b": ["U rimor Medina", "6f6a5d55"], "d": ["Pas një rrethimi të gjatë, Medina u dorëzua. Rimarrja e qytetit të Profetit u festua në Stamboll me të shtëna topash; Mehmet Aliut, si shpërblim, iu dha edhe valiu i Xhidës.", "45cc4c79"]},
"OLAYLAR_EK4:1813-01-23:0":{"b": ["U rimor Meka — u hap rruga e haxhit", "3d6d66a0"], "d": ["Forcat egjiptiane që hynë në Mekë bënë që në Qabe të lexohej përsëri hytbeja në emër të padishahut osman. Karvanet e haxhit, të ndërprera prej dhjetë vjetësh, mundën të niseshin sërish. Në hartë Hixhazi kthehet nën sovranitetin osman, por, meqë administrimi ishte në Kajro, paraqitet me ngjyrë vartëse. Vend tjetër që po në atë datë kalon në administrim vartës: Xhida.", "f0970e28"]},
"OLAYLAR_EK4:1813-05-02:0":{"b": ["Rimarrja e Taifit — përfundimi i fushatës së Hixhazit", "6315fb31"], "d": ["Pas Medinës (dhjetor 1812) dhe Mekës (janar 1813), ushtria egjiptiane nën komandën e Tosun Pashës së fundi ua rimori vehabitëve Taifin. Sundimi saudit dhjetëvjeçar mori fund dhe të tri qendrat e shenjta të Hixhazit hynë përsëri nën kontrollin osmano-egjiptian.", "374bf563"]},
"OLAYLAR_EK4:1813-08-28:0":{"b": ["Mehmet Aliu kaloi vetë në Hixhaz", "fda0ea2d"], "d": ["Valiu, që pa se fushata po ecte ngadalë, e mori administrimin drejtpërdrejt në dorë; duke bërë pazar me krerët e fiseve, u përpoq ta shpërbënte frontin saudit nga brenda. Me këtë fushatë u rrit edhe pjesa e Egjiptit në tregtinë e Detit të Kuq.", "aeb051d1"]},
"OLAYLAR_EK4:1815-01-20:0":{"b": ["Beteja e Bisalit: forcat saudite u shpartalluan", "9c9ab91f"], "d": ["Sauditët, që pësuan një disfatë të rëndë në betejën fushore, u tërhoqën në brendësi. Armëpushimi i bërë nuk qe i qëndrueshëm; dy vjet më vonë operacioni do të zhvendosej në zemër të Nexhdit. Atlasi konsideron se pas kësaj fitoreje Turaba dhe Hurma, në lindje të Taifit, dolën nga duart saudite (burimi i ngjarjes: Lorimer, Gazetteer; dëshmia specifike për vendbanimet dhe dita 13 janar janë përafërsi e deklaruar).", "551e1880"]},
"OLAYLAR_EK4:1816-09-01:0":{"b": ["Ibrahim Pasha doli në fushatën e Nexhdit", "d5ed80d1"], "d": ["Ibrahim Pasha, që mori komandën pas vdekjes së të vëllait, Tosunit, nisi një marshim të rëndë në shkretëtirë që zgjati dy vjet. Ushtria, duke përparuar pus pas pusi dhe duke i mënjanuar fiset një nga një, arriti përpara kryeqytetit saudit.", "e84c2cef"]},
"OLAYLAR_EK4:1818-09-09:0":{"b": ["Ra Dirija — mori fund Shteti i parë Saudit", "aa96206d"], "d": ["Pas rrethimit gjashtëmujor, Dirija u dorëzua dhe u shkatërrua. Emiri Abdullah bin Saud u dërgua në Stamboll dhe u ekzekutua. Flamuri osman për herë të parë arriti kaq thellë në brendësi të Arabisë; garnizoni i Nexhdit qëndroi deri në vitin 1824. Vende të tjera që u bashkuan në të njëjtën datë: Dirija (Nexhd).", "4b161cf5"]},
"OLAYLAR_EK4:1820-07-20:0":{"b": ["Filloi fushata e Sudanit", "b1fc6905"], "d": ["Synimi i Mehmet Aliut ishte i trefishtë: të mblidhte ushtarë për ushtrinë, të arrinte te ari i Senarit dhe të zhdukte mbetjet e qylemenëve të ikur. Forca nën komandën e të birit, Ismail Pashës, duke ndjekur Nilin, zbriti drejt jugut.", "478563e9"]},
"OLAYLAR_EK4:1820-11-01:0":{"b": ["Dongola i kaloi ushtrisë egjiptiane pa dhunë (memlukët e kishin braktisur në qershor 1820)", "bc5942c0"], "d": ["Dongola, në kthesën e madhe të Nilit, pasi memlukët e braktisën në qershor 1820, kaloi pa dhunë në duart e ushtrisë egjiptiane të Ismail Pashës. Në hartë Sudani që nga kjo datë shfaqet në shtresën vartëse: pushtuesi është Kajro dhe sundues do të jetë përsëri Kajro.", "61ac03d6"]},
"OLAYLAR_EK4:1820-12-04:0":{"b": ["Beteja e Xhebel ed-Dajkës — konfederata Shajkija mundet përfundimisht nga ushtria egjiptiane", "befc9539"], "d": ["Ushtria e Ismail Pashës, të birit të Mehmet Ali Pashës, një muaj pas përplasjes së parë në Kurti, e mundi Shajkijan në betejën e dytë dhe vendimtare pranë Xhebel ed-Dajkës. Kreu i Shajkijas, Mak Subajri, u dorëzua; Mak Shavishi vazhdoi rezistencën. Pas kësaj sundimi egjiptian në kthesën e Nilit u bë i përhershëm.", "5e0734a7"]},
"OLAYLAR_EK4:1821-06-14:0":{"b": ["Sulltanati i Senarit (Funxh) u dorëzua", "3cac7dd2"], "d": ["Dinastia treshekullore Funxh u dorëzua pa luftë. Po atë vit, kampi ushtarak i ngritur në pikën ku bashkohen dy degët e Nilit, për pak kohë u shndërrua në Hartum, qendrën administrative të Sudanit. Vende të tjera që u bashkuan në të njëjtën datë: Senar.", "1ad105c1"]},
"OLAYLAR_EK4:1821-08-19:0":{"b": ["U mor Kordofani", "06440602"], "d": ["Kolona e dytë, e dërguar drejt perëndimit, duke mundur forcat e Darfurit në Bara, mori Kordofanin së bashku me rrethinat e Nuhudit. Kështu sundimi egjiptian në Sudan u zgjerua nga lugina e Nilit deri në stepat perëndimore.", "6bc3a4f6"]},
"OLAYLAR_EK4:1822-06-28:0":{"b": ["Forcat egjiptiane zbarkuan në Kretë", "835aee90"], "d": ["Kur kryengritja greke u përhap në Kretë, Porta e Lartë kërkoi dërgimin e një force egjiptiane në ishull. Ndikimi i Mehmet Aliut në ishull filloi me këtë ndërhyrje dhe tetë vjet më vonë përfundoi me dhënien atij të valisë së Kretës.", "8d651366"]},
"OLAYLAR_EK4:1822-10-24:0":{"b": ["Vrasja e Ismail Pashës në Shendi", "223860c9"], "d": ["Emiri vendor Nimri, i zemëruar nga kërkesa për taksa të rënda dhe ushtarë, i vuri flakën shtëpisë ku Ismail Pasha po bujtte dhe e dogji atë me shpurën e tij. Fushata hakmarrëse e ktheu krahinën në një liqen gjaku; administrimi i Sudanit pas kësaj u ndërtua mbi ashpërsinë.", "722af711"]},
"OLAYLAR_EK4:1824-07-19:0":{"b": ["Mahmudi II i kërkoi ndihmë Mehmet Aliut për Morenë", "03594a42"], "d": ["Për kryengritjen e Moresë, që ushtria e jeniçerëve nuk arriti ta shtypte për tre vjet, padishahu iu drejtua ushtrisë egjiptiane të stërvitur sipas mënyrës evropiane. Në këmbim u premtuan valia e Moresë dhe Kreta. Kjo kërkesë ishte pranimi i parë i hapur se perandoria ishte bërë e varur nga vilajeti i vet.", "1b0ee342"]},
"OLAYLAR_EK4:1825-02-24:0":{"b": ["Ibrahim Pasha zbarkoi në Modon", "9c993dba"], "d": ["Forca e zbarkimit, e mbrojtur nga flota egjiptiane, shkeli në skajin jugperëndimor të Moresë. Kjo ushtri, e pajisur me këmbësori të rregullt dhe me artileri fushore, brenda pak kohe fitoi epërsi ndaj çetave kryengritëse.", "edf38fca"]},
"OLAYLAR_EK4:1825-06-22:0":{"b": ["U rimor Tripolica — ra qendra e Moresë", "8a478c11"], "d": ["Me rënien e Tripolicës, qendrës drejtuese të kryengritjes, pjesa më e madhe e Moresë u vu përsëri nën kontroll. Në hartë gadishulli, meqë ishte në duart e forcave egjiptiane, shfaqet me ngjyrë vartëse.", "e7d9b818"]},
"OLAYLAR_EK4:1826-04-22:0":{"b": ["Ra Misolongji", "07257f87"], "d": ["Pas një rrethimi njëvjeçar qyteti u mor. Megjithatë, jehona që mbrojtja pati në shtypin evropian e çoi në kulm simpatinë për çështjen greke dhe përgatiti terrenin për ndërhyrjen e fuqive të mëdha.", "9bf1efc2"]},
"OLAYLAR_EK4:1827-06-05:0":{"b": ["U mor Akropoli i Athinës", "3b19f946"], "d": ["Me rënien e Akropolit, kryengritja greke ushtarakisht pothuajse kishte marrë fund. Pikërisht në këtë pikë çështja pushoi së qeni kryengritje e brendshme dhe u bë temë e diplomacisë evropiane.", "e096fc52"]},
"OLAYLAR_EK4:1827-07-06:0":{"b": ["Traktati i Londrës: tri shtetet imponuan autonominë greke", "7ce46fd8"], "d": ["Anglia, Franca dhe Rusia vendosën të vepronin bashkë për t'i detyruar Osmanët dhe grekët të pranonin armëpushim dhe kushtin e autonomisë; u njoftua se, nëse refuzohej, flotat e tyre do të ndërhynin. Porta e Lartë e refuzoi propozimin.", "8382f516"]},
"OLAYLAR_EK4:1828-08-06:0":{"b": ["Konventa e Aleksandrisë: vendimi për tërheqjen e Egjiptit nga Moreja", "cc978f37"], "d": ["Mehmet Aliu, që humbi flotën në Navarin, pa u këshilluar me Stambollin, u mor vesh drejtpërdrejt me admiralin anglez dhe pranoi t'i tërhiqte forcat e veta nga Moreja. Fakti që një vali lidhte marrëveshje të pavarur me fuqitë e mëdha paralajmëronte krizën e ardhshme.", "9430ea24"]},
"OLAYLAR_EK4:1828-10-05:0":{"b": ["Forcat egjiptiane zbrazën Morenë", "8fb742dd"], "d": ["Njësitë e fundit u hipën në anije; gadishulli de fakto doli nga duart dhe me Protokollin e Londrës të vitit 1830 u bë bërthama e Greqisë së pavarur. Kurse Mehmet Aliu nuk mundi të merrte valinë e premtuar të Moresë dhe në këmbim kishte humbur një flotë e ushtri të madhe. Vendbanime të tjera që u humbën në të njëjtën datë: Modoni, Koroni.", "7bfbefe0"]},
"OLAYLAR_EK4:1830-11-01:0":{"b": ["Administrimi i Kretës iu la Mehmet Aliut", "7f76396d"], "d": ["Si kompensim për humbjen e Moresë, Mehmet Aliut iu dha valia e Kretës. Ishulli për dhjetë vjet u qeveris nga Kajro; gjatë kësaj kohe në hartë paraqitet me ngjyrë vartëse. Vende të tjera që u bashkuan në të njëjtën datë: Kandia (Kretë).", "5b000d2b"]},
"OLAYLAR_EK4:1831-10-31:0":{"b": ["Ibrahim Pasha hyri në Siri — filloi kriza e parë", "1a5cc386"], "d": ["Pretekst ishte valiu i Akkës, që nuk i kthente felahët e ikur nga Egjipti; arsyeja e vërtetë ishte nevoja e Mehmet Aliut për lëndën drusore, portet dhe burimet njerëzore të Sirisë. Ushtria kaloi Sinain dhe pushtoi shpejt bregun e Palestinës.", "9d41b0f9"]},
"OLAYLAR_EK4:1831-11-26:0":{"b": ["Filloi rrethimi i Akkës", "b211d96d"], "d": ["Kalaja që ndali Napoleonin në vitin 1799 rezistoi gjashtë muaj. Rrethimi ishte prova e parë e madhe e artilerisë moderne të ushtrisë egjiptiane.", "97d9816b"]},
"OLAYLAR_EK4:1832-05-27:0":{"b": ["Ra Akka", "0f47917b"], "d": ["Kur bateritë që goditnin muret hapën të çarë, kalaja u mor. Dera e Sirisë ishte hapur; Porta e Lartë po në ato ditë e shpalli Mehmet Aliun rebel dhe i hoqi valinë.", "f92b4224"]},
"OLAYLAR_EK4:1832-06-16:0":{"b": ["U dorëzua Damasku", "48da3b62"], "d": ["Qyteti u dorëzua pa luftë. Ibrahim Pasha, duke shpallur rendin tatimor dhe barazinë e njohur jomyslimanëve, u përpoq të fitonte mbështetjen vendore; po këto politika pas pak vjetësh do të bëheshin edhe shkaku i kryengritjeve kundër tij. Vende të tjera që u bashkuan në po ato ditë: Bejruti, Tripoli i Sirisë (Trablusshami), Sidoni.", "c67bd97e"]},
"OLAYLAR_EK4:1832-07-08:0":{"b": ["Beteja e Homsit", "867810ee"], "d": ["Ushtria osmane e dërguar për të shpëtuar Sirinë u shpartallua në fushë të hapur. U pa se ushtria e re, e krijuar gjashtë vjet pas shfuqizimit të korpusit të jeniçerëve, nuk ishte ende gati.", "f429ba2e"]},
"OLAYLAR_EK4:1832-07-15:0":{"b": ["U mor Halepi", "9c0ead76"], "d": ["Ra edhe qendra tregtare dhe administrative e Sirisë Veriore. Kështu ushtria egjiptiane arriti rrëzë maleve të Taurit dhe u drejtua për në qafat në derën e Anadollit.", "b8b4a1bd"]},
"OLAYLAR_EK4:1832-07-29:0":{"b": ["Disfata e Qafës së Belenit (Beylan) — u hap Çukurova", "4bae872b"], "d": ["Në qafën e ngushtë të maleve Amanos u ça vija mbrojtëse. Antakia, Adana dhe Tarsi kaluan te forcat egjiptiane (pushtimi i Marashit, sipas TDV-së, është i vitit 1833, zë më vete); në hartë Çukurova kalon në ngjyrë vartëse. Rruga drejt brendësisë së Anadollit tashmë ishte e pambrojtur.", "73cb1c5e"]},
"OLAYLAR_EK4:1832-09-13:0":{"b": ["Ra Qafa e Gylekut — bregu i Içelit (Mersin, Silifke) hyri nën kontrollin egjiptian", "d9049b5b"], "d": ["Qafa e Gylekut, porta e Çukurovës në Tauri, kaloi në duart e ushtrisë egjiptiane. Ibrahim Pasha emëroi mytesellimin e vet në Sanxhakun e Içelit dhe të gjitha skelat bregdetare hynë nën kontrollin egjiptian. Në hartë Mersini dhe Silifkja paraqiten si të lidhura me Egjiptin që nga kjo ditë (kufiri i poshtëm; dita e emërimit mungon te burimi); meqë me vendimin e Kytahjas kaloi vetëm muhasillëku i Adanasë, ky kontroll merr fund me evakuimin e Anadollit.", "fa650158"]},
"OLAYLAR_EK4:1832-09-13:1":{"b": ["Ereglia e Konjas nën pushtim egjiptian — gryka e Taurit në rrugën Konja–Adana", "fb908900"], "d": ["Ereglia, në rrugën për në Konja të ushtrisë egjiptiane që kaloi Qafën e Gylekut, hyri nën pushtimin e Ibrahim Pashës në vitin 1832 dhe, kur u zbraz me rregullimin e Kytahjas të vitit 1833, u lidh përsëri me vilajetin e Karamanit. Në hartë është pikë e ndërmjetme e mbështetur në burim e vijës së pushtimit midis Adanasë dhe Konjas; për Ulukëshlanë dhe Karapënarin nuk u gjet dëshmi në nivel qyteti.", "c5c7c153"]},
"OLAYLAR_EK4:1832-11-21:0":{"b": ["Ushtria egjiptiane hyri në Konja", "13952a2d"], "d": ["Ushtria që kaloi Taurin arriti në Anadollin Qendror. Forcat e një valiu osman për herë të parë po përparonin në tokat bërthamë të perandorisë. Vende të tjera që u bashkuan në të njëjtën datë: Karaman.", "569bd202"]},
"OLAYLAR_EK4:1832-12-21:0":{"b": ["Beteja Fushore e Konjas: veziri i madh u zu rob", "ec82cc9a"], "d": ["Ushtria osmane, e shpërndarë në mjegull, pësoi një disfatë të rëndë dhe veziri i madh Reshid Mehmed Pasha u zu rob. Ushtria qendrore e shtetit nuk ekzistonte më; midis Stambollit dhe forcave egjiptiane nuk kishte mbetur asnjë fuqi që të qëndronte.", "30e73138"]},
"OLAYLAR_EK4:1833-01-01:0":{"b": ["Marashi pësoi pushtimin egjiptian", "f558e383"], "d": ["Sipas TDV-së, Marashi në vitin 1833 pësoi pushtimin e Ibrahim Pashës së Kavallës dhe mbeti nën administrimin e tij afro nëntëmbëdhjetë muaj. Meqë Marashi mbetej jashtë kufijve të ejaletit të rregullimit të Kytahjas, ky administrim nuk ishte juridik, por de fakto.", "3d3c898a"]},
"OLAYLAR_EK4:1833-01-01:1":{"b": ["Karahisar-i Sahib (Afjon) pësoi pushtimin egjiptian — rruga Konja–Kytahja", "ae0c2c78"], "d": ["Karahisar-i Sahib, në rrugën e ushtrisë egjiptiane që pas Betejës Fushore të Konjas përparoi drejt Kytahjas, në vitin 1833 mbeti për ca kohë në duart e Ibrahim Pashës. Në hartë është pikë e ndërmjetme e mbështetur në burim e vijës së pushtimit midis Konjas dhe Kytahjas; për Akshehirin, Ilgënin dhe Ishaklinë nuk u gjet dëshmi në nivel qyteti, ato janë me ngjyrë osmane.", "bce0b466"]},
"OLAYLAR_EK4:1833-02-02:0":{"b": ["Ushtria egjiptiane arriti në Kytahja", "214f8df6"], "d": ["Ibrahim Pasha u ndal në Kytahja, tri etapa larg Stambollit. Mosvazhdimi përpara nuk ishte ushtarak, por politik: ishin marrë parasysh ndërhyrja ruse dhe reagimi i Evropës.", "0f1c5f03"]},
"OLAYLAR_EK4:1833-02-20:0":{"b": ["Flota ruse përpara Büyükderesë", "6f836d61"], "d": ["Mahmudi II, që nuk mundi të merrte ndihmë nga Anglia dhe Franca, iu drejtua armikut të djeshëm, Rusisë. Ky vendim, që përmendet me fjalën e padishahut \"kush bie në det kapet edhe pas gjarprit\", përfundoi me daljen e ushtarëve rusë në ngushtica dhe ngriti alarmin në Evropë.", "3e402e00"]},
"OLAYLAR_EK4:1833-05-06:0":{"b": ["Marrëveshja e Kytahjas (gojore) — Siria dhe Adana te Mehmet Aliu nga Kavalla", "25fe9985"], "d": ["Porta e Lartë, përveç Egjiptit, Kretës dhe Hixhazit, ia la Mehmet Aliut valinë e Damaskut, të Halepit, të Tripolit të Sirisë dhe të Sidonit; muhasillëkun e Adanasë ia la Ibrahim Pashës. Në këmbim, ushtria u tërhoq në jug të Taurit. Kjo nuk ishte traktat, por kishte formën e fermaneve që padishahu i dha një valiu — çështja nuk ishte zgjidhur, por shtyrë.", "4160e4f4"]},
"OLAYLAR_EK4:1833-06-15:0":{"b": ["Tërheqja e ushtrisë egjiptiane nga Anadolli përfundoi përmes Gylekut", "a53ac2a3"], "d": ["Pas rregullimit të Kytahjas, forcat egjiptiane zbrazën Anadollin; rreth mesit të qershorit e gjithë ushtria kaloi nga Qafa e Gylekut në Çukurovë. Bregu i Içelit (Mersin, Silifke) kthehet përsëri nën administrimin osman; muhasillëku i Adanasë dhe Siria mbeten te Egjipti.", "c5e13625"]},
"OLAYLAR_EK4:1833-07-08:0":{"b": ["Traktati i Hünkâr İskelesit", "da741d5c"], "d": ["Me Rusinë u nënshkrua një aleancë e ndërsjellë mbrojtëse tetëvjeçare. Sipas nenit sekret, nëse Rusia sulmohej, Osmanët do t'i mbyllnin ngushticat për anijet luftarake. Ky u bë një nga vendimet më të diskutuara të diplomacisë osmane dhe e bëri Anglinë aktive në çështjen egjiptiane.", "43dc2c96"]},
"OLAYLAR_EK4:1834-05-19:0":{"b": ["Kryengritja e Palestinë-Nablusit kundër administrimit egjiptian", "4fe43e27"], "d": ["Shërbimi ushtarak i detyrueshëm, mbledhja e armëve dhe taksat e reja shkaktuan një kryengritje të gjerë në Palestinë. Kryengritja u shtyp ashpër; mbështetja e popullsisë vendase për administrimin egjiptian u shkri shpejt.", "2a3301a2"]},
"OLAYLAR_EK4:1834-08-01:0":{"b": ["Fundi i administrimit egjiptian në Marash (përafërsisht)", "bb46ca42"], "d": ["Nëse fjalia e TDV-së për kohëzgjatjen 'afro nëntëmbëdhjetë muaj' llogaritet nga pushtimi i vitit 1833, administrimi egjiptian merr fund rreth verës së vitit 1834. Fakti që Mustafa Beu nga familja Kyçykalioglu, në vitin 1834, pa mundur t'i rezistonte ushtrisë egjiptiane, u tërhoq drejt Marashit tregon gjithashtu se Marashi në atë kohë ishte një strehë jashtë kontrollit egjiptian.", "fbb6814a"]},
"OLAYLAR_EK4:1837-10-15:0":{"b": ["Kryengritja e Xhebel Druzit", "12e74626"], "d": ["Rezistenca që shpërtheu në krahinën druze zgjati dy vjet. Pakënaqësia e grumbulluar në Siri, kur në vitin 1840 flotat aleate dolën në breg, do t'ia zbrazte shpinën ushtrisë egjiptiane.", "75c50707"]},
"OLAYLAR_EK4:1838-05-25:0":{"b": ["Mehmet Aliu njoftoi synimin për pavarësi", "48633bbd"], "d": ["Valiu u deklaroi konsujve të fuqive të mëdha se po mendonte të shpallte pavarësinë e Egjiptit dhe të Sirisë. Anglia e kundërshtoi prerë: lindja në Mesdhe e një shteti të fortë dhe afër Francës do të kërcënonte rrugën e Indisë.", "d6181bd9"]},
"OLAYLAR_EK4:1839-04-21:0":{"b": ["Ushtria osmane kaloi Eufratin", "9af1ea69"], "d": ["Mahmudi II, për të rimarrë atë që kishte humbur në Kytahja, e shtyu ushtrinë drejt kufirit sirian. Oficeri prusian Moltke, që ndodhej në ushtri si këshilltar, kundërshtoi zgjedhjen e pozicionit dhe ofensivën e parakohshme; kundërshtimet e tij nuk u dëgjuan.", "85d5db1c"]},
"OLAYLAR_EK4:1839-06-24:0":{"b": ["Beteja e Nizipit — ushtria osmane u shpërbë", "156b3cdf"], "d": ["Ushtria osmane e vendosur keq u shpartallua brenda pak orësh. Padishahu vdiq para se lajmi i disfatës të arrinte në Stamboll; shteti, brenda pak ditësh, do të humbte ushtrinë, sundimtarin e më pas flotën.", "fb8af82d"]},
"OLAYLAR_EK4:1839-06-28:0":{"b": ["Vdekja e Mahmudit II", "07eccfff"], "d": ["Padishahu që gjatë sundimit tridhjetë e një vjeçar shfuqizoi korpusin e jeniçerëve dhe rindërtoi administrimin qendror, vdiq pa mundur të mundte kundërshtarin më të madh. Sëmundjes së tij nuk iu bë diagnoza e saktë. Vdekja u mbajt e fshehtë deri më 30 qershor, derisa në qytet u morën masa ushtarake, nga frika se mentaliteti jeniçer do të vihej në lëvizje.", "3174d901"]},
"OLAYLAR_EK4:1839-07-01:0":{"b": ["Hipja në fron e Abdylmexhidit dhe funerali i Mahmudit II", "d0f3d2cc"], "d": ["Pas vdekjes së të atit, Abdylmexhidi gjashtëmbëdhjetëvjeçar hipi në fron. Po atë ditë trupi i Mahmudit II u soll në Sarajin Topkapë; trazirat e frikshme nuk ndodhën dhe turma të gjera popullore, myslimane e jomyslimane, iu bashkuan kortezhit të varrimit.", "7b398ea4"]},
"OLAYLAR_EK4:1839-07-14:0":{"b": ["Dorëzimi i flotës në Aleksandri", "a53e6103"], "d": ["Kapudan pashai Ahmed Fevzi Pasha, me dyshimin se veziri i madh Koxha Hysrev Pasha do t'ia jepte flotën Rusisë, e çoi flotën në Aleksandri dhe ia dorëzoi Mehmet Aliut. Brenda po atij muaji Shteti Osman mbeti pa ushtri, pa padishah dhe pa flotë.", "78a26255"]},
"OLAYLAR_EK4:1839-07-27:0":{"b": ["Nota e përbashkët e fuqive të mëdha", "2a3b8316"], "d": ["Pesë shtete i dërguan Portës së Lartë një notë, duke kërkuar që në çështjen egjiptiane të mos bënte marrëveshje të veçantë. Kështu një çështje e brendshme u bë zyrtarisht \"çështje evropiane\"; shteti osman de fakto humbi kompetencën për të vendosur për vilajetin e vet.", "979e7f0a"]},
"OLAYLAR_EK4:1840-07-15:0":{"b": ["Traktati i Londrës: katër shtete në anën e Osmanëve", "a517f775"], "d": ["Traktati, i nënshkruar duke lënë jashtë Francën, i dha Mehmet Aliut një ultimatum: nëse pranonte brenda dhjetë ditësh, valinë e trashëgueshme të Egjiptit dhe, me kusht përjetësie, Akkën; nëse pranonte brenda njëzet ditësh, vetëm Egjiptin; nëse refuzonte, asgjë. Valiu refuzoi.", "fc066f82"]},
"OLAYLAR_EK4:1840-09-10:0":{"b": ["Bombardimi i Bejrutit dhe zbarkimi aleat", "0905ce92"], "d": ["Flota anglo-austriake e goditi me topa Bejrutin; popullit që u ngrit kundër administrimit egjiptian në malet e Libanit iu shpërndanë armë. Kontrolli i Ibrahim Pashës në Siri u shemb midis kryengritjes së brendshme dhe ndërhyrjes së jashtme.", "743ec7e2"]},
"OLAYLAR_EK4:1840-10-10:0":{"b": ["Bejruti dhe qytetet bregdetare dolën nga duart", "09bdaf23"], "d": ["Pas përleshjeve në drejtim të Baalbekut, forcat egjiptiane u tërhoqën nga bregdeti. Në hartë bregu i Libanit del nga ngjyra vartëse dhe kthehet në administrimin e drejtpërdrejtë osman.", "fe5e95aa"]},
"OLAYLAR_EK4:1840-11-03:0":{"b": ["Akka ra brenda dy orësh", "5aec21f0"], "d": ["Gjatë bombardimit të flotës aleate shpërtheu depoja e municionit të kalasë dhe Akka u dorëzua brenda pak orësh. Kalaja që tetë vjet më parë Ibrahim Pasha mundi ta merrte vetëm për gjashtë muaj tregoi epërsinë e artilerisë detare.", "5cf01edf"]},
"OLAYLAR_EK4:1840-11-27:0":{"b": ["Konventa e Aleksandrisë", "85cb47b0"], "d": ["Mehmet Aliu pranoi të hiqte dorë nga Siria, Adana, Kreta dhe Hixhazi, të kthente flotën osmane dhe të njihte sovranitetin e padishahut; në këmbim iu sigurua valia e trashëgueshme e Egjiptit.", "63d90626"]},
"OLAYLAR_EK4:1841-02-25:0":{"b": ["Ushtria egjiptiane zbrazi Sirinë dhe Çukurovën", "719a28dc"], "d": ["Pushtimi nëntëvjeçar mori fund; ushtria e Ibrahim Pashës u kthye në Egjipt përmes Sinait. Në hartë brezi i gjerë nga Halepi në Gazë, nga Adana në Kretë kalon përsëri në administrimin e drejtpërdrejtë osman. Vendbanime të tjera që u humbën në të njëjtën datë: Urfa, Marashi, Tarsi, Antakia, Kandia (Kretë), Hama, Damasku, Jerusalemi, Jafa, Nablusi.", "a678b17a"]},
"OLAYLAR_EK4:1841-05-24:0":{"b": ["Fermani: valia e Egjiptit iu la si e trashëgueshme familjes së Mehmet Aliut", "87b89ff8"], "d": ["Fermani i padishahut e njohu valinë si të trashëgueshme brenda dinastisë, nga ati te i biri; në këmbim, numri i ushtrisë u ul në tetëmbëdhjetë mijë, taksa u lidh me Stambollin, u hoqën kompetencat për të prerë monedhë dhe për të lidhur traktate. Egjipti mbeti vilajet, por tashmë ishte vendi i një dinastie më vete. Administrimi i Hixhazit dhe i Haremejnit iu kthye Portës së Lartë. Vendbanime të tjera që po në atë datë kthehen nga shtresa vartëse në atë të drejtpërdrejtë: Meka, Medina, Xhida, Jenboja.", "48099454"]},
"OLAYLAR_EK4:1841-07-13:0":{"b": ["Konventa e Londrës për Ngushticat", "0e95a1ea"], "d": ["Konventa që zëvendësoi Hünkâr İskelesin përcaktoi që në kohë paqeje ngushticat të ishin të mbyllura për të gjitha anijet luftarake. Kështu privilegji që Rusia e kishte fituar vetë u shndërrua në garanci të përbashkët të Evropës; çështja e ngushticave fitoi status ndërkombëtar.", "5bbbb459"]},
"OLAYLAR_EK4:1848-09-01:0":{"b": ["Ibrahim Pasha u bë de fakto vali i Egjiptit", "9e14f5d9"], "d": ["Në vend të Mehmet Aliut, që ishte plakur dhe kishte humbur aftësitë mendore, vali u bë i biri, Ibrahim Pasha. Por pas pak muajsh, në nëntor 1848, vdiq para të atit.", "338908f8"]},
"OLAYLAR_EK4:1849-08-02:0":{"b": ["Vdekja e Mehmet Ali Pashës nga Kavalla", "871310e0"], "d": ["Valiu, i lindur në Kavallë, që krijoi dinasti në Egjipt dhe dy herë e çoi perandorinë në buzë të greminës, vdiq tetëdhjetë vjeç. Dinastia që themeloi sundoi në Egjipt deri në vitin 1953; shteti, duke parë se plagën që hapi ai mund ta mbyllte vetëm me ndërhyrjen evropiane, përparoi në rrugën e Tanzimatit.", "c0877894"]},
"OLAYLAR_EK5:1086-06-04:0":{"b": ["Sulejman b. Kutallmëshi u mund dhe vdiq në Ajnusejlem; Antiokia doli nga selxhukët e Anadollit", "0412dfa1"], "d": ["Sulejman b. Kutallmëshi, që më 1084 ia mori Antiokinë Bizantit, vdiq në betejën e Ajnusejlemit kundër Tutushit, sundimtarit selxhuk të Sirisë; qyteti kaloi nën kontrollin e Melikshahut, sulltanit të selxhukëve të mëdhenj, dhe Jagisijani u emërua vali.", "67de3930"]},
"OLAYLAR_EK5:1092-11-20:0":{"b": ["Vdiq Melikshahu; Antiokia bashkë me Jagisijanin iu lidh Tutushit, selxhukut të Sirisë", "c61da1b4"], "d": ["Pas vdekjes së Melikshahut, sulltanit të selxhukëve të mëdhenj, shteti u nda mes trashëgimtarëve; valiu i Antiokisë, Jagisijani, iu lidh Tutushit, zotit të Sirisë.", "6c441576"]},
"OLAYLAR_EK5:1097-06-19:0":{"b": ["Nikea iu dorëzua kryqtarëve; qendra selxhuke u tërhoq në Konja, Bizanti filloi të rimerrte Anadollin perëndimor", "8a4e90fa"], "d": ["Pas rrethimit të Nikeas nga kryqtarët, qyteti më 19 qershor 1097 iu dorëzua Bizantit; sulltani selxhuk Këlëç Arslani I e tërhoqi qendrën në brendësi, në Konja, ndërsa Bizanti rimori vende si Efesi në brigjet e Anadollit perëndimor.", "c63f0616"]},
"OLAYLAR_EK5:1180-05-28:0":{"b": ["Këlëç Arslani II ia mori Bizantit Dorileumin (Eskishehirin) dhe Kutahjan", "3ddee6c2"], "d": ["Pas Miriokefalonit (1176), kështjellat bizantine të Dorileumit dhe Kutahjas në brendësi të Anadollit, në vitet e fundit të Manuelit/pas vdekjes së tij, më 576/1180 kaluan në duart e Këlëç Arslanit II.", "4358e7d4"]},
"OLAYLAR_EK5:1276-06-15:0":{"b": ["Karamanoglu Mehmet Beu u emërua subash i Ermenekut dhe mori nën administrim Iç Ilin", "6d62be11"], "d": ["Karamanoglu Mehmet Beu në vitin 675 (1276) u emërua subash i Ermenekut dhe vuri nën administrimin e vet Iç Ilin; Ermeneku u bë qendra e parë e Karamanogullëve, që vitin pasues do të marshonin mbi Konja.", "dc2f3a25"]},
"OLAYLAR_EK5:1281-01-01:0":{"b": ["Vdekja e Ertogrul Gaziut dhe kalimi i Osman Beut në krye të bejlikut — trashëgimia e Sëgytit dhe e Domaniçit", "395fb9fa"], "d": ["Sipas TDV-së, Ertogrul Gaziu vdiq në vitin 680 (1281-82); zëri shënon se jepen edhe datat 1288 dhe 1289. Osman Beu nga i ati nuk mori një qytet të pushtuar, por dy caktimet që sulltani selxhuk ia kishte dhënë Ertogrulit, të cilin e kishte vendosur në vijën më të përparuar të zonës kufitare: në Sëgyt një jurt (kullotë dimërore) dhe në Domaniç një verishte (kullotë verore). Pra bejliku e nisi punën jo me një trashëgimi pushtimi, por me dy caktime kullotash; në hartë këto dy vende paraqiten jo si 'pushtim', por si 'trashëgimi'.", "37fbc33c"]},
"OLAYLAR_EK5:1282-03-30:0":{"b": ["Vesprat Siçiliane — dinastia Anzhu humbi ishullin e Siçilisë", "547db635"], "d": ["Kryengritja që shpërtheu në Palermo, të hënën e Pashkëve, në kohën e lutjes së mbrëmjes, kundër sundimit të Karlit I të Anzhuit, e shkëputi ishullin e Siçilisë nga dinastia Anzhu. Mbretëria e Siçilisë u nda në dy pjesë: ishulli u drejtua nga Aragona, kurse dinastia Anzhu u mbajt në mbretërinë kontinentale me qendër Napolin. Edhe zotërimet e jashtme të dinastisë në Adriatik dhe Mesdhe mbetën të lidhura me këtë mbretëri: Korfuzi, në duart e tyre që nga viti 1267, dhe Durrësi, që e mbanin nga vitet 1270, vazhduan si pjesë e Mbretërisë së Napolit; edhe kalatë e Vlorës, Kaninës dhe Himarës në bregun shqiptar mbetën në mbretërinë me qendër Napolin (komandanti i Vlorës, John of Taxis, rezistoi kundër bizantinëve gjatë gjithë vitit 1282; Durrësi, Vlora dhe Kanina me shumë gjasë i kaluan Bizantit në fillim të vitit 1285). Kurse Malta ra në duart e aragonezëve vetëm në vitin 1284.", "7c8ea21d"]},
"OLAYLAR_EK5:1285-01-01:0":{"b": ["Sulmi i befasishëm mbi Kulaxhahisar — operacioni i parë ushtarak i Osman Beut", "79b00b14"], "d": ["Zëri Osman I i TDV-së: 'Ai plaçkiti dhe i vuri zjarrin kalasë së vogël Kulaxha pranë Inegëlit (684/1285).' Ky është veprimi i parë ushtarak i Osman Beut që mund të datohet në burime. Nuk u mor ndonjë vendbanim i përhershëm, kështjella u plaçkit dhe u dogj; prandaj, më shumë se pushtim, është një sulm tipik kufitar. Konsiderohet pikënisja e veprimtarisë ushtarake të bejlikut.", "15ee9a09"]},
"OLAYLAR_EK5:1288-01-01:0":{"b": ["Pushtimi i Karaxhahisarit — fitimi i parë i qytetit dhe sundimi mbi Eskishehir", "178ae619"], "d": ["Zëri Osman I i TDV-së: Osman Beu në vitin 687 (1288) 'duke pushtuar Karaxhahisarin u bë zot i Eskishehirit'. Ky është fitimi i parë i vërtetë i një qyteti nga bejliku dhe, sipas rrëfimit, me këtë sukses Osman Beu u ngrit në gradën e sanxhakbeut në kufi; tregohet se hytbeja e parë e xhumasë në emrin e tij u lexua në Karaxhahisar dhe se aty u emërua kadiu i parë. Zëri i TDV-së për Eskishehirin vëren se tradita osmane jep datën 1291, por saktësia e saj është e dyshimtë.", "90949e22"]},
"OLAYLAR_EK5:1291-05-18:0":{"b": ["Rënia e Akkës te memlukët — dëbimi i kryqtarëve nga bregu i Sirisë: Sidoni dhe Bejruti", "3ca7a464"], "d": ["Akkën, që për një kohë të gjatë ishte qendra e Mbretërisë Kryqtare të Jerusalemit, e pushtoi sulltani memluk al-Ashraf Halil dhe sundimi i kryqtarëve në Palestinë mori fund. Kalorësit templarë të tërhequr nga Akka u strehuan në Sidon; kur u afrua ushtria memluke, ata e lanë kështjellën detare, ikën në Qipro dhe qyteti po atë verë u kaloi memlukëve. Edhe Bejruti, në duart e kryqtarëve që nga viti 1197, në 1291 u mor nga valiu i Damaskut, Sanxhar ash-Shuxhai. Kështu prania kryqtare dyshekullore u fshi nga bregu Siri-Palestinë.", "63b3c40c"]},
"OLAYLAR_EK5:1299-01-01:0":{"b": ["Pushtimi i Bilexhikut dhe i Jarhisarit me sulm nate", "f461b0af"], "d": ["Zëri Bilexhik i TDV-së: 'Edhe pse tekfurët e tjerë të krahinës, midis tyre tekfuri i Bilexhikut, përgatitën një atentat kundër Osman Gaziut, pasi u mor vesh ky komplot, forcat osmane me një sulm të befasishëm pushtuan Jarhisarin dhe Bilexhikun (1299).' Të dyja kalatë u morën në një operacion të vetëm, në të njëjtin sulm nate. Kjo datë është kthesa e pranuar si viti i themelimit të Shtetit Osman. Vende të tjera që u bashkuan në të njëjtën datë: Inegël.", "ec452c9e"]},
"OLAYLAR_EK5:1302-07-27:0":{"b": ["Beteja e Kojunhisarit (Bafeut) — fitorja e parë e madhe kundër ushtrisë bizantine", "584a9512"], "d": ["Zëri Osman I i TDV-së: Osman Beu më 27 korrik 1302 luftoi në Bafe (Kojunhisar) me ushtrinë bizantine dhe e mundi. Kjo fitore është kthesa që e ngriti Osman Beun nga një bej kufitar krahinor në statusin e themeluesit të dinastisë. Pas betejës, fusha e Bursës hyri nën kontrollin osman dhe filloi bllokada e Iznikut.", "b82fb787"]},
"OLAYLAR_EK5:1303-01-01:0":{"b": ["Fitorja e Dimbosit dhe më pas marrja e Kites dhe e Ulubatit", "e168ab64"], "d": ["Zëri Osman I i TDV-së: në vitin 702 (1303), aleanca e krijuar nga tekfurët e Bursës, Kestelit, Kites dhe Adranosit u shpartallua në Grykën e Dimbosit; armiku, duke luftuar, u shty deri në grykën e ngushtë dhe tekfuri i Kestelit vdiq në fushën e betejës. Menjëherë pas fitores u morën kalatë e Kites dhe të Ulubatit, u pre lidhja tokësore e Bursës dhe u shtrëngua bllokada. Në këtë betejë mori pjesë edhe Orhani i ri.", "4afb53bf"]},
"OLAYLAR_EK5:1304-01-01:0":{"b": ["Fushata e Sakarjas: marrja e Leblebixhihisarit, Lefkes, Mekexhes dhe Gejves", "a51ba4d3"], "d": ["Zëri Osman I i TDV-së jep radhën e fushatës së Sakarjas të vitit 704 (1304): 'Kur arriti në kalanë Leblebyxhi, tekfuri u nënshtrua... Arriti në Lefke... Arriti në Mekexhe... Shkoi në Gejve dhe mori kështjellën që e gjeti të braktisur.' Lefkja është porta e luginës së Sakarjas që hapet drejt Bilexhikut. Kjo fushatë e vetme, duke e kaluar nën kontrollin osman vargun e kalave përgjatë luginës, mbylli krahun lindor të pellgut të Iznikut.", "ae2866c2"]},
"OLAYLAR_EK5:1304-01-01:1":{"b": ["Kiosi kaloi nën kontrollin e familjes gjenoveze Zaccaria", "9eebe4de"], "d": ["Përballë kërcënimit të Ajdënogullëve, perandori bizantin i kërkoi ndihmë gjenovezit Benedetto Zaccaria; ishulli kaloi nën kontrollin e tij (vasalitet nominal bizantin). Sundimi i Zaccarias zgjati deri më 1329.", "4d0e4fd8"]},
"OLAYLAR_EK5:1304-01-01:2":{"b": ["Samosi hyri në pronësinë e gjenovezëve (Zaccaria) të Kiosit", "0e6f51e3"], "d": ["Familja gjenoveze Zaccaria, që vuri nën kontroll Kiosin, e bashkoi me pronat e saj edhe Samosin, pothuajse të zbrazur (TDV: 1304-1329).", "8eb44fb2"]},
"OLAYLAR_EK5:1305-01-01:0":{"b": ["Pushtimi i kalave të Grykës së Gejves: Karaçepüsh, Karatigin dhe Absu", "76907c78"], "d": ["Zëri Orhan i TDV-së: Orhani, në fushatën e Sakarjas të vitit 705 (1305), 'pushtoi kalatë Karaçepüsh (Katoikia), Karatigin përpara Iznikut dhe Absu (Hypsu: në Grykën e Gejves)'. Këto tri kala, duke mbyllur kalimin midis luginës së Sakarjas dhe pellgut të Iznikut, ia prenë plotësisht Iznikut ndihmën tokësore. Në Karaçepüsh dhe Absu të grykës së Gejves u vendos Gazi Abdurrahmani; qyteti tashmë mund të rrëzohej vetëm me uri.", "d330595f"]},
"OLAYLAR_EK5:1323-09-01:0":{"b": ["Fushata e Adranosit (Orhaneli) — fushata e fundit e Osman Beut", "4811546c"], "d": ["Zëri Orhan i TDV-së e shënon fushatën e Kalasë së Adranosit në vjeshtën e vitit 1323 si fushatën e fundit të Osman Beut. Tekfuri i Adranosit ishte anëtar i aleancës së tekfurëve të krijuar njëzet vjet më parë në Dimbos kundër Osmanëve; kjo fushatë do të thoshte mbyllje e asaj llogarie. Dita e saktë e pushtimit të kalasë nuk dihet; operacionin e vazhdoi Orhan Beu.", "1e8ea25a"]},
"OLAYLAR_EK5:1324-01-01:0":{"b": ["Vdekja e Osman Gaziut dhe kalimi i Orhan Beut në krye të bejlikut", "021487cd"], "d": ["Osman Gaziu, që i dha emrin bejlikut, vdiq në vitin 724 (1324), siç dëshmojnë vakëfnamet e Asporça Hatunit dhe të Mekexhes. I biri, Orhani, që që nga viti 1305 ishte në krye të ushtrisë në fushata, pas vdekjes së të atit u vendos në krye të bejlikut pa asnjë grindje për fron. Fakti që brezi themelues e dorëzoi flamurin pa tronditje tregon se dinastia e kaloi me qetësi provën e saj të parë të madhe në rrugën nga bejliku kufitar te shteti.", "6f95e64a"]},
"OLAYLAR_EK5:1329-01-01:0":{"b": ["Marrja e Kiosit nga Zaccaria dhe lidhja me Bizantin", "f6741b26"], "d": ["Perandori Androniku III e largoi Zaccarian nga ishulli dhe e lidhi ishullin me Bizantin me Benedetton III si guvernator. Ishulli më 1346 do të pushtohej nga gjenovezi Simone Vignosi.", "84f19c2b"]},
"OLAYLAR_EK5:1329-01-01:1":{"b": ["Samosi u kthye nga Zaccaria te Bizanti (zinxhiri i Kiosit)", "08034974"], "d": ["Me shembjen e senjorisë së Zaccarias (lidhja e Kiosit me Bizantin më 1329) mori fund edhe pronësia gjenoveze në Samos.", "314dce74"]},
"OLAYLAR_EK5:1329-06-01:0":{"b": ["Beteja e Pelekanonit (Maltepe) dhe marrja e gjithë Koxhaelit", "389e7bd4"], "d": ["Zëri Orhan i TDV-së: ditën e parë të betejës Orhan Gaziu, për të tërhequr ushtrinë bizantine, dërgoi një forcë prej treqind vetash; ditën e dytë, me zbritjen në fushë të njësive nën komandën e Pazarlusë, beteja u zgjerua dhe, kur perandori u plagos me shigjetë, në ushtrinë bizantine ra paniku. Përfundimi është i prerë: 'Orhani mori gjithë Koxhaelin; pas fitores, banorëve të Iznikut nuk u mbeti asnjë shpresë.' Qytezat bregdetare nga Hereke deri në Yskydar hynë nën sundimin osman dhe Gebzeja u bë qendra e krahinës. Kjo ishte ushtria e fundit perandorake bizantine që erdhi për të shpëtuar Stambollin.", "73fe4332"]},
"OLAYLAR_EK5:1331-03-03:0":{"b": ["Themelimi i medresesë së parë osmane në Iznik", "c85fb625"], "d": ["Orhan Beu, menjëherë pas marrjes së Iznikut, emëroi aty kadi Çandarli Kara Halilin, shndërroi një bazilikë në xhami dhe, duke ndërtuar pranë saj një imaret dhe një medrese, nisi ndërtimin e qytetit. Sipas zërit Davud Kajseriu të TDV-së, ndërtimi i medresesë përfundoi në vitin 1336 dhe Orhan Gaziu caktoi si myderriz të saj Davud Kajseriun me 30 akçe në ditë. Kjo medrese është hapi i parë institucional i jetës shkencore osmane; bejliku i shtoi fuqisë së pushtimit edhe një traditë dijeje. Shndërrimi i një kryeqyteti bizantin të pushtuar në qendër të dijes islame ishte shenja e parë konkrete e pretendimit osman për t'u bërë shtet i ngulitur.", "4f11a077"]},
"OLAYLAR_EK5:1333-08-01:0":{"b": ["Bizanti bëhet haraçpagues — rrethimi i Izmitit dhe traktati", "0c1ec8d3"], "d": ["Zëri Orhan i TDV-së: Orhani, në verën e vitit 733 (1333), e rrethoi Izmitin me një ushtri të madhe dhe me katapulta, dhe perandori pranoi marrëveshje. Në këmbim të heqjes së rrethimit, Bizanti pranoi t'i paguante Orhanit 12.000 monedha ari (hyperper) në vit; 'kështu, në sytë e emirit osman, Bizanti ra në gjendjen e një vendi haraçpagues'. Në këmbim, Orhani do të bëhej mik i perandorit dhe nuk do të sulmonte qytetet vartëse të Bizantit. Fakti që një bejlik kufitar e lidhi me taksë Romën e Lindjes ishte shpallja se sa ishte përmbysur ekuilibri i forcave.", "e2e3eeb4"]},
"OLAYLAR_EK5:1335-01-01:0":{"b": ["Samotraka kaloi nga venedikasit te familja gjenoveze Gattilusio", "c499ed5f"], "d": ["Venedikasit, që e mbanin ishullin që nga viti 1204, u nxorën nga ishulli nga familja gjenoveze Gattilusio.", "97a996b3"]},
"OLAYLAR_EK5:1345-01-01:0":{"b": ["Aneksimi i Bejlikut të Karesit: Balikesiri, Bergama, Biga, Edremiti dhe Erdeku", "c7cb0511"], "d": ["Zëri Orhan i TDV-së (İnalcık) e vendos aneksimin në vitin 735 (1334-35): me vdekjen e Demirhan Beut, gazitë e Karesit dhe Haxhi Ilbeu e ftuan Dursun Beun në fron dhe i kërkuan ndihmë Orhanit. Orhani marshoi fillimisht mbi Balikesir; kur Dursun Beu, që po shkonte për bisedime paqeje, vdiq nga një shigjetë e hedhur nga kalaja e Bergamës, bejliku iu bashkua tërësisht vendit osman. Në të njëjtin operacion Kirmasti dhe Mihaliçi u nënshtruan, u mor Gëljaza dhe u pushtua përfundimisht Ulubati, i lënë më parë me garanci sigurie. Orhani emëroi Sulejman Pashën në sanxhakun e Karesit dhe e bëri Bigën qendër kufitare — kështu u fitua kuadri detar i kalimit në Rumeli. Shënim: zëri Karesiogllutë i TDV-së për të njëjtën ngjarje jep datën 746 (1345); enciklopedia bie në kundërshtim me veten. Vende të tjera që u bashkuan në të njëjtën datë: Çanakkala.", "f5ed82c2"]},
"OLAYLAR_EK5:1346-06-15:0":{"b": ["Samosi hyri në pronësinë e Maonës së Kiosit", "01628b2f"], "d": ["Me marrjen e Kiosit nga gjenovezi Simone Vignosi dhe lënien e administrimit shoqërisë Maona, edhe Samosi hyri në pronësinë e gjenovezëve të Kiosit (Maona) (TDV: 1346-1475).", "3b122d12"]},
"OLAYLAR_EK5:1352-01-01:0":{"b": ["Kapitulacioni i parë i Orhan Gaziut me gjenovezët", "e64cb196"], "d": ["Orhan Gaziu, që gjatë luftës venedikaso-gjenoveze u mor vesh me gjenovezët, pas betejës së Bosforit në shkurt 1352 dërgoi 1000 harkëtarë për mbrojtjen e Perës dhe dha 60.000 monedha ari për transportin e ushtarëve; në këmbim u dhuroi gjenovezëve kapitulacionin e parë. Teksti i plotë i traktatit nuk ka mbërritur deri në ditët tona. Kjo është marrëveshja e parë zyrtare e Osmanëve me një fuqi detare evropiane dhe do të ripërtërihej tridhjetë e pesë vjet më vonë, në 1387.", "68c60677"]},
"OLAYLAR_EK5:1354-03-02:0":{"b": ["Marrja e Galipolit — krye-urë e përhershme në Rumeli", "ba51a160"], "d": ["Osmanët morën në vitin 1354 Galipolin, rrethinat e të cilit i njohën si aleatë të Kantakuzenit midis viteve 1349-1352; mundësinë e kishte krijuar tërmeti i madh që shembi muret e qytetit. Kështu krye-ura e ngushtë në Çimpe u shndërrua në një bazë të vërtetë në anën rumeliote të Bosforit dhe dera drejt Trakës u hap krejt. Galipoli do të dilte nga duart në vitin 1366 me Kryqëzatën e Savojës, por me pushtimin e dytë të vitit 1376 do të hynte përfundimisht nën sundimin osman. Vende të tjera që u bashkuan në të njëjtën datë: Kilitbahir.", "cac0192e"]},
"OLAYLAR_EK5:1357-09-01:0":{"b": ["Vdekja e Sulejman Pashës, pushtuesit të Rumelisë", "2dc98228"], "d": ["Sulejman Pasha, djali i madh i Orhan Beut dhe arkitekti i pushtimeve të Rumelisë, vdiq duke rënë nga kali gjatë një gjuetie në vjeshtën e vitit 1357, data më e pranuar ndër datat që burimet japin: 758 (1357), 759 dhe 760 (1359). Vdekja e shehzadesë, që me kalimet midis viteve 1352-1354 krijoi praninë e përhershme osmane në Rumeli, ia la radhën e trashëgimtarit të vëllait, Muratit. Tyrbja e Sulejman Pashës, të varrosur në Bolajir, mbeti monumenti më i vjetër dinastik osman në Evropë.", "1f780557"]},
"OLAYLAR_EK5:1361-01-01:0":{"b": ["Ligji i Penxhikut — hedhja e themeleve të Korpusit të Jeniçerëve", "e5877c2d"], "d": ["Pas pushtimeve të Rumelisë, me këshillën e Kara Rustem Karamanliut nga ulemaja, hyri në fuqi sistemi i penxhikut, që parashikonte ndarjen për shtetin të një të pestës së robërve të luftës ose të vlerës së saj në para. Me përgatitjen e të përzgjedhurve nga këta robër pranë familjeve turke dhe marrjen në ushtri u formua bërthama e një force këmbësorie të përhershme, të lidhur drejtpërdrejt me padishahun — Korpusi i Jeniçerëve. Shndërrimi i një bejliku kufitar të mbështetur te kalorësia fisnore në një shtet me ushtri qendrore filloi me këtë rregullim.", "f28873dd"]},
"OLAYLAR_EK5:1363-01-01:0":{"b": ["Zbritja në Trakën Perëndimore: pushtimi i Gjymylxhinës", "9ef69221"], "d": ["Pas marrjes së Edrenesë, forcat kufitare që u drejtuan në perëndim të Maricës, nën komandën e Gazi Evrenos Beut, morën Gjymylxhinën, qendrën e Trakës Perëndimore. Qyteti u bë shtabi i përparuar prej nga Evrenos Beu do t'i shtrinte sulmet në Maqedoni. Kështu pjesa e Trakës që shtrihet deri në bregun e Egjeut hyri nën kontrollin osman dhe u hap rruga e Selanikut.", "0206d2bb"]},
"OLAYLAR_EK5:1369-01-01:0":{"b": ["Varna i kaloi Principatës së Dobruxhës dhe u bë kryeqytet", "2bfe73f9"], "d": ["Në procesin e shpërbërjes së Caratit Bullgar, Varna, në bregun e Detit të Zi, iu bashkua Principatës së Dobruxhës së themeluar nga Dobrotiçi dhe u bë kryeqytet i këtij shteti të vogël.", "5115e7b2"]},
"OLAYLAR_EK5:1373-01-01:0":{"b": ["Në perëndim të Filipopojës: bashkimi i Tatarpazarxhikut dhe i Ihtimanit", "1664d0e1"], "d": ["Pas marrjes së Filipopojës në vitin 1372, Tatarpazarxhiku, në skajin e sipërm të luginës së Maricës, dhe Ihtimani, që zinte qafën që hapet drejt Sofjes, u lidhën me administrimin osman. Kjo vijë, në duart e bejlerëve vendorë të vasalizuar pas Betejës së Çirmenit, u kalua në administrim të drejtpërdrejtë dhe itinerari Filipopojë-Sofje u bë i pandërprerë. Ky përparim është përgatitja e rrugës që dymbëdhjetë vjet më vonë do të çonte në pushtimin e Sofjes.", "0e9acfa0"]},
"OLAYLAR_EK5:1373-05-15:0":{"b": ["Kryengritja e Savxhë Beut — rebelim i përbashkët i shehzadesë dhe princit trashëgimtar bizantin", "75198c33"], "d": ["Savxhë Beu, i biri i Muratit I, dhe Androniku Paleolog, i biri i perandorit bizantin Joan V, në fillim të majit 1373, njëkohësisht në Bursë dhe në Stamboll u ngritën kundër etërve të tyre. Kjo aleancë që bashkonte trashëgimtarët e dy dinastive u shtyp shpejt; Savxhë Beu u kap, iu shuan sytë me hekur të nxehtë dhe u ekzekutua. Data 787 (1385) që rrëfimi osman jep për kryengritjen është e gabuar; ngjarja bie menjëherë pas viteve kur Bizanti hyri në vasalitetin osman dhe tregon sa shumë ishin ndërthurur dy sarajet.", "9776426c"]},
"OLAYLAR_EK5:1374-01-01:0":{"b": ["Luginat e Strumës dhe të Mestës: bashkimi i Qystendilit, Petriçit, Nevrokopit dhe Dramës", "8c0980c4"], "d": ["Luginat e Strumës dhe të Mestës, në duart e bejlerëve vendorë serbë dhe bullgarë që pas fitores së Çirmenit filluan t'u paguanin haraç Osmanëve, me përparimin e bejlerëve kufitarë u morën nën administrimin e drejtpërdrejtë osman. Me bashkimin e Qystendilit, Petriçit, Nevrokopit dhe Dramës u hap gjysma lindore e Maqedonisë dhe Selaniku e Serezi hynë në unazën e rrethimit. Zgjerimi i Rumelisë drejt jugperëndimit në hartë është pasojë e këtij operacioni.", "a50a02ad"]},
"OLAYLAR_EK5:1381-03-28:0":{"b": ["Fundi i Bejlikut të Eretnës dhe themelimi i Shtetit të Kadi Burhanedinit", "60dcaf57"], "d": ["Eretnaogllutë, që lindën nga valiu ilhanid në vitin 1335 dhe për dyzet e gjashtë vjet sunduan Anadollin Qendror me qendra Sivasin dhe Kajserinë, u shpërbënë nga grindjet brenda sarajit. Kadi Burhanedini, që u bë vezir në maj 1378, pasi eliminoi rivalët Këlëçarsllan dhe Haxhi Shadgeldi, në vjeshtën e vitit 1381, duke shpallur sulltanatin e vet, i dha fund bejlikut dhe themeloi shtetin që mban emrin e tij. Kështu ndërroi dorë fqinji lindor i Osmanëve; vija Sivas-Kajseri pas kësaj do të mbetej shtatëmbëdhjetë vjet në duart e Kadi Burhanedinit.", "f5b2be0c"]},
"OLAYLAR_EK5:1381-04-01:0":{"b": ["Timuri mori Heratin: fundi i dinastisë Kert dhe kalimi i Horasanit te timuridët", "15f6019e"], "d": ["Horasani, në vitin 1380, ishte i copëtuar nga lufta midis Sarbedarëve, Kertëve dhe Muzaferidëve. Timuri, pasi e dërgoi të birin, Miran Shahun, në krahinë, vetë marshoi mbi Herat dhe, pas një rrethimi, e mori qytetin nga meliku Kert Gijasedin Pir Aliu. Kryengritja që shpërtheu pas largimit të tij u shtyp me gjak nga Miran Shahu dhe iu dha fund dinastisë Kert, që sundonte në Herat që nga viti 1255. I gjithë Horasani, nga Mashhadi në Nishapur, në këtë datë hyri nën administrimin timurid.", "6ae06d43"]},
"OLAYLAR_EK5:1385-01-01:0":{"b": ["Përparimi në brendësi të Maqedonisë: pushtimi i Manastirit dhe i Ohrit", "63bb7838"], "d": ["Manastiri mbi Via Egnatia dhe Ohri në bregun e liqenit hynë nën administrimin osman gjatë sulmeve në drejtim të Shqipërisë. Të dy ishin pika kyçe të rrugës që shtrihet drejt Adriatikut; Ohri ishte gjithashtu një nga qendrat më të vjetra kryepeshkopale ortodokse të Ballkanit. TDV shënon se për datën e pushtimit të Ohrit nuk ka të dhëna të sakta dhe se janë propozuar datat 787 (1385) dhe 797 (1395), pas vdekjes së Kraliviç Markos; këtu u mor për bazë viti 1385. Manastiri në shekujt pasues do të bëhej një nga qendrat ushtarake më të rëndësishme të Rumelisë.", "e5418654"]},
"OLAYLAR_EK5:1385-09-18:0":{"b": ["Beteja e Savrës — hapja e dyerve të Shqipërisë", "dda6671b"], "d": ["Me kërkesën për ndihmë të beut shqiptar Karlo Topia, i shtrënguar nga dinastia Balsha, forcat osmane shpartalluan në fushën e Savrës ushtrinë e Balshës II; Balsha humbi jetën në fushën e betejës. Kjo betejë, ku hynë me ftesën e një beu vendas, u siguroi Osmanëve për herë të parë ndikim të përhershëm në tokat shqiptare që shtriheshin deri në brigjet e Adriatikut. Kjo politikë, që e shfrytëzonte grindjen midis bejlerëve të krahinës, do të bëhej metoda e pandryshueshme e pushtimeve ballkanike gjatë shekullit pasues.", "05382964"]},
"OLAYLAR_EK5:1386-01-01:0":{"b": ["'Fushata trevjeçare' e Timurit: marrja e Azerbajxhanit dhe e Iranit Verior", "2a98ec51"], "d": ["Timuri, që gjatë fushatave në Horasan pa nga afër gjendjen e shpërndarë të Iranit, në vitin 788 (1386) marshoi drejt perëndimit. Në operacionin 1386-1388, i njohur si 'fushata trevjeçare', përmes Mazanderanit, Lorestanit dhe Gjeorgjisë kaloi në Azerbajxhan dhe arriti në Karabak; Tebrizi, Ardebili, Urmia dhe Nahçevani hynë nën administrimin timurid. Marrja e Iranit Verior dhe e Azerbajxhanit, ashtu si dikur midis ulusit të Xhoxhit dhe ilhanidëve, u bë fillimi i një përplasjeje të gjatë me Hordhinë e Artë.", "aaf3b558"]},
"OLAYLAR_EK5:1386-06-01:0":{"b": ["Beteja e Frenkjazësë dhe rrethimi i Konjës — fushata e parë kundër Karamanit", "af4e5d77"], "d": ["Kundër Karamanogllu Alaedin Ali Beut, i cili, ndonëse ishte dhëndri i tij, ishte i shqetësuar nga zgjerimi osman në Anadollin Perëndimor, Murati I doli vetë në fushatë; në betejën e zhvilluar në vendin e quajtur Frenk Jazësi, ushtria osmane e stërvitur dhe me përvojë i mundi forcat e Karamanit. Më pas u rrethua kalaja e Konjës, por me faljen e Alaedin Beut bejliku nuk u zhduk plotësisht. Kjo fushatë është akti hapës i llogarive të gjata midis Osmanëve dhe Karamanit, që do të zgjaste një shekull dhe do të përfundonte vetëm me aneksimin përfundimtar në 1468.", "087a605a"]},
"OLAYLAR_EK5:1387-01-22:0":{"b": ["Mushi kaloi nga administrimi karakojunlu nën administrimin e Timurit (789/1387)", "ed2e7a11"], "d": ["Mushi, që pas periudhës mongole kaloi nën administrimin karakojunlu, në vitin 789 (1387) hyri nën administrimin e Timurit, i cili zotëroi tokat karakojunlu. Në atlas, Mushi në këtë vit shënohet si kalim nga karakojunlutë te timuridët.", "9475520a"]},
"OLAYLAR_EK5:1390-06-01:0":{"b": ["Themelimi i Arsenalit të Galipolit — lindja e flotës osmane", "47546241"], "d": ["Arsenali i parë i organizuar i Shtetit Osman u themelua në vitin 1390 nga Bajazidi Jëlldërëm në Galipoli, në vendin e arsenalit të mbetur nga Bizanti. Osmanët, që trashëguan trashëgiminë detare të bejliqeve të Anadollit Perëndimor, kështu për herë të parë u bënë një fuqi detare që ndërtonte vetë anijet e veta. Arsenali, i vendosur në pikën kyçe të Ngushticës së Dardaneleve, nga rrethimi i Stambollit deri te fushatat në Egje, për një shekull e gjysmë shërbeu si baza kryesore e flotës osmane.", "f214717c"]},
"OLAYLAR_EK5:1391-01-01:0":{"b": ["Vendi i Hamidit iu bashkua Osmanëve: Isparta, Burduri, Uluborlu, Egirdiri", "e3da7de5"], "d": ["Bajazidi Jëlldërëm, që doli në fushatë pas sulmit të Karamanogllu Alaedin Beut në vendin e Hamidit dhe ankesave të popullit, mori të gjitha tokat e mbetura të Hamidogllutëve dhe administrimin ia dha të birit, Isa Çelebiut.", "8a997ead"]},
"OLAYLAR_EK5:1393-01-01:0":{"b": ["Fundi i dinastisë muzaferide: disfata e Shah Mansurit përpara Shirazit", "5fd14eb8"], "d": ["Shah Mansuri, sundimtari i fundit i fuqishëm i muzaferidëve, që sundonin në Jazd, Fars, Isfahan dhe Kerman nga viti 1318, u bashkua me të afërmit dhe u ngrit kundër Timurit. Në betejën pranë Shirazit, kur njëri nga emirët e tij kaloi në anën tjetër, ai humbi pjesën më të madhe të forcave, u mund dhe u vra. Kur Timuri më pas urdhëroi të vriteshin edhe të gjithë anëtarët e dinastisë, sundimi muzaferid mori fund dhe Farsi me Kermanin iu bashkuan administrimit timurid.", "8e89c2dc"]},
"OLAYLAR_EK5:1393-06-01:0":{"b": ["Bashkimi i Amasjas me tokat osmane", "fe2860cf"], "d": ["Emiri i Amasjas, i rrethuar gjatë operacionit të Bajazidit Jëlldërëm në Anadollin Qendror, ua dorëzoi qytetin Osmanëve dhe Bajazidi hyri në qytet në vitin 1393. Sulltani ia la administrimin këtij vendi të birit, Mehmet Çelebiut; Amasja si sanxhak shehzadesh pas kësaj u bë një nga vatrat më të rëndësishme të edukimit të dinastisë osmane. Vendbanime të tjera që u humbën në të njëjtën datë: Ladik (Amasja), Merzifon, Osmanxhik, Çorum. Kjo zgjedhje do të ishte vendimtare në Periudhën e ardhshme të Interregnumit, kur Mehmet Çelebiu do ta zhvillonte pikërisht nga kjo bazë e Amasjas luftën për ribashkimin e shtetit.", "bc5eb00d"]},
"OLAYLAR_EK5:1393-08-29:0":{"b": ["Timuri pushtoi Bagdadin — xhelairidët ikën në Anadoll", "4d5602b3"], "d": ["Timuri, pas një rrethimi të gjatë, mori Bagdadin; sundimtari i qytetit, sulltan Ahmed Xhelairi, duke ikur drejt perëndimit, u strehua fillimisht te memlukët e pastaj në sarajin osman. Kështu zgjerimi i Timurit drejt perëndimit për herë të parë ra drejtpërdrejt në kontakt me zonën e ndikimit osman. Hallka e parë e armiqësisë midis dy sundimtarëve fillon këtu.", "2fac674f"]},
"OLAYLAR_EK5:1393-09-01:0":{"b": ["Marrja e Varnës në bregun e Detit të Zi", "a84b2abf"], "d": ["Gjatë shtrëngimit të tokave të Caratit Bullgar midis Danubit dhe Detit të Zi, Varna, porti më i madh i bregdetit, kaloi nën administrimin osman. Marrja e portit i hapi rrugën përparimit drejt Dobruxhës dhe u siguroi Osmanëve skelën e parë të madhe në bregun perëndimor të Detit të Zi. Varna, pesëdhjetë e një vjet më vonë, do të ishte edhe skena e fitores së vitit 1444, ku do të asgjësohej ushtria kryqtare.", "2e425501"]},
"OLAYLAR_EK5:1398-01-01:0":{"b": ["Viset e Nevshehirit dhe Ürgüpit kaluan nga Karamanogullët në duart osmane", "06ff59e8"], "d": ["Gjatë fushatave të Bajazitit Rrufe (Yıldırım) kundër Karamanogullëve, viset e Nevshehirit (Muşkara) dhe Ürgüpit më 800/1398 kaluan nën administrimin osman; pas Betejës së Ankarasë më 1402, Timuri ua ktheu zonën Karamanogullëve.", "5faa82e5"]},
"OLAYLAR_EK5:1398-07-15:0":{"b": ["Rënia e Shtetit të Kadi Burhanedinit", "b13391e3"], "d": ["Kadi Burhanedini, i zënë rob nga sundimtari akkojunlu Karajylyk Osman Beu, megjithëse propozoi të lirohej në këmbim të dorëzimit të Sivasit, populli i qytetit rezistoi dhe sulltani u ekzekutua përpara mureve. Parësia e Sivasit vuri në krye të birin, Alaedin Ali Çelebiun, por, përballë presionit akkojunlu, i kërkuan ndihmë Bajazidit Jëlldërëm; forcat osmane nën komandën e Sulejman Çelebiut e mundën Karajylykun dhe u bënë zot të qytetit. Kështu Shteti i Kadi Burhanedinit hyri në histori, dhe Sivasi, Tokati, Niksari dhe Kajseria iu bashkuan tokave osmane. Vende të tjera që u bashkuan në të njëjtën datë: Kërshehir, Çorum.", "2a0c7f3a"]},
"OLAYLAR_EK5:1399-11-01:0":{"b": ["Përballja me Timurin: u refuzua dorëzimi i të arratisurve", "33790bc8"], "d": ["Me presionin e Timurit, sulltan Ahmed Xhelairi dhe udhëheqësi i karakojunlive, Kara Jusufi, u strehuan në tokat osmane; Timuri kërkoi dorëzimin e këtyre dy të arratisurve, Bajazidi Jëlldërëm refuzoi. Pas kësaj midis dy sundimtarëve filluan të shkëmbeheshin letra me fyerje të rënda reciproke. Terreni ideologjik i luftës u ndërtua me këtë korrespondencë, para se të lëvizte qoftë edhe një ushtar i vetëm.", "ac66be59"]},
"OLAYLAR_EK5:1400-01-01:0":{"b": ["Spitali i Jëlldërëmit në Bursë — spitali i parë osman", "5f0dc59a"], "d": ["Bajazidi Jëlldërëm, në vitet kur ndërtonte në Bursë Xhaminë e mrekullueshme Ulu, i dhuroi qytetit edhe një darushifa (spital); ishte hallka e programit të gjerë të bamirësisë, të përbërë nga imareti, medreseja, hani dhe ura, që i kushtohej mjekësisë. Ky ndërtim, spitali i parë i ngritur nga shteti, duke luajtur edhe rolin e shkollës mjekësore që përgatiste mjekë, përcaktoi modelin e institucioneve shëndetësore osmane. Vepra, e përfunduar vetëm dy vjet para katastrofës së Ankarasë, është ndër hallkat e fundit të vizionit të Jëlldërëmit për ta shndërruar Bursën në kryeqytet perandorak.", "5765ebac"]},
"OLAYLAR_EK5:1400-08-01:0":{"b": ["Timuri e rrafshoi Sivasin", "f4d79de6"], "d": ["Timuri, që marshoi mbi Sivas me udhërrëfimin e akkojunlut Karajylyk Osman Beu dhe të emirit të Erzinxhanit, Mutahhartenit, e rrethoi qytetin tetëmbëdhjetë ditë dhe, pasi e mori me premtimin se nuk do të derdhej gjaku i askujt, bëri një masakër të madhe; mbrojtësit i hodhi në hendeqe dhe urdhëroi t'i mbulonin të gjallë. U shkatërruan veprat e rëndësishme të qytetit, në radhë të parë muret, dhe Sivasi u shemb demografikisht. Kjo është goditja e parë e madhe që Timuri u dha tokave osmane dy vjet para Betejës së Ankarasë.", "8ddb3e3a"]},
"OLAYLAR_EK5:1401-02-01:0":{"b": ["Bajazidi Jëlldërëm rimori Erzinxhanin dhe Kemahun", "7047ca08"], "d": ["Bajazidi Jëlldërëm, duke përfituar nga dalja e Timurit në fushatën e Sirisë, ia mori emirit të Erzinxhanit, Mutahhartenit, vartës i Timurit, Erzinxhanin dhe Kemahun. Megjithëse nuk kishte ndërhyrë në shkatërrimin e Sivasit, ky veprim ishte një sfidë e drejtpërdrejtë ndaj zonës së ndikimit të Timurit në Anadollin Lindor. Pas kësaj marrëdhëniet midis dy sundimtarëve u bënë të pariparueshme.", "2160d645"]},
"OLAYLAR_EK5:1402-03-13:0":{"b": ["Ultimatumi i Timurit nga Tebrizi — katër kushte", "3e1ac50e"], "d": ["Timuri, me ambasadorin që dërgoi nga Tebrizi, njoftoi katër kushte: kthimin e Kemahut te Mutahharteni, kthimin pronarëve të tokave të marra nga bejlerët e Anadollit, dërgimin e një shehzadeje osman si peng dhe pranimin e kësulës dhe brezit si shenjë vartësie, si dhe dorëzimin e Kara Jusufit. Bajazidi nuk pranoi asnjërin prej tyre; megjithë këmbënguljen e burrështetasve dhe ndërmjetësimin e Mutahhartenit, bisedimet dështuan. Timuri ishte i vendosur ta mbyllte përfundimisht çështjen e Anadollit para se të dilte në fushatën kundër Kinës.", "bd475bc3"]},
"OLAYLAR_EK5:1402-08-17:0":{"b": ["Saruhanogllutë u rikrijuan — Manisa doli nga Osmanët", "ac747b05"], "d": ["Tri javë pas disfatës së Ankarasë, me mbështetjen e Timurit, Orhan Beu kaloi në krye të bejlikut dhe vendi i Saruhanit u bë përsëri i pavarur. Krahina me qendër Manisën, dymbëdhjetë vjet pas aneksimit osman të vitit 1390, doli nga harta. Kjo është një nga zbatimet e para me datë të njohur saktësisht të politikës së Timurit për ringjalljen e bejliqeve.", "9fe5744d"]},
"OLAYLAR_EK5:1402-08-20:0":{"b": ["Emir Sulejmani iku në Rumeli me thesarin shtetëror", "0a2b7363"], "d": ["Emir Sulejmani, duke marrë me vete thesarin shtetëror në Bursë, arkivat, familjen dhe vëllezërit, nga Gemliku me anije kaloi në Güzelcehisar (Anadoluhisari), prej andej arriti në Galipoli dhe në Edrene shpalli sundimin e vet. Zhvendosja në Rumeli e arkivit dhe e thesarit shtetëror është fillimi i kalimit, për një brez, të qendrës së rëndesës osmane në Ballkan. Në hartë Rumelia që nga kjo datë vizatohet me ngjyrën e vetë Emir Sulejmanit.", "393aa053"]},
"OLAYLAR_EK5:1402-09-15:0":{"b": ["Timuri i rikrijoi bejliqet e Anadollit — bashkimi turk u shpërbë", "15187774"], "d": ["Timuri, pas fitores së Ankarasë, ua ktheu tokat e dikurshme bejlerëve që kishte pranë. Karamanogllu Mehmed Beut dhe Ali Beut u dha vendi i Karamanit me Kajserinë, Kërshehirin, Sivrihisarin dhe Bejshehirin; Germijanogllu Jakub Beut II iu dha Kytahja dhe vendi i Germijanit; Xhandarogllu Isfendijar Beut, përveç vijës Kastamonu-Sinop, iu dhanë Çankëri dhe Kalexhiku. Edhe vendet e Ajdënit, Mentesheut dhe Tekesë u kthyen te dinastitë e dikurshme. Bashkimi turk i Anadollit, që Bajazidi Jëlldërëm e kishte ndërtuar për dhjetë vjet, u shpërbë brenda një vere; në hartë këto bejliqe shfaqen përsëri me ngjyrat e veta. Vendbanime të tjera që ndërruan dorë në të njëjtin proces: Aksaraj, Denizli, Eregli (Konja), Ermenek, Ilgën, Karapënar, Kajseri, Konja, Kërshehir, Kytahja, Sivrihisar, Sëke.", "0c3d6fbf"]},
"OLAYLAR_EK5:1402-12-14:0":{"b": ["Timuri ua mori Izmirin kalorësve të Shën Gjonit", "66dd1dd4"], "d": ["Timuri, që zbriti drejt perëndimit përmes Kytahjas, Denizlisë, Ajdënit, Ajasolukut dhe Tires, e rrethoi dhe e mori Izmirin bregdetar, në duart e të krishterëve që nga viti 1344. Duke e pushtuar brenda një kohe të shkurtër këtë kala që Bajazidi Jëlldërëm nuk kishte mundur ta merrte për vite, Timuri, pasi mori edhe kalatë përreth, ua la vendin e Ajdënit zotërve të dikurshëm dhe u kthye në lindje. Qyteti pas kësaj hyri nën administrimin e Ajdënogllu Xhunejd Beut.", "b6c372a5"]},
"OLAYLAR_EK5:1402-12-20:0":{"b": ["Isa Çelebiu mori Bursën — lindi pjesa e Anadollit", "955128c1"], "d": ["Isa Çelebiu, që pas disfatës së Ankarasë ishte tërhequr në anët e Karesit, mori Bursën ndërsa Timuri ishte në Izmir. Në kryeqytetin e dikurshëm, të plaçkitur e të djegur nga ushtarët e Timurit, shpalli sundimin e vet dhe urdhëroi të pritej monedhë në emrin e tij; në janar 1403 njihej në Anadoll me titullin 'sundimtari i turqve'. Në hartë kjo pjesë, që shtrihet përgjatë bregut aziatik të Marmarasë, duket me ngjyrën e vetë Isa Çelebiut.", "fdd5eed3"]},
"OLAYLAR_EK5:1403-03-15:0":{"b": ["Tërheqja e Timurit nga Anadolli", "93a98839"], "d": ["Timuri, që mori lajmin e vdekjes së Bajazidit Jëlldërëm në Akshehir, duke e konsideruar të përfunduar punën në Anadoll, u drejtua nga lindja. Pas tij mbetën bejliqet që i shprehën besnikëri dhe shehzadetë osmanë të përçarë; disa qytete si Sivasi iu lanë emirëve vartës të Timurit si Mezid Beu. Timuri nuk u kthye më në Anadoll, por ky rend i copëtuar që krijoi zgjati dhjetë vjet.", "646cb1bc"]},
"OLAYLAR_EK5:1404-03-01:0":{"b": ["Emir Sulejmani kaloi në Anadoll: Bursa i ra në dorë", "9b27aa5f"], "d": ["Emir Sulejmani, që mori vesh disfatën e Isa Çelebiut, së bashku me Çandarli Ali Pashën kaloi në Anadoll me një ushtri të fortë dhe mori Bursën; regjistrimet e marsit 1404 tregojnë se edhe Eregli i Detit të Zi ishte nën administrimin e tij. Mehmet Çelebiu nuk mundi t'i rezistonte Sulejmanit, i cili brenda pak kohe u bë zot si i Rumelisë, ashtu dhe i pjesës më të madhe të Anadollit. Vendbanime të tjera që në të njëjtin proces kaluan nga Mehmet Çelebiu te Emir Sulejmani: Akjazë, Anadolu Hisari, Absu (Hypsu), Adranos (Orhaneli), Akhisar (Pamukova), Armutlu, Kalaja e Ajdosit, Ajvalëk, Balëkesir, Behramkale (Assos), Bergama, Bejkoz, Biga. Në hartë që nga kjo datë deri në rimarrjen e Bursës nga Mehmet Çelebiu (1410) të dy brigjet duken me një ngjyrë, në pjesën e Emir Sulejmanit.", "0fc7e1b4"]},
"OLAYLAR_EK5:1405-01-01:0":{"b": ["Beteja e fushës së Jenishehirit — Mehmet Çelebiu u tërhoq në Amasja", "f1568288"], "d": ["Mehmet Çelebiu, që humbi Bursën dhe Ankaranë, u mund nga Emir Sulejmani në fushën e Jenishehirit, humbi të gjitha fitimet në Anadollin Perëndimor dhe u tërhoq në bazën Tokat-Amasja. Pas kësaj disfate, duke shmangur përplasjen e drejtpërdrejtë, u përqendrua në forcimin e autoritetit të vet në brendësi të Anadollit. Kështu filloi faza më e gjatë e heshtur e Interregnumit.", "8c8a3c8c"]},
"OLAYLAR_EK5:1406-01-01:0":{"b": ["Emir Sulejmani ia mori Ankaranë Mehmet Çelebiut", "d6a2acd6"], "d": ["Ankaranë, që pas tërheqjes së Timurit nga Anadolli kishte mbetur në duart e Mehmet Çelebiut, e rrethoi Emir Sulejmani në vitin 1406. Komandanti i kalasë, Jakub Beu, qëndroi për ca kohë, por me një dredhi të vezirit të madh Çandarli Ali Pashës ia dorëzoi kalanë Sulejmanit. Pas kësaj Mehmet Çelebiu u mor vesh me Karamanogllu Mehmed Beun dhe veproi kundër Sulejmanit.", "f2a18bf9"]},
"OLAYLAR_EK5:1408-06-01:0":{"b": ["Mehmet Çelebiu ia rimori Sivasin timuridit Mezid Beu", "90079b0c"], "d": ["Pas pushtimit timurid, administrimi i Sivasit i ishte lënë Mezid Beut, vartës i Timurit. Mehmet Çelebiu, në Amasja, dërgoi komandantin e vet, Bajazid Pashën, për ta marrë qytetin dhe, pas një rezistence të ashpër, Sivasi për herë të dytë kaloi në duart e dinastisë osmane. Kështu pjesa e Mehmetit, gjashtë vjet pas Betejës së Ankarasë, arriti në lindje kufirin e dikurshëm.", "22c266b9"]},
"OLAYLAR_EK5:1409-01-01:0":{"b": ["Fundi i dinastisë Artukide: dorëzimi i Mardinit te karakojunlitë", "15b06f33"], "d": ["Artukidët, dega më jetëgjatë e dinastisë që sundonte në Mardin që nga viti 1106, nuk mundën të qëndronin përballë presionit akkojunlu. Melik Ahmedi, që kuptoi se nuk mund ta mbronte qytetin, u mor vesh me sundimtarin karakojunlu, Kara Jusufin, dhe ia dorëzoi Mardinin. Kështu mori fund sundimi artukid që kishte zgjatur mbi tre shekuj; Mardini me rrethinat, deri sa kaloi te Osmanët një shekull më vonë, u bë skenë e luftës midis karakojunlive dhe akkojunlive.", "52e31654"]},
"OLAYLAR_EK5:1410-02-13:0":{"b": ["Beteja e Jambollit — Musa Çelebiu hyri në Edrene", "8f978408"], "d": ["Musa Çelebiu, që përmes Vllahisë kaloi në Rumeli, me mbështetjen vllahe dhe serbe i shpartalloi në Jamboll forcat e Emir Sulejmanit dhe hyri në Edrene. Gjatë Interregnumit Rumelia doli për herë të parë nga duart e Emir Sulejmanit. Por sundimi i tij nuk qe i qëndrueshëm; katër muaj më vonë, i mundur në Kosmidion, do të tërhiqej në brendësi të Ballkanit.", "e80e7126"]},
"OLAYLAR_EK5:1412-10-01:0":{"b": ["Beteja e Inxhegizit — disfata e parë e Mehmet Çelebiut në Rumeli", "3c35cd43"], "d": ["Mehmet Çelebiu, që me anijet e Bizantit kaloi në Rumeli, hyri në betejë me Musa Çelebiun në Inxhegiz; Musa, me shtatë mijë jeniçerë nën urdhrat e vet, e mundi Mehmetin dhe Mehmeti u detyrua të kthehej në Anadoll. Kjo disfatë e shtyu Mehmetin, në vend të luftës së drejtpërdrejtë, drejt strategjisë së tërheqjes në anën e vet të bejlerëve kufitarë të Rumelisë dhe të despotatit serb. Terreni i fitores së Çamurlusë, nëntë muaj më vonë, u përgatit me këtë diplomaci.", "dd443a98"]},
"OLAYLAR_EK5:1415-03-01:0":{"b": ["Rrethimi i Konjës dhe marrëveshja me Karamanogllutë — u rimorën vendi i Hamidit, Said-ili, Bejshehiri, Sejdishehiri dhe Akshehiri", "0996257e"], "d": ["Kundër Karamanogllutëve, që gjatë Interregnumit sulmonin tokat osmane dhe rrethuan e dogjën Bursën, Mehmet Çelebiu organizoi një fushatë të madhe dhe në muharrem 818 rrethoi Konjën. Karamanogllu Mehmed Beu II u detyrua të kërkonte paqe; si rezultat i marrëveshjes, vendi i Hamidit (krahina e Ispartës) dhe Said-ili iu bashkuan përsëri tokave osmane, u kthyen edhe Bejshehiri, Sejdishehiri dhe Akshehiri; edhe Sivrihisari, që Timuri ua kishte dhënë Karamanogllutëve në vitin 1402, iu kthye Osmanëve. Kjo fushatë, me të cilën filloi të arnohej bashkimi i Anadollit i shpërbërë nga Beteja e Ankarasë, është nga arsyet konkrete pse Mehmet Çelebiu konsiderohet 'themeluesi i dytë'.", "952c9f73"]},
"OLAYLAR_EK5:1415-06-01:0":{"b": ["Marrja e Izmirit nga Ajdënogllu Xhunejd Beu", "2377ca51"], "d": ["Izmiri, qendra e Ajdënogllu Xhunejd Beut, që gjatë Interregnumit ndërronte vazhdimisht anë midis shehzadeve, pas një rrethimi dhjetëditor u mor nga Mehmet Çelebiu; Xhunejdi u fal dhe u dërgua sanxhakbej në Nikopojë. Kështu qyteti, që Timuri në vitin 1402 ua kishte kthyer Ajdënogllutëve, pas trembëdhjetë vjetësh iu kthye Osmanëve. Xhunejdi do ta rimerrte qytetin në vitin 1422, dhe çështja do të mbyllej vetëm në vitet 1424-1426 nga Murati II.", "41fefe61"]},
"OLAYLAR_EK5:1416-01-01:0":{"b": ["Ekzekutimi i Torllak Kemalit — Saruhani përfundimisht osman", "8a09dbf1"], "d": ["Torllak Kemali, që drejtonte krahun e Anadollit Perëndimor të lëvizjes së Shejh Bedredinit, u mund në krahinën e Manisës dhe u ekzekutua. Pas kësaj date krahina e Saruhanit hyri përfundimisht nën kontrollin osman dhe bejliku që Timuri e kishte ringjallur në vitin 1402 hyri në histori. Kështu u pastruan mbetjet e fundit politike të Interregnumit në Anadollin Perëndimor.", "43bec619"]},
"OLAYLAR_EK5:1417-01-01:0":{"b": ["Pushtimi i Vlorës, Beratit dhe Kaninës", "1e1949b8"], "d": ["Osmanët në vitin 1417 vunë nën sundim Vlorën në bregun e Adriatikut, së bashku me qytetin e Beratit në brendësi të vendit dhe Kalanë e Kaninës. Një vit më vonë përpjekja e Venedikut për ta rimarrë qytetin dështoi dhe duke u krijuar këtu një organizim sanxhaku, autoriteti osman u bë i përhershëm. Marrja e Vlorës, duke i bërë Osmanët për herë të parë zotër të drejtpërdrejtë të një porti në Adriatik, u dha një trampolinë përtej detit kundrejt Italisë.", "508b9927"]},
"OLAYLAR_EK5:1419-01-01:0":{"b": ["Rimarrja e Anadollit Qendror: Kajseri dhe Kërshehir", "204eacb3"], "d": ["Qytetet e Anadollit Qendror, që gjatë Interregnumit kishin rënë në duart e Karamanogllutëve, gjatë fushatave të Mehmet Çelebiut për të rimëkëmbur shtetin u kthyen nën administrimin osman. Me bashkimin e Kajserisë dhe të Kërshehirit u rimor në masë të madhe pellgu i lumit Këzëlërmak, i humbur në Betejën e Ankarasë. Ky përparim është vazhdimi i politikës së drejtimit nga lindja, që filloi katër vjet më parë me rrethimin e Konjës.", "c663fc08"]},
"OLAYLAR_EK5:1419-01-28:0":{"b": ["Memlukët ia dhanë Kajserinë Nasirudin Muhamedit nga Dulkadirogllutë", "aad4b00c"], "d": ["Ushtria memluke që doli në fushatë kundër Karamanogllu Mehmed Beut pushtoi Kajserinë; komandanti memluk, duke ia lënë qytetin me rrethina Nasirudin Muhamedit të Dulkadirëve, u kthye në vendin e vet.", "8cd84dc4"]},
"OLAYLAR_EK5:1421-06-25:0":{"b": ["Vdekja e Mehmetit I dhe hipja në fron e Muratit II", "98acac77"], "d": ["Mehmeti I, që i dha fund Periudhës së Interregnumit dhe e bashkoi përsëri vendin osman në një dorë, vdiq në Edrene më 25 qershor 1421 dhe i biri Murati hipi në fron në Bursë. Sipas marrëveshjes së bërë me Bizantin para vdekjes, djemtë e tij të vegjël do të dërgoheshin si pengje pranë perandorit, kurse perandori nuk do ta lironte pretendentin për fron Mustafa Çelebi që e mbante në dorë; Murati II refuzoi t'i dërgonte vëllezërit te perandori.", "c8093fa8"]},
"OLAYLAR_EK5:1423-01-01:0":{"b": ["Likuidimi përfundimtar i Tekeogllutëve: marrja e Antalisë", "e65565b2"], "d": ["Bejliku i Tekeogllutëve, i rikrijuar pas Betejës së Ankarasë me ringjalljen nga Timuri, mori fund me rrethimin e Antalisë nga forcat osmane nën komandën e Hamza Beut; njeriu i fundit i rëndësishëm i bejlikut, Osman Çelebiu, u eliminua. Kështu vendi i Tekesë në bregun e Mesdheut, pas njëzet e një vjet ndarjeje, iu bashkua përfundimisht Osmanëve. Bejliku sundonte në Antalia që nga viti 1321 si degë e shkëputur nga Hamidogllutë.", "6b81398d"]},
"OLAYLAR_EK5:1423-05-01:0":{"b": ["Fushata e Turahan Beut në More dhe shembja e murit Hexamilion", "c6c2706d"], "d": ["Për shkak të mbështetjes bizantine për pretendentin rival të fronit, Mustafa Çelebiun, Murati II dërgoi Turahan Beun kundër Moresë. Turahan Beu e shembi murin Hexamilion, që mbyllte nga një skaj në tjetrin Istmin e Korintit, hyri në gadishull dhe shkaktoi shkatërrime të mëdha. Paqja u arrit me kushtin që muri të mos ndërtohej më dhe të paguhej taksë vjetore; kështu despotati i Moresë u la ushtarakisht i pambrojtur dhe terreni i pushtimit përfundimtar të vitit 1460 u përgatit tridhjetë e shtatë vjet më parë.", "3482eb23"]},
"OLAYLAR_EK5:1424-01-01:0":{"b": ["Hyrja e manastireve të Athosit (Aynaroz) nën mbrojtjen osmane", "562de5ea"], "d": ["Në vitet kur Selaniku ishte nën rrethim, republika monastike e Athosit, në gishtin lindor të Kalkidikisë, iu drejtua Muratit II, kërkoi mbrojtje dhe pranoi sovranitetin osman. Të drejtat e pronësisë dhe të adhurimit të murgjve u garantuan; manastiret, në këmbim të taksës, u lanë të lira në punët e brendshme. Ky rend u bë shembulli më jetëgjatë i marrëdhënies së mbrojtjes që Osmanët krijuan me institucionet ortodokse dhe zgjati pesë shekuj.", "6be1a9f2"]},
"OLAYLAR_EK5:1427-01-01:0":{"b": ["Aneksimi i Bejlikut të Taxheddinogllutëve: Niksari", "370ffd47"], "d": ["Me presionin e bejlerbeut të Amasjas, Jorgyç Pashës, Taxheddinogllu Husamedin Hasan Beu në vitin 830 (1427) dorëzoi çelësat e vendit të tij me qendër Niksarin; atij iu dha një sanxhak në Rumeli. Kështu mori fund bejliku i themeluar në gjysmën e dytë të shekullit XIV, kufijtë e të cilit herë-herë shtriheshin deri në Kelkit, Amasja, Samsun, Ordu dhe Giresun. Po atë vit u regjistruan edhe tokat e Haxhiemirogllutëve dhe u lidhën me sanxhakun e Xhanikut; u mbyll periudha e bejliqeve në Detin e Zi Qendror.", "06fa8222"]},
"OLAYLAR_EK5:1427-01-01:1":{"b": ["Lënia e Beogradit Hungarisë — Traktati i Tatës", "62481183"], "d": ["Pas vdekjes së despotit serb Stefan Lazarević, sipas Traktatit të Tatës, të lidhur mes mbretit hungarez Sigismund dhe trashëgimtarit Gjergj (Georg) Brankoviq, kështjella e Beogradit iu dorëzua Hungarisë. Kështjella, në pikën ku bashkohen Danubi dhe Sava, deri atëherë ishte në duart e despotatit serb dhe për osmanët ishte kyçi i derës që hapej drejt Evropës Qendrore. Ky dorëzim e bëri Beogradin për njëqind vjet pengesën më të fortë përpara përparimit osman: rrethimet e viteve 1440 dhe 1456 do të dështonin, dhe kështjella do të binte vetëm më 1521.", "ee1ad2d8"]},
"OLAYLAR_EK5:1432-01-01:0":{"b": ["Mardini kaloi nga rojtari karakojunlu te akkojunlu Karajylyk Osman Beu", "d82bc97f"], "d": ["Mardinin, që Kara Jusufi e mori në vitin 1409, karakojunlitë e qeverisën me valinj; emiri Nasir, i lënë si rojtar, ia dorëzoi qytetin në vitin 835 (1432) akkojunlu Karajylyk Osman Beut. Administrimi akkojunlu vazhdoi deri në fillim të shekullit XVI.", "407382cb"]},
"OLAYLAR_EK5:1435-01-01:0":{"b": ["Karamanogllutë ua morën Kajserinë Dulkadirëve", "2b09e8e8"], "d": ["Beu i Karamanit, me fitoren që korri kundër Dulkadirëve, i shtoi vendit të vet Kajserinë, Urgypin, Karahisarin e Develisë dhe Uçhisarin.", "39a543cc"]},
"OLAYLAR_EK5:1446-05-05:0":{"b": ["Ngjarja e Buçuktepes — kryengritja e parë e jeniçerëve dhe rikthimi në fron i Muratit II", "6388dda1"], "d": ["Ngjarja e Buçuktepes, që shpërtheu në Edrene dhe është kryengritja e parë e jeniçerëve që njeh historia, filloi me kërkesën për rritjen e rrogave me gjysmë akçeje dhe përfundoi me rrëzimin nga froni të Mehmetit II të ri. Murati II, më 8 safer 850, u nis me ngut nga Manisa dhe nisi sundimin e dytë. Ngjarja ishte shenja e parë se korpusi kapikulu ishte bërë tashmë një forcë me zë mbi fronin dhe i dha formë kujdesit që Fatihu do ta ruante gjithë jetën ndaj jeniçerëve.", "c03ef4f8"]},
"OLAYLAR_EK5:1449-01-01:0":{"b": ["Bashkimi i bregut të Epirit: Arta dhe Preveza", "796f7ecf"], "d": ["Nëntëmbëdhjetë vjet pas dorëzimit të Janinës në vitin 1430, edhe Arta dhe Preveza, në pjesën bregdetare të Despotatit të Epirit, hynë nën administrimin osman. Kështu u vu nën kontroll gjiri i Ambrakisë që hapet në Detin Jon dhe u plotësua lidhja detare e Janinës. Preveza është pika kyçe e gjirit që nëntëdhjetë vjet më vonë do t'i jepte emrin fitores historike të Barbarosës.", "b5e95ae5"]},
"OLAYLAR_EK5:1451-02-18:0":{"b": ["Vdekja e Muratit II dhe hipja e dytë në fron e Mehmetit II", "8f8256ad"], "d": ["Murati II, që u sëmur pas dasmës së të birit, vdiq në Edrene më 1 muharrem 855 (3 shkurt 1451). Nëntëmbëdhjetëvjeçari Mehmeti II, më 16 muharrem 855 (18 shkurt 1451), hipi për herë të dytë në fronin osman — këtë herë përgjithmonë. Kthimi i sundimtarit të ri, i rrëzuar pesë vjet më parë në Buçuktepe, është fillimi i sundimit që dy vjet më vonë do të kurorëzohej me pushtimin e Stambollit dhe do ta shndërronte Bejlikun Osman në një perandori botërore.", "5363b0f7"]},
"OLAYLAR_EK5:1454-07-14:0":{"b": ["Rrethimi i parë i Kafës nga forcat e përbashkëta osmano-krimease", "e346d163"], "d": ["Hani i Krimesë, Haxhi Giraji, i cili u mor vesh me Sulltan Mehmetin Fatih në qershor 1454, me 7000 kalorës e rrethoi Kafën nga toka; edhe një flotë osmane prej pesëdhjetë-gjashtëdhjetë galerash u vendos në det të hapur. Kafa gjenoveze e hoqi rrethimin duke paguar haraç dhe pushtimi përfundimtar mbeti njëzet e një vjet më vonë, në 1475. Ky operacion i parë i përbashkët ishte shembulli i parë i bashkëpunimit ushtarak osmano-krimeas, që do të përsëritej më pas në pushtimin përfundimtar të Kafës.", "bf590b3e"]},
"OLAYLAR_EK5:1455-01-01:0":{"b": ["Marrja e ishujve të Egjeut Verior: Bozxhaada (Tenedos), Imbros dhe Taso", "76575895"], "d": ["Menjëherë pas pushtimit të Stambollit, Sulltan Mehmeti Fatih, për të siguruar rrugën detare të kryeqytetit të ri, u drejtua nga ishujt në grykën egjeane të Ngushticës së Dardaneleve; Bozxhaada dhe Imbrosi u morën nga Bizanti, kurse Taso nga familja Gattilusio me origjinë gjenoveze. Këta ishuj, që mbyllnin të dy anët e ngushticës, pas kësaj u bënë hallka e parë e vijës së furnizimit dhe të mbrojtjes së Stambollit. Me ndërhyrjet e flotave të papatit dhe të Venedikut sundimi për ca kohë shkoi e erdhi dhe u përfundua vetëm në vitin 1459.", "9a34e8f0"]},
"OLAYLAR_EK5:1455-06-01:0":{"b": ["Pushtimi i Kosovës: marrja e Prishtinës dhe e Novi Pazarit", "d7ed2345"], "d": ["Ushtria osmane që marshoi mbi Despotatin Serb mori Prishtinën në fushën e Kosovës dhe Novi Pazarin, qendrën e krahinës së Rashkës; në të njëjtin operacion u mor edhe Novobërda, e njohur për minierat e argjendit. Kështu gjysma jugore e Serbisë u lidh drejtpërdrejt me administrimin osman dhe despotati në Smederevë u shkëput nga tokat qendrore. Ky pushtim ishte hapi vendimtar i rrugës që katër vjet më vonë çoi në aneksimin e plotë të Serbisë.", "b2c7fcce"]},
"OLAYLAR_EK5:1456-01-01:0":{"b": ["Peja (İpek) hyri nën administrimin osman — një nga qendrat e sanxhakut të Dukagjinit", "19511588"], "d": ["Në vitin 1455, menjëherë pas fushatës së Sulltan Mehmetit Fatih në Serbi, Peja, qendra e patriarkanës serbe, kaloi nën administrimin osman; në burimet osmane nuk ka asnjë regjistrim për këtë kalim. Qyteza me kohë u bë një qytezë e vogël myslimane dhe një nga rezidencat e sanxhakbeut në sanxhakun e Dukagjinit.", "4d7160f6"]},
"OLAYLAR_EK5:1456-01-24:0":{"b": ["Pushtimi i Enosit dhe i Samotrakisë — plotësimi i bregut të Trakës Perëndimore", "106e723b"], "d": ["Enosi, ku lumi Marica derdhet në det, u mor nga familja Gattilusio me origjinë gjenoveze, që e mbante prej tetëdhjetë vjetësh; ishulli i Samotrakisë, i lidhur me të, u mor në të njëjtin operacion. Me rënien e Enosit, brezi bregdetar i Trakës Perëndimore nga Selaniku deri në Galipoli u bë tokë osmane e pandërprerë. Në duart e familjes Gattilusio mbeti vetëm Lesbosi; edhe ai do të merrej gjashtë vjet më vonë.", "327297a0"]},
"OLAYLAR_EK5:1456-07-22:0":{"b": ["Dështimi i rrethimit të Beogradit", "3d53a604"], "d": ["Sulltan Mehmeti Fatih, pas pushtimit të Stambollit, rrethoi Beogradin, i konsideruar kyçi i Evropës Qendrore; por përforcimet që Jan Huniadi solli nga Danubi dhe vullnetarët e mbledhur nga predikuesi kryqtar Kapistrano e penguan rënien e kalasë. Padishahu, megjithë trimërinë personale që tregoi gjatë rrethimit, u plagos dhe u detyrua të tërhiqej. Ky dështim do t'ia mbyllte kufirin hungarez përparimit osman për gjashtëdhjetë e pesë vjet; Beogradi mundi të merrej vetëm në vitin 1521 nga Kanuniu.", "036836cb"]},
"OLAYLAR_EK5:1458-05-01:0":{"b": ["Pushtimi i Moresë Veriore: Patra (Balyabadra)", "c08a8509"], "d": ["Në të njëjtat vite me aneksimin e Serbisë, forcat e Sulltan Mehmetit Fatih, që u drejtuan kundër despotatit të Moresë, morën Patrën në veriperëndim të gadishullit. Ky port që zinte grykën e gjirit të Korintit është kyçi i hyrjes tokësore në More; marrja e tij përgatiti terrenin për pushtimin përfundimtar dy vjet më vonë. Qyteti ishte skela e fundit e madhe përmes së cilës despotët bizantinë lidheshin me botën latine.", "4490cc14"]},
"OLAYLAR_EK5:1459-06-20:0":{"b": ["Marrja e bregut të Detit të Zi Perëndimor: Amasra", "f43608fc"], "d": ["Amasra, kolonia e fortifikuar gjenoveze në Detin e Zi Perëndimor, nën presionin e përbashkët të flotës dhe të forcave tokësore të Sulltan Mehmetit Fatih u dorëzua pa rezistuar. Ky port në bregun Bartën-Zonguldak qëndronte si një xhep latin midis Xhandarogllutëve dhe tokave osmane; me marrjen e tij bregu u bashkua. Rënia e Amasrës është hapi i parë i fushatës së madhe të Detit të Zi, që dy vjet më vonë (1461) do të drejtohej drejt Sinopit dhe Trapezundës.", "b8b9f4f0"]},
"OLAYLAR_EK5:1462-09-17:0":{"b": ["Pushtimi i ishullit të Lesbosit", "fe17aeba"], "d": ["Ushtria osmane nën komandën e Sulltan Mehmetit Fatih, në dhulhixhe 866, pas një rrethimi të shkurtër por të ashpër, ia mori Lesbosin familjes Gattilusio me origjinë gjenoveze dhe e aneksoi. Rënia e ishullit më të madh të Egjeut Verior likuidoi edhe bazën e fundit të rëndësishme gjenoveze në krahinë. Ishulli, falë afërsisë me bregun anadollak, pas kësaj do të shërbente si post i përparuar për flotën osmane dhe njëkohësisht do të hynte në historinë detare si vendi ku u rritën vëllezërit Barbarosa.", "453088e2"]},
"OLAYLAR_EK5:1463-07-28:0":{"b": ["Fillimi i Luftës osmano-venedikase gjashtëmbëdhjetëvjeçare", "563ddb68"], "d": ["Venedikasit, për të ndalur përparimin osman në More dhe Egje, duke lidhur aleancë me sundimtarët e Karamanit dhe të akkojunlive, nisën luftën në vitin 1463. Kjo strategji rrethimi, me Uzun Hasanin në lindje, Venedikun në perëndim dhe Karamanin në mes, e detyroi Fatihun të luftonte njëkohësisht në disa fronte. Lufta gjashtëmbëdhjetëvjeçare do të përfshinte të gjitha operacionet e mëdha të kohës, nga Otllukbeli deri te fushatat e Shqipërisë, dhe do të përfundonte vetëm me Traktatin e Stambollit të vitit 1479.", "e70079e9"]},
"OLAYLAR_EK5:1466-01-01:0":{"b": ["Pushtimi i pjesës më të madhe të Hercegovinës: Trebinja dhe Mostari", "f54c0100"], "d": ["Tokat e dukës së Hercegovinës, Stjepan Vukčić-Kosača, që kishte krijuar një administrim të veçantë nga Bosnja, tri vjet pas rënies së Mbretërisë së Bosnjës kaluan në masë të madhe nën administrimin osman: në jug Trebinja u mor në vitin 1466 \"së bashku me pothuajse gjithë krahinën e Hercegovinës\". Edhe Mostari, i krijuar rreth dy kalave të vogla të urës mbi Neretvë, duhet të jetë marrë pak para pushtimit të Blagajit, qendrës së Hercegovinës, në vitet 1466-1468; në regjistrin përmbledhës të Bosnjës të viteve 1468-1469 shënohet me emrin \"Kyprylly Hisar\" (Kalaja me Urë). Me kalatë e mbetura të dukatit, pushtimi i Hercegovinës përfundoi në vitin 1483.", "a7f22be7"]},
"OLAYLAR_EK5:1466-06-01:0":{"b": ["Fushata e dytë e Shqipërisë — marshimi vetë i Fatihut kundër Skënderbeut", "9cdd2bfa"], "d": ["Për të thyer rezistencën e Skënderbeut që kalonte një çerek shekulli, Sulltan Mehmeti Fatih në vitet 1466-1467 organizoi fushata të mëdha që i komandoi vetë. Ushtria osmane rrethoi Krujën dhe, për të vënë krahinën nën kontroll, ndërtoi kalanë e Elbasanit. Fushata, megjithëse ia theu shpinën rezistencës shqiptare, nuk arriti ta merrte kalanë; nënshtrimi i plotë i krahinës do të zgjaste dhjetë vjet pas vdekjes së Skënderbeut.", "00e75aca"]},
"OLAYLAR_EK5:1467-10-01:0":{"b": ["Forcat pararojë akkojunlu ia morën kështjellën e Bingölit karakojunlunjve", "51b94cbc"], "d": ["Në javët e fundit të fushatës që Xhihan Shahu ndërmori kundër Uzun Hasanit, forcat pararojë akkojunlu shtinë në dorë kështjellën e Bingölit; me vrasjen e Xhihan Shahut më 10 nëntor 1467, sundimi karakojunlu në rajon mori fund.", "c150063d"]},
"OLAYLAR_EK5:1467-11-10:0":{"b": ["Shembja e Shtetit Karakojunlu: vrasja e Xhihan Shahut", "30bc6358"], "d": ["Sundimtari karakojunlu Xhihan Shahu, që po kthehej nga fushata kundër Uzun Hasanit për shkak të ardhjes së dimrit, ra në pritë dhe u vra ndërsa ikte midis Bingëlit dhe Kigëit. Pas kësaj goditjeje shteti nuk mundi të rimëkëmbej; sundimtari i fundit, Hasan Aliu, në vitin 1469 u zu rob nga Ugurlu Mehmedi, i biri i Uzun Hasanit, dhe u vra. Kështu sundimi karakojunlu, që për afro një shekull sundonte në Anadollin Lindor, Azerbajxhan dhe Irak, u kaloi akkojunlive.", "5a5288e7"]},
"OLAYLAR_EK5:1468-01-17:0":{"b": ["Vdekja e Skënderbeut — shuarja e rezistencës shqiptare", "9158c35f"], "d": ["Skënderbeu, i rritur në sarajin osman, i cili në vitin 1444 pas disfatës së Zlaticës u ngrit në kryengritje dhe për më shumë se një çerek shekulli rezistoi në Shqipëri, vdiq në Lezhë, ku ishte strehuar. Kjo rezistencë, që në kohën e Muratit II dhe të Fatihut i kishte vonuar shpesh ushtritë osmane, me vdekjen e tij humbi udhëheqjen qendrore. Me shembjen e frontit shqiptar të ushqyer nga papati dhe Venediku, osmanët brenda dhjetë vjetësh morën Krujën dhe Shkodrën dhe e shtuan krahinën përfundimisht në tokat e tyre.", "5c7cffad"]},
"OLAYLAR_EK5:1474-01-01:0":{"b": ["Në Kajseri u vendos administrimi osman: Gedik Ahmet Pasha u dha fund Karamanogullëve", "33cf35fc"], "d": ["Kur Gedik Ahmet Pasha më 1474 u dha fund Karamanogullëve, Kajseria hyri nën administrimin osman; qyteti gjatë shekullit XV kishte ndërruar duar mes Dulkadirëve, Ramazanogullëve dhe Karamanogullëve. Me administrimin osman, Kajseria u bë qendër sanxhaku e bejlerbejllëkut të Karamanit.", "5d1db169"]},
"OLAYLAR_EK5:1475-01-01:0":{"b": ["Samosi u braktis: mori fund pronësia gjenoveze (e Maonës)", "5bdc380c"], "d": ["Sipas TDV-së, ishulli u braktis pas vitit 1475; më 1479 Sulltan Mehmeti Fatih e pushtoi ishullin dhe urdhëroi ndërtimin e një kështjelle.", "4e48c423"]},
"OLAYLAR_EK5:1475-01-10:0":{"b": ["Disfata e Rakovës (Vaslui) në Moldavi", "a1a74bf7"], "d": ["Vojvoda i Moldavisë, Stefan cel Mare, duke i tërhequr forcat osmane nën komandën e bejlerbeut të Rumelisë, Hadëm Sulejman Pashës, në një terren moçalor, u shkaktoi një disfatë të rëndë. Kjo disfatë, një nga humbjet më të rënda tokësore të kohës së Fatihut, pati jehonë të madhe në Evropë dhe i solli Stefanit famë në botën kryqtare. Padishahu vitin pasues do të dilte vetë në fushatë për hakmarrje.", "3247c9fe"]},
"OLAYLAR_EK5:1476-07-26:0":{"b": ["Fitorja e Valea Albës (Akdere) — fushata e Moldavisë", "45a66791"], "d": ["Sulltan Mehmeti Fatih, që doli vetë në fushatë për të marrë hakun për disfatën e Rakovës të një viti më parë, me ushtrinë osmane u shkaktoi njësive moldave një disfatë të madhe në vendin Valea Albă dhe hyri në Suçava, qendrën e principatës. Por kalatë nuk u morën; për shkak të mungesës së ushqimeve, murtajës që nisi midis jeniçerëve dhe përgatitjeve hungareze, ushtria u detyrua të tërhiqej. Varësia përfundimtare e Moldavisë mundi të arrihej vetëm në vitet pasuese dhe me marrjen e Kilias dhe të Akkermanit në vitin 1484.", "27b9dd1c"]},
"OLAYLAR_EK5:1478-06-15:0":{"b": ["Pushtimi i Krujës (Akçahisar) dhe plotësimi i Shqipërisë", "559a79b4"], "d": ["Dhjetë vjet pas vdekjes së Skënderbeut, në vitin 1478, me marrjen e Krujës, Drishtit, Lezhës dhe Zhabjakut u plotësua në masë të madhe pushtimi i Shqipërisë. Rënia e Kalasë së Krujës, që për vite i kishte rezistuar ushtrive osmane dhe ishte simbol i rezistencës së Skënderbeut, do të thoshte fund i aleancës venedikaso-shqiptare në krahinë. Kurse Shkodra e mbetur do t'u lihej Osmanëve me Traktatin e Stambollit që do të nënshkruhej vitin pasues.", "4f6059e8"]},
"OLAYLAR_EK5:1479-01-01:0":{"b": ["Bashkimi i gadishullit të Tamanit", "4ef917b8"], "d": ["Pas marrjes së Kafës dhe Kerçit në vitin 1475, flota që Sulltan Mehmeti Fatih dërgoi në brigjet e Kaukazit, së bashku me Anapën dhe Kopan, pushtoi Matregën gjenoveze (Tamatarhan) në gadishullin e Tamanit. Kështu u vunë nën kontroll të dy brigjet e ngushticës dhe hyrja në Detin e Azovit u bë krejtësisht e kontrollueshme. Tamani, si porta drejt Kaukazit Verior, u lidh me sanxhakun e Kafës.", "74a0de9f"]},
"OLAYLAR_EK5:1479-01-01:1":{"b": ["Hyrja e Samosit nën administrimin osman (Fatihu)", "c877bc14"], "d": ["Sulltan Mehmeti Fatih pushtoi Samosin, urdhëroi ndërtimin e një kështjelle dhe riorganizoi regjistrimin e popullsisë; kështjellën Bajaziti II urdhëroi ta shembnin më 1483 për shkaqe politike.", "2965b1d9"]},
"OLAYLAR_EK5:1480-07-28:0":{"b": ["Dështimi i rrethimit të Rodosit", "35a85c28"], "d": ["Me urdhër të Sulltan Mehmetit Fatih, flota prej 160 anijesh nën komandën e Mesih Pashës në pranverën e vitit 885 (1480) rrethoi Rodosin dhe ishulli mbeti tre muaj nën bllokadë. Kalorësit e Shën Gjonit, nën udhëheqjen e mjeshtrit të madh Pierre d'Aubusson, megjithë humbjet e rënda rezistuan fort; pasi u zmbraps edhe sulmi i fundit i madh i 20 xhumadelula 885, flota u tërhoq më 3 gusht. Pas këtij dështimi muret e qytetit u rinovuan nga fillimi dhe u bënë fortifikimi më i fortë i Evropës, dhe ishulli mundi të merrej vetëm në vitin 1522 nga Kanuniu.", "23334bd0"]},
"OLAYLAR_EK5:1481-01-01:0":{"b": ["Nikaria (Ikaria) hyri nën administrimin e Kalorësve të Shën Gjonit të Rodosit", "5cbc2669"], "d": ["Nikaria, mes Samosit dhe Kiosit, nga viti 1481 deri më 1521 ishte nën administrimin e Kalorësve të Shën Gjonit të Rodosit.", "9d387479"]},
"OLAYLAR_EK5:1481-06-22:0":{"b": ["Beteja e Jenishehirit — disfata e Xhem Sulltanit", "c35abee2"], "d": ["Dy vëllezërit që pas vdekjes së Fatihut u vunë në lëvizje për fron u ndeshën në fushën e Jenishehirit dhe Xhem Sulltani pësoi një disfatë vendimtare. Shehzadeja, që sundoi në Bursë tetëmbëdhjetë ditë dhe urdhëroi të lexohej hytbeja në emrin e vet, pas disfatës u detyrua të strehohej fillimisht në Konja, prej andej në tokat memluke. Jenishehiri nisi krizën dinastike më të gjatë të historisë osmane: çështja e Xhemit për katërmbëdhjetë vjet do ta paralizonte politikën e jashtme osmane ndaj Evropës.", "9d30204e"]},
"OLAYLAR_EK5:1482-01-01:0":{"b": ["Aneksimi i Hercegovinës", "bf247891"], "d": ["Tokat e Dukatit të Hercegovinës, që kishte mbijetuar pas pushtimit të Bosnjës në vitin 1463, kaluan hap pas hapi nën administrimin osman: Trebinja dhe Mostari u morën në vitin 1466, sanxhaku i Hercegovinës u formua në vitin 1470, kurse tokat e fundit të dukatit në bregun e Adriatikut, së bashku me Herceg Novin, u pushtuan në fillim të vitit 1482 dhe iu bashkuan sanxhakut. Kështu krahina malore prapa Adriatikut u bë tërësisht osmane dhe Bosnja me Hercegovinën u bënë një gjeografi e vetme administrative. I biri i dukës së fundit, që hyri në sarajin osman, është Hercegzade Ahmed Pasha, i cili më vonë do të ngrihej deri në postin e vezirit të madh.", "0522e47f"]},
"OLAYLAR_EK5:1482-01-01:1":{"b": ["Lënia e Zakintosit (Zaklise) Venedikut me haraç vjetor", "268a691a"], "d": ["Zakintosi, një nga ishujt e Jonit që në fund të kohës së Fatihut iu mor familjes Tocco, iu la Venedikut nga padishahu i ri, i cili, i zënë me çështjen e Xhem Sulltanit, kërkonte qetësi në Perëndim. Ishulli iu dorëzua një administrate venedikase që njihte sovranitetin osman dhe paguante pesëqind dukate haraç në vit. Kështu në Detin Jon administrimi i drejtpërdrejtë osman mbeti vetëm në Ajamavrë.", "0773761c"]},
"OLAYLAR_EK5:1482-07-29:0":{"b": ["Strehimi i Xhem Sulltanit në Rodos", "2228d6da"], "d": ["Xhem Sulltani, të cilit i mbeti pa rezultat edhe përpjekja për të rrethuar Konjën, me rreth tridhjetë njerëz iku nga Anadolli, arriti në Rodos dhe u prit me ceremoni nga kalorësit e Shën Gjonit. Por mikpritja brenda pak kohe u shndërrua në robëri; shehzadeja iu dorëzua fillimisht Francës, pastaj papatit dhe u bë një kartë në duart e politikës evropiane. Bajazidi II u detyrua të paguante çdo vit për mbajtjen e të vëllait dhe veprimet ushtarake osmane drejt Perëndimit u pezulluan deri në vdekjen e Xhemit.", "05ca0dd6"]},
"OLAYLAR_EK5:1485-01-01:0":{"b": ["Fillimi i luftës osmano-memluke (fronti i Çukurovës)", "3fe3f0c7"], "d": ["Lufta për ndikim mbi Dulkadirogllutët dhe armiqësia që la strehimi i Xhem Sulltanit në tokat memluke, në vitin 1485 nisën midis dy fuqive të mëdha sunite një luftë që do të zgjaste gjashtë vjet. Në përleshjet në Çukurovë, rreth Adanasë dhe Tarsit, asnjëra palë nuk fitoi epërsi; ushtritë osmane pësuan disa goditje të rënda. Kjo luftë është faza e parë e çarjes në marrëdhëniet osmano-memluke dhe hapja e procesit që tridhjetë vjet më vonë do të përmbyllej me fushatat e Javuzit në Mexh Dabik dhe Ridanije.", "08141630"]},
"OLAYLAR_EK5:1491-05-01:0":{"b": ["Paqja osmano-memluke — ndërmjetësimi i Tunisit", "60dd6719"], "d": ["Në luftën osmano-memluke që filloi në vitin 1485 palët nuk mundën të korrnin një fitore vendimtare; me ndërmjetësimin e sundimtarit të Tunisit, Osman Hafsit, në vitin 1491 u arrit marrëveshja. Traktati i ktheu kufijtë në masë të madhe në gjendjen e para luftës dhe llogaria midis dy shteteve islame u shty për një brez. Lufta rraskapitëse gjashtëvjeçare është një nga arsyet kryesore të politikës së jashtme të kujdesshme të Bajazidit II dhe të përqendrimit të tij te rregullimet e brendshme në vend të drejtimit nga lindja.", "406d3b78"]},
"OLAYLAR_EK5:1492-08-01:0":{"b": ["Pranimi në Perandorinë Osmane i hebrenjve sefardë të dëbuar nga Spanja", "5c2b5c24"], "d": ["Pas rënies së Granadës, një pjesë e hebrenjve që iknin nga dhuna e inkuizicionit në Spanjë u strehuan në tokat osmane dhe u vendosën në qytete të ndryshme. Nën administrimin osman këto komunitete sefarde fituan një liri që nuk e kishin parë deri atëherë: të vendoseshin ku të donin, të jetonin besimin e tyre, të hapnin institucione arsimore dhe të ndërtonin sinagoga të reja. Kjo shpërngulje, që me njohuritë e shtypshkronjës, mjekësisë dhe financave që sollën me vete e transformoi jetën ekonomike të Selanikut dhe të Stambollit, u bë shembulli më i përfolur në Evropë i rendit osman të tolerancës.", "b5b4a53b"]},
"OLAYLAR_EK5:1495-02-25:0":{"b": ["Vdekja e Xhem Sulltanit — fundi i pengmarrjes katërmbëdhjetëvjeçare", "f6588b70"], "d": ["Xhem Sulltani, i dorëzuar nga papati te mbreti i Francës Karli VIII, pasi u nis nga Roma më 27 janar 1495, vdiq në vendin e quajtur Castel Capuana; burimet shënojnë se mund të jetë helmuar nga rrethet papnore. Vdekja e shehzadesë, që për katërmbëdhjetë vjet u mbajt në duart e shteteve evropiane si kartë kërcënimi kundër Osmanëve, më në fund ia liroi duart Bajazidit II. Vërtet, pas kësaj padishahu do t'i shpallte luftë Venedikut dhe do ta çonte flotën në fitoren e saj të parë të madhe.", "8f2579d5"]},
"OLAYLAR_EK5:1499-08-28:0":{"b": ["Fitorja Detare e Sapienzës (Zonchio) — suksesi i parë i madh i flotës në Mesdhe", "9754aaef"], "d": ["Bajazidi II, që me përfundimin e çështjes së Xhemit i kishte duart e lira, në vitin 1499 i shpalli luftë Venedikut; flota osmane, duke mundur flotën venedikase në ujërat e Sapienzës (Zonchio), korri fitoren e parë të madhe detare në Mesdhe. Me këtë fitore flota shpalli se tashmë mund t'i bënte ballë Venedikut në det.", "5fa6989c"]},
"OLAYLAR_EK5:1500-12-24:0":{"b": ["Humbja e Qefalonisë dhe Itakës", "60f0f687"], "d": ["Venediku, i tronditur nga marrja e Modonit dhe Koronit, u bashkua me Spanjën, kaloi në kundërsulm dhe rrethoi Qefaloninë, që nga viti 1479 ishte në duart osmane. Pas qëndresës dyzet e shtatë ditore kështjella ra, ishulli bashkë me Itakën kaloi te Venediku dhe për treqind vjet nuk u kthye më nën administrimin osman. Kjo humbje krijoi një ekuilibër në të cilin ajo që u fitua në More u kthye në Jon.", "a61731e0"]},
"OLAYLAR_EK5:1502-03-01:0":{"b": ["Shembja e Hanatit të Hordhisë së Artë dhe ngritja e Krimesë", "0d1dc515"], "d": ["Sundimtari i fundit, Shejh Ahmed Hani (1481-1502), nuk mundi ta shpëtonte vendin nga kriza ku kishte rënë dhe Hanati i Hordhisë së Artë, në vitin 1502, me goditjen e hanit të Krimesë, Mengli Girajit, hyri në histori. Si pasojë e grindjeve për fronin dhe e copëtimit, në tokat e dikurshme të Hordhisë së Artë dolën hanatet e Krimesë, Kazanit, Nogait, Astrahanit dhe Sibirit. Kjo fitore e Krimesë nën mbrojtjen osmane e bëri të padiskutueshëm ndikimin osman në veri të Detit të Zi, kurse boshllëkun që lindi në krahinë do ta mbushte në shekullin pasues Moska.", "9314f239"]},
"OLAYLAR_EK5:1502-12-14:0":{"b": ["Përfundimi i luftës osmano-venedikase dhe paqja", "125b1526"], "d": ["Lufta që filloi në vitin 1499 dhe e tronditi Venedikun me Sapienzën dhe me humbjen e Lepantos, Modonit dhe Koronit, përfundoi me paqe në vitin 1502. Venediku, duke humbur bazat më të rëndësishme në More, u detyrua të pranonte epërsinë osmane në këmbim të ruajtjes së privilegjeve tregtare në Mesdheun Lindor. Sundimi i Bajazidit II, që konsiderohet i kujdesshëm, me këtë luftë i kishte ngritur Osmanët për herë të parë në pozitën e një fuqie të vërtetë detare në Mesdhe.", "3d102f53"]},
"OLAYLAR_EK5:1511-07-02:0":{"b": ["Kryengritja e Shahkullut — kryengritja kizilbashe nga krahina e Tekesë deri në Sivas", "3beadca7"], "d": ["Shahkulu Baba Tekeli, i cili nën ndikimin e propagandës safavide në Anadoll e shfaqi hapur kryengritjen në vitin 1510, në mars 1511 sulmoi pazarin e Antalisë dhe në prill i mundi forcat osmane në Kytahja dhe rrethina. Në përleshjen e fundit me vezirin e madh Hadëm Ali Pasha pranë Sivasit, të dyja palët pësuan humbje të rënda; si veziri i madh, si udhëheqësi i kryengritjes humbën jetën. Kjo kryengritje, që e tronditi autoritetin shtetëror në Anadoll, nxori në pah boshllëkun e pushtetit në vitet e fundit të Bajazidit II dhe u bë arsyeja më e fortë e marshimit të shehzade Selimit drejt fronit.", "846180f5"]},
"OLAYLAR_EK5:1512-04-24:0":{"b": ["Heqja dorë nga froni e Bajazidit II dhe hipja e Sulltan Selimi Javuzit", "c4cfab69"], "d": ["Me presionin e shehzade Selimit, që në luftën për fron me vëllezërit kishte pas vetes mbështetjen e jeniçerëve, Bajazidi II hoqi dorë nga froni më 24 prill 1512 dhe Selimi I po atë ditë hipi në fron si sundimtari i nëntë osman. Padishahu plak, ndërsa po shkonte në Dimotikë, ku kishte lindur, vdiq rrugës në fshatin Abalar pranë Çorlusë, më 25 rebiulevel 918 (10 qershor 1512). Sundimin tridhjetë e një vjeçar, të kujdesshëm dhe të mbyllur, e zëvendësoi epoka e Javuzit, që për tetë vjet do t'i dyfishonte kufijtë e perandorisë.", "7194b8c2"]},
"OLAYLAR_EK5:1513-01-01:0":{"b": ["Pushtimi i kështjellës së Sinjit", "83271ea5"], "d": ["Forcat akinxhi osmane në kufirin e Bosnjës ia morën Mbretërisë së Hungarisë kështjellën e Sinjit, që shtrihej në brendësi të Dalmacisë. Kjo ishte një hallkë e hershme e vijës kufitare dalmate, që nëntë vjet më vonë do të zgjerohej me pushtimin e Kninit dhe rrethinave nga Gazi Husrev Beu; kështjella do t'i humbte Venedikut më 1686.", "28c20426"]},
"OLAYLAR_EK5:1513-04-01:0":{"b": ["Beteja e Jenishehirit dhe eliminimi i shehzade Ahmedit", "e2ed15dd"], "d": ["Sulltan Selimi Javuz shpartalloi në fushën e Jenishehirit pranë Bursës të vëllanë e madh, shehzade Ahmedin, rivalin më të fortë për fronin, e zuri rob dhe e eliminoi. Kështu u mbyll grindja e vëllezërve që vazhdonte që nga viti 1511 dhe mori fund përçarja e brendshme në Anadoll. Selimi, duke siguruar shpinën, fitoi lirinë për t'u marrë me çështjen safavide.", "ed5f5ec0"]},
"OLAYLAR_EK5:1514-09-06:0":{"b": ["Hyrja e Sulltan Selimit Javuz në Tebriz", "dad2e227"], "d": ["Pas fitores së Çalldiranit, ushtria osmane hyri në kryeqytetin safavid, Tebriz, dhe në qytet u lexua hytbeja në emër të padishahut. Selimi qëndroi aty një javë dhe urdhëroi të zhvendosej në Stamboll një pjesë e artizanëve dhe dijetarëve të Tebrizit; ky transferim do të ndikonte thellë në artin e sarajit osman. Megjithëse qyteti u la për shkak të afrimit të dimrit dhe pakënaqësisë së jeniçerëve, epërsia safavide në Lindje ishte thyer. Vendet që në hartë këtë ditë u kalojnë Osmanëve nuk janë të ngjitura me njëri-tjetrin dhe kjo është e saktë: Tebrizi është një pushtim nëntëditor i ushtrisë; fusha e Erzinxhanit u dorëzua pa luftë gjatë fushatës, kurse kalaja e Kemahut në mes të saj rezistoi te safavidët deri më 19 maj 1515; Siirtin ua rimori safavidëve meliku i Hasankejfit, Halil Beu, i cili u shpëtua nga burgu i Shah Ismailit në Tebriz dhe iu nënshtrua Osmanëve — kurse rrethinat e tij, Dijarbekiri deri në 1515 dhe Hasankejfi deri në 1517, mbetën safavide.", "3f65211e"]},
"OLAYLAR_EK5:1515-02-25:0":{"b": ["Mushi dhe Bingöli (Çapakçur) kaluan nga safavidët nën administrimin osman", "b0a53b5a"], "d": ["Me marrjen e Anadollit Lindor nga safavidët pas Çalldiranit, Mushi më 921/1515 hyri nën administrimin osman; fqinji Çapakçur (Bingöl) iu bashkua osmanëve në të njëjtin proces.", "9c979b3f"]},
"OLAYLAR_EK5:1515-05-19:0":{"b": ["Pushtimi i Kalasë së Kemahut nga safavidët", "73fd8671"], "d": ["Sulltan Selimi Javuz, që kthimin nga Çalldirani e kaloi dimrin në Amasja, e ngarkoi Bëjëkllë Mehmed Pashën me pushtimin e Kalasë së fortifikuar të Kemahut, që zinte vendkalimin e Eufratit. Në fund të rrethimit ku mori pjesë vetë padishahu, kalaja u mor nga safavidët dhe u hap porta e Anadollit Lindor. Ky pushtim është hapi i parë konkret që e shndërroi fitoren e Çalldiranit në fitim të qëndrueshëm territorial.", "9e896ebe"]},
"OLAYLAR_EK5:1515-06-13:0":{"b": ["Fitorja e Turnadagut — Bejliku i Dulkadirëve u bë vartës i Osmanëve", "fd879145"], "d": ["Forcat osmane mundën në vendin Ordekli, midis Goksunit dhe Andërinit, beun e Dulkadirëve, Alaudevle Bozkurt, i cili gjatë fushatës së Çalldiranit mbajti qëndrim të dyshimtë; Alaudevleja u vra në këtë betejë. Bejliku në këtë datë nuk u aneksua: pas Alaudevles, në krye të Bejlikut të Dulkadirogllutëve Sulltan Selimi Javuz vendosi Shehsuvarogllu Ali Beun dhe vendi me qendër Marash-Elbistan vazhdoi si bejlik vartës i Osmanëve. Kështu zona tampon në kufirin memluk hyri nën kontrollin osman dhe u hap rruga për fushatën e Egjiptit dy vjet më vonë; aneksimi do të bëhej pas vrasjes së Ali Beut.", "cf9c7460"]},
"OLAYLAR_EK5:1515-09-19:0":{"b": ["Pushtimi i Amidit (Dijarbekirit) dhe krijimi i Bejlerbejllëkut të Dijarbekirit", "a6867d5b"], "d": ["Pasi Idris Bitlisiu fitoi për Osmanët bejlerët kurdë sunitë të krahinës, forcat safavide nuk mundën t'i qëndronin rrethimit të gjatë dhe çelësat e Amidit iu dorëzuan Bëjëkllë Mehmed Pashës. Qyteti u bë qendra e Bejlerbejllëkut të sapokrijuar të Dijarbekirit. Kështu bërthama administrative e Mesopotamisë së Epërme kaloi në duart osmane.", "70169bcc"]},
"OLAYLAR_EK5:1516-03-26:0":{"b": ["Pushtimi i Harputit — hapja e rrugës së Dijarbekirit", "564eb269"], "d": ["Bejlerbeu i Karamanit, Hysrev Pasha, që u nis për ta shpëtuar nga rrethimi safavid Dijarbekirin e marrë pas Çalldiranit, në fund të një rrethimi tre ditor mori Kalanë e Harputit, rrethinat e së cilës i kishte pushtuar më parë Çerkez Husein Beu. Kështu u sigurua rruga në lindje të Eufratit që shtrihet drejt Dijarbekirit.", "eb738178"]},
"OLAYLAR_EK5:1516-05-01:0":{"b": ["Beteja e Koçhisarit (Këzëltepe) — disfata e Kara Hanit", "9ea9e843"], "d": ["Ushtria osmane nën komandën e Bëjëkllë Mehmed Pashës, pranë Koçhisarit, në vendin Koruk të fushës së Dede Garkënit, e mundi valiun safavid Kara Han në një betejë fushore që zgjati gjithë ditën; koka e prerë e Kara Hanit u dërgua në kampin e padishahut. Më pas forcat osmane hynë në qytetin e Mardinit, por qëndruan pak ditë dhe u larguan; Kalaja e Mardinit, në duart e rojtarëve safavidë, mundi të merrej vetëm një vit më vonë. Kjo fitore, duke e siguruar kufirin jugor të Javuzit, i mundësoi të drejtohej për në fushatën e Egjiptit. Vende të tjera që u bashkuan në të njëjtën datë: Palu, Çemishgezek, Siverek.", "6bc19ce1"]},
"OLAYLAR_EK5:1516-06-05:0":{"b": ["Nisja e Sulltan Selimi Javuzit nga Stambolli për fushatën e Egjiptit", "ac258b4b"], "d": ["Sulltan Selimi Javuz, në dukje me përgatitje për një fushatë të re lindore kundër safavidëve, u nis nga Stambolli dhe përmes Akshehirit u drejtua drejt jugut. Fakti që sulltani memluk Kansu Gavri lidhi kontakte me Shah Ismailin dhe kërcënoi krahun lindor osman do të çonte brenda pak kohe në ndryshimin e objektivit. Fushata është fillimi i operacionit të madh që do të zgjaste dy vjet dhe do t'i shndërronte Osmanët në një perandori të Lindjes së Mesme.", "6b27f782"]},
"OLAYLAR_EK5:1516-06-20:0":{"b": ["Marrja e Zebidit: hyrja e parë e detarëve osmanë në Detin e Kuq", "38740e0c"], "d": ["Detarët me origjinë osmane Husein Beu dhe Selman Reisi, të dërguar në Detin e Kuq me kërkesën e sulltanit memluk Kansu Gavri përballë presionit portugez në Oqeanin Indian, me flotën e tyre morën Zebidin. Ky operacion, i kryer ende në shërbim të memlukëve, është prania e parë de fakto e marinës osmane në vijën Deti i Kuq-India. Kur një vit më vonë Egjipti u kaloi Osmanëve, po ajo flotë do të lidhej drejtpërdrejt me Stambollin.", "f715b0aa"]},
"OLAYLAR_EK5:1516-07-30:0":{"b": ["Shpallja zyrtare e memlukëve dhe e Halepit si objektiv i fushatës", "689e310d"], "d": ["Sulltan Selimi Javuz, pasi Kansu Gavri, duke u marrë vesh me safavidët, e shtyu ushtrinë drejt Halepit, e shpalli hapur se objektiv i fushatës ishin sulltani memluk dhe Halepi. Kështu rivaliteti i fshehtë shumëvjeçar midis dy shteteve sunite u shndërrua në luftë të hapur. Kjo shpallje nisi numërimin mbrapsht katërjavor drejt Mexh Dabikut.", "f2a137f3"]},
"OLAYLAR_EK5:1516-08-02:0":{"b": ["Dështimi i rrethimit të Adenit: përpjekja e parë në Detin e Kuq kundër Portugalisë", "8ffd46f2"], "d": ["Selman Reisi dhe Husein Beu, për të marrë Adenin, portën e Detit të Kuq drejt Oqeanit Indian, zhvilluan një rrethim tetë ditor, por përballë fortifikimit të fortë të qytetit u detyruan të tërhiqeshin. Mosmarrja e Adenit do ta pengonte për shumë vite strategjinë jugore kundër Portugalisë. Kjo përpjekje është prova e parë e politikës oqeanike osmane.", "8b584b76"]},
"OLAYLAR_EK5:1516-08-24:0":{"b": ["Lidhja e Bejlikut të Ramazanogllutëve me Osmanët", "cfaa3754"], "d": ["Gjatë caktimeve të bëra pas fitores së Mexh Dabikut, Bejliku i Ramazanogllutëve me qendër Adananë iu dha Mahmud Beut dhe u mor nën sovranitetin osman. Bejliku, që doli nga vartësia memluke, në vend që të zhdukej, iu la familjes me statusin 'odxhakllëk'; Ramazanogllutë vazhduan të administronin Çukurovën në cilësinë e sanxhakbejlerëve osmanë. Ky rend i privilegjuar vazhdoi deri në vitin 1608, kur Pir Mansuri e la bejlikun. Vende të tjera që u bashkuan në të njëjtën datë: Malatja, Tarsi, Mosuli, Antepi.", "af7c4758"]},
"OLAYLAR_EK5:1516-08-28:0":{"b": ["Hyrja e Halepit, Rakas dhe Deir ez-Zorit nën sundimin osman", "2088eb6a"], "d": ["Katër ditë pas Mexh Dabikut, Sulltan Selimi Javuz hyri pa rezistencë në Halep dhe në xhamitë e qytetit u lexua hytbeja në emrin e tij. Rënia kaq e shpejtë e Halepit, i konsideruar kryeqyteti tregtar dhe administrativ i Sirisë, tregon se autoriteti memluk në krahinë ishte shembur. Marrja e qytetit hapi menjëherë rrugën drejt Damaskut e prej andej drejt Egjiptit. Vende të tjera që u bashkuan në të njëjtën datë: Antakia, Raka, Deir ez-Zori.", "6055ffc7"]},
"OLAYLAR_EK5:1516-08-29:0":{"b": ["Takimi me halifin abasid Mutavakkil III në Gökmejdan të Halepit", "22979f42"], "d": ["Halifi abasid i Kajros, Mutavakkil III, i zënë rob në Mexh Dabik së bashku me ushtrinë memluke, u nxor në Halep, në Gökmejdan, përpara padishahut dhe Sulltan Selimi Javuz i tregoi respekt të madh. Halifati i Kajros, që që nga viti 1261 ishte një post simbolik nën hijen e sulltanëve memlukë, me këtë takim kaloi de fakto nën mbrojtjen osmane. Halifi më vonë do të çohej me padishahun në Stamboll.", "b1490892"]},
"OLAYLAR_EK5:1516-09-26:0":{"b": ["Hyrja e Tripolit të Sirisë dhe e Hamas nën administrimin osman", "a1e19a79"], "d": ["Pas Halepit dhe Hamas, edhe Tripoli i Sirisë, në bregun sirian, kaloi pa rezistencë nën administrimin osman. Qyteti, një nga portet më të gjallë të Mesdheut Lindor, ishte porta detare e Damaskut dhe qendra e tregtisë së mëndafshit dhe të sheqerit. Me marrjen e tij, brezi bregdetar i Bilad al-Shamit ndërroi plotësisht dorë.", "57168655"]},
"OLAYLAR_EK5:1516-09-27:0":{"b": ["Hyrja e Damaskut nën sundimin osman", "2b844d91"], "d": ["Sulltan Selimi Javuz, të cilit pas Halepit iu hap rruga me dorëzimin e Hamas dhe të Homsit, më 27 shtator arriti përpara Damaskut; nuk hyri menjëherë në qytet, por ngriti çadrën jashtë, në vendin Mastaba, dhe ditën e dymbëdhjetë të ardhjes hyri me ceremoni të madhe. Duke qëndruar gjatë në Damask, vendosi rendin administrativ të Sirisë dhe urdhëroi të ndërtohej varri i Muhjiddin Ibn Arabiut. Kështu i gjithë Bilad al-Shami doli nga administrimi memluk. Vende të tjera që u bashkuan në të njëjtën datë: Bejruti.", "7cd1cd2b"]},
"OLAYLAR_EK5:1516-10-10:0":{"b": ["Shpallja e Tomanbeut sulltan memluk në Kajro", "6020d90d"], "d": ["Pas Kansu Gavriut, që vdiq në Mexh Dabik, emirët memlukë hipën në fron Tomanbeun, që do të ishte sulltani i fundit i shtetit. Sulltani i ri me origjinë çerkeze mori një shtet që kishte humbur Sirinë, e kishte thesarin të shterur dhe i mungonin armët e zjarrit. Megjithatë, duke ngritur një vijë mbrojtëse përpara Kajros, do të organizonte një rezistencë të fundit ndaj përparimit osman.", "c55b45e9"]},
"OLAYLAR_EK5:1516-12-21:0":{"b": ["Beteja e Gazës (Han Junusit): disfata e Xhanbirdi Gazaliut", "9f1eb8cb"], "d": ["Sulltan Selimi Javuz dërgoi në Gazë vezirin e madh Hadëm Sinan Pashën me një pararojë prej katër mijë vetash. Xhanbirdi Gazaliu, i emëruar nga Tomanbeu zëvendës (naib) i Damaskut, u përpoq ta ndalte pararojën osmane në vijën Gazë-Han Junus, por pësoi një disfatë të rëndë dhe iku në Egjipt. Me shpërndarjen e forcës së fundit tampon memluke në Palestinë, rruga drejt shkretëtirës së Sinait u hap plotësisht.", "042a934e"]},
"OLAYLAR_EK5:1516-12-28:0":{"b": ["Lindja e Jordanit: hyrja e Amanit nën administrimin osman", "9db62667"], "d": ["Pas betejës së Gazës, ndërsa forcat osmane që përgatiteshin për fushatën e Egjiptit zbrisnin drejt jugut, edhe Amani, në lindje të Jordanit, hyri nën administrimin osman. Kurse qytetet bregdetare dhe të brendshme të Palestinës (Jafa, Nablusi, Sidoni, Akka, Jerusalemi) kishin ndërruar dorë tashmë pas Mexh Dabikut, në vjeshtën e vitit 1516. Këto qytete për katër shekuj u administruan si sanxhakë të ejaletit të Damaskut.", "fac75355"]},
"OLAYLAR_EK5:1516-12-29:0":{"b": ["Ardhja e Sulltan Selimi Javuzit në Jerusalem", "66d7bfad"], "d": ["Në Jerusalem, që pas Mexh Dabikut kishte kaluar pa rezistencë nën administrimin osman, pas betejës së Gazës erdhi Sulltan Selimi Javuz me parinë e shtetit dhe me ushtrinë. Padishahu vizitoi Kubbet es-Sahran dhe Xhaminë Al-Aksa dhe konfirmoi statusin e shenjtë të qytetit. Jerusalemi që nga kjo datë deri në dhjetor 1917 do të mbetej plot katër shekuj nën administrimin osman.", "42cf2ec1"]},
"OLAYLAR_EK5:1517-01-02:0":{"b": ["Hyrja e Sulltan Selimi Javuzit në Gazë dhe drejtimi drejt shkretëtirës së Sinait", "2106bfc7"], "d": ["Pas disfatës së Xhanbirdi Gazaliut në Han Junus (21 dhjetor 1516), Gaza ishte në duart e pararojës. Padishahu më 2 janar 1517 hyri në Gazë, u takua aty me Sinan Pashën, në krye të pararojës, dhe ushtria bëri përgatitjet e fundit për kalimin në Egjipt. Nëpër shkretëtirën pa ujë të Katjas (Sinait), nga Gaza deri në Salihije, do të bëheshin tetë etapa dhe uji do të mbartej me deve. Ky kalim është faza më e rrezikshme dhe logjistikisht më e vështirë e fushatës.", "5c3d7bc1"]},
"OLAYLAR_EK5:1517-01-24:0":{"b": ["Marrja e Suezit — porta drejt Detit të Kuq", "05f3324e"], "d": ["Me hyrjen e njësive osmane në Kajro pas fitores së Ridanijes, edhe Suezi, në skajin verior të Detit të Kuq, kaloi nën administrimin osman. Ky port-arsenal, prej nga memlukët dërgonin flotë në Oqeanin Indian, u bë baza e politikës jugore që do të zhvillohej kundër Portugalisë. Suezi është gryka veriore e vijës ku tre shekuj më vonë do të hapej kanali.", "501facb1"]},
"OLAYLAR_EK5:1517-01-24:1":{"b": ["Hyrja e parë e njësive osmane në Kajro", "0a3f4f4d"], "d": ["Ditën pas fitores së Ridanijes ushtrive osmane iu lejua të hynin në Kajro dhe më 24 janar njësitë u vendosën në qytet. Por kjo hyrje nuk do të thoshte kontroll i plotë i qytetit; Tomanbeu ishte tërhequr në Egjiptin e Epërm dhe rezistenca memluke ende nuk ishte thyer. Pushtimi i Kajros do të përfundonte jo brenda një dite, por në një proces të përgjakshëm që do të zgjaste me javë.", "32d9401c"]},
"OLAYLAR_EK5:1517-01-27:0":{"b": ["Sulmi i befasishëm i Tomanbeut mbi Kajro dhe luftimet tri ditore në rrugë", "b83b6ce6"], "d": ["Tomanbeu, i tërhequr në Egjiptin e Epërm, natën e 27-28 janarit, me rreth shtatë mijë veta që kishte pranë, hyri papritur në Kajro, nisi rezistencën brenda qytetit dhe i la njësitë osmane në pozitë shumë të vështirë. Në përleshjet e ashpra tri ditore në rrugë, memlukët mbajtën përkohësisht pjesën më të madhe të qytetit. Rezistenca mundi të thyhej vetëm me hyrjen në veprim të artilerisë osmane dhe të forcave përforcuese.", "98838d21"]},
"OLAYLAR_EK5:1517-02-08:0":{"b": ["Hyrja e Xhanbirdi Gazaliut në shërbimin osman", "a94ea459"], "d": ["Ish-emiri memluk Xhanbirdi Gazaliu, që pas Ridanijes u tërhoq në Salihije, iu drejtua padishahut dhe kërkoi falje (aman). Sulltan Selimi Javuz, duke menduar se do të ishte i dobishëm për vendosjen e rendit në Egjipt dhe Siri, e pranoi në shërbim. Kjo zgjedhje është shembulli i parë i madh i politikës osmane për t'i përfshirë kuadrot memluke në sistem në vend që t'i likuidonte.", "847c1e81"]},
"OLAYLAR_EK5:1517-02-15:0":{"b": ["Hyrja ceremoniale e Sulltan Selimi Javuzit në Kajro dhe leximi i hytbesë", "6d98080c"], "d": ["Pas shtypjes së përleshjeve në rrugë, padishahu më 15 shkurt 1517 hyri në Kajro me një ceremoni shumë madhështore dhe në xhami u lexua hytbeja në emrin e tij. Leximi i hytbesë në Kajro në emrin e sulltanit osman është shpallja se sundimi memluk, që vazhdonte që nga viti 1250, kishte marrë fund juridikisht. Kjo datë konsiderohet çasti simbolik i përfundimit të pushtimit de fakto të Egjiptit.", "3f8589a3"]},
"OLAYLAR_EK5:1517-03-30:0":{"b": ["Kapja e sulltanit të fundit memluk, Tomanbeut, në Terruxhe", "7058e6ad"], "d": ["Tomanbeu, që pasi la Kajron u fsheh në deltën e Nilit, u denoncua nga beduinët që i kishin dhënë strehë dhe u kap në krahinën e Terruxhes. Kapja e tij e zhduku qendrën e organizuar të rezistencës memluke. Sulltani i fundit pas kësaj do të mbahej katërmbëdhjetë ditë në duart e osmanëve.", "5fc98f13"]},
"OLAYLAR_EK5:1517-04-13:0":{"b": ["Ekzekutimi i Tomanbeut në Bab Zuvejle dhe fundi i Shtetit Memluk", "ad9820be"], "d": ["Katërmbëdhjetë ditë pas kapjes, Tomanbeu u var në portën e njohur të Kajros, Bab Zuvejle; trupi i tij më pas u varros në medresenë që kishte ndërtuar xhaxhai i tij. Kështu Shteti Memluk, që sundonte Egjiptin dhe Sirinë që nga viti 1250, hyri zyrtarisht në histori. Me thyerjen e rezistencës, edhe qytete të Egjiptit të Epërm (Said) si Asjuti dhe Asuani u lidhën me administrimin osman.", "96555946"]},
"OLAYLAR_EK5:1517-04-18:0":{"b": ["Sulmi i flotës portugeze mbi Xhidë dhe mbrojtja nga Selman Reisi", "52322cf5"], "d": ["Flota portugeze, e përbërë nga rreth tridhjetë galera dhe galeona, sulmoi Xhidën; Selman Reisi, duke drejtuar mbrojtjen e qytetit, e pengoi armikun të zbarkonte dhe fundosi disa anije portugeze. Kjo mbrojtje pengoi që porti i Mekës, e si rrjedhim edhe rruga e haxhit, të binte në duart e një shteti të krishterë. Xhida pas pak muajsh, me betimin e besnikërisë (bejat) të Hixhazit, do të përfshihej zyrtarisht në administrimin osman.", "a480f1f5"]},
"OLAYLAR_EK5:1517-05-19:0":{"b": ["Marrja në dorëzim e Aleksandrisë me flotë — përfundimi i pushtimit të Egjiptit", "386878fe"], "d": ["Plot katër muaj pas Ridanijes dhe tridhjetë e gjashtë ditë pas ekzekutimit të Tomanbeut, me ardhjen në port të flotës osmane nën komandën e Xhafer Beut, Aleksandria kaloi nën administrimin osman; po në atë proces u lidhën edhe portet e deltës si Rashidi dhe Damieta. Fakti që ky port i madh i Egjiptit në Mesdhe u mor muaj pas rënies së Kajros dhe jo nga toka, por nga deti, tregon qartë se pushtimi nuk u përfundua me një betejë të vetme, por krahinë pas krahine. Aleksandria pas kësaj do të bëhej porti jetik që lidhte Stambollin me Kajron. Vende të tjera që u bashkuan në të njëjtën datë: Rashidi (Rosetta).", "52187c14"]},
"OLAYLAR_EK5:1517-07-06:0":{"b": ["Bashkimi pa luftë i Hixhazit: betimi i besnikërisë i Ebu Numejjit, të birit të Sherifit të Mekës", "c13b98c7"], "d": ["Sulltan Selimi Javuz fillimisht kishte menduar të dërgonte ushtri për të marrë Mekën me rrethinat, por, kur emiri i Mekës, sherif Berekati, njoftoi nënshtrimin, hoqi dorë nga kjo. Djali dymbëdhjetëvjeçar i Berekatit, Ebu Numejji, erdhi në Kajro me dhuratat e të atit dhe me çelësat e Mekës dhe u pranua përpara padishahut. Kështu Hixhazi iu bashkua Osmanëve jo si pasojë automatike e Ridanijes, por pesë muaj e gjysmë më vonë, pa u shkrepur asnjë plumb, me paqe dhe me anë të betimit të besnikërisë. Vende të tjera që u bashkuan në të njëjtën datë: Taifi. Vendbanime të tjera që u humbën në të njëjtën datë: Hurma (lindja e Taifit), Rabigu, Bedri.", "74c58fb7"]},
"OLAYLAR_EK5:1517-07-12:0":{"b": ["Pranimi i titullit Hadim ul-Haremejn dhe hytbeja në Medinë", "63b32b59"], "d": ["Pas pritjes së dytë të delegacionit të Mekës, Sulltan Selimi Javuz mori zyrtarisht përsipër mbrojtjen e Haremejnit dhe filloi të përdorte titullin 'hadim ul-Haremejn esh-Sherifejn' (shërbëtor i dy vendeve të shenjta). Sherif Berekati, duke veshur hil'atin që iu dërgua, urdhëroi të lexohej hytbeja në emër të padishahut; me shkuarjen në Stamboll edhe të delegacionit të Medinës, emirati i Berekatit u konfirmua me berat. Padishahu, duke u dërguar banorëve të Haremejnit dyqind mijë monedha ari dhe ushqime të bollshme, nisi traditën e surres që do të përsëritej çdo vit. Vende të tjera që u bashkuan në të njëjtën datë: Jenboja, Tabuku.", "3b3bfd8f"]},
"OLAYLAR_EK5:1517-08-28:0":{"b": ["Hyrja e Selman Reisit në shërbimin osman dhe kalimi i politikës së Detit të Kuq", "771da99a"], "d": ["Selman Reisi, që mbrojti Xhidën kundër portugezëve, erdhi në Kajro dhe u paraqit përpara Sulltan Selimit Javuz; ndonëse për ca kohë u mbajt, në vitin 1519 u thirr në Stamboll dhe u zotua të përgatiste tridhjetë galera dhe disa galiota kundër kërcënimit portugez. Ky takim është fillimi i kalimit të politikës së Detit të Kuq dhe Oqeanit Indian nga trashëgimia memluke dhe i lidhjes së saj drejtpërdrejt me Stambollin. Osmanët tashmë, përveç se ishin një shtet mesdhetar, ishin edhe një fuqi që ndiqte politikë oqeanike.", "c87580bd"]},
"OLAYLAR_EK5:1517-09-10:0":{"b": ["Largimi i Sulltan Selimit Javuz nga Kajro dhe bejlerbejllëku i Hajër Beut", "8cd4fb23"], "d": ["Sulltan Selimi Javuz, që qëndroi afro tetë muaj në Egjipt dhe vendosi rendin administrativ, financiar dhe ushtarak, u largua nga Kajro; ish-naibi i Halepit, Hajër Beu, që në Mexh Dabik, duke tërhequr krahun e majtë, përshpejtoi disfatën memluke, si bejlerbeu i parë osman i Egjiptit filloi të qeveriste nga Kal'at ul-Xhebeli. Zgjedhja e një valiu me origjinë memluke ishte politikë e vetëdijshme tranzicioni, që siguronte që administrimi i ri të mos u dukej i huaj banorëve vendas. Padishahu, në rrugën e kthimit, mori me vete në Stamboll halifin e fundit abasid Mutavakkil III dhe artizanët e dijetarët e shquar të Egjiptit.", "c2b3bc7e"]},
"OLAYLAR_EK5:1517-09-11:0":{"b": ["Fundi i halifatit abasid të Kajros — rrëfimi i 'ceremonisë së dorëzimit'", "1d357640"], "d": ["Sulltan Selimi Javuz, pasi pushtoi Egjiptin, e solli me vete në Stamboll halifin e fundit Mutavakkil III-Alellah, të zënë rob në Mexh Dabik; kështu mori fund halifati abasid i Kajros, që që nga viti 1261 vazhdonte pa kompetenca nën hijen e sulltanëve memlukë. Nga ana tjetër, rrëfimi i njohur se halifati iu dorëzua Javuzit me ceremoni zyrtare në Ajasofje shfaqet për herë të parë në fund të shekullit XVIII në veprën e d'Ohssonit dhe nuk gjendet në asnjë nga burimet e periudhës së Javuzit. Enciklopedia Islame e TDV-së, meqë nuk ka burim origjinal që e dokumenton ceremoninë, e konsideron rrëfimin të trilluar; por shënon gjithashtu se për kalimin e halifatit sipas sheriatit nuk kishte nevojë për një ceremoni të tillë dorëzimi.", "86efdf28"]},
"OLAYLAR_EK5:1518-01-01:0":{"b": ["Erzurumi iu bashkua administrimit osman — u thye ndikimi safavid në Anadollin Lindor", "78d1be02"], "d": ["Megjithëse pas fitores së Çalldiranit (1514) ndikimi osman në krahinë u rrit, pushtimi i plotë i Erzurumit u vonua deri në thyerjen e ndikimit iranian; qyteti iu bashkua administrimit osman vetëm pas fushatës së Egjiptit, në vitet 1518-19. Erzurumi në vitin 1502, kur Shah Ismaili i dha fund Bejlikut Akkojunlu, kishte hyrë nën sundimin safavid; kjo periudhë gjashtëmbëdhjetëvjeçare u mbyll kështu. Në vitin 1534, gjatë Fushatës së Dy Irakëve, do të krijohej Bejlerbejllëku i Erzurumit. Midis viteve 1518-1519, së bashku me krahinën e Erzurumit, edhe Ashkalja iu bashkua administrimit osman (dita e pakonfirmuar).", "41e2822f"]},
"OLAYLAR_EK5:1519-03-01:0":{"b": ["Fillimi i kryengritjeve xhelali: kryengritja e Shejh Xhelalit nga Bozoku", "99bd8a99"], "d": ["Në krahinën e Bozokut, një person i quajtur Shejh Xhelal, duke shpallur veten mehdi, u ngrit në kryengritje rreth Tokatit; megjithëse kryengritja u shtyp, emri i tij për një shekull u bë emërtim për të gjitha lëvizjet e banditizmit dhe të kryengritjes në Anadoll. Xhelalizmi, në fund të shekullit XVI, duke u bashkuar me shpërbërjen e rendit të timarit dhe me presionin demografik, u shndërrua në problemin më të gjatë të sigurisë së brendshme të perandorisë. Kryengritjet çuan në Anadoll në shpërngulje masive të quajtura 'arratia e madhe'.", "ec33f73b"]},
"OLAYLAR_EK5:1519-09-01:0":{"b": ["Lidhja e Algjerisë me Shtetin Osman", "b8eba4c1"], "d": ["Hajreddin Reisi, që rezistonte kundër presionit spanjoll në Afrikën Veriore, për t'u mbajtur iu drejtua Stambollit, ia ofroi Algjerinë padishahut dhe hytbeja u lexua në emër të Sulltan Selimit Javuz. Kështu Algjeria iu bashkua zyrtarisht tokave osmane dhe Hajreddinit, me titullin bejlerbej, iu dërguan ushtarë e topa. Kjo lidhje hodhi themelet e sundimit detar osman në Mesdheun Perëndimor që do të zgjaste me shekuj. Vende të tjera që u bashkuan në të njëjtën datë: Konstantina, Cherchell, Medea (Titteri), Setifi.", "42dac5d2"]},
"OLAYLAR_EK5:1520-09-21:0":{"b": ["Vdekja e Sulltan Selimit Javuz në Çorlu", "9fe83744"], "d": ["Selimi I, që për tetë vjet e rriti territorin e shtetit më shumë se dyfish, më 18 korrik 1520 u nis nga Stambolli për një fushatë të re; për shkak të një tumori të madh që i doli në shpinë, nuk mundi të shkonte përtej Çorlusë. Megjithë ndërhyrjen e mjekëve, sëmundja u rëndua dhe, pas një mjekimi pa shpresë dymujor, vdiq aty më 8-9 sheval 926 (21-22 shtator 1520). Me Çalldiranin, Mexh Dabikun dhe Ridanijen ai kishte ndalur Iranin, kishte zhdukur Shtetin Memluk dhe u kishte sjellë Osmanëve halifatin dhe mbrojtjen e Haremejnit. Pas tij la vetëm një djalë: Sulejmanin.", "39cccc63"]},
"OLAYLAR_EK5:1521-01-01:0":{"b": ["Hyrja e ishullit të Nikarias (Ikarias) nën administrimin osman", "6afa972b"], "d": ["Nikaria, mes Samosit dhe Kiosit, nga viti 1481 deri më 1521 ishte nën administrimin e Kalorësve të Shën Gjonit të Rodosit; periudha e parë osmane në ishull filloi më 1522 dhe zgjati deri më 1822. Në këtë periudhë, për mbledhjen dhe pagesën e taksave përgjigjej kajmekami; si në ishujt e tjerë të Egjeut, edhe këshilli vendor i pleqve (demogerontia) vazhdoi të ekzistonte dhe herë pas here u përplas me administratën osmane.", "7c6cc486"]},
"OLAYLAR_EK5:1522-01-01:0":{"b": ["Aneksimi i vendit të Dulkadirëve — ejaleti i Dulkadirit me qendër në Marash", "595c3c30"], "d": ["Vendi i Dulkadirëve, që pas disfatës së Turnadagut të vitit 1515 vazhdoi si bejllëk vartës i osmanëve, pas vrasjes në Artukova të Shehsuvaroglu Ali Beut bashkë me fëmijët, iu bashkua drejtpërdrejt tokave osmane dhe u bë ejalet me qendër Marashin. Zona Bozok e bejllëkut iu lidh administrimit osman si sanxhak më vete. Kështu u mbyll periudha dulkadire gati dyshekullore e Marashit, Elbistanit, Göksunit, Gürünit, Zamantëse dhe Darendes; bejllëku tampon në kufirin mamluk u zhduk plotësisht.", "9b819db9"]},
"OLAYLAR_EK5:1522-05-29:0":{"b": ["Pushtimi i Kninit", "a46d3117"], "d": ["Me inkursionet e sanxhakbeut të Bosnjës, Gazi Husrev Beut, në vitet 927-928 (1521-1522), një varg kështjellash venedikase, me Kninin, Skradinin dhe Ostrovicën në krye, kaluan nën administrimin osman; kufiri u shty përtej vargut të dytë malor. Ky varg pushtimesh hodhi bazën e sanxhakut të Dalmacisë, që pesëmbëdhjetë vjet më vonë do të plotësohej me marrjen e Klisit.", "21f9fbd5"]},
"OLAYLAR_EK5:1523-01-05:0":{"b": ["Tërheqja e kalorësve: dorëzimi i Bodrumit, Kosit dhe Dymbëdhjetë Ishujve", "ea01666e"], "d": ["Sipas kushteve të dorëzimit të Rodosit, kalorësit e Shën Gjonit boshatisën jo vetëm qendrën e ishullit, por të gjitha pozicionet që kishin mbajtur për dyqind vjet. Kështu kështjella e Bodrumit (Saint Pierre) në bregun anadollak dhe ishujt Kos, Kalimnos dhe Leros kaluan pa përleshje nën administrimin osman. Me këtë dorëzim, të përfunduar dy javë pas rënies së Rodosit, prania latine në qoshen juglindore të Egjeut mori fund plotësisht.", "bcbe8fa8"]},
"OLAYLAR_EK5:1524-01-01:0":{"b": ["Kryengritja e Ahmed Pashës Tradhtar në Egjipt", "b18bb805"], "d": ["Ahmed Pasha, që priste postin e vezirit të madh e u dërgua vali në Egjipt, duke e shpallur veten në Kajro 'al-Melik al-Mansur sulltan Ahmed', njoftoi pavarësinë. Kryengritja u shtyp shpejt dhe pashai u vra, por ngjarja tregoi brishtësinë e kontrollit qendror në ejaletin më të pasur të perandorisë. Pas kësaj Ibrahim Pasha shkoi në Egjipt dhe urdhëroi përgatitjen e Kanunamesë së njohur të Egjiptit, që riorganizoi administrimin e ejaletit.", "35eb542c"]},
"OLAYLAR_EK5:1528-01-01:0":{"b": ["Aneksimi i Bosnjës Veriore: Jajce dhe Banja Lluka", "8ec86cfa"], "d": ["Kur pas Mohaçit u shemb vija mbrojtëse hungareze, sanxhakbeu i Bosnjës, Gazi Husrev Beu, marshoi nëpër luginën e Vrbasit dhe mori kështjellat e fundit të Bosnjës që i kishin mbetur mbretërisë hungareze. Me rënien e Jajces dhe Banja Llukës, ejaleti i Bosnjës në veri u mbështet te lumi Sava dhe lindi fronti i Kroacisë. Banja Lluka brenda pak kohe u bë qendra e dytë e ejaletit.", "1f634005"]},
"OLAYLAR_EK5:1529-09-08:0":{"b": ["Marrja e Budës dhe dhënia e saj Zapolyait", "fba4f89b"], "d": ["Në rrugën e fushatës së Vjenës, ushtria osmane rrethoi dhe rimori Budën, që kishte rënë në duart e Ferdinandit, dhe ia dorëzoi qytetin mbretit hungarez János Szapolyai nën mbrojtjen osmane. Kështu për Hungarinë, në rivalitetin habsburgo-osman, u krijua modeli i një mbretërie vasale tampon. Ky rend do të zgjaste deri në vitin 1541; pas vdekjes së Zapolyait, Buda do të bëhej drejtpërdrejt ejalet osman.", "6777eb1d"]},
"OLAYLAR_EK5:1532-04-25:0":{"b": ["Kanuniu doli në fushatën gjermane — sfidë ndaj Karlit V", "7c3d7055"], "d": ["Pasi rrethimi i Vjenës mbeti pa rezultat dhe Ferdinandi e rrethoi përsëri Budën, padishahu, këtë herë për ta tërhequr vetë perandorin Karli V në betejë fushore, u nis nga Stambolli. Ushtria në gusht do të vonohej nga rezistenca e kalasë së vogël të Güns-it dhe, meqë perandori nuk doli në luftë, fushata do të mbetej e kufizuar me sulme. Fushata përgatiti terrenin për paqen e parë me Habsburgët vitin pasues.", "c3e6e378"]},
"OLAYLAR_EK5:1532-08-05:0":{"b": ["Fushata gjermane dhe rrethimi i Güns-it (Kőszeg)", "8aec937a"], "d": ["Kanuniu, me synim ta detyronte Karlin V në një betejë fushore, marshoi me ushtrinë mbi Austri; kalaja e vogël e Güns-it, duke rezistuar njëzet e pesë ditë, e vonoi përparimin e ushtrisë. Meqë perandori nuk doli në luftë, akënxhinjtë goditën rrethinat e Vjenës dhe, me avancimin e stinës, u kthyen. Fushata nuk solli fitime territoriale, por, duke i vënë Habsburgët në tryezë, përgatiti terrenin për paqen e vitit pasues.", "792fc40e"]},
"OLAYLAR_EK5:1533-01-01:0":{"b": ["Traktati i Stambollit — paqja e parë me Habsburgët", "b085767a"], "d": ["Padishahu, duke pritur ambasadorin e Ferdinandit, Kornelin, pranoi armëpushimin dhe doli në dritë teksti i parë zyrtar i paqes midis Osmanëve dhe Austrisë. Me traktatin, Ferdinandi pranoi të paguante taksë vjetore në këmbim të tokave hungareze që mbante, dhe arkiduka i Austrisë në protokoll u konsiderua i barabartë me vezirin e madh. Ky status i pabarabartë ishte shprehja e hapur e pretendimit për epërsi të diplomacisë osmane në shekullin XVI.", "e51c434d"]},
"OLAYLAR_EK5:1534-06-01:0":{"b": ["Marrja e Karsit dhe hapja e kufirit verilindor", "742e3101"], "d": ["Teksa kolona pararojë e Fushatës së Irakejnit drejtohej nga Erzurumi drejt lindjes, kështjella e Karsit, që ishte në duart e atabegllëkut gjeorgjian dhe e rrënuar që nga Timuri, u mor në dorëzim pa hasur rezistencë. Qyteti konsiderohej çelësi i portës veriore që hapej drejt Iranit, sepse zotëronte kalimin mes harkut të Araksit dhe Çëldërit. Ky fitim u bë hallka e parë e bejlerbejllëkut të Karsit, që do të krijohej tridhjetë vjet më vonë, dhe e vijës së Kaukazit.", "b3a27cc8"]},
"OLAYLAR_EK5:1534-07-13:0":{"b": ["Hyrja e parë në Tabriz — hapja e Fushatës së Irakejnit", "cf7ed4e3"], "d": ["Ibrahim Pasha, që si serdar ekrem lëvizte përpara, hyri pa hasur rezistencë në Tabriz, kryeqytetin safavid, pasi Shah Tahmaspi i shmangej betejës fushore dhe u tërhoq në thellësi. Edhe Sulejmani Ligjvënës arriti në qytet në shtator; por për shkak të ardhjes së dimrit dhe zgjatjes së tepërt të linjës së furnizimit, ushtria u drejtua nga Bagdadi dhe Tabrizi nuk mundi të mbahej gjatë. Qyteti, i marrë për herë të dytë pas Çalldiranit, u bë vendi ku osmanët mësuan se në lindje ishte e lehtë të shtije në dorë, por e vështirë të mbaje.", "a303a9e4"]},
"OLAYLAR_EK5:1534-09-22:0":{"b": ["Pushtimi i Tunisit nga Barbarosa", "d8754216"], "d": ["Kapudan pashai Barbaros Hajreddin Pasha, pasi goditi me flotë brigjet e Italisë, u drejtua drejt Tunisit, e detyroi sundimtarin hafsid Mulej Hasan të ikte dhe hyri në qytet. Marrja e Tunisit, me pozitën që kontrollonte ngushticën e Siçilisë, e ktheu menjëherë ekuilibrin e forcave në Mesdheun Perëndimor në favor të Osmanëve. Por ky sundim nuk do të zgjaste shumë; Karli V vitin pasues do të përgjigjej me një flotë të madhe.", "b0aeb30e"]},
"OLAYLAR_EK5:1535-07-21:0":{"b": ["Humbja e Tunisit ndaj Karlit V", "a691f0f8"], "d": ["Karli V, me një fushatë të madhe të mbështetur nga flotat gjenoveze dhe papnore, pasi rrëzoi La Goulette-n (Halkul-Vad), mori Tunisin dhe e riktheu në fron Mulej Hasanin nën mbrojtjen spanjolle. Duke u vendosur një garnizon spanjoll në qytet, përparimi osman në Mesdheun Qendror u ndal përkohësisht. Pushtimi përfundimtar i Tunisit do të ishte i mundur vetëm dyzet vjet më vonë, në vitin 1574.", "cbb995cd"]},
"OLAYLAR_EK5:1536-01-01:0":{"b": ["Operacioni i Gazi Husrev Beut përgjatë Savës: Bosanski Brod dhe Jasenovac", "3740ec83"], "d": ["Pas marrjes së Jajces dhe Banja Llukës më 1528, kështjellat përgjatë lumit Sava mbetën edhe për një farë kohe në kufirin kroato-sllavon të lidhur me kurorën habsburge. Gazi Husrev Beu, që më 1536 u bë për të tretën herë sanxhakbe i Bosnjës, po atë vit, ndërsa merrte Požegën dhe rrethinat, i bashkoi me administrimin osman edhe kështjellat e Brodit dhe Jasenovacit në bregun e Savës. Kështu kufiri verior i Bosnjës u mbështet te Sava; zona u plotësua dy vjet më vonë me marrjen e Dubicës.", "415f0592"]},
"OLAYLAR_EK5:1536-03-15:0":{"b": ["Ekzekutimi i Makbul Ibrahim Pashës", "348aa7b8"], "d": ["Ibrahim Pasha, që shërbeu trembëdhjetë vjet si vezir i madh, miku më i ngushtë i Kanuniut dhe njeriu i dytë de fakto i shtetit, u ftua në saraj për iftar dhe, pa iu paraqitur asnjë arsye, u ekzekutua me mbytje. Sjellja e tij gjatë fushatës së Dy Irakëve, përdorimi i titullit 'serasker sulltan' dhe ekuilibrat brenda sarajit konsiderohen ndikues në vdekjen e tij. Ekzekutimi është një kthesë që tregon se në qeverisjen qendrore osmane vezirët e mëdhenj nuk kishin siguri absolute.", "a780f3de"]},
"OLAYLAR_EK5:1537-03-12:0":{"b": ["Pushtimi i Kalasë së Klisit dhe krijimi i sanxhakut të Dalmacisë", "6ffd4ebf"], "d": ["Qehajai i Gazi Hysrev Beut, Murad Beu, i konvertuar me origjinë kroate, ia mori Venedikut Kalanë strategjike të Klisit, menjëherë në veri të Splitit. Menjëherë pas pushtimit, Klisi u bë qendra e një sanxhaku të ri dhe e një kazaje që përfshinte rrethinat; kufijtë e këtij sanxhaku vizatuan në masë të madhe kornizën e Kroacisë osmane. Ky pushtim, pesëmbëdhjetë vjet pas Kninit, plotësoi skeletin administrativ të brendësisë së Dalmacisë.", "8338f8aa"]},
"OLAYLAR_EK5:1537-08-25:0":{"b": ["Rrethimi i Korfuzit dhe lufta me Venedikun", "11af95bd"], "d": ["Pas fushatës së Pulias (Apulia), ushtria osmane zbarkoi ushtarë në Korfuz dhe rrethoi kalanë e fortë venedikase të ishullit. Për shkak të terrenit të thepisur të kalasë, humbjeve të rënda dhe kushteve të stinës, bllokada u hoq më 6 shtator dhe ushtria u tërhoq. Megjithëse rrethimi mbeti pa rezultat, lufta e hapur me Venedikun përfundoi me bashkimin e shumë ishujve të Egjeut dhe të Adriatikut me Osmanët dhe vitin pasues me fitoren e Prevezës.", "f023c2b9"]},
"OLAYLAR_EK5:1537-10-01:0":{"b": ["Fushata e Barbarosit në Egje: marrja e ishujve të drejtuar drejtpërdrejt nga Venediku", "1b32ed96"], "d": ["Flota që u kthye nga rrethimi i Korfuzit, duke përfituar nga fakti që Venedikut i ishte shpallur luftë, mori në dorëzim njërin pas tjetrit në Egje ishujt që nuk vareshin nga dukati, por drejtpërdrejt nga Venediku. Egina u shtie në dorë pas një qëndrese të ashpër, Astipalia në duart e familjes Querini si dhe Karpathosi e Kasosi u dorëzuan, dhe Patmosi nën administrim manastiri e pranoi mbrojtjen osmane. Dukati i Naksosit u la në vend duke iu vënë haraç; aneksimi i tij do të priste vitin 1566.", "632f4747"]},
"OLAYLAR_EK5:1538-08-01:0":{"b": ["Fushata e Barbarosit në Egjeun Verior: marrja e Skirosit dhe Sporadeve Veriore", "20ab688e"], "d": ["Në rrugën drejt Prevezës, flota mori në dorëzim njërin pas tjetrit ishujt e Egjeut Verior që pas pushtimit të Stambollit i ishin strehuar Venedikut. Kështu Skirosi në veri të Eubesë dhe Skiathosi, Skopelosi e Alonisosi, që zotëronin grykën e gjirit të Selanikut, hynë nën administrimin osman. Me këta ishuj u mbyll boshllëku i fundit i Egjeut Verior, që, megjithëse Eubea ishte marrë më 1470, kishte mbetur edhe gjashtëdhjetë e tetë vjet në duart e Venedikut.", "2a9ea08f"]},
"OLAYLAR_EK5:1538-08-03:0":{"b": ["Marrja e Adenit dhe aneksimi i bregdetit të Jemenit", "e7d46d8f"], "d": ["Flota e nisur nga Suezi për fushatën e Indisë, ngaqë pa e siguruar Detin e Kuq nuk mund të dilej në oqean, fillimisht u drejtua nga bregu i Jemenit. Hadëm Sulejman Pasha hyri në portin e Adenit më 3 gusht 1538; sundimtari tahirid Amir b. Davud, që anonte nga portugezët, u soll te porta e kapedanit dhe u ekzekutua, dhe në qytet u la një garnizon prej 500 vetash. Gjatë së njëjtës fushatë u morën në dorëzim edhe Moka dhe ishujt Kameran e Farasan që zotëronin ngushticën, dhe u hodh themeli i bejlerbejllëkut të Jemenit. Kështu Shteti Osman për herë të parë zotëroi të gjithë bregun verior të Bab-el-Mandebit; ndërsa Sana dhe zonat e brendshme do të duhej të prisnin edhe nëntë vjet.", "495e1991"]},
"OLAYLAR_EK5:1538-09-01:0":{"b": ["Fushata e Moldavisë dhe aneksimi i krahinës së Buxhakut (Benderit)", "90a88a56"], "d": ["Në fushatën kundër vojvodës së Moldavisë, Petru Rareş, që nuk përmbushte detyrimet ndaj Osmanëve, u pushtua Suçava, kurse qytetin e Jashit e plaçkiti hani i Krimesë, Sahib Giraj. Padishahu vendosi në vojvodat Stefan Lëkundësin (Stefan Lăcustă) dhe së bashku me Benderin aneksoi drejtpërdrejt në tokat osmane krahinën e Buxhakut (Besarabia Jugore). Ky aneksim u bë një nga hallkat që i shndërruan brigjet veriperëndimore të Detit të Zi në det të brendshëm osman. Moldavia ishte tashmë vojvodat vartës i Osmanëve; kjo fushatë nuk ia mori tokën një shteti të huaj, por vetëm ia hoqi vojvodës administrimin e brendshëm të Benderit dhe të Buxhakut dhe e lidhi drejtpërdrejt me padishahun; pjesa tjetër e vojvodatit e ruajti statusin vartës. E njëjta strukturë do të përsëritej në vitin 1484 në Kili dhe Akkerman dhe në vitin 1713 në Hotin: kalatë kufitare drejtpërdrejt, tokat e brendshme vartëse.", "96376de1"]},
"OLAYLAR_EK5:1540-11-01:0":{"b": ["Marrja me traktat e Nauplias (Anabolu)", "104d0937"], "d": ["Lufta trevjeçare me Venedikun pas Prevezës përfundoi kur republika pranoi të lëshonte dy kështjellat e fundit në More. Nauplia dhe Monemvasia (Benefşe), që nuk mundën të merreshin me rrethim, iu dorëzuan osmanëve në tryezë, bashkë me treqind mijë dukate dëmshpërblim lufte. Kështu gadishulli i Moresë u bashkua i tëri, pa mbetur asnjë gjurmë këmbe venedikase.", "4a26ee03"]},
"OLAYLAR_EK5:1543-01-01:0":{"b": ["Hyrja e Szegedit nën administrimin osman dhe formimi i livasë së Szegedit", "019aa000"], "d": ["Pas vendosjes së plotë të administrimit osman në Budin më 1541, paria e Szegedit e përqafoi sundimin e Ferdinandit I dhe u përgatit për mbrojtje të armatosur. Bejlerbeu i Budinit, Kyçyk Bali Pasha, në fillim të vitit 1543 i thirri pranë vetes drejtuesit e qytetit dhe i ekzekutoi me akuzën e tradhtisë, pastaj dërgoi një njësi për të shtënë në dorë qytetin. Në këtë kohë u formua livaja e Szegedit dhe sanxhakbe i parë u emërua i biri i Bali Pashës, Dervish Beu; livaja në fillim shtrihej mes Danubit dhe Tisës.", "8293a839"]},
"OLAYLAR_EK5:1543-07-21:0":{"b": ["Pushtimi i Valpos, Siklósit dhe Pecsit", "2ca030a3"], "d": ["Objektivi i parë i fushatës së Hungarisë, e nisur dy vjet pas aneksimit të Budinit, ishte sigurimi i krahut jugor të ejaletit të ri mes Dravës dhe Danubit. Pasi u morën kështjellat e Valpos dhe Siklósit, u dorëzua Pecsi, qendra e Baranjës. Qyteti do të bëhej qendra më e populluar dhe më e ndërtuar e Hungarisë osmane, dhe prej tij historiani Ibrahim do të merrte emrin Peçevi.", "aacf43d3"]},
"OLAYLAR_EK5:1543-08-10:0":{"b": ["Pushtimi i Estergomit dhe i Székesfehérvárit (İstolni Belgrad)", "efca9e05"], "d": ["Në fushatën e Hungarisë, ku doli vetë Kanuniu, pas një rrethimi dy javë e gjysmë, Estergomi, qendra fetare dhe qyteti i kryepeshkopatës i Mbretërisë së Hungarisë, hyri nën administrimin osman. Më pas u mor edhe Székesfehérvári, qyteti ku kurorëzoheshin mbretërit hungarezë, dhe u plotësua brezi mbrojtës i ejaletit të Budës. Estergomi deri në vitin 1595 do të mbetej në duart osmane si kalaja kyçe e vijës së Danubit.", "93577806"]},
"OLAYLAR_EK5:1544-09-01:0":{"b": ["Brezi mbrojtës verior dhe perëndimor i Budinit: Vác, Hatvan dhe Simontornya", "733ee5ce"], "d": ["Pasi u morën Estergomi dhe Székesfehérvári (İstolni Belgrad), bejlerbeu i Budinit u vu në veprim pa fushatë të padishahut për të plotësuar unazën e kështjellave rreth kryeqytetit. Váci në bërrylin e Danubit, Hatvani, porta e Alföldit, dhe Simontornya në vijën e Siós u morën në dorëzim njëra pas tjetrës. Fitimet e këtij viti të qetë e shndërruan Budinin nga qytet kufitar në qendër ejaleti që do të qëndronte njëqind e dyzet vjet.", "0ca98fa3"]},
"OLAYLAR_EK5:1545-12-26:0":{"b": ["Aneksimi i Basrës dhe dalja në Gjirin e Basrës", "02f87c11"], "d": ["Gjatë pushtimit të Bagdadit (1534), sundimtari i Basrës Rashid b. Megamis i kishte njoftuar bindjen Sulejmanit Ligjvënës dhe më 1538 i kishte dërguar çelësat e qytetit. Kur pasardhësi i tij, Sheik Jahja, u kthye kundër osmanëve, bejlerbeu i Bagdadit, Ajas Pasha, marshoi nga toka, kurse sanxhakbeu i Mosulit me 120 anije nëpër Eufrat; Ajas Pasha hyri në Basrë më 26 dhjetor 1545 dhe qyteti u bë qendër bejlerbejllëku. Ky port në grykën e Shatt-el-Arabit ishte dera nga e cila osmanët dilnin në gjirin që portugezët e kontrollonin nga Hormuzi; me Traktatin e Amasjas të vitit 1555 edhe Irani e njohu këtë gjendje.", "8905782c"]},
"OLAYLAR_EK5:1547-01-01:0":{"b": ["Pushtimi i Sanasë dhe i brendësisë së Jemenit", "d31ded85"], "d": ["Pas Taizit u mor edhe Sanaja dhe i gjithë vendi iu lidh bejlerbejllëkut. Megjithatë, për shkak të gjeografisë së thepisur dhe dallimit të medhhebit, ky sundim nuk ishte kurrë i qetë; Jemeni u bë për osmanët një front që vazhdimisht përpinte ushtarë.", "66968d6d"]},
"OLAYLAR_EK5:1547-02-01:0":{"b": ["Pushtimi i Taizit", "d4509df9"], "d": ["Në Jemen, ku nëntë vjet më parë ishin mjaftuar me rripin bregdetar, ngaqë imamët zejditë po forcoheshin gjithnjë e më shumë në zonën malore të brendshme, forcat e Ozdemir Pashës u ngjitën në rrafshnaltë dhe shtinë në dorë Taizin.", "46b811eb"]},
"OLAYLAR_EK5:1547-06-19:0":{"b": ["Traktati i Stambollit — paqe pesëvjeçare me Habsburgët", "41f81773"], "d": ["Midis Osmanëve dhe Habsburgëve u nënshkrua një paqe me afat pesëvjeçar; Ferdinandi pranoi të paguante 30.000 dukate në vit për tokat hungareze që mbante. Traktati e regjistroi juridikisht gjendjen de fakto të Hungarisë të ndarë në tri pjesë. Sigurimi në këtë mënyrë i frontit perëndimor i dha Kanuniut mundësinë të organizonte fushata të reja kundër Iranit.", "36cfadaa"]},
"OLAYLAR_EK5:1548-07-27:0":{"b": ["Fushata e dytë e Iranit dhe rimarrja e Tabrizit", "e82365df"], "d": ["Në fushatën e ndërmarrë me nxitjen e Elkas Mirzës, vëllait të Shah Tahmaspit që u ngrit kundër tij dhe u strehua në Stamboll, ushtria hyri për herë të dytë në Tabriz. Meqë safavidët përsëri nuk pranuan betejë fushore dhe u tërhoqën duke djegur tokën, në qytet mundi të qëndrohej vetëm pak javë. Fushata e bëri të qartë se Tabrizi nuk mund të mbahej dhe e orientoi strategjinë osmane drejt krijimit të një vije kufitare të qëndrueshme, domethënë drejt fortifikimit të Vanit.", "bb2a7ceb"]},
"OLAYLAR_EK5:1548-08-24:0":{"b": ["Pushtimi i Vanit dhe përcaktimi i qëndrueshëm i kufirit lindor", "fc8f930b"], "d": ["Kështjella e Vanit, e rrethuar gjatë kthimit nga Tabrizi, me pozitën e saj mbi një shkëmb në bregun lindor të liqenit ishte padiskutim çelësi i rajonit dhe pas një rrethimi të shkurtër u dorëzua. Qyteti u bë menjëherë qendër bejlerbejllëku; sanxhakët e Erxhishit, Adilxhevazit dhe Hakkarit iu lidhën atij. Ndryshe nga Tabrizi, Vani u mbajt dhe për katërqind vjet mbeti pozicioni i përhershëm më i përparuar osman në lindje.", "3ca861b4"]},
"OLAYLAR_EK5:1550-01-01:0":{"b": ["Aneksimi i Lahsës dhe Katifit — bregu arab i Gjirit", "f6701e60"], "d": ["Pas marrjes së Basrës u shtie në dorë Katifi, që në bregun perëndimor të gjirit ishte bërë postblloku i përparuar i Portugalisë, dhe bashkë me oazet e Lahsës në brendësi u krijua një bejlerbejllëk i ri. Prej këtej niseshin operacionet drejt Bahreinit dhe Hormuzit. Kështu Shteti Osman pati fjalë njëkohësisht në brigjet e Detit të Kuq dhe të Gjirit të Basrës të gadishullit arab.", "240c0b43"]},
"OLAYLAR_EK5:1550-01-01:1":{"b": ["Humbja e Shehrizorit — beu i Ardelanit, Suhrabi, anoi nga safavidët", "5600efc9"], "d": ["Viset e Shehrizorit, që gjatë Fushatës së Irakejnit (1535) e kishin njohur administrimin osman, drejtoheshin nga emiri i Ardelanit Bige Beu, që qëndronte në kështjellën Zalm. Pas vdekjes së Bige Beut më 1550, i vëllai Suhrabi, që shtiu në dorë kështjellën Zalm dhe u bë zot i bejllëkut, u drejtua nga safavidët dhe doli nga bindja ndaj osmanëve; kështu viset e Shehrizorit dolën nga ndikimi osman. Rajoni u rifitua vetëm gjatë fushatës së Nahiçevanit, më 1554, me rrethimin dhe marrjen e kështjellës Zalm.", "62ddad8a"]},
"OLAYLAR_EK5:1551-01-01:0":{"b": ["Marrja e Ardahanit dhe pellgut të Çëldërit", "14c9eb76"], "d": ["Gjatë luftës që vazhdonte me safavidët, bejlerbeu i Erzurumit u drejtua nga tokat e atabegëve gjeorgjianë në harkun e Kurës dhe ia lidhi administrimit osman Ardahanin dhe rrethinat e Çëldërit. Kështu vija Kars-Ardahan u bashkua dhe u vunë nën kontroll trojet e larta që në verilindje hapeshin drejt Gjeorgjisë. Rendi përfundimtar administrativ i rajonit do të plotësohej me ejaletin e Çëldërit, që do të krijohej njëzet e shtatë vjet më vonë.", "2f8d92cc"]},
"OLAYLAR_EK5:1551-09-07:0":{"b": ["Mehmet Pashë Sokoli kaloi Danubin — fillimi i luftës së Transilvanisë", "38fde931"], "d": ["Për shkak të trazirave që shkaktoi murgu Martinuzzi, kujdestar i mbretit të vogël të Transilvanisë János Zsigmond, dhe lënies së kështjellave të Banatit nga Transilvania Ferdinandit, u pa e nevojshme një fushatë e re; komanda iu dha bejlerbeut të Rumelisë, Mehmet Pashë Sokolit. Ushtria, megjithë përpjekjet e Martinuzzit për ta zvarritur, kaloi Danubin dhe mori Beçen, Beçkerekun, Çanadin dhe Lipën; megjithatë, rrethimi i Temeshvarit u hoq më 16 nëntor për shkak të të ftohtit. Kështu në Hungari u hap një luftë e re osmano-habsburge.", "85071c5e"]},
"OLAYLAR_EK5:1551-11-06:0":{"b": ["Qyteti i Lipovës (Lipës) kaloi në duart e ushtrisë austriake të Castaldos — kështjella u dorëzua më 5 dhjetor", "a0e1ff0d"], "d": ["Lipovën, që Mehmet Pashë Sokoli e kishte marrë në tetor 1551, ushtria e gjeneralit Castaldo e rrethoi më 4 nëntor; dy ditë më vonë qyteti kaloi në duart e austriakëve. Ulama Pasha, me një garnizon prej 5.000 vetash, e mbrojti kështjellën edhe nëntë ditë dhe më 5 dhjetor 1551 doli me marrëveshje. Deri në rënien e Temeshvarit më 1552, Lipova mbeti në duart habsburge.", "22c85b1c"]},
"OLAYLAR_EK5:1552-07-27:0":{"b": ["Forcat e dërguara nga Temeshvari zënë palankat e Banatit Jugor — Versec, Haram, Keve", "edca0921"], "d": ["Pas dorëzimit të Temeshvarit ushtrisë osmane, njësitë e shkëputura nga ushtria rrethuese u drejtuan drejt palankave të vogla të Banatit; sipas rrëfimit të Bánlaky-t, palankat e Versecit, Facsetit, Mehádiás, Csákóvárit, Haramvárit dhe Kevesë u zunë nga këto forca. Kështu edhe Harami në bregun e Danubit kaloi në duart osmane.", "a5906d21"]},
"OLAYLAR_EK5:1552-09-04:0":{"b": ["Pushtimi i Szolnokut dhe dështimi i rrethimit të Egerit", "a7156e8f"], "d": ["Pas marrjes së Temeshvarit, dy ushtritë osmane të bashkuara shtinë në dorë Szolnokun mbi Tisë pothuajse pa përleshje, kur garnizoni mercenar e braktisi kështjellën. Ndërsa kështjella e Egerit, e rrethuar më pas, nuk mundi të merrej përballë qëndresës tridhjetë e tetë ditore të garnizonit prej dy mijë vetash nën komandën e István Dobó-s dhe, kur erdhi dimri, ushtria u tërhoq. Fakti që në të njëjtën fushatë njëra kështjellë ra lehtë kurse tjetra rezistoi, ishte shenja e parë e qartë se në Hungari kufiri nuk përparonte më vetvetiu në favor të osmanëve.", "354ed31f"]},
"OLAYLAR_EK5:1553-02-01:0":{"b": ["Aleanca osmano-franceze — flota franceze nën urdhrin osman", "a8e01b22"], "d": ["Me traktatin e datës 1 shkurt 1553, flota franceze u vu nën urdhrin e flotës osmane; u parashikua operacion i përbashkët në Mesdheun Perëndimor kundër Spanjës. Pas traktatit, Turgut Reisi më 15 qershor 1553 doli në fushatë me dyzet e pesë galera për të mbështetur Francën. Ky ishte traktati i parë zyrtar i aleancës që e çoi terrenin tregtar të kapitulacioneve të vitit 1536 në bashkëpunim ushtarak.", "bfa2fc2d"]},
"OLAYLAR_EK5:1553-10-05:0":{"b": ["Ekzekutimi i shehzade Mustafait në Eregli të Konjas", "dec36858"], "d": ["Shehzade Mustafai, që hyri në çadrën e të atit për t'iu bashkuar ushtrisë së mbledhur për fushatën e Nahçevanit, në çastin kur do të paraqitej përpara tij u përball me xhelatët dhe u vra me mbytje. Vrasja e kandidatit për trashëgimtar, shumë të dashur në ushtri, shkaktoi zemërim të thellë midis jeniçerëve dhe Rustem Pasha u shkarkua nga posti i vezirit të madh. Ngjarja kaloi në letërsi dhe në kujtesën popullore si një nga thyerjet më të diskutuara të politikës osmane për shehzadetë.", "ce2742ae"]},
"OLAYLAR_EK5:1555-01-01:0":{"b": ["Zhvendosja drejt jugut e kufirit të Ibrimit dhe Nubisë", "c57d5d77"], "d": ["Kufiri jugor i bejlerbejllëkut të Egjiptit u zhvendos përtej kataraktës së dytë, kur kështjella e Ibrimit, e ngritur mbi një kep shkëmbor mbi Nil, u fortifikua nga Ozdemir Beu dhe Nubia e Poshtme iu bashkua plotësisht Egjiptit osman. (Në Ibrim organizimi administrativ osman ishte ngritur pas pushtimit të Egjiptit; në hartë Ibrimi tregohet osman që nga viti 1517. Ky vit është i përafërt, burimi nuk jep vit.) Kështjella ishte si pengesë kundër inkursioneve që vinin nga Nubia, ashtu edhe pikë kontrolli e rrugës së arit dhe skllevërve që shkonte në Senar. Njësia mbrojtëse boshnjake e vendosur këtu u bë aq e përhershme sa pasardhësit e saj treqind vjet më pas ndodheshin ende në kështjellë. Për kohën e hyrjes së Ibrimit nën administrimin osman burimet japin dy rrëfime të ndryshme: ndërsa zëri 'Sudan' i TDV-së bashkimin e Nubisë së Poshtme me Egjiptin osman e lidh me operacionin e Ozdemir Pashës në mes të shekullit XVI, zëri 'Nubi' shkruan se zona deri në luginën e Halfës dhe organizimi administrativ në Ibrim u ngritën menjëherë pas pushtimit të vitit 1517. Sanxhaku i Ibrimit më 26 korrik 1573 iu lidh ejaletit të Habeshit.", "cd2c7ae9"]},
"OLAYLAR_EK5:1555-09-27:0":{"b": ["Marrja e Bexhajas (Bougie) nga spanjollët", "49691cda"], "d": ["Bexhaja, që prej dyzet e tre vjetësh ishte në duart e Spanjës dhe e ndante në dysh bregdetin mes Algjerit dhe Konstantinës, pas rrethimit nga toka e deti u dorëzua. Me rënien e kështjellës, bregdeti i odxhakut të Algjerit u bë i pandërprerë deri në Oran. Kjo humbje ngjalli në Spanjë një zemërim aq të madh, saqë komandanti Alonso de Peralta, që dorëzoi kështjellën, u ekzekutua në vendin e tij.", "a030d882"]},
"OLAYLAR_EK5:1559-01-01:0":{"b": ["Bashkimi i Zejlës me Ejaletin e Habeshit", "7bbf369a"], "d": ["Porti i Zejlës, në skajin jugor të ejaletit të Habeshit, në bregun afrikan të Gjirit të Adenit, u lidh me administrimin osman. Ky qytet, dera e Sulltanatit të Adalit drejt detit, ishte pika e fundit e furnizimit për anijet që dilnin jashtë Bab-el-Mandebit. Me bashkimin e Zejlës, kufiri i Shtetit Osman në Afrikë arriti pikën më jugore.", "fe4597b7"]},
"OLAYLAR_EK5:1559-05-30:0":{"b": ["Beteja e shehzadeve në Konja", "1c8de387"], "d": ["Shehzade Bajazidi, që hyri në luftë për fron, me një forcë prej rreth 30.000 vetash erdhi përpara Konjas dhe në përleshjen dyditore u mund nga i vëllai, shehzade Selimi. Bajazidi i shpartalluar, përmes Amasjas, u strehua në Iran, te Shah Tahmaspi. Beteja e shndërroi krizën e trashëgimisë së sulltanatit në vitet e fundit të Kanuniut në një problem të politikës së jashtme.", "d466cfc5"]},
"OLAYLAR_EK5:1560-05-14:0":{"b": ["Fitorja Detare e Xherbës", "c7b905c1"], "d": ["Flota osmane nën komandën e Pijale Pashës, përpara Xherbës, me një manovrë ndarjeje në dysh shpartalloi flotën aleate spanjollo-gjenovezo-malteze të mbledhur për të rimarrë Tripolin. Aleatët humbën pjesën më të madhe të flotës dhe edhe kalaja në ishull ra shpejt. Xherba, pas Prevezës, konsiderohet fitorja e dytë e madhe detare që përforcoi epërsinë osmane në Mesdhe.", "e987b794"]},
"OLAYLAR_EK5:1562-07-23:0":{"b": ["Ekzekutimi i shehzade Bajazitit në Kazvin", "a759de14"], "d": ["Shehzade Bajaziti, që ishte strehuar në Iran, pas pazaresh të gjata iu dorëzua delegacionit osman nga Shah Tahmaspi dhe u vra me mbytje bashkë me katër djemtë e tij. Në këmbim të dorëzimit, safavidët siguruan lëshime të rëndësishme materiale dhe garanci kufitare. Me këtë ekzekutim u hoq pengesa e fundit përpara hipjes së Selimit II në fron dhe u ruajt rendi paqësor i Traktatit të Amasjas.", "cf625eb3"]},
"OLAYLAR_EK5:1566-04-14:0":{"b": ["Marrja e Kiosit (Sakızit) nga gjenovezët", "a4559b96"], "d": ["Kiosi, që prej dyqind vjetësh drejtohej si koloni tregtare e familjes gjenoveze Giustiniani dhe u paguante haraç osmanëve, me arsyetimin se kishte vonuar haraçin dhe u kishte dhënë port anijeve armike, u mor në dorëzim nga Pijale Pasha pa u shtënë asnjë plumb. Bashkë me Kiosin dhe Psaran u likuidua edhe prania e fundit gjenoveze në bregun lindor të Egjeut. Duke u ruajtur prodhimi i mastikës dhe privilegjet e banorëve të Kiosit, ishulli iu lidh ejaletit të Ishujve të Detit të Mesëm (Cezayir-i Bahr-i Sefid).", "a5ec4417"]},
"OLAYLAR_EK5:1566-04-15:0":{"b": ["Aneksimi i Dukatit të Naksosit — të gjithë ishujt Ciklade", "68f0ec0b"], "d": ["Dukati latin i Naksosit, që ekzistonte nga viti 1207 dhe që nga 1537 u paguante haraç osmanëve, u shfuqizua me arsyetimin e ankesave për shtypjen që duka i fundit, Giacomo Crispo, ushtronte mbi popullin. Naksosi, Parosi, Milosi, Androsi, Sirosi, Mikonosi, Iosi, Amorgosi dhe të gjithë ishujt Ciklade përreth u morën me një vendim të vetëm nën administrimin e drejtpërdrejtë osman. Sulejmani Ligjvënës për një farë kohe ia dha drejtimin e ishujve Jozef Nasit; kështu sundimi latin tre shekuj e gjysmë mori fund në mes të Egjeut.", "d4d7a143"]},
"OLAYLAR_EK5:1567-04-01:0":{"b": ["Kryengritja e Jemenit dhe fushata e Koxha Sinan Pashës në Jemen", "c8218d8e"], "d": ["Imami zejdit Mutahhar u ngrit në kryengritje me arsyetimin se taksat po mblidheshin me forcë dhe ia shkëputi administratës osmane pjesën më të madhe të Jemenit. Koxha Sinan Pasha, i dërguar nga Stambolli, me operacionin që zhvilloi në vitet 1568-1570 e mori Kaukabanin pas një rrethimi të gjatë dhe e rivendosi sundimin osman në rajon. Fushata kishte rëndësi jetike për ruajtjen e kontrollit mbi portën jugore të Detit të Kuq dhe mbi rrugën tregtare të Oqeanit Indian.", "d4771f85"]},
"OLAYLAR_EK5:1567-10-01:0":{"b": ["Aleanca mbrojtëse me Sulltanatin e Açehut dhe ndihma në Oqeanin Indian", "8e835f24"], "d": ["Të dërguarit e Açehut, që përballë sulmeve portugeze i kishin kërkuar ndihmë Sulejmanit Ligjvënës (Kanuni), pas vdekjes së padishahut në Siget ia paraqitën besnikërinë e tyre Selimit II dhe me të u nënshkrua një traktat mbrojtjeje. Padishahu urdhëroi që nga Aleksandria të dërgoheshin topa, pushkë, municion dhe mjeshtra; u përgatitën shtatëmbëdhjetë anije lufte për t'u nisur drejt ujërave indiane. Zgjerimi i kryengritjes së Jemenit e pengoi nisjen e flotës, por topçinjtë dhe mjeshtrat osmanë që arritën në Açeh lanë gjurmë të qëndrueshme në rajon.", "65c41562"]},
"OLAYLAR_EK5:1570-07-02:0":{"b": ["Zbarkimi në Qipro: marrja e Limasolit", "9074ccc9"], "d": ["Ushtria osmane që zbarkoi në ishull shtiu në dorë Limasolin pa hasur ndonjë rezistencë të madhe dhe të nesërmen u drejtua nga Larnaka. Falë faktit se popullsia vendëse nuk ishte e kënaqur me administrimin venedikas dhe i ndihmonte forcat osmane, as në Larnaka nuk u has rezistencë serioze; Skela e Tuzllës u bë bazë për zbarkimin e ushtarëve dhe pajisjeve. Venediku e kishte përqendruar mbrojtjen në Nikosi dhe Famagustë; guvernatori i Pafosit ia shprehu bindjen serdarit vetëm pasi ra Nikosia.", "6bbd2fee"]},
"OLAYLAR_EK5:1570-09-09:0":{"b": ["Pushtimi i Nikosisë", "413d866b"], "d": ["Pas rrethimit që filloi më 25 korrik 1570 dhe zgjati dyzet e pesë ditë, Nikosia, kryeqyteti i Qipros nën administrimin venedikas, iu dorëzua ushtrisë osmane. Rënia e qendrës së ishullit e ngujoi rezistencën venedikase në kështjellën e Famagustës. Pushtimi pati jehonë të madhe në Perëndim dhe e përshpejtoi procesin që çoi në krijimin e flotës së Lidhjes së Shenjtë nën udhëheqjen e Papës.", "1ef832d4"]},
"OLAYLAR_EK5:1570-09-17:0":{"b": ["Dorëzimi i Kirenias — bregdeti verior i Qipros", "39fdeea5"], "d": ["Rënia e Nikosisë më 9 shtator, me kalimin në shpatë, theu rezistencën në veri të Qipros. Kështjella e Kirenias, prapa maleve Pentadaktilos, kur mësoi fatin e kryeqytetit, tetë ditë më pas u dorëzua me kushte dhe garnizonit iu lejua të largohej nga ishulli. Në ishull flamuri venedikas mbeti vetëm në Famagustë; edhe ajo do të qëndronte edhe njëmbëdhjetë muaj.", "ecf762c9"]},
"OLAYLAR_EK5:1572-06-01:0":{"b": ["Rindërtimi i flotës pas Lepantos", "db51fe44"], "d": ["Puna e parë e Këlëç Ali Pashës, i emëruar kapudan pasha pas disfatës së Lepantos, ishte të ringrinte flotën që kishte pësuar humbje të rënda; arsenalet detare punuan pa ndërprerje gjatë gjithë dimrit 1571-1572. Në qershor 1572 në Mesdhe doli një flotë e re prej rreth 250 galerash dhe 300 galerash të reisave vullnetarë. Kjo rimëkëmbje e shpejtë tregoi se Lepanto nuk kishte mundur ta thyente përgjithmonë fuqinë detare osmane.", "324f2d99"]},
"OLAYLAR_EK5:1573-03-07:0":{"b": ["Traktati i Stambollit me Venedikun — njohja e Qipros", "4d08ef50"], "d": ["Venediku, i mbetur vetëm pas shpërbërjes së Lidhjes së Shenjtë, bëri paqe më vete me osmanët, e njohu zyrtarisht se Qiproja u përkiste osmanëve dhe pranoi të paguante dëmshpërblim lufte. Traktati tregoi hapur se fitorja e Lepantos nuk i kishte sjellë botës së krishterë ndonjë fitim politik. Pas kësaj, për shtatëdhjetë vjet Venediku do t'i shmangej hyrjes në luftë të drejtpërdrejtë me osmanët.", "de6151ba"]},
"OLAYLAR_EK5:1574-12-13:0":{"b": ["Vdekja e Selimit II", "c289f5ee"], "d": ["Selimi II, pasi u rrëzua, për rreth dy muaj nuk mundi të dilte në divan dhe vdiq. Vdekja e tij u mbajt e fshehtë në saraj për dymbëdhjetë ditë, derisa djali i madh Murati, që ndodhej në Manisa, të arrinte në Stamboll. Për ditën e vdekjes burimet ndryshojnë: Selaniki jep 15 dhjetorin; Gerlach, Mehmed b. Mehmed dhe Xhenabi japin 13 dhjetorin.", "e9e279ab"]},
"OLAYLAR_EK5:1574-12-22:0":{"b": ["Shpallja e vdekjes së Selimit II dhe hipja në fron e Muratit III", "84334d70"], "d": ["Vdekja e Selimit II dhe hipja në fron e Muratit III, të sjellë nga Manisa, u shpallën zyrtarisht më 22 dhjetor 1574. Padishahu i ri do të qëndronte në fron njëzet e një vjet dhe sundimi i tij do të mbahej mend për luftërat e gjata me Iranin në Lindje, për pragun e Luftës së Gjatë në Perëndim dhe për zhvlerësimin e akçes brenda vendit. Deri në vdekjen e Mehmet Pashë Sokolit më 1579, në drejtimin e shtetit vazhdoi rendi i vjetër.", "3e1ec091"]},
"OLAYLAR_EK5:1578-08-04:0":{"b": ["Beteja e Uadi es-Sejlit (El-Ksar el-Kebir) — Abdulmaliku, i mbështetur nga osmanët, asgjësoi ushtrinë portugeze", "21280dac"], "d": ["Abdulmaliku, që u ul në fronin e Marokut me mbështetjen osmane, e asgjësoi në Uadi es-Sejl ushtrinë e madhe të mbretit portugez Sebastian; ngaqë në betejë vdiqën njëherësh tre sundimtarë, në burimet perëndimore ajo njihet si 'Beteja e Tre Mbretërve'. Fuqia ushtarake e Portugalisë u shemb dhe pas pak kohe vendi kaloi në duart e Spanjës. Edhe Abdulmaliku vdiq në betejë; vëllai që e pasoi, Ahmed el-Mansuri, ia njoftoi fitoren Stambollit me një delegacion. Marrëdhënia mes dy shteteve nuk ishte ajo e haraçit apo e vasalitetit, por mbeti në nivelin e shkëmbimit të ambasadorëve dhe dhuratave, dhe pas pak kohe u acarua për çështjen e dhuratave.", "0ddf3962"]},
"OLAYLAR_EK5:1578-10-05:0":{"b": ["Banorët e Derbendit i shprehin besnikëri Lala Mustafa Pashës — Porta e Hekurt nën administrimin osman", "9c55aeff"], "d": ["Gjatë fushatës së Shirvanit, një delegacion prej shtatë vetash nga banorët e Derbendit shkoi te serdari Lala Mustafa Pasha, që ndodhej në Eresh, dhe i shprehu besnikërinë. Derbendi (Porta e Hekurt, Demirkapı), që mbyllte kalimin e ngushtë mes murit kaukazian dhe Detit Kaspik, si kalim i detyruar i rrugëve tokësore që vinin nga veriu luante rol kyç në mbajtjen e Shirvanit. Sundimi osman këtu vazhdoi deri në vitin 1607.", "9776382c"]},
"OLAYLAR_EK5:1578-11-01:0":{"b": ["Pushtimi i Shirvanit: marrja e Shamahisë", "9afae4c1"], "d": ["Pas fitores së Çëldërit, ushtria që u hap drejt Kaukazit hyri në Shirvan, ejaletin më të pasur safavid në bregun e Kaspikut, dhe mori qytetin qendror, Shamahinë. Këtu u emërua bejlerbe Ozdemiroglu Osman Pasha dhe krahu verior i Rrugës së Mëndafshit u vu nën kontrollin osman. Shirvani do të bëhej fronti që ndërroi më së shumti duar dhe që kushtoi më shtrenjtë në luftën lindore dymbëdhjetëvjeçare.", "9955f6f2"]},
"OLAYLAR_EK5:1583-08-01:0":{"b": ["Marrja e Bakusë — dalja në bregun e Kaspikut", "eb5adab8"], "d": ["Si hallka e fundit e operacionit të Shirvanit, u mor porti i Bakusë në bregun perëndimor të Detit Kaspik. Puset e naftës rreth qytetit ishin edhe në atë kohë burim i njohur të ardhurash dhe porti ishte pika e daljes së mëndafshit iranian që vinte përmes Kaspikut. Kështu Shteti Osman për herë të parë dhe të vetme në historinë e vet pati breg në Detin Kaspik.", "ffafa858"]},
"OLAYLAR_EK5:1583-09-13:0":{"b": ["Pushtimi i Jerevanit (Revanit) dhe ndërtimi i kështjellës", "7f623b7b"], "d": ["Ferhat Pasha, që në Kars mori urdhrin të shkonte në Jerevan dhe të ndërtonte atje një kështjellë, marshoi mbi Jerevan dhe qyteti u vu nën kontrollin osman në fillim të ramazanit 991 (mesi i shtatorit 1583). Në Jerevan, që zotëronte portën veriore të luginës së Araksit, u ndërtua një kështjellë e re dhe e madhe; qyteti u bë qendër bejlerbejllëku. Jerevani, në mes të rrugës ushtarake mes Karsit dhe Tabrizit, ishte shtylla kurrizore logjistike e frontit lindor. Kështjella u ndërtua aq e fortë, saqë për dyqind vjetët pasuese mbeti objektivi i pandryshuar i luftërave osmano-iraniane.", "f6b3bd6e"]},
"OLAYLAR_EK5:1588-09-01:0":{"b": ["Aneksimi i Karabakut dhe Gjanxhës", "29abaead"], "d": ["Si fitimi i fundit i luftës lindore dhjetëvjeçare, Ferhat Pasha më 1588 marshoi mbi Gjanxhë dhe më 1 shtator hyri në qytet; zona e Karabakut mes Kurës dhe Araksit dhe qendra e saj Gjanxha u morën nën administrimin osman. Kështu, duke u bashkuar Shirvani, Jerevani dhe Karabaku, u formua në Kaukaz një vijë osmane e pandërprerë. Traktati i Ferhat Pashës, i nënshkruar më 1590, do ta konfirmonte këtë kufi, por fitimi mundi të mbahej vetëm njëzet vjet.", "67f1d89d"]},
"OLAYLAR_EK5:1592-06-19:0":{"b": ["Pushtimi i Bihaqit", "651a7275"], "d": ["Bejlerbeu i Bosnjës, Telli Hasan Pasha, pasi në nëntor 1591 mori Ripaçin, kështjellën e përparme të Bihaqit, në vitin 1592 shtiu në dorë edhe vetë qytetin me kështjellën; pas një rrethimi dhjetëditor, komandanti Lamberg u dorëzua. Ky pushtim e shtyu përpara kufirin e Bosnjës përgjatë lumit Una dhe ishte fitimi i fundit i madh osman në pragun e Luftës së Gjatë, e cila do të shpërthente një vit më vonë me rënien dëshmor të Telli Hasan Pashës para lumit Kupa.", "b6814991"]},
"OLAYLAR_EK5:1593-07-01:0":{"b": ["Fillimi i 'Luftës së Gjatë' osmano-austriake", "bd22c392"], "d": ["Pasi bejlerbeu i Bosnjës, Telli Hasan Pasha, u thye para Kupës (Sisakut) dhe ra dëshmor, Shteti Osman i shpalli luftë Austrisë dhe filloi Lufta e Gjatë që do të zgjaste trembëdhjetë vjet. Kjo luftë, në të cilën këmbësoria me armë zjarri ishte vendimtare, e përshpejtoi përdorimin e sekbanëve dhe të ushtarëve me pushkë në organizimin ushtarak osman dhe e thelloi rënien e spahinjve me timar. Lufta do të përfundonte në vitin 1606 me Traktatin e Zsitvatorokut.", "f309a27f"]},
"OLAYLAR_EK5:1593-07-19:0":{"b": ["Koxha Sinan Pasha u nis në fushatë kundër Austrisë — fushata e parë e Luftës së Gjatë", "d4a2f46d"], "d": ["Pasi bejlerbeu i Bosnjës, Hasan Pasha, u thye para Siskës (Sisakut) dhe ra dëshmor, veziri i madh Koxha Sinan Pasha e bindi padishahun për luftë me fjalë të shkëlqyera e premtime dhe u nis me 12.000 jeniçerë e njësi të tjera. Kështu u hap fushata e parë e luftës osmano-austriake që do të zgjaste trembëdhjetë vjet.", "0f217276"]},
"OLAYLAR_EK5:1594-09-27:0":{"b": ["Pushtimi i Janëkkalasë (Győr)", "14b75207"], "d": ["Veziri i madh Koxha Sinan Pasha, pas një rrethimi që zgjati më shumë se një muaj, mori në dorëzim Janëkkalanë, e cila konsiderohej çelësi i rrugës për në Vjenë. Rënia e kështjellës shkaktoi panik të madh në Evropë dhe ishte fitimi më i shkëlqyer osman në Luftën e Gjatë. Mirëpo kështjella do të mbahej vetëm katër vjet.", "a634af40"]},
"OLAYLAR_EK5:1595-01-17:0":{"b": ["Vdekja e Muratit III", "1b62e886"], "d": ["Pas një sundimi njëzet e njëvjeçar, Murati III vdiq në ditët kur ushtria e Vllahisë digjte Brailën dhe shtrihej deri në Silistër, dhe u varros në varrezën (haziren) e Ajasofjes. Djali i tij Mehmeti III, i thirrur nga Manisa, arriti në Stamboll dhjetë ditë më vonë dhe hipi në fron (27 janar 1595).", "1deabc61"]},
"OLAYLAR_EK5:1595-09-02:0":{"b": ["Humbja e Estergomit nga Austria", "f420d333"], "d": ["Në rrethimin e drejtuar nga Karl von Mansfeld, garnizoni i Estergomit, që nuk mori ndihmë të mjaftueshme, ia dorëzoi kështjellën arkidukës Matias. Me përfundimin e sundimit osman pesëdhjetë e dyvjeçar u këput zinxhiri mbrojtës në vijën e Danubit dhe Budini (Buda) u vu nën kërcënim të drejtpërdrejtë. Kështjella do të mund të rimerrej vetëm dhjetë vjet më pas, në vitin 1605.", "7617d6f2"]},
"OLAYLAR_EK5:1596-10-12:0":{"b": ["Pushtimi i kështjellës së Egerit", "3e511629"], "d": ["Pas një përleshjeje trejavore, kështjella e fortë e Egerit, të cilën osmanët më parë nuk kishin mundur kurrsesi ta merrnin, ra me dorëzimin e mbrojtësve. Ky pushtim, në të cilin ishte i pranishëm vetë padishahu, e riparoi deri diku moralin e lëkundur nga humbja e Estergomit dhe u krijua Ejaleti i Egerit. Me fitoren e Haçovës (Mezőkeresztes), të arritur dy javë më vonë, viti 1596 u bë viti më i suksesshëm osman i Luftës së Gjatë.", "5dc53fa9"]},
"OLAYLAR_EK5:1598-03-29:0":{"b": ["Humbja e Janëkkalasë (Győr)", "b4ccc679"], "d": ["Trupat nën komandën e Miklós Pálffy-t dhe Adolf von Schwarzenbergut, me një sulm të befasishëm, hodhën në erë portat e kështjellës dhe e rimorën Janëkkalanë. Humbja e kështjellës, që Koxha Sinan Pasha e kishte fituar me mundime të mëdha katër vjet më parë, e shembi vijën e përparme osmane në Hungari. Ndonëse po atë vit forcat armike që rrethuan Budinin u zmbrapsën, ekuilibri i luftës gjithnjë e më shumë u shndërrua në luftë rraskapitëse.", "80bf88e0"]},
"OLAYLAR_EK5:1599-01-01:0":{"b": ["Kryengritja e Karajazëxhi Abdulhalimit", "30493b0d"], "d": ["Karajazëxhi Abdulhalimi, duke mbledhur sekbanët dhe levendët që kishin ikur nga ushtria gjatë Luftës së Gjatë, vuri nën kontroll një zonë të gjerë në Anadollin Qendror, shtiu në dorë kështjellën e Urfës (nëntor 1599), me titullin 'Halim Shah' e shpalli veten padishah dhe dërgoi fermane që mbanin tugrën e tij. Karajazëxhiu, i konsideruar si udhëheqësi i parë i valës së madhe xhelali, vdiq në vitin 1602, ndërsa lëvizjen e vazhdoi i vëllai, Deli Hasani. Kryengritja shënon fillimin e periudhës së 'ikjes së madhe', kur fshatarësia anadollake i braktisi masivisht tokat e veta.", "ceda9161"]},
"OLAYLAR_EK5:1601-09-10:0":{"b": ["Mbrojtja e Kanizhës nga Tirjaki Hasan Pasha", "d56a5e6a"], "d": ["Arkiduka Ferdinand dhe aleatët e tij, duke dashur të rimerrnin Kanizhën e pushtuar një vit më parë, e rrethuan kështjellën për më shumë se dy muaj; Tirjaki Hasan Pasha rezistoi me një forcë prej 9000 vetash. Edhe pse nuk mori ndihmë nga jashtë, ai i zmbrapsi sulmet e përgjithshme dhe me dalje sulmuese e detyroi armikun të tërhiqej me humbje të rënda. Mbrojtja u kthye në legjendë në historiografinë osmane dhe 'Rrethimi i Kanizhës' u bë një zhanër letrar më vete.", "edc6d7b6"]},
"OLAYLAR_EK5:1603-12-20:0":{"b": ["Vdekja e Mehmetit III dhe hipja në fron e Ahmetit I", "da735fde"], "d": ["Pas vdekjes së Mehmetit III më 20 dhjetor, në fron hipi djali i tij katërmbëdhjetëvjeçar, Ahmeti I. Fakti që ai ishte padishahu i parë që u ul në fron në moshë fëminore dhe pa dalë në sanxhak tregon se praktika e edukimit të shehzadeve në provincë kishte marrë fund në praktikë. Gjatë sundimit të Ahmetit I, vëllavrasja do të braktisej dhe do të kalohej te parimi i 'senioratit' (hipja në fron e anëtarit mashkull më të moshuar).", "a5f7151a"]},
"OLAYLAR_EK5:1605-10-03:0":{"b": ["Rimarrja e Estergomit", "7330f273"], "d": ["Veziri i madh Lala Mehmet Pasha rrethoi Estergomin e humbur dhjetë vjet më parë dhe e ktheu sërish nën administrimin osman. Gjatë së njëjtës fushatë u çliruan edhe Peshti e Váci, dhe osmanët e kishin riorganizuar vijën e tyre në Hungari. Ky sukses bëri të mundur që vitin pasues në Zsitvatorok të uleshin në tryezë nga një pozitë relativisht e fortë; Estergomi do të mbetej në duart osmane deri në vitin 1683.", "242d3547"]},
"OLAYLAR_EK5:1607-10-24:0":{"b": ["Fitorja e Fushës së Oruçit dhe shtypja e kryengritjes së Xhanbolladogllu", "30f93532"], "d": ["Xhanbolladogllu Ali Pasha, që kishte ngritur në Halep një principatë të pavarur dhe kërkonte aleancë me Toskanën, pësoi në Fushën e Oruçit një disfatë të rëndë nga veziri i madh Kujuxhu Murat Pasha. Me rivendosjen e autoritetit qendror në Siri u thye krahu më i rrezikshëm i valës xhelali. Spastrimi i pamëshirshëm dyvjeçar i Kujuxhu Murat Pashës siguroi, qoftë edhe përkohësisht, rendin në Anadoll.", "6e620c57"]},
"OLAYLAR_EK5:1608-08-09:0":{"b": ["Fitorja e Alaçajërit dhe shtypja e kryengritjes së Kalenderogllut", "55db0485"], "d": ["Udhëheqësi xhelali Kalenderogllu, që u kishte vënë haraç viseve të Manisës e të Bursës, u thye në Alaçajër nga Kujuxhu Murat Pasha dhe u detyrua të ikte në Iran. Me këtë fitore u shpërnda e fundit prej ushtrive të mëdha xhelali në Anadoll. Spastrimi i ashpër i Kujuxhu Murat Pashës, për të cilin tregohet se i mbushte me kufomat e rebelëve të vrarë me urdhër të tij puset që kishte hapur, ndonëse në afat të shkurtër vendosi rendin, nuk mundi t'i kompensonte humbjet e Anadollit në popullsi dhe prodhim.", "dc332b4b"]},
"OLAYLAR_EK5:1612-07-06:0":{"b": ["Dhënia e ahidnamesë së parë Holandës", "5d9d117e"], "d": ["Ambasadori i Republikës së Provincave të Bashkuara të Holandës, Cornelis Haga, arriti të merrte nga Ahmeti I një ahidname me të njëjtin përmbajtje si ato që u ishin dhënë Francës dhe Anglisë. Kështu Holanda fitoi të drejtën të hapte ambasadë në Stamboll, konsullata në skelat osmane dhe të bënte tregti me flamurin e vet. Kjo ahidname simbolizon hyrjen në tregun osman të fuqive detare veriore që e zëvendësuan Venedikun në tregtinë e Mesdheut.", "7991027b"]},
"OLAYLAR_EK5:1617-11-22:0":{"b": ["Vdekja e Ahmetit I dhe hipja në fron e Mustafait I — parimi i senioratit", "9901c09e"], "d": ["Pas një sëmundjeje të stomakut që zgjati pesëdhjetë e një ditë, Ahmeti I vdiq në moshën njëzet e tetë vjeç dhe në fron, në vend të djalit, u ngrit vëllai i tij Mustafai I. Kështu u braktis radha e trashëgimisë nga babai te i biri dhe u kalua në praktikë te sistemi i 'senioratit', sipas të cilit në fron hipte anëtari mashkull më i moshuar i dinastisë. Ky sundim i parë, që zgjati nëntëdhjetë e gjashtë ditë, shënon edhe fillimin e epokës së rritjes së shehzadeve në 'kafaz'.", "1f866a67"]},
"OLAYLAR_EK5:1618-02-26:0":{"b": ["Rrëzimi i Mustafait I dhe hipja në fron e Osmanit të Ri (Osmani II)", "e0f552f2"], "d": ["Me arsyetimin se nuk ishte në gjendje të mirë mendore, Mustafai I u rrëzua nga froni në fund të nëntëdhjetë e gjashtë ditëve dhe padishah u bë Osmani II, djali katërmbëdhjetëvjeçar i Ahmetit I. Sipas rrëfimit që mbështetet te Hasanbejzade, në këtë vendim rrëzimi ndikoi kizllar agai Mustafa Aga. Osmani i Ri, me projektin për të shfuqizuar odxhakun e jeniçerëve dhe për të krijuar një ushtri të re, konsiderohet emri i parë radikal i debateve osmane për reforma. Ky projekt, katër vjet më vonë, do t'i kushtonte jetën.", "4d655aca"]},
"OLAYLAR_EK5:1618-09-26:0":{"b": ["Traktati i Seravit — ripërtëritja e paqes me Iranin", "e778aca8"], "d": ["Traktati i Seravit, i lidhur me Iranin pas disfatës së Pul-i Shikestes, në vija të përgjithshme i konfirmoi kushtet e Traktatit të Nasuh Pashës të vitit 1612; sasia vjetore e mëndafshit që do të dërgonin safavidët u ul nga dyqind ngarkesa në njëqind. Kështu u mbyll faza e dytë e luftërave lindore që vazhdonin që nga viti 1603. Paqja nuk do të ishte jetëgjatë; me humbjen e Bagdadit në vitin 1623 lufta do të ndizej sërish.", "f14d72aa"]},
"OLAYLAR_EK5:1621-10-09:0":{"b": ["Fushata e Hotinit dhe Traktati i Hotinit", "bc4c823c"], "d": ["Ushtria e madhe, e komanduar personalisht nga Osmani II, nuk mundi të kapërcente kampin e fortifikuar që Chodkiewiczi kishte ngritur para Hotinit dhe sulmet që zgjatën me muaj nuk dhanë rezultat. Me traktatin e nënshkruar më 9 tetor, lumi Dnjestër u pranua si kufi, ndërsa polakët u zotuan të pengonin inkursionet e kozakëve. Fushata, që nuk dha rezultat edhe pse u paraqit si fitore, e përforcoi mosbesimin e padishahut të ri ndaj jeniçerëve dhe synimin e tij për të likuiduar odxhakun.", "7d812c58"]},
"OLAYLAR_EK5:1622-04-23:0":{"b": ["Marrja e Hormuzit nga portugezët", "93e5f6cf"], "d": ["Forcat safavide rrethuan dhe rimorën Hormuzin, që nga viti 1515 ishte në duart e Portugalisë; edhe Qeshmi dhe Gamruni (Bender Abbasi) në breg kaluan nën administrimin safavid dhe tregtia e Gjirit u zhvendos në portin e ri.", "cc55e4bf"]},
"OLAYLAR_EK5:1623-09-10:0":{"b": ["Rrëzimi i dytë i Mustafait I dhe hipja në fron e Muratit IV", "1b3a9e74"], "d": ["Mustafai I, i ngritur në fron për herë të dytë pas vrasjes së Osmanit II, u rrëzua përsëri pas një viti e tre muajsh dhe padishah u shpall Murati IV, njëmbëdhjetë vjeç. Në nëntë vitet e para shteti u drejtua në praktikë nga nëna e tij Kösem Sulltan dhe nga dinjitarët e sarajit. Murati IV, duke e marrë personalisht në dorë pushtetin nga viti 1632, do të niste një periudhë centralizimi të ashpër.", "6dea0fec"]},
"OLAYLAR_EK5:1623-11-28:0":{"b": ["Humbja e Bagdadit nga safavidët", "db81be0c"], "d": ["Në përfundim të pazareve që Bekir Subashi, i ngritur në kryengritje në Bagdad, bëri me safavidët, i biri i tij Dervish Mehmedi, që mbronte kështjellën e brendshme, ua dorëzoi qytetin forcave të Shah Abasit. Humbja e njërit prej qyteteve simbol të trashëgimisë së hilafetit dhe e pjesës më të madhe të Irakut ngjalli zemërim të madh në Stamboll. Rimarrja e Bagdadit do të ishte për pesëmbëdhjetë vjet objektivi i vetëm i politikës lindore osmane.", "ef09360d"]},
"OLAYLAR_EK5:1628-09-22:0":{"b": ["Shtypja e kryengritjes së Abaza Mehmet Pashës me qendër në Erzurum", "e6da2729"], "d": ["Bejlerbeu i Erzurumit, Abaza Mehmet Pasha, që u ngrit kundër jeniçerëve duke pretenduar se do të merrte hakun për vrasjen e Osmanit II, e mbajti për vite me radhë nën kontroll Anadollin Lindor dhe i rezistoi qendrës. Me rrethimin e Erzurumit nga veziri i madh Husrev Pasha u detyrua të dorëzohej, u fal dhe u emërua në Bosnjë. Përfundimi i kryengritjes ishte parakusht që Murati IV të mund të dilte në fushatë kundër Iranit.", "68311e29"]},
"OLAYLAR_EK5:1634-01-08:0":{"b": ["Ekzekutimi i parë i një shejhulislami: Ahizade Husein Efendiu", "a60a58c5"], "d": ["Me arsyetimin se kishte ndërmjetësuar gjatë trazirave ushtarake dhe i kishte dërguar padishahut një paralajmërim me shkrim për procedurën gjyqësore, shejhulislami Ahizade Husein Efendi u ekzekutua pranë Bujukçekmexhesë. Të qenit shejhulislami i parë osman i ekzekutuar e theu traditën me rrënjë të thella, sipas së cilës dënimi më i rëndë për pjesëtarët e ilmijes ishte internimi. Ngjarja konsiderohet simbol i autoritetit gjithnjë e më të ashpër të Muratit IV dhe i prishjes së ekuilibrit mes shtetit dhe ulemave.", "2822f303"]},
"OLAYLAR_EK5:1635-08-08:0":{"b": ["Pushtimi i Jerevanit (Revanit) nga Murati IV", "b65a9b73"], "d": ["Murati IV, që u nis nga Stambolli më 28 mars 1635, e rrethoi Jerevanin më 28-29 korrik dhe më 8 gusht e mori kështjellën në dorëzim; pastaj hyri në Tabrizin e boshatisur dhe urdhëroi shkatërrimin e qytetit. Në kujtim të fitores, padishahu ndërtoi në Sarajin Topkapë Qoshkun e Revanit. Kjo fushatë ishte operacioni i parë i madh lindor, pas një ndërprerjeje tridhjetëvjeçare, në të cilin vetë padishahu komandonte ushtrinë.", "2da4da04"]},
"OLAYLAR_EK5:1636-04-01:0":{"b": ["Humbja e Jerevanit nga safavidët", "fbb8dd25"], "d": ["Pas tërheqjes së ushtrisë osmane, forcat e Shah Safiut e rrethuan Jerevanin dhe e rimorën brenda tetë muajsh. Humbja kaq e shpejtë e kështjellës tregoi sa i vështirë ishte nga ana logjistike sundimi i qëndrueshëm në Kaukaz. Edhe me Traktatin e Kasr-i Shirinit të vitit 1639, Jerevani do t'i mbetej Iranit dhe osmanët do të hiqnin dorë nga pretendimi për Azerbajxhanin.", "f90cb004"]},
"OLAYLAR_EK5:1638-12-24:0":{"b": ["Ripushtimi i Bagdadit", "4d2f27f3"], "d": ["Murati IV, që doli nga Stambolli më 8 maj 1638, pas një rrethimi të ashpër dyzetditor rimori Bagdadin, i cili prej pesëmbëdhjetë vjetësh ishte në duart safavide; gjatë rrethimit veziri Tajar Mehmet Pasha ra dëshmor. Me pushtimin e qytetit, administrimi osman në Irak u rivendos dhe padishahu mori titullin 'Pushtues i Bagdadit'. Pushtimi u bë i qëndrueshëm me Traktatin e Kasr-i Shirinit të vitit pasues dhe hodhi bazën e kufirit të sotëm Turqi-Iran.", "bb99d1fb"]},
"OLAYLAR_EK5:1640-02-09:0":{"b": ["Vdekja e Muratit IV dhe hipja në fron e Sulltan Ibrahimit", "e2ca1ca0"], "d": ["Pas Muratit IV, që vdiq në moshën njëzet e shtatë vjeç (njëzet e tetë sipas llogarisë hixhri), në fron hipi vëllai i tij Ibrahimi, i vetmi mashkull i dinastisë që kishte mbetur gjallë. Gjatë sundimit të padishahut të ri, që kishte jetuar me vite në kafaz, shpenzimet e sarajit dhe luftërat për ndikim brenda sarajit e tronditën rendin shtetëror. Me rrëzimin e tij nga froni dhe vrasjen tetë vjet më vonë, historia osmane do të përjetonte vrasjen e dytë të një padishahu.", "9ad0a971"]},
"OLAYLAR_EK5:1642-02-26:0":{"b": ["Rimarrja e kështjellës së Azovit nga kozakët", "e5fcf160"], "d": ["Kështjella e Azovit, të cilën kozakët e Donit e kishin shtënë në dorë në vitin 1637, u boshatis përballë operacionit të përbashkët të Sulltanzade Mehmet Pashës dhe hanit të Krimesë Mehmet Giraj IV; kozakët i vunë zjarrin kështjellës dhe u tërhoqën. Rimarrja e portës veriore të Detit të Zi e mbylli periudhën e rrezikshme kur inkursionet kozake shtriheshin deri në ngushticën e Bosforit. Në vitin 1696 kështjella do t'i humbej këtë herë carit rus Pjetri I.", "39448f1f"]},
"OLAYLAR_EK5:1645-08-22:0":{"b": ["Fillimi i fushatës së Kretës dhe pushtimi i Hanjas", "a1b0c77f"], "d": ["Me pretekstin se korsarët e Maltës sulmuan një anije osmane haxhilerësh dhe u strehuan në Kretë, Venedikut iu shpall luftë dhe flota nën komandën e Jusuf Pashës zbarkoi ushtarë në ishull. Pas një rrethimi pesëdhjetë e katërditor u mor kështjella e Hanjas dhe u krijua baza e parë e përhershme osmane në Kretë. Kështu filloi lufta më e gjatë e historisë osmane; ishulli do të mund të pushtohej tërësisht vetëm njëzet e katër vjet më vonë, në vitin 1669.", "2809708a"]},
"OLAYLAR_EK5:1646-11-13:0":{"b": ["Pushtimi i Retimos — ndarja e Kretës në dysh", "8f2c4353"], "d": ["Një vit pas marrjes së Hanjas ra edhe kështjella e Retimos në pjesën qendrore të ishullit dhe gjysma perëndimore e Kretës hyri tërësisht nën administrimin osman. Në duart e Venedikut mbetën vetëm kryeqyteti Kandia dhe skaji lindor; ishulli jetoi i ndarë në dysh për njëzet e tre vjet. Marrja e Retimos ishte hapi që nisi rrethimin e Kandias — këtu filloi rrethimi më i gjatë i historisë.", "88ec9840"]},
"OLAYLAR_EK5:1648-03-31:0":{"b": ["Humbja e Klisit nga Venediku", "5473c22c"], "d": ["Kundërsulmi i komandantit venedikas Leonardo Foscolo në frontin dalmat të Luftës së Kretës (Kandias) përfshiu edhe Klisin, që prej vitit 1537 ishte qendër sanxhaku; kështjella kaloi te Venediku. Përqendrimi i osmanëve me gjithë forcën te Kreta e bëri të pamundur rimarrjen e kësaj humbjeje në kufirin dalmat — Klisi nuk do të kthehej më kurrë nën administrimin osman; qendra e sanxhakut u zhvendos në Livno.", "d0ec59d4"]},
"OLAYLAR_EK5:1648-05-01:0":{"b": ["Fillimi i rrethimit të Kandias", "13016b10"], "d": ["Pas marrjes së Hanjas dhe Retimos, ushtria osmane e vuri nën rrethim Kandian, mbështetjen e fundit të madhe të Venedikut në ishull. Kjo bllokadë, që do të zgjaste njëzet e një vjet, u shënua si një nga rrethimet më të gjata në historinë ushtarake botërore. Gjatë rrethimit, përpjekjet e flotës venedikase për të mbyllur ngushticën e Dardaneleve do ta çonin luftën në zemër të Egjeut.", "8a35e8f9"]},
"OLAYLAR_EK5:1651-09-02:0":{"b": ["Vrasja e Valide së Madhe Kösem Sulltan", "9d763f79"], "d": ["Kösem Sulltani, rreth gjashtëdhjetë e dy vjeçe, u gjet në një dhomë të Haremit dhe u vra nga Bashllalla Uzun Sulejman Aga dhe njerëzit e tij, që vepronin me urdhër të Turhan Sulltanit, nënës së Mehmetit IV. Vdekja e kësaj gruaje të fuqishme të dinastisë, që drejtoi politikën shtetërore gjatë mbretërimit të tre padishahëve, konsiderohet fundi faktik i periudhës së quajtur 'Sulltanati i Grave'. Vakuumi i autoritetit hapi rrugën që pesë vjet më vonë çoi në emërimin e Mehmet Pashë Qyprillit si vezir i madh me kompetenca të jashtëzakonshme.", "d1ff09cb"]},
"OLAYLAR_EK5:1656-07-13:0":{"b": ["Disfata e Dardaneleve dhe humbja e Tenedosit dhe e Lemnosit", "e01a1f7e"], "d": ["Fitorja e madhe detare e admiralit venedikas Mocenigo para ngushticës së Dardaneleve në qershor 1656 e asgjësoi pothuajse tërësisht flotën osmane; pastaj u pushtuan Tenedosi, Lemnosi dhe Samotraka. Me kalimin e ngushticës nën bllokadën venedikase, në Stamboll çmimet e ushqimeve u hodhën përpjetë dhe u përhap frika e një sulmi mbi kryeqytetin. Kjo fatkeqësi u bë shkaku i drejtpërdrejtë i emërimit të Mehmet Pashë Qyprillit si vezir i madh në shtator 1656, me kushte dhe me kompetenca të jashtëzakonshme.", "31f7a914"]},
"OLAYLAR_EK5:1657-08-25:0":{"b": ["Fitorja e Dardaneleve dhe rimarrja e Tenedosit", "603da863"], "d": ["Flota që mobilizoi Mehmet Pashë Qyprilliu e theu flotën venedikase para ngushticës më 19 korrik 1657; pastaj forcat nën komandën e Kurd Pashës e rimorën Tenedosin më 25 gusht dhe më 30 gusht venedikasit e boshatisën plotësisht ishullin. Në nëntor u çlirua edhe Lemnosi, u thye bllokada e Dardaneleve dhe u rihap rruga e furnizimit të Stambollit. Qyprilliu kaloi vetë në ishull dhe urdhëroi riparimin e fortifikimeve; ky sukses është fitimi i parë i madh ushtarak i epokës së Qyprillinjve.", "af4d7bfd"]},
"OLAYLAR_EK5:1658-08-27:0":{"b": ["Pushtimi i Janovës (Ineu) dhe fushata e Transilvanisë", "d1089616"], "d": ["Mehmet Pashë Qyprilliu, që doli në fushatë për të ndëshkuar princin e Transilvanisë György Rákóczi II, i cili kishte shkelur mbrojtjen osmane duke ndërmarrë pa leje një fushatë kundër Polonisë, marshoi nëpër Beograd dhe mori kështjellën strategjike të Janovës. Në Transilvani u emërua një princ i ri dhe lidhja e vasalitetit iu kujtua ashpër. Kjo fushatë ishte hallka e parë e përpjekjes osmane për të rivendosur autoritetin në Evropën Qendrore. Transilvania ishte tashmë një principatë vartëse e osmanëve; marrja e Janovës nuk ishte pushtim nga një shtet i huaj, por shkëputja e kësaj kështjelle të Transilvanisë vartëse nga administrimi i principatës dhe lidhja e saj drejtpërdrejt me një sanxhak osman; pjesa tjetër e principatës mbeti në statusin vartës.", "4e24d834"]},
"OLAYLAR_EK5:1659-02-16:0":{"b": ["Shtypja e kryengritjes së Abaza Hasan Pashës", "4ba74321"], "d": ["Abaza Hasan Pasha, duke pasur mbrapa bejlerbejlerët e Anadollit dhe agallarët e sekbanëve kundër spastrimeve të ashpra të Mehmet Pashë Qyprillit, nisi një kryengritje të madhe duke kërkuar shkarkimin e vezirit të madh. Kryengritja u shtyp në Halep dhe krerët e saj u zhdukën; kjo ishte rezistenca e fundit kolektive e pashallarëve të provincës kundër qendrës. Kështu autoriteti i Qyprilliut u bë i padiskutueshëm dhe posti i vezirit të madh u ngrit përsëri në qendrën e vërtetë ekzekutive të shtetit.", "900e66b5"]},
"OLAYLAR_EK5:1660-08-27:0":{"b": ["Pushtimi i Varadit (Oradea)", "0e6ad300"], "d": ["Në kuadër të fushatës kundër princit të Transilvanisë György Rákóczi II, që i kishte shpallur luftë osmanëve, u morën kështjella dhe qyteti i Varadit. Me rënien e njërës prej kështjellave kyçe të Transilvanisë u krijua në rajon një ejalet i ri osman (Ejaleti i Varadit). Pushtimi i alarmoi habsburgët dhe u bë një nga shkaqet e drejtpërdrejta të luftës osmano-austriake që do të fillonte tre vjet më vonë. Vendet e tjera që u bashkuan në të njëjtën datë: Varadi. Edhe këtu toka nuk u mor nga një shtet i huaj: Transilvania ishte tashmë një principatë osmane vartëse; shndërrimi i Varadit në ejalet vetëm sa e shkëputi administrimin e këtij qyteti nga principata vartëse dhe e lidhi drejtpërdrejt me padishahun, njësoj si te Janova dy vjet më parë.", "991162de"]},
"OLAYLAR_EK5:1664-08-01:0":{"b": ["Beteja e Shën Gotardit (St. Gotthard)", "61ebc1f2"], "d": ["Forcat osmane që kaluan lumin Raab u ndalën nga ushtria aleate evropiane nën komandën e Montecuccolit dhe pësuan humbje të rënda. Beteja konsiderohet pikë kthese në historinë ushtarake, sepse për herë të parë tregoi hapur epërsinë e zjarrit të disiplinuar të pushkëve të këmbësorisë mbi sulmin e kalorësisë osmane. Megjithë disfatën, osmanët arritën të siguronin kushte të favorshme në Traktatin e Vasvárit, të nënshkruar nëntë ditë më vonë.", "4ab743fc"]},
"OLAYLAR_EK5:1664-08-09:0":{"b": ["Traktati i Vasvárit", "089c978c"], "d": ["Traktati, i nënshkruar megjithë disfatën e Shën Gotardit, përcaktoi që Ujvari dhe Varadi t'u mbeteshin osmanëve, që Transilvania të mbetej neutrale nën mbrojtjen osmane dhe që Austria të paguante 200.000 kurush si 'dhuratë'. Kjo paqe njëzetvjeçare është një nga shembujt e rrallë ku pala që humbi luftën fitoi në tryezë. Pakënaqësia që traktati ngjalli në opinionin habsburg do të ushqente lëvizjen e Hungarisë së Mesme dhe, tërthorazi, fushatën e Vjenës të vitit 1683.", "61ca5d47"]},
"OLAYLAR_EK5:1671-01-01:0":{"b": ["Fillimi i administrimit të dejëve në Algjeri", "e99faa51"], "d": ["Odxhaku i Algjerisë dhe taifja e reisëve (kapitenët korsarë) shkarkuan agën e fundit dhe zgjodhën Haxhi Mehmedin dej për gjithë jetën. Pas kësaj date Algjerinë nuk e qeveriste bejlerbeu i emëruar nga Stambolli, por deji që odxhaku vendor e zgjidhte nga gjiri i vet; lidhja osmane mbeti e kufizuar te përmendja e emrit të padishahut në hytbe, te flamuri dhe te detyrimi për fushata. Kështu Algjeria u shndërrua nga ejalet në odxhakllëk — të njëjtin shndërrim e përjetuan Tunizia me Husejnidët në vitin 1705 dhe Tripoli me Karamanlinjtë në vitin 1711.", "b8decd95"]},
"OLAYLAR_EK5:1672-06-04:0":{"b": ["Filloi fushata e Polonisë — Mehmeti IV dhe Fazëll Ahmet Pasha në krye të ushtrisë", "75e15a39"], "d": ["Meqë sulmet e Polonisë vazhdonin kundër hetmanit ukrainas Petro Doroshenko, që kishte hyrë nën mbrojtjen osmane, Stambolli i kërkoi mbretit polak të hiqte dorë nga sulmet; pasi nuk erdhi përgjigje pozitive, u vendos fushata kundër Polonisë. Veziri i madh Fazëll Ahmet Pasha, me ushtrinë ku ndodhej edhe padishahu, u nis drejt Polonisë më 4 qershor 1672. Fushata do të përfundonte me pushtimin e Kamianecit dhe me Traktatin e Buchaçit.", "7340721a"]},
"OLAYLAR_EK5:1672-08-27:0":{"b": ["Pushtimi i Kamianecit dhe krijimi i Ejaletit të Podolisë", "c3f4f6d0"], "d": ["Pas një rrethimi nëntëditor u mor në dorëzim Kamianeci, që konsiderohej kështjella më e fortë lindore e Polonisë; më 2 shtator Mehmeti IV fali namazin e parë të xhumasë në xhaminë e kthyer nga katedralja. Me kështjellën si qendër u krijua Ejaleti i Podolisë dhe flamuri osman arriti pikën më veriore në trojet e Ukrainës së sotme. Kamianeci do të mbetej skaji veriperëndimor i perandorisë deri në Traktatin e Karllofçës të vitit 1699.", "d89c513a"]},
"OLAYLAR_EK5:1674-08-03:0":{"b": ["Kara Mustafa Pasha mori në dorëzim Umanin nga Polonia", "0d3543a0"], "d": ["Kara Mustafa Pasha, i dërguar kundër Polonisë, mori në dorëzim Umanin, një nga kështjellat që mbante Polonia; qyteti mbeti nën administrimin osman deri në Karllofçë.", "bdb8e553"]},
"OLAYLAR_EK5:1678-08-21:0":{"b": ["Pushtimi i kështjellës së Çehrinit", "a17cedd0"], "d": ["Pas operacionit pa rezultat të Melek Ibrahim Pashës një vit më parë, veziri i madh Merzifonlu Kara Mustafa Pasha, duke komanduar personalisht, e rrethoi kështjellën e fortifikuar të Çehrinit (19/21 korrik) dhe e shtiu në dorë më 21 gusht. Rënia e kështjellës, simbol i rivalitetit osmano-rus mbi hetmanatin kozak në Ukrainë, e detyroi Rusinë të bënte paqe. Ky sukses u bë edhe një nga burimet e vetëbesimit që do ta drejtonte Merzifonluun drejt Vjenës.", "aee53ec4"]},
"OLAYLAR_EK5:1681-02-13:0":{"b": ["Traktati i Bahçesarajit — paqja e parë zyrtare me Rusinë", "df82bc0b"], "d": ["Në përfundim të bisedimeve që u zhvilluan me ndërmjetësimin e hanit të Krimesë pas fushatave të Çehrinit, mes Shtetit Osman dhe Rusisë u nënshkrua një paqe njëzetvjeçare, duke pranuar lumin Ozi (Dnjepër) si kufi. Duke qenë traktati i parë gjithëpërfshirës mes dy shteteve, ai konsiderohet dokumenti fillestar i marrëdhënieve osmano-ruse. Falë paqes u sigurua fronti lindor dhe ushtria mund të drejtohej drejt Evropës Qendrore.", "56f57388"]},
"OLAYLAR_EK5:1682-09-16:0":{"b": ["Dhënia e beratit të mbretërisë së Hungarisë së Mesme Imre Thökölyt", "3cd8d51d"], "d": ["Fisniku protestant hungarez Imre Thököly, që ishte ngritur kundër trysnisë habsburge, nga prilli 1682 filloi të konsiderohej 'mbret i zgjedhur i Hungarisë së Mesme' dhe më 16 shtator bejlerbeu i Budinit, Ibrahim Pasha, i dorëzoi shenjat e principatës. Kështu u krijua një shtet i ri vasal hungarez nën mbrojtjen osmane. Kjo ndërhyrje e bëri të pashmangshme luftën me Austrinë dhe nisi zinxhirin që çoi në Rrethimin e Dytë të Vjenës të vitit pasues.", "6f7f5236"]},
"OLAYLAR_EK5:1684-08-06:0":{"b": ["Humbja e Ajamavrës (Lefkadës) nga Venediku", "e6905fee"], "d": ["Flota e Venedikut, që iu bashkua Lidhjes së Shenjtë, pasi e goditi qytetin me topa, pushtoi ishullin e Ajamavrës në Detin Jon. Me rënien po atë vit edhe të Prevezës u thye kontrolli osman në hyrjen e Adriatikut. Këto humbje ishin hapat fillestarë të operacionit me të cilin Morosini brenda tre vjetësh do të pushtonte gjithë Morenë.", "8fe34c55"]},
"OLAYLAR_EK5:1685-08-11:0":{"b": ["Humbja e Koronit nga Venediku", "2ed762bc"], "d": ["Forcat venedikase nën komandën e Morosinit shtinë në dorë kështjellën e Koronit në skajin jugperëndimor të gadishullit të Moresë; pas kësaj qyteti do të mbetej tridhjetë vjet nën administrimin venedikas. Rënia e Koronit ishte fitimi i parë i madh i operacionit venedikas për pushtimin e Moresë. Kështjella mundi të rimerrej vetëm në vitin 1715 nga ushtria osmane nën komandën e Silahdar Ali Pashës.", "506cf83e"]},
"OLAYLAR_EK5:1688-04-08:0":{"b": ["Rimarrja e Athinës — tërheqja e Venedikut", "03393b46"], "d": ["Morosini, që në shtator 1687 bombardoi Akropolin dhe hodhi në erë Partenonin, pasi e kaloi dimrin në Athinë kuptoi se nuk mund të mbahej në qytet. Për shkak të epidemisë së murtajës, vështirësive të furnizimit dhe riorganizimit të forcave osmane, garnizoni venedikas e boshatisi qytetin dhe u tërhoq në More. Kështu Athina u kthye pa luftë nën administrimin osman, por shkatërrimi që pësoi Partenoni nuk mundi të kthehej mbrapsht.", "79c8586a"]},
"OLAYLAR_EK5:1688-06-22:0":{"b": ["Lipova (Lipa) iu dorëzua Caraffës — kaloi në duart austriake", "7f0a8d38"], "d": ["Pas rrethimit tre ditor të Antonio Caraffës, Lipova u dorëzua mes 12 dhe 22 qershorit 1688 dhe kaloi në duart e Austrisë. Osmanët më vonë e rimorën qytetin, Austria e shtiu përsëri në dorë më 1691; në fushatën e vitit 1695 osmanët e rivendosën kontrollin. Vendbanimet e tjera që në atlas kalojnë po atë datë nga osmanët te habsburgët: Aradi dhe Világosi (Şiria). Për Aradin burimi jep vetëm vitin (MKL, Arad: në duart osmane mes 1551-1688); dita është marrë nga Lipova, Világosi ndjek zinxhirin e Aradit (përafrim i deklaruar). Edhe kështjellat e Lugozhit (Lugoj) dhe Karánşebeşit (Caransebeş) kaluan te Austria në fund të qershorit (Bánlaky 0016/1302 'Jenővel elveszett Lugos és Karánsebes'; 0017/1443 'június végén').", "2c8131d4"]},
"OLAYLAR_EK5:1688-10-20:0":{"b": ["Zmbrapsja e rrethimit venedikas të Eubesë", "aae7e6a0"], "d": ["Morosini, që pas pushtimit të Moresë u drejtua nga Egjeu, u përpoq të merrte Eubenë me një rrethim që zgjati më shumë se tre muaj; por përballë fortifikimeve të përforcuara në dimrin 1687-1688 dhe rezistencës së garnizonit u detyrua të tërhiqej me humbje të rënda. Ky dështim e ndali përparimin venedikas në Egje dhe e tronditi prestigjin ushtarak të Morosinit. Eubea do të mbetej në duart osmane edhe në Karllofçë.", "ea8430a3"]},
"OLAYLAR_EK5:1690-04-23:0":{"b": ["Humbja e kështjellës së Kanizhës nga Austria", "553b45f3"], "d": ["Kanizha, që nga janari 1690 u vu nën bllokadën e ngushtë të ushtrisë habsburge prej 60.000 vetash, pasi rezistoi me muaj pa marrë ndihmë, u dorëzua me marrëveshjen e dorëzimit që nënshkroi mbrojtësi i saj i fundit, Mustafa Pasha. Kështu mori fund sundimi nëntëdhjetëvjeçar osman në kështjellën e njohur për mbrojtjen legjendare të Tirjaki Hasan Pashës. Humbja e Kanizhës ishte shembja e mbështetjes së fundit të madhe osmane në perëndim të Hungarisë.", "dc630d57"]},
"OLAYLAR_EK5:1691-06-22:0":{"b": ["Vdekja e Sulejmanit II", "d2478080"], "d": ["Sulejmani II, i ngritur në fron më 1687 pasi kishte kaluar rreth dyzet vjet në kafaz, i sëmurë teksa ndiqte përgatitjet e ushtrisë, vdiq në Edrene të premten, më 22 qershor 1691, afër mesditës; sundimi i tij zgjati tre vjet, tetë muaj e dy ditë. Veziri i madh kishte dhënë më parë udhëzimet e nevojshme që, në rast vdekjeje të padishahut, në fron të ngrihej i vëllai Ahmeti. Namazi i xhenazes u fal po atë ditë në Qoshkun e Parakalimit (Alay Köşkü); trupi u soll në Stamboll dhe u varros në tyrben e Sulltan Sulejman Kanuniut, në anën e djathtë të tij.", "3cf4fcb1"]},
"OLAYLAR_EK5:1691-06-23:0":{"b": ["Hipja në fron e Ahmetit II", "52947b14"], "d": ["Pas vdekjes së Sulejmanit II, vëllai i tij dyzet e nëntë vjeç, Ahmeti II, hipi në fron në Edrene. Sundimi i tij përkoi me vitet më të rënda të luftërave kundër Lidhjes së Shenjtë; dy muaj pas hipjes në fron, në Slankamen ra dëshmor veziri i madh Fazëll Mustafa Pasha. Megjithatë, sistemi i malikanes, i vënë në zbatim gjatë kohës së tij, u bë një nga rregullimet më të rëndësishme që ndryshuan strukturën afatgjatë të financave osmane.", "d3441b14"]},
"OLAYLAR_EK5:1693-01-06:0":{"b": ["Vdekja e Mehmetit IV në Edrene", "17388b7e"], "d": ["Mehmet Gjahtari (Avcı Mehmed), i rrëzuar nga froni më 1687, u soll në Edrene gjatë fushatës hungareze të Sulejmanit II më 1689 dhe e pa edhe sundimin e vëllait tjetër, Ahmetit II. Vdiq në këtë qytet që e donte shumë. Trupi u soll në Stamboll dhe u varros në tyrben e së ëmës, Turhan Sulltan, pranë xhamisë Jeni.", "fd0f3d8c"]},
"OLAYLAR_EK5:1695-02-06:0":{"b": ["Vdekja e Ahmetit II në Edrene", "c6306c08"], "d": ["Ahmeti II, sundimi katërvjeçar i të cilit kaloi në luftë, vdiq në Edrene në moshën pesëdhjetë e dy vjeç nga hidropsia (edema). Trupi u soll në Stamboll dhe u varros në tyrben e Sulltan Sulejman Kanuniut. Në vend të tij erdhi nipi Mustafa II.", "a61e819c"]},
"OLAYLAR_EK5:1696-01-01:0":{"b": ["Shtënia në dorë e Basrës nga iranianët", "a9cdf3a3"], "d": ["Ndërsa Shteti Osman merrej në perëndim me luftërat kundër Lidhjes së Shenjtë, Basra, pas epidemisë së murtajës së vitit 1690, ishte plaçkitur fillimisht nga Mani, sheiku i Muntefikut, pastaj nga Ferexhullah, hani i Huvejzës. Duke përfituar nga ky rrëmujë, iranianët më 1696 shtinë në dorë qytetin dhe lanë në Basrë një mbrojtës.", "2db76d27"]},
"OLAYLAR_EK5:1700-07-14:0":{"b": ["Traktati i Stambollit — lënia e Azovit Rusisë", "79db4724"], "d": ["Në Karllofçë me Rusinë ishte arritur vetëm një armëpushim dyvjeçar; paqja e përhershme u nënshkrua në Stamboll pas pazaresh të ashpra që zgjatën një vit e gjysmë. Shteti Osman ia lëshoi zyrtarisht Rusisë kështjellën e Azovit, të humbur në vitin 1696, dhe tokat përreth saj, si dhe hoqi dorë nga taksa vjetore që hani i Krimesë merrte nga Moska. Në këmbim, Rusia fitoi të drejtën të mbante ambasador të përhershëm në Stamboll; kështu prania ruse në bregun verior të Detit të Zi u regjistrua juridikisht.", "a3a5a803"]},
"OLAYLAR_EK5:1701-01-01:0":{"b": ["Rimarrja e Kurnës dhe Basrës nga Daltaban Mustafa Pasha", "7adb777d"], "d": ["Daltaban Mustafa Pasha, i emëruar pas Traktatit të Karllofçës vali i Bagdadit dhe serasker i Basrës, marshoi drejt jugut me forcat e Halepit, Rakkas, Sivasit dhe Karamanit dhe me një flotë lumore që zbriti nga Birexhiku. Sheikët e fiseve përreth iu nënshtruan njëri pas tjetrit, mbrojtësi iranian i Basrës, Davud Hani, e braktisi qytetin dhe Kurna e Basra hynë përsëri nën administrimin osman.", "60abbe06"]},
"OLAYLAR_EK5:1703-12-29:0":{"b": ["Vdekja e Mustafait II", "626c394d"], "d": ["Mustafai II, që me Ngjarjen e Edrenesë ia la fronin vëllait Ahmetit III, rreth pesë muaj pas rrëzimit vdiq në Edrenenë që e donte shumë. Sëmundjes i ishte shtuar edhe hidhërimi për ngjarjet e fundit. Disa burime perëndimore shkruajnë se në popull ishte i përhapur mendimi se ai ishte helmuar.", "8ce146e8"]},
"OLAYLAR_EK5:1704-01-01:0":{"b": ["Fillimi i administrimit kölemen (mamluk) në Bagdad", "abe52618"], "d": ["Me emërimin e Hasan Pashës me origjinë gjeorgjiane si vali i Bagdadit, në Irak filloi periudha kur në vend të valinjve të emëruar nga qendra sundonte një shtresë drejtuesish e dalë nga skllevërit e tyre. Kur Sulejman Pasha u bë vali në vitin 1749, sistemi u rrënjos mirë dhe Porta e Lartë tani detyrohej të emëronte jo njeriun që donte, por njërin nga kölemenët që e kishin marrë në dorë ndikimin. Kjo strukturë gjysmë-autonome, ndonëse ishte e dobishme për mbrojtjen e kufirit iranian, për një shekull e gjysmë e dobësoi kontrollin e autoritetit qendror mbi Irakun.", "7cf655d4"]},
"OLAYLAR_EK5:1705-07-12:0":{"b": ["Themelimi i dinastisë Huseinide në Tunizi", "cb1a98f9"], "d": ["Në vakuumin e autoritetit që u krijua pas pushtimit të Tunizisë nga forcat algjeriane, agai i spahinjve me origjinë turke, Husein b. Ali, e shtiu në dorë bejllëkun dhe fitoi legjitimitet duke i shprehur besnikëri padishahut osman. Dinastia që ai themeloi e sundoi Tunizinë në vitet 1705-1735 dhe 1756-1957; në vend të sundimit të odxhakut zuri vend një rend bejllëku që kalonte nga babai te i biri. Kështu lindi shembulli i parë i strukturave dinastike të lidhura me qendrën, por faktikisht autonome, në odxhaqet e Perëndimit.", "941c7858"]},
"OLAYLAR_EK5:1708-04-04:0":{"b": ["Marrja e Oranit (Vahran) dhe e Mers-el-Kebirit nga spanjollët", "b67ce06a"], "d": ["Forcat e bejlerbeut të Odxhakut të Algjerisë, pas një rrethimi të gjatë, shtinë në dorë Oranin dhe portin e tij Mers-el-Kebir, që prej dy shekujsh ishin në duart e garnizonit spanjoll. Ishte suksesi më i madh që odxhaqet e Perëndimit nën mbrojtjen osmane arritën kundër Spanjës në Mesdheun perëndimor dhe siguroi krahun perëndimor të Algjerisë. Qyteti do të pushtohej përsëri nga spanjollët në vitin 1732, por do të rimerrej përfundimisht në vitin 1792.", "33d9da74"]},
"OLAYLAR_EK5:1711-07-21:0":{"b": ["Traktati i Prutit — rimarrja e Azovit dhe e Taganrogut", "bac5d2a1"], "d": ["Traktati me shtatë nene, i nënshkruar pas dorëzimit të ushtrisë ruse të rrethuar buzë Prutit, përcaktonte kthimin e kështjellës së Azovit te osmanët bashkë me tokat dhe municionin e saj. Fortifikimet e Taganrogut, Kamenkës dhe Jenikalesë do të shkatërroheshin dhe palët nuk do të ndërtonin kështjella të reja në këto zona. Flota dhe sistemi i bazave që Pjetri I kishte ngritur për gjashtëmbëdhjetë vjet në Voronezh dhe Azov u shembën; dalja e Rusisë në Detin e Zi u vonua rreth pesëdhjetë vjet.", "657d45ff"]},
"OLAYLAR_EK5:1711-07-29:0":{"b": ["Themelimi i dinastisë Karamanli në Tripoli", "e1105d4a"], "d": ["Në Tripolin e Libisë, të lodhur nga grindjet e agallarëve të odxhakut, oficeri i kalorësisë Ahmet Karamanli e shtiu në dorë pushtetin dhe e zyrtarizoi pozitën e vet me beratin e bejlerbeut të marrë nga Stambolli. Përmes Ahmet Pashës, djalit të tij Mehmet Pasha dhe nipit Jusuf Pasha lindi një dinasti që zgjati në vitet 1711-1835; u shfaq një strukturë gjysmë e pavarur, që ngriti flotën e vet dhe nënshkruante drejtpërdrejt traktate me shtetet evropiane. Kjo periudhë do të merrte fund vetëm në vitin 1835, kur ejaleti u lidh drejtpërdrejt me qendrën.", "b1c3dd0a"]},
"OLAYLAR_EK5:1713-06-24:0":{"b": ["Traktati i Edrenesë me Rusinë", "14901a70"], "d": ["Meqë premtimet e dhëna në Prut nuk u mbajtën, lufta u shpall edhe dy herë të tjera; më në fund, pasi rusët i pranuan zotimet, në Edrene u nënshkrua një paqe e përhershme. Traktati i konfirmoi kushtet e Prutit; Rusia nuk do të përzihej në punët e Polonisë, do të tërhiqej nga tokat kozake dhe nuk do ta pengonte kthimin në vendin e vet të mbretit të Suedisë, Karlit XII (Demirbaş Şarl). Mbyllja e frontit verior në këtë mënyrë i mundësoi Shtetit Osman të kthente fytyrën nga fronti i Moresë dhe i Venedikut. Vendet e tjera që u bashkuan në të njëjtën datë: Hotini.", "34010e06"]},
"OLAYLAR_EK5:1714-12-08:0":{"b": ["Shpallja e luftës Venedikut — përgatitja e fushatës së Moresë", "d970b122"], "d": ["Me arsyetimin se Venediku mbështeste kryengritësit e Malit të Zi, sekuestronte anijet tregtare osmane dhe e shtypte me taksa të rënda Morenë që kishte marrë në Karllofçë, në Divan u mor vendimi për luftë. Fushata e përgatitur nga veziri i madh Silahdar Damad Ali Pasha do të përfundonte vitin pasues me rimarrjen e gjithë gadishullit të Moresë për më pak se njëqind ditë. Mirëpo ky sukses do ta vinte në veprim Austrinë dhe do t'i hapte derën një lufte shumë më të rëndë në vitin 1716.", "ef2edb5f"]},
"OLAYLAR_EK5:1715-06-05:0":{"b": ["Tinosi (Istendil): dorëzimi i ishullit të fundit të Venedikut në Egje", "4abec891"], "d": ["Flota e nisur për fushatën e Moresë u ankorua gjatë rrugës para Tinosit, ishullit të vetëm që i kishte mbetur Venedikut në Egje. Ishulli, që megjithëse Dukati i Naksosit ra më 1566, falë popullsisë latine kishte mbajtur edhe njëqind e pesëdhjetë vjet flamurin venedikas, pas një rrethimi të shkurtër u dorëzua pa derdhje gjaku. Kështu u fshi gjurma e fundit e këmbës venedikase në Detin Egje dhe deti u bë tërësisht një det i brendshëm osman.", "7b191aca"]},
"OLAYLAR_EK5:1715-07-20:0":{"b": ["Pushtimi i Nauplias (Anabolu) — kështjella kyçe e Moresë", "62a5808a"], "d": ["Nauplia, kryeqyteti venedikas dhe fortifikimi më i fortë në More, ra pasi reduta e Palamidit u shtie në dorë pas bombardimit nëntëditor. Marrja kaq e shpejtë e kështjellës theu rezistencën në pjesën tjetër të gadishullit. Rimarrja e Moresë, e humbur në Karllofçë, faktikisht u plotësua këtu. Vendbanimi tjetër që në atlas kalon po atë datë nga Venediku te osmanët: Argosi — ndjek zinxhirin e qendrës mëmë të Nauplias (TDV anabolu; përafrim i deklaruar).", "8467e05c"]},
"OLAYLAR_EK5:1715-08-01:0":{"b": ["Dorëzimi i Modonit", "43faa909"], "d": ["Pas rënies së Nauplias, kështjella e Modonit në skajin jugperëndimor të Moresë u rrethua nga toka nga ushtria dhe nga deti nga flota dhe pas pak kohe u dorëzua. Ky port, që Venediku e kishte përdorur për dyqind vjet në udhëtimet e veta në Mesdheun Lindor, ishte vendndalim i detyrueshëm ku anijet merrnin ujë e ushqime. Humbja e tij i dha fund lëvizshmërisë së flotës venedikase në Egje.", "0d2c6d1a"]},
"OLAYLAR_EK5:1715-08-16:0":{"b": ["Dorëzimi i Koronit — përfundimi i fushatës së Moresë", "e4b9c8a4"], "d": ["Me dorëzimin e kështjellës së Koronit, që zotëronte grykën e gjirit të Mesenisë, administrimi venedikas në gadishullin e Moresë mori fund plotësisht. Gadishulli i humbur në Karllofçë u rimor i tëri vetëm tre muaj pas hapjes së fushatës. Në vazhdim të së njëjtës fushatë, në shtator 1715, Venedikut iu mor edhe ishulli i Ajamavrës (Lefkadës) në Detin Jon. Kjo shpejtësi e detyroi Venedikun ta fuste Austrinë në luftë dhe tre vjet më vonë u hap rruga për në Pasarofçë.", "d3173b05"]},
"OLAYLAR_EK5:1715-09-07:0":{"b": ["Marrja e ishullit të Kitherës", "494de6c6"], "d": ["Ishulli i Kitherës, në skajin jugor të Moresë, pas plotësimit të gadishullit u mor në dorëzim nga flota. Ishulli, që vëzhgonte kalimin mes Detit Jon dhe Egjeut, ishte postblloku i përparuar që Venediku përdorte për të kontrolluar këto ujëra. Megjithatë, nuk mbeti përgjithmonë ishull osman: tre vjet më vonë, në Pasarofçë, iu kthye Venedikut.", "42162c0d"]},
"OLAYLAR_EK5:1716-04-13:0":{"b": ["Austria dhe Venediku lidhën aleancë — dera e luftës osmano-austriake të viteve 1716-1718", "99511ca2"], "d": ["Pasi osmanët ia rimorën Morenë Venedikut, Austria, duke pretenduar se ishte shkelur Traktati i Karllofçës, nënshkroi me Venedikun një traktat aleance; princ Eugjeni, në letrën që i shkroi vezirit të madh, kërkoi kthimin e vendeve të marra nga Venediku. Në këshillimin në kampin ushtarak të Davutpashës, nën trysninë e vezirit të madh Ali Pasha, Austrisë iu shpall luftë dhe për këtë u mor fetva nga shejhulislami.", "4a2089d7"]},
"OLAYLAR_EK5:1716-04-24:0":{"b": ["Veziri i madh Ali Pasha u nis në fushatë kundër Austrisë", "2fbdce42"], "d": ["Pas shpalljes së luftës kundër Austrisë, serdari ekrem Ali Pasha u nis në fushatë kundër Austrisë me një ushtri prej mbi 100.000 vetash; ndërsa flota, po atë verë, u drejtua nga Korfuzi. Ushtria do të marshonte nga Beogradi mbi Petrovaradin dhe në disfatën e fillimit të gushtit veziri i madh do të binte dëshmor.", "02a5590b"]},
"OLAYLAR_EK5:1716-08-05:0":{"b": ["Disfata e Petrovaradinit (Varadinit) — rënia dëshmor e Damad Ali Pashës", "265c1d81"], "d": ["Ushtria osmane, që kaloi Danubin përmes Beogradit, u përball para Petrovaradinit me forcat austriake nën komandën e princ Eugjenit; ndonëse në hovin e parë sulmi i jeniçerëve i shtrëngoi llogoret armike, me shembjen e krahut të kalorësisë radhët u shpërndanë. Veziri i madh Silahdar Damad Ali Pasha u godit në ballë dhe ra dëshmor, ndërsa kampi ushtarak dhe pajisjet e artilerisë ranë tërësisht në duart e armikut. Kjo disfatë, që kronikat osmane e përmendin si 'viti i Varadinit', ishte hallka e parë e zinxhirit që çoi në humbjen e Temeshvarit dhe vitin pasues të Beogradit.", "ad21a2c3"]},
"OLAYLAR_EK5:1716-08-20:0":{"b": ["Dështimi i rrethimit të Korfuzit", "b2aa7011"], "d": ["Seraskeri i Moresë, Kara Mustafa Pasha, nga toka dhe kapudan pasha Xhanëm Hoxha Mehmet Pasha me flotë nga deti iu vërsulën Korfuzit; ishulli ishte baza kyçe e Venedikut në Adriatik. Megjithatë, fortifikimet jashtëzakonisht të forta të kështjellës, përforcimet e sjella nga flota venedikase dhe lajmet e disfatës që vinin nga fronti i Danubit çuan në heqjen e rrethimit. Mosmarrja e Korfuzit e shoi entuziazmin që ishte ngjallur me ripushtimin e Moresë dhe e zhvendosi qendrën e rëndesës së luftës në Hungari.", "4589579c"]},
"OLAYLAR_EK5:1716-10-13:0":{"b": ["Humbja e Temeshvarit nga Austria", "27fe1365"], "d": ["Pas disfatës së Petrovaradinit, princ Eugjeni marshoi drejtpërdrejt mbi Temeshvar dhe kështjella, në fund të një rrethimi që kaloi dyzet ditë, u dorëzua me kusht (vire). Kështu humbi qyteti që ishte pushtuar në vitin 1552 në kohën e Sulejmanit Ligjvënës dhe që për 164 vjet, si qendër bejlerbejllëku, konsiderohej shtylla lindore e mbrojtjes së Hungarisë. Me rënien e Temeshvarit, e gjithë krahina e Banatit kaloi te Austria dhe kufiri osman u shty në jug të Danubit. Vendbanimet e tjera që në atlas kalojnë po atë datë nga osmanët te habsburgët: Csákóvár, Facset dhe Karánşebeş (Caransebeş) — bashkë me dorëzimin e ejaletit të Temeshvarit (TDV timisvar; në burim nuk ka ditë në nivel vendi, zinxhiri i qendrës mëmë, përafrim i deklaruar).", "a1408ad1"]},
"OLAYLAR_EK5:1716-11-16:0":{"b": ["Dorëzimi i kështjellës së Haramit (Palanka e Re) Austrisë — humbi bregu danubian i Banatit", "38ee4c6d"], "d": ["Gjenerali i kalorësisë austriake Mercy, i ngarkuar pas rënies së Temeshvarit me marrjen e pjesës tjetër të Banatit, më 14 nëntor marshoi mbi Haramin (Palanka e Re) në bregun e Danubit; kur më 16 nëntor arriti te kështjella, garnizoni osman prej 200 vetash ngriti flamurin e bardhë dhe u dorëzua me kushtin e tërheqjes së lirë. Kështu edhe vija danubiane e Banatit Jugor, që ishte në duart osmane që nga viti 1552, kaloi te Austria. Vendbanimi tjetër që në atlas kalon po atë datë nga osmanët te habsburgët: Versec — ndjek zinxhirin e qendrës mëmë të Haramit (Bánlaky 0019/1703; përafrim i deklaruar).", "5b54ecb0"]},
"OLAYLAR_EK5:1718-07-21:0":{"b": ["Traktati i Pasarofçës — u fitua Morea, u humbën Beogradi dhe Banati", "d46aa216"], "d": ["Morea i ishte rimarrë Venedikut, por Austria, që hyri në luftë, me fitoret në Petrovaradin dhe Beograd u ul në tryezë me epërsi. Traktati, i nënshkruar me ndërmjetësimin e Anglisë dhe Holandës, ia la Morenë osmanëve, kurse në këmbim bashkë me Beogradin iu lëshuan Austrisë Serbia Veriore, Banati dhe Vllahia e Vogël; sipas shprehjes së TDV-së, 'Bosnja Veriore iu la tërësisht Austrisë' — kështjellat përgjatë Savës, si Dubica boshnjake dhe Bosanski Brodi, kalojnë në hartë te Austria nga kjo ditë (kufirin e saktë komisarët e vizatuan një nga një, TDV nuk i përmend me emër këto kështjella); ndërsa Venediku ruajti pozicionet në bregun e Jonit si Preveza dhe Kithera. Me ahidnamenë tregtare të nënshkruar po atë ditë, dogana mbi mallrat austriake u ul nga pesë në tre për qind. Traktati, ndërsa konfirmonte tërheqjen e Shtetit Osman në Evropën Qendrore, me paqen njëzet e shtatëvjeçare që hapi hodhi bazën e Epokës së Tulipanëve (1718-1730): shtypshkronja e parë osmane nën drejtimin e Nevshehirli Damad Ibrahim Pashës (1727, Ibrahim Myteferrika), komisionet e përkthimit, vëzhgimet për vaksinën e lisë dhe një jetë e re oborrtare e kulturore janë fryt i këtyre viteve paqeje. Vendbanimet e tjera që ndërruan dorë po atë ditë në atlas: Kraiova (Craiova), Rimniku (Râmnicu Vâlcea) dhe Turnu Severini (Vllahia e Vogël/Oltenia, nga osmanët te Austria) si dhe Ajamavra (Lefkada) (nga osmanët te Venediku; TDV ayamavra: më 1718 me Traktatin e Pasarofçës ishulli iu lëshua Venedikut). Në Vllahinë e Vogël, veç kësaj, Tërgu Zhiu kalon te Austria; Vonitsa (Voniçe, TDV pasarofca-antlasmasi) dhe ishulli i Kitherës (TDV cuka-adasi: neni 3 i Pasarofçës) kalojnë te Venediku.", "ec4430bf"]},
"OLAYLAR_EK5:1723-06-15:0":{"b": ["Fushata lindore: marrja e Tiflisit dhe fillimi i luftës me Iranin", "78343dc2"], "d": ["Kur shteti safavid u shemb nga pushtimi afgan dhe Rusia zbriti në brigjet e Kaspikut, Shteti Osman dërgoi ushtri në lindje që vakuumi të mos i mbetej tërësisht ndikimit rus. Duke marrë Tiflisin, Gjeorgjia u lidh me administrimin osman; pastaj përparimi vazhdoi në drejtim të Gjanxhës, Jerevanit dhe Nahiçevanit. Kjo fushatë, e zhvilluar prapa pamjes paqësore të Epokës së Tulipanëve, u bë fillimi i një aventure të gjatë lindore që do të zgjaste trembëdhjetë vjet dhe do të përfundonte me kthimin e çdo vendi të fituar.", "5c412d91"]},
"OLAYLAR_EK5:1723-08-01:0":{"b": ["Fushata e Iranit e vitit 1723: hyrja në Shirvan dhe Gjeorgji", "c81189fc"], "d": ["Pas shembjes së shtetit safavid nga pushtimi afgan, me arsyetimin se duhej penguar zbritja e Rusisë në brigjet e Kaspikut, u hap një fushatë drejt lindjes. Ushtria e Erzurumit hyri përmes Gjeorgjisë në Tiflis, kurse krahu i Shirvanit në Shamahi, duke rimarrë tokat e humbura njëqind e tridhjetë vjet më parë. Kjo fushatë ishte përparimi i fundit i madh osman në Kaukaz.", "9f84acd9"]},
"OLAYLAR_EK5:1723-10-01:0":{"b": ["Marrja e Kermanshahut — porta e Zagrosit", "ad14799f"], "d": ["Ushtria e Bagdadit, duke kapërcyer qafat e Zagrosit, shtiu në dorë Kermanshahun, që konsiderohej porta perëndimore e Iranit. Qyteti ndodhej mbi rrugën e karvaneve dhe ushtrive që shkonte nga Bagdadi në Isfahan dhe marrja e tij siguronte sigurinë lindore të ejaletit të Irakut. Ky përparim nisi garën e ndarjes mes osmanëve dhe Rusisë në vendin safavid që po shpërbëhej.", "65dba49c"]},
"OLAYLAR_EK5:1724-06-24:0":{"b": ["Marrëveshja e Ndarjes së Stambollit — ndarja e Iranit me Rusinë", "fce8eec2"], "d": ["Për të shmangur përballjen mes osmanëve dhe Rusisë mbi vendin safavid në shembje, me ndërmjetësimin e ambasadorit francez u nënshkrua një traktat ndarjeje. Brigjet perëndimore dhe jugore të Detit Kaspik iu lanë Rusisë, ndërsa Gjeorgjia, Shirvani, Azerbajxhani dhe qytetet e Iranit Perëndimor Shtetit Osman. Kjo ndarje, që në letër dukej si fitim i madh, pas pak kohe, me ngritjen e Nadir Shahut, do të mbetej faktikisht e pavlefshme. Sipas traktatit, tokat pjellore të Shirvanit si Shabrani dhe Mushkuri iu lanë palës ruse (Çaycıoğlu, DergiPark).", "7b0b411b"]},
"OLAYLAR_EK5:1724-08-11:0":{"b": ["Marrja e Nahiçevanit", "bdf14d0a"], "d": ["Forcat osmane që përparonin përgjatë Araksit morën Nahiçevanin dhe Ordubadin; edhe Xhulfa iu bashkua livasë së Nahiçevanit. Qyteti, si porta veriperëndimore e Iranit, iu lidh ejaletit të sapokrijuar të Jerevanit. Kështu kufiri osman arriti përsëri vijën më lindore të kohës së Sulejmanit Ligjvënës.", "9e602879"]},
"OLAYLAR_EK5:1724-08-31:0":{"b": ["Pushtimi i Hamadanit", "e1339a97"], "d": ["Ushtria që marshoi nga Kermanshahu drejt lindjes, pas një rrethimi të gjatë mori Hamadanin në pragun perëndimor të rrafshnaltës iraniane. Qyteti ishte ndalesa e fundit e madhe e rrugës për Isfahan, pikës më lindore ku ushtritë osmane kishin mundur të arrinin që nga Fushata e Irakejnit. Po atë vit, marrëveshja e Stambollit e nënshkruar me Rusinë e hodhi në letër ndarjen e Iranit në shpërbërje mes osmanëve dhe Rusisë.", "81552031"]},
"OLAYLAR_EK5:1724-10-03:0":{"b": ["Ripushtimi i Jerevanit", "88acabef"], "d": ["Pas një rrethimi të ashpër nëntëdhjetëditor, kështjella kyçe e luginës së Araksit, Jerevani, hyri përsëri nën administrimin osman. Kështjella, e ndërtuar më 1583 dhe e humbur më 1604, kësaj radhe u përforcua me një garnizon më të fortë. Gjatësia e rrethimit ishte tregues se ushtria osmane nuk përparonte më lehtë. Edhe nahijet Karpi (Üçkilise), Sherur, Maku dhe Shuregel iu lidhën ejaletit të Jerevanit.", "a989b1eb"]},
"OLAYLAR_EK5:1725-07-28:0":{"b": ["Marrja e Tabrizit — shtënia në dorë e Azerbajxhanit", "e502a4f7"], "d": ["Tabrizi, i rrethuar sërish pas përpjekjes së pasuksesshme të një viti më parë, pas një beteje të ashpër rrugë më rrugë iu dorëzua ushtrisë osmane. Edhe Merandi, Maraga dhe Savuxhbulaku (Mahabadi), që vareshin nga ejaleti i Tabrizit, hynë nën administrimin osman. Po atë vit u morën edhe Lori, Gjanxha, Ardebili dhe Hurremabadi, dhe zonat që sipas Marrëveshjes së Ndarjes së Stambollit u binin osmanëve u pushtuan faktikisht. Kjo shtrirje e arritur në lindje ishte kufiri më i përparuar që nga koha e Traktatit të Ferhat Pashës; por mbajtja e saj i ngarkoi ushtrisë dhe thesarit një barrë të rëndë.", "e0953563"]},
"OLAYLAR_EK5:1725-09-04:0":{"b": ["Pushtimi i Gjanxhës — fundi i fushatës së Kaukazit", "875bca7a"], "d": ["Gjanxha, objektivi i fundit i operacionit kaukazian, u mor në dorëzim si qendra e Karabakut mes Kurës dhe Araksit. Me plotësimin e vijës Shirvan, Jerevan, Nahiçevan dhe Gjanxhë, Shteti Osman arriti në Kaukaz shtrirjen e vitit 1590. Megjithatë, ky fitim ishte jetëshkurtër: ngritja e Nadir Shahut brenda dhjetë vjetëve do të rimerrte gjithë rajonin.", "265db7e0"]},
"OLAYLAR_EK5:1727-10-04:0":{"b": ["Traktati i Hamadanit — bashkimi i Iranit Perëndimor me osmanët", "94a29dc3"], "d": ["Me traktatin e nënshkruar me sundimtarin afgan Eshref Shah përfundoi lufta katërvjeçare dhe u njohën juridikisht tokat e Iranit Perëndimor të pushtuara nga Shteti Osman. Në këmbim, Eshref Shahu pranoi hilafetin e padishahut osman dhe mori përsipër që në Iran hytbeja të lexohej në emër të padishahut. Kjo fitore diplomatike ishte jetëshkurtër; kundërofensiva që Nadir Shahu nisi në vitin 1730 do t'i fshinte brenda pak vitesh fitimet e traktatit.", "fd0174b9"]},
"OLAYLAR_EK5:1731-01-01:0":{"b": ["Hekimoglu Ali Pasha mori Urminë", "eac7f64d"], "d": ["Në fushatën e Iranit, Hekimoglu Ali Pasha mori fillimisht Urminë (Rumije), pastaj, më 15 nëntor 1731, Tabrizin e boshatisur për osmanët. TDV nuk jep ditën e marrjes së Urmisë; dihet vetëm viti dhe që ndodhi para Tabrizit.", "f99d74f9"]},
"OLAYLAR_EK5:1732-01-08:0":{"b": ["Traktati i Ahmet Pashës — kthimi i pjesës më të madhe të Iranit Perëndimor", "590d839f"], "d": ["Pas fitores së Nadir Shahut në Malajer dhe sulmeve iraniane të njëpasnjëshme, valiu i Bagdadit, Ahmet Pasha, nënshkroi një tekst paqeje pa u këshilluar me qendrën. Sipas traktatit, lumi Araks u pranua si kufi; qytetet e Iranit Perëndimor si Hamadani, Kermanshahu, Ardelani, Ardebili dhe Tabrizi iu kthyen Iranit, ndërsa Gjanxha dhe Tiflisi mbetën te osmanët. Ky tekst, që në Stamboll u prit me reagim, u gjet i pamjaftueshëm edhe nga Nadir Shahu, dhe para se të mbushej viti 1732 lufta u ndez përsëri. Atlasi e konsideron se edhe Koturi, që ndjek zinxhirin e Hoit, kalon po atë ditë nga osmanët te safavidët (TDV hoy; për Koturin nuk ka ditë të veçantë në burim — përafrim i deklaruar).", "fdaa1e6f"]},
"OLAYLAR_EK5:1732-07-01:0":{"b": ["Humbja e dytë e Oranit (Vahran) nga Spanja", "20485027"], "d": ["Flota e madhe zbarkuese e dërguar nga mbreti i Spanjës, Filipi V, nën komandën e kontit Montemar mbërriti para Oranit, i theu forcat e Odxhakut të Algjerisë dhe e rimori qytetin. Porti i pushtuar njëzet e katër vjet më parë do të mbetej përsëri gjashtëdhjetë vjet në duart e garnizonit spanjoll. Kjo humbje, që tregoi kufijtë e fuqisë së odxhaqeve të Perëndimit në Mesdheun perëndimor, mundi të kompensohej vetëm në vitin 1792 me pushtimin përfundimtar të Oranit.", "b255a8da"]},
"OLAYLAR_EK5:1733-05-01:0":{"b": ["Reformimi i odxhakut të humbaraxhinjve sipas mënyrës evropiane dhe themelimi i Humbarahanes", "d980cf2a"], "d": ["Humbaraxhi Ahmet Pasha me origjinë franceze, që hyri në shërbim osman, me mbështetjen e vezirit të madh Hekimoglu Ali Pasha e shndërroi odxhakun e humbaraxhinjve në një njësi me rrogë dhe të organizuar sipas modelit evropian. Treqind ushtarëve të rekrutuar nga Bosnja iu dha arsim i rregullt i bazuar në llogaritje dhe gjeometri; u përgatitën rregullore të reja për organizimin, pajisjet dhe pensionimin dhe me teknikë bashkëkohore u prodhuan njëqind topa humbare dhe pesëdhjetë mijë predha. Humbarahaneja, ku mësohej gjeometria, konsiderohet bërthama e parë e arsimit modern të inxhinierisë ushtarake te osmanët.", "181b7161"]},
"OLAYLAR_EK5:1736-06-24:0":{"b": ["Vdekja e Ahmetit III", "455f7fba"], "d": ["Ahmeti III, i rrëzuar nga froni më 1730 me kryengritjen e Patrona Halilit, gjashtë vitet e fundit të jetës i kaloi në apartamentin e Sarajit Topkapë të rezervuar për padishahët e rrëzuar dhe vdiq në moshën gjashtëdhjetë e tre vjeç. U varros në tyrben e gjyshes së tij Turhan Sulltan pranë xhamisë Jeni në Bahçekapë.", "00cc8767"]},
"OLAYLAR_EK5:1736-09-01:0":{"b": ["Traktati i Stambollit — lënia e Kaukazit Jugor Iranit", "8c205aab"], "d": ["Lufta e dytë me Iranin, që zgjati katër vjet, përfundoi me traktatin e nënshkruar pas disfatës së Arpaçajit dhe humbjes së Gjanxhës e të Tiflisit. Shteti Osman u tërhoq nga të gjitha tokat e Kaukazit Jugor dhe të Iranit Perëndimor që kishte shtënë në dorë që nga viti 1723, dhe kufiri u kthye në vijën e Kasr-i Shirinit të vitit 1639. Nga fushatat lindore trembëdhjetëvjeçare mbetën një barrë e rëndë financiare dhe një thesar i zbrazur; megjithatë, mbyllja e frontit lindor ishte një fitim jetik për luftën e re që kishte filluar me Rusinë.", "bcb0cbe8"]},
"OLAYLAR_EK5:1737-07-11:0":{"b": ["Rënia e kështjellës së Ozit (Oçakovit) në duart ruse", "f93e61f3"], "d": ["Ushtria ruse nën komandën e mareshalit Münnich e rrethoi kështjellën e Ozit në grykën e Dnjeprit; me shpërthimin e depos së municionit mbrojtja u shemb dhe kështjella ra me humbje të mëdha jetësh. Humbja e Ozit, që konsiderohej çelësi i bregut veriperëndimor të Detit të Zi, ua hapi rusëve rrugën për në Krime dhe shkaktoi panik të madh në Stamboll. Vitin pasues, për shkak të epidemisë dhe vështirësive të furnizimit, rusët e boshatisën kështjellën dhe ajo kaloi përsëri te osmanët.", "479e0090"]},
"OLAYLAR_EK5:1737-08-04:0":{"b": ["Fitorja e Banja Llukës — shpëtimi i Bosnjës", "f603865a"], "d": ["Kur forcat austriake hynë në Bosnjë dhe rrethuan Banja Llukën, valiu i Bosnjës, Hekimoglu Ali Pasha, nxitoi në ndihmë me forcat që mblodhi nga popullsia vendëse dhe i shkaktoi armikut, më të madh në numër, një disfatë të rëndë. Kjo fitore e shembi që në hapin e parë planin austriak për pushtimin e Bosnjës dhe veriu i ejaletit u rimor plotësisht. Banja Lluka u bë një nga pikat e kthesës që e ngritën moralin e ushtrisë osmane, e cila pas vitit 1683 vazhdimisht tërhiqej përballë Austrisë.", "81c1850e"]},
"OLAYLAR_EK5:1739-07-22:0":{"b": ["Fitorja e Hisarxhëkut (Grocka) — hapja e rrugës për në Beograd", "2101cdff"], "d": ["Ushtria austriake, që përparonte për të mbrojtur Beogradin, ra në pritë në grykën e ngushtë buzë Danubit dhe pësoi humbje të rënda në betejën që zgjati gjithë ditën. Ndërsa forcat e mareshalit Wallis tërhiqeshin në mënyrë të çrregullt drejt Beogradit, ushtria osmane arriti para kështjellës dhe nisi rrethimin. Hisarxhëku ishte fitorja më vendimtare në fushëbetejë kundër Austrisë që nga Karllofça dhe bëri të mundur drejtpërdrejt rimarrjen e Beogradit.", "5811893a"]},
"OLAYLAR_EK5:1739-10-03:0":{"b": ["Traktati i Nishit — paqja me Rusinë, neutralizimi i Azovit dhe ndalimi i inkursioneve të Krimesë", "674f974e"], "d": ["Rusia, e mbetur vetëm pasi Austria pranoi paqen në Beograd, me ndërmjetësimin e ambasadorit francez Villeneuve u detyrua t'i jepte fund luftës. Fortifikimet e kështjellës së Azovit u shkatërruan dhe zona u shpall tokë neutrale mes dy shteteve; Rusia pranoi kushtin për të mos mbajtur anije lufte dhe tregtare në Detin e Zi. Kështu synimi i Rusisë për të dalë në det u shty edhe për një brez dhe Shteti Osman u ngrit për herë të fundit në shekullin XVIII nga tryeza me fitim.", "7ca0d614"]},
"OLAYLAR_EK5:1739-12-12:0":{"b": ["Ozi u kthye nga pushtimi rus: me paqen e 1739-s u dorëzua pasi kështjella u shkatërrua", "7ecc2bef"], "d": ["Rusët e kishin marrë Ozin më 11 korrik 1737. Sipas paqes së bërë me Rusinë në vitin 1739, kështjella iu dorëzua përsëri osmanëve pasi u shkatërruan fortifikimet e saj; osmanët e mbajtën Ozin deri në vitin 1788, para Traktatit të Jashit.", "39ee6708"]},
"OLAYLAR_EK5:1743-10-23:0":{"b": ["Mbrojtja e Mosulit — zmbrapsja e Nadir Shahut", "c03ffbc1"], "d": ["Nadir Shahu, që pasi mori Kirkukun dhe Erbilin arriti para Mosulit, e goditi qytetin me topa për dyzet ditë dhe organizoi sulme të përgjithshme të njëpasnjëshme. Mbrojtja që drejtoi valiu Husein Pasha el-Xhelili, duke armatosur edhe popullsinë e qytetit, e detyroi ushtrinë iraniane të hiqte rrethimin me humbje të rënda. Qëndresa e Mosulit e pengoi humbjen e gjithë Irakut dhe e përforcoi për një shekull ndikimin e familjes Xhelili në qytet.", "b9f67e29"]},
"OLAYLAR_EK5:1744-01-01:0":{"b": ["Aleanca e Dirijes — themelimi i emiratit të parë saudit në Nexhd", "188751bf"], "d": ["Emiri Muhammed b. Suud, që e mori në mbrojtje në Dirije dijetarin Muhammed b. Abdulvehhab të dëbuar nga Ujejneja, lidhi me të një aleancë që e vinte autoritetin politik në shërbim të thirrjes fetare. Kjo marrëveshje nisi një histori të re për familjen Suud dhe i bashkoi emiratet e shpërndara të oazeve të Nexhdit rreth një lëvizjeje të vetme. Kjo fuqi, që brenda gjysmë shekulli do të shtrihej deri në Qerbela, Mekë dhe Medinë, do ta detyronte Shtetin Osman të mbronte sundimin e vet në Hixhaz.", "6843c874"]},
"OLAYLAR_EK5:1746-09-04:0":{"b": ["Traktati i Kerdenit — fundi i luftërave osmano-iraniane", "1d3a919e"], "d": ["Me traktatin e nënshkruar pas luftës së fundit katërvjeçare, kufiri i Kasr-i Shirinit të vitit 1639 u ripërtëri siç ishte; asnjëra palë nuk arriti të fitonte toka. Kërkesa këmbëngulëse e Nadir Shahut që xhaferizmi të njihej si medhhebi i pestë mbeti pa përgjigje, ndërsa u vendos që haxhilerët iranianë të bënin lirisht haxhin dhe të këmbeheshin ambasadorë. Kështu luftërat osmano-iraniane, që kishin zgjatur mbi dy shekuj, u mbyllën faktikisht; ky kufi është ruajtur në masë të madhe deri sot.", "2a089331"]},
"OLAYLAR_EK5:1754-12-13:0":{"b": ["Vdekja e Mahmudit I dhe hipja në fron e Osmanit III", "30203700"], "d": ["Mahmudi I, që gjatë sundimit të tij njëzet e katërvjeçar me Traktatin e Beogradit rimori tokat e humbura dhe mbështeti reformën e odxhakut të humbaraxhinjve, vdiq duke u kthyer nga ceremonia e xhumasë (cuma selamlığı). Në vend të tij hipi vëllai i tij Osmani III, që kishte jetuar në kafaz deri në moshën pesëdhjetë e tetë vjeç. Filloi një sundim i shkurtër e i shqetësuar; në kohën e Osmanit III, që brenda tre vjetëve ndërroi gjashtë vezirë të mëdhenj, në punët shtetërore sundoi një amulli e dukshme.", "8bdf7c4e"]},
"OLAYLAR_EK5:1757-10-30:0":{"b": ["Vdekja e Osmanit III dhe hipja në fron e Mustafait III", "3ac10f85"], "d": ["Pas vdekjes së Osmanit III, pas një sundimi trevjeçar, në fron hipi Mustafai III, i hapur ndaj ideve të reformës dhe me interesim të afërt për punët shtetërore. Padishahu i ri, duke u mbështetur në përvojën e vezirit të madh Koxha Ragëp Pashës, u përpoq të ndreqte financat dhe të ripërtërinte ushtrinë; topçinjtë e shpejtë të Baron de Tott-it u krijuan në këtë periudhë. Megjithatë, lufta me Rusinë, ku u hy në vitin 1768, do të linte në hije të gjitha arritjet e sundimit shtatëmbëdhjetëvjeçar.", "2d13aff2"]},
"OLAYLAR_EK5:1768-10-08:0":{"b": ["Shpallja e luftës Rusisë — ngjarja e Baltës dhe fillimi i luftës së viteve 1768-1774", "9c6aabe0"], "d": ["Kur njësitë ruse dhe kozake, që ndiqnin Konfederatën e Barit në Poloni, sulmuan dhe dogjën qytezën Balta në kufirin osman, Divani vendosi për luftë dhe ambasadori rus u burgos në Jedikule. Lufta, në të cilën u hy pa një përgatitje serioze ushtarake dhe duke u shpallur gjashtë muaj përpara, shkoi keq që në fillim. Ky konflikt që do të zgjaste gjashtë vjet, me djegien e flotës në Çeshme, disfatën e Kagulit dhe pushtimin e Krimesë, do të shndërrohej në një nga vargjet më të rënda të disfatave në historinë osmane.", "18bfa4d5"]},
"OLAYLAR_EK5:1769-09-20:0":{"b": ["Humbja e kështjellës së Hotinit nga rusët", "66d43ea4"], "d": ["Ndonëse dy përpjekjet e ushtrisë ruse nën komandën e princit Golicin u zmbrapsën, pas disfatës që veziri i madh pësoi mes Kamianecit dhe Hotinit ushtria u tërhoq dhe garnizoni e boshatisi kështjellën. Humbja pa rezistencë e fortifikimit më të fortë osman në veri të Danubit ua hapi rusëve dyert e Vllahisë dhe Moldavisë. Të dy principatat u pushtuan po atë vit; Hotini mundi të rimerrej vetëm në vitin 1774 me Traktatin e Kyçyk-Kajnarxhës.", "1d0b219f"]},
"OLAYLAR_EK5:1770-08-01:0":{"b": ["Disfata e fushës së Kagulit (Kartal)", "6f408eaf"], "d": ["Tri javë pas djegies së flotës në Çeshme, ushtria kryesore osmane në brigjet e Danubit u shpërnda në fushën e Kagulit përballë njësive shumë më të vogla në numër, por të disiplinuara, të mareshalit Rumjancev. Kampi ushtarak, bagazhet dhe qindra topa ranë në duart e armikut; njësitë që iknin pësuan humbje të mëdha duke kaluar Danubin. Asgjësimi brenda së njëjtës verë si i flotës ashtu edhe i ushtrisë tokësore çoi në rënien njëra pas tjetrës të Kilisë, Akermanit, Ismailit dhe Benderit dhe në pushtimin e Krimesë.", "0fd97052"]},
"OLAYLAR_EK5:1771-07-01:0":{"b": ["Pushtimi rus i gadishullit të Krimesë", "217837b0"], "d": ["Ushtritë ruse, që një vit më parë kishin shtënë në dorë Buxhakun, nën komandën e princit Dollgorukov kapërcyen Or Kapinë dhe pushtuan tërë gadishullin e Krimesë. Hani u rrëzua nga froni dhe në krye u vu Sahib Giraj, ithtar i Rusisë, duke hedhur hapin e parë drejt shkëputjes së hanatit nga osmanët. Humbja e Krimesë, që për tri shekuj kishte qenë mburoja veriore e osmanëve, ishte fillimi i procesit të pavarësisë në vitin 1774 dhe të aneksimit të drejtpërdrejtë në vitin 1783.", "952270d8"]},
"OLAYLAR_EK5:1774-01-21:0":{"b": ["Vdekja e Mustafait III dhe hipja në fron e Abdylhamidit I", "42cba8e2"], "d": ["Në vend të Mustafait III, që vdiq në çastin më kritik të luftës me Rusinë, në fron hipi në moshën dyzet e nëntë vjeç vëllai i tij Abdylhamidi I, i cili kishte kaluar dyzet e tre vjet në kafazin e sarajit. Padishahu i ri, që mori trashëgim një nga periudhat më të vështira të shtetit, u detyrua të përballej me kushtet e rënda të Traktatit të Kyçyk-Kajnarxhës, që do të nënshkruhej po atë vit. Sundimi i tij pesëmbëdhjetëvjeçar do të kalonte me humbjen e Krimesë dhe me një luftë të re me Rusinë dhe do të përfundonte me goditjen në tru që pësoi në vitin 1789 teksa lexonte lajmin e rënies së Ozit.", "05963836"]},
"OLAYLAR_EK5:1774-06-25:0":{"b": ["Disfata e Kozllugjës — humbja që çoi në Kyçyk-Kajnarxhë", "8e0542f9"], "d": ["Forcat osmane të mbledhura para Shumenit u mundën në Kozllugjë nga kolonat e bashkuara të Suvorovit dhe Kamenskit dhe pjesa më e madhe e ushtrisë u shpërnda. Me këtë disfatë nuk mbeti forcë për të rezistuar në Ballkan; pararojat ruse e rrethuan Shumenin dhe shtabi i vezirit të madh u vu nën kërcënim. Ulja në tryezë në Kyçyk-Kajnarxhë para se të mbushej një muaj dhe pranimi i kushteve jashtëzakonisht të rënda janë pasojë e drejtpërdrejtë e kësaj disfate.", "6721d6e3"]},
"OLAYLAR_EK5:1775-05-07:0":{"b": ["Lëshimi i Bukovinës (Moldavisë Veriore) Austrisë", "190f9caa"], "d": ["Austria, duke përfituar nga dobësia që shkaktoi Kyçyk-Kajnarxha, kërkoi krahinën e Bukovinës, që siguronte lidhjen mes Moldavisë dhe Transilvanisë, dhe e fitoi këtë tokë me kërcënim e ryshfet, pa hyrë në luftë. Humbja e kësaj krahine pjellore dhe strategjike në jugperëndim të Hotinit e ndau faktikisht në dysh vojvodllëkun e Moldavisë. Ky lëshim, i ndodhur pa u shtënë as edhe një plumb, u konsiderua një nga treguesit më të qartë se Shteti Osman e kishte humbur tashmë aftësinë frenuese. Me lëshimin e Bukovinës më 1775, Suçava dhe Çernovici kaluan te Austria (dita e pavërtetuar).", "93bbc1f7"]},
"OLAYLAR_EK5:1776-04-16:0":{"b": ["Pushtimi iranian i Basrës", "0161e709"], "d": ["Sadik Han, vëllai i sundimtarit zend Kerim Han, pas një rrethimi njëvjeçar shtiu në dorë Basrën dhe Shteti Osman humbi portin e vet më të rëndësishëm në Gjirin e Basrës. Pushtimi goditi drejtpërdrejt rrugën tregtare të Indisë, të ardhurat nga hurmat e margaritarët dhe mbrojtjen jugore të Irakut. Qyteti mundi të rimerrej vetëm më 1779, gjatë luftërave për fron që shpërthyen në Iran pas vdekjes së Kerim Hanit.", "838306ba"]},
"OLAYLAR_EK5:1779-03-21:0":{"b": ["Marrëveshja Shpjeguese e Ajnallëkavakut — kompromis i përkohshëm për Krimenë", "9b3b0468"], "d": ["Të dy shtetet, që për çështjen se kush do të vihej në krye të hanatit të Krimesë kishin arritur në prag të luftës, me ndërmjetësimin e Francës nënshkruan në Qoshkun e Ajnallëkavakut një tekst shpjegues. Rusia pranoi të tërhiqte ushtarët nga Krimea, ndërsa Shteti Osman të njihte hanllëkun e Shahin Girajt, ithtar i Rusisë; u konfirmua e drejta fetare e hilafetit të padishahut mbi Krimenë. Ky ekuilibër i brishtë, që do të zgjaste katër vjet, do të shembej plotësisht në vitin 1783, kur Rusia e aneksoi drejtpërdrejt gadishullin.", "8a428802"]},
"OLAYLAR_EK5:1781-01-01:0":{"b": ["Ndërtimi i kështjellës së Anapës — vija mbrojtëse kaukaziane", "be92a80f"], "d": ["Kur me Kyçyk-Kajnarxhën Krimea doli nga dora, për të ruajtur ndikimin osman në Kaukaz u nis ndërtimi i një kështjelle të re në grykën e lumit Kuban. Anapa, e ngritur mbi rrënojat e kolonisë gjenoveze, me pazarin, hamamet dhe më shumë se dyqind e pesëdhjetë dyqanet, brenda pak kohe u bë qytet që siguronte lidhjen me fiset çerkeze. Kështjella mbeti për dyzet e tetë vjet postblloku më i përparuar osman kundër zbritjes së Rusisë në Kaukaz.", "334a40cb"]},
"OLAYLAR_EK5:1785-04-27:0":{"b": ["Shkarkimi dhe ekzekutimi i vezirit të madh Halil Hamid Pashës", "c44001ca"], "d": ["Veziri i madh reformator Halil Hamid Pasha, me shërbimet e të cilit Abdylhamidi I e kishte shprehur kënaqësinë në raste të ndryshme, në agim të 31 marsit 1785 u shkarkua befas, u internua në Galipoli dhe të gjitha pasuritë iu konfiskuan. Fillimisht iu dhanë ejaleti i Habeshit, sanxhaku i Xhedës dhe posti i sheikulharemit të Mekës; ndërsa prillin 1785 e kalonte në Tenedos duke u përgatitur për rrugë, u shkarkua edhe nga kjo detyrë dhe me fermanin e ekzekutimit që doli u vra nga Karakethüdazade Ali, një nga njerëzit e Gazi Hasan Pashë Algjerianit. Koka e prerë u dërgua në Stamboll dhe u ekspozua në Portën e Mesme (Ortakapı). Sipas TDV-së, ndonëse kjo rënie e beftë është interpretuar me akuzën për komplot për të rrëzuar padishahun dhe për të vënë në vend shehzade Selimin, shkaqet e vërteta duhet të kenë qenë zemërimi për heshtjen e tij ndaj aneksimit të Krimesë, armiqësia e qarqeve të dëmtuara nga reformat e tij dhe kundërshtimi i Gazi Hasan Pashës.", "6f73b0a5"]},
"OLAYLAR_EK5:1787-08-16:0":{"b": ["Shpallja e luftës Rusisë — filloi lufta osmano-ruse e viteve 1787-1792", "3bfb870c"], "d": ["Për shkak të udhëtimit të bujshëm të Katerinës II në Krime dhe marrjes së Gjeorgjisë nën mbrojtjen e saj, Divani vendosi për luftë me synim kthimin mbrapsht të aneksimit dhe ambasadori rus u mbyll përsëri në Jedikule. Mirëpo ushtria nuk ishte gati, thesari ishte bosh dhe kërkimi i aleatëve kishte mbetur pa rezultat. Lufta që do të zgjaste pesë vjet do të përfundonte me rënien e Ozit me masakër, humbjen e Ismailit dhe kushtet e rënda të Traktatit të Jashit.", "80a26d8f"]},
"OLAYLAR_EK5:1788-02-09:0":{"b": ["Hyrja e Austrisë në luftë — luftë në dy fronte", "ae912290"], "d": ["Sipas aleancës së fshehtë që kishte bërë me Rusinë në vitin 1781, perandori austriak Jozefi II i shpalli luftë Shtetit Osman dhe u vu në veprim drejt Beogradit dhe Bosnjës. Ushtria osmane u detyrua befas të luftonte njëkohësisht në dy fronte, në veri me Rusinë dhe në perëndim me Austrinë. Megjithë fitoret e arritura ndaj austriakëve në Lazarethane, Mehadi dhe Sebesh, me humbjen e Beogradit më 1789 do të shembej edhe fronti perëndimor.", "402d5acd"]},
"OLAYLAR_EK5:1790-01-31:0":{"b": ["Aleanca osmano-prusiane", "03b88e51"], "d": ["Selimi III, që sapo hipi në fron kërkoi aleatë në Evropë, nënshkroi me Prusinë një traktat aleance që parashikonte ndihmë të ndërsjellë; Prusia u zotua t'i shpallte luftë Rusisë dhe Austrisë, ndërsa Shteti Osman të mos bënte paqe pa rimarrë Krimenë. Ky ishte teksti i parë i vërtetë i një aleance të ndërsjellë që në historinë osmane u nënshkrua me një shtet evropian dhe tregonte se po braktisej koncepti klasik 'nuk bëhet aleancë me qafirët'. Prusia nuk hyri në luftë, por duke e detyruar Austrinë të bënte paqe i hapi rrugën Traktatit të Sistovës.", "de29f327"]},
"OLAYLAR_EK5:1790-12-22:0":{"b": ["Rënia dhe masakra e kështjellës së Ismailit", "6a296b0c"], "d": ["Kështjella e Ismailit, që konsiderohej fortifikimi më i fortë i deltës së Danubit, u shtie në dorë brenda një dite me sulmin e përgjithshëm të përgjakshëm të organizuar nga gjenerali Suvorov; garnizoni dhe popullsia e qytetit u kaluan në masë të madhe në shpatë. Kjo masakër, që pati jehonë të gjerë në Evropë, shkaktoi tronditje të thellë në opinionin osman dhe e theu shtyllën kurrizore të vijës mbrojtëse të Danubit. Një vit më vonë kështjella do të rimerrej me Traktatin e Jashit, por fati i luftës do të ishte vendosur prej kohësh.", "225351fb"]},
"OLAYLAR_EK5:1791-08-04:0":{"b": ["Traktati i Sistovës — mbyllja e frontit austriak", "58741f1d"], "d": ["Falë trysnisë së Prusisë dhe faktit që Revolucioni Francez e mbante të zënë Austrinë në perëndim, të dy shtetet arritën paqen duke marrë për bazë kufijtë e paraluftës. Austria i ktheu të gjitha vendet e pushtuara, përfshirë Beogradin; Shteti Osman pranoi vetëm ndreqje të vogla në kufirin e Kroacisë. Mbyllja e frontit perëndimor me këto kushte i mundësoi Shtetit Osman të përqendronte gjithë forcën kundër Rusisë dhe e kufizoi humbjen në Traktatin e Jashit. Me këto ndreqje në kufirin kroat, Cetini (Cetingrad) dhe Drežnik Gradi kalojnë nga osmanët te habsburgët (TDV zistovi-antlasmasi; Korić 2016, shën. 118, neni 4). Orsova (Orsova e Vjetër) është i vetmi vend që nuk u kthye (Bánlaky 0019/1796); atlasi e shënon kalimin juridik në këtë ditë (pushtimi faktik më 16 prill 1790).", "83845e51"]},
"OLAYLAR_EK5:1792-01-10:0":{"b": ["Traktati i Jashit — humbja përfundimtare e Krimesë dhe kufiri i Dnjestrit", "a56fd194"], "d": ["Me traktatin e nënshkruar në fund të luftës pesëvjeçare, lumi Dnjestër (Turla) u pranua si kufi; bregu i majtë i lumit i mbeti Rusisë, bregu i djathtë osmanëve dhe Ozi me rrethinat humbi përfundimisht. Shteti Osman hoqi dorë plotësisht nga shpresa për të rimarrë Krimenë dhe e njohu juridikisht aneksimin e vitit 1783; Vllahia dhe Moldavia u kthyen me përjashtim dyvjeçar nga taksa. U pranua edhe detyrimi për dëmshpërblim lufte prej dymbëdhjetë milionë kurushësh dhe kështu veriu i Detit të Zi iu lëshua përgjithmonë Rusisë. Vendet e tjera që u bashkuan në të njëjtën datë: Ismaili.", "277ee99d"]},
"OLAYLAR_EK5:1792-02-12:0":{"b": ["Boshatisja e Oranit (Vahran) nga spanjollët dhe dorëzimi te Algjeria", "9f95cee6"], "d": ["Kur në tërmetin e vitit 1790 kështjella dhe qyteti u shkatërruan në masë të madhe, Spanja, që nuk mund ta mbante më garnizonin e kushtueshëm që e kishte mbajtur për tre shekuj, u mor vesh me odxhakun e Algjerisë dhe i dorëzoi pa luftë Oranin dhe Mers-el-Kebirin. Kështu u likuidua edhe pozicioni i fundit evropian në bregdetin e Afrikës Veriore. Algjeria osmane, për tridhjetë e tetë vjetët deri në pushtimin francez, mbeti zot e të gjithë bregdetit.", "c73636aa"]},
"OLAYLAR_EK5:1795-03-01:0":{"b": ["Sundimi faktik i Pazvandoglu Osmanit në Vidin", "0ce70361"], "d": ["Pazvandoglu Osmani, që u ngrit kundër rregullimeve të Nizam-i Xhedidit, duke e detyruar valiun e Vidinit të ikte, shtiu në dorë qytetin dhe e fortifikoi me hendeqe të thella përgjatë Danubit. Në kulmin e fuqisë së tij më 1797, duke mbledhur afro tetëdhjetë mijë forca, vuri nën kontroll Nikopolin, Sistovën, Rusçukun, Sofjen dhe Nishin; e paraqiste veten jo si rebel, por si reformator. Rrethimi i Portës së Lartë që zgjati me muaj në vitet 1798-1799 mbeti pa rezultat dhe ai sundoi gjysmë i pavarur në Bullgarinë Veriore deri në vdekjen e tij më 1807.", "b0acf80b"]},
"OLAYLAR_EK5:1795-09-01:0":{"b": ["Hapja e Shkollës Perandorake të Inxhinierisë Tokësore (Mühendishane-i Berr-i Hümayun)", "e9a3a34b"], "d": ["Në Haskëj u hap shkolla e inxhinierisë tokësore për të përgatitur oficerë topçinj, fortifikimesh dhe hartografë për ushtrinë e Nizam-i Xhedidit; ishte homologia në ushtrinë tokësore e Shkollës së Inxhinierisë Detare të themeluar më 1773. Në program mësoheshin algjebra, gjeometria, mekanika, fortifikimet dhe balistika, dhe u përkthyen libra matematike e artilerie nga gjuhët evropiane. Kjo shkollë, e konsideruar rrënja e arsimit modern inxhinierik në Turqi, pranohet si fillimi i Universitetit Teknik të sotëm të Stambollit.", "ff1a8344"]},
"OLAYLAR_EK5:1798-09-09:0":{"b": ["Shpallja e luftës Francës dhe aleanca me Rusinë dhe Anglinë", "80e95bd7"], "d": ["Pas pushtimit të Egjiptit nga Napoleoni, Shteti Osman, duke prishur miqësinë tradicionale dy shekuj e gjysmëshe me Francën, i shpalli luftë asaj. Në të njëjtin proces, për herë të parë në historinë e vet bëri aleancë me Rusinë dhe lejoi flotën ruse të kalonte ngushticat dhe të dilte në Mesdhe; pastaj u nënshkrua aleancë edhe me Anglinë. Falë këtyre aleancave ishujt e Jonit iu morën francezëve, por hapja e ngushticave një flote të huaj krijoi një precedent që më vonë do të kushtonte shtrenjtë.", "7d8a9e45"]},
"OLAYLAR_EK5:1798-10-23:0":{"b": ["Marrja e Prevezës nga francezët — Beteja e Nikopolit", "d8e5e892"], "d": ["Kur më 1797 u shemb Republika e Venedikut, ishujt e Jonit dhe në tokë Preveza, Parga e Vonitsa kaluan në duart e Francës. Valiu i Janinës, Ali Pashë Tepelena, duke përfituar nga lufta e hapur për shkak të pushtimit francez të Egjiptit, marshoi mbi Prevezë dhe në rrënojat e Nikopolit jashtë qytetit i shkaktoi garnizonit francez një disfatë të rëndë. Kështu ky port, që në Pasarofçë i ishte lënë Venedikut, tetëdhjetë vjet më vonë hyri nën administrimin osman. Butrinti (Butrinto) ra më 25 tetor, kur garnizoni francez hodhi në erë fortifikimet dhe u tërhoq në Korfuz (Curlin, Preveza B, 2010; atlasi ditën e merr nga Preveza) dhe hyri nën administrimin osman.", "f32e8843"]},
"OLAYLAR_EK5:1799-05-20:0":{"b": ["Mbrojtja e Akrës — zmbrapsja e Napoleonit", "56b5c45b"], "d": ["Napoleoni, që përparonte nga Egjipti drejt Sirisë, rrethoi Akrën dhe për dy muaj organizoi sulme të njëpasnjëshme; qytetin e mbrojti Xhezar Ahmet Pasha me mbështetjen e flotës angleze dhe me njësitë e Nizam-i Xhedidit të dërguara nga Stambolli. Napoleoni, i detyruar të hiqte rrethimin dhe të tërhiqej në Egjipt, e varrosi para këtyre mureve ëndrrën e tij për t'u shtrirë drejt lindjes. Lajmi u prit në Stamboll me gëzim të madh dhe u konsiderua provë se ushtria e re e stërvitur kishte kaluar provimin e saj të parë serioz.", "78b85f0c"]},
"OLAYLAR_EK5:1801-04-01:0":{"b": ["Sulmi i vehabitëve mbi Qerbela", "522341ed"], "d": ["Forcat vehabite të nisura nga Nexhdi hynë në Qerbela, e plaçkitën qytetin, shkatërruan tyrben e Hazreti Huseinit dhe vranë më shumë se tre mijë njerëz. Valinjtë kölemen të Shtetit Osman në Irak nuk mundën ta pengonin sulmin; ngjarja ngjalli reagim të madh si në Iran ashtu edhe në Stamboll. Ky sulm ishte shpallja se lëvizja saudite nuk ishte më një emirat oazesh, por ishte shndërruar në një fuqi rajonale që kërcënonte qytetet e shenjta të osmanëve.", "f571ab30"]},
"OLAYLAR_EK5:1801-09-24:0":{"b": ["Kartli-Kaheti (Gjeorgjia Lindore) iu aneksua Rusisë", "3b650c5e"], "d": ["Mbretëria e Kartli-Kahetit, që më 1783 kishte pranuar mbrojtjen ruse dhe më 1795 kishte pësuar fushatën shkatërrimtare të Iranit, u shpërnda; me urdhrin e datës 12 shtator 1801 u shpall provincë e Rusisë dhe filloi të vendosej sistemi administrativ rus. Gjeorgjia nga kjo datë humbi pavarësinë; brenda pak vitesh edhe Megrelia (1803), Imeretia dhe Guria (1804) hynë nën sundimin rus dhe Rusia arriti në kufirin kaukazian osman. Me këtë ngjarje, Gori, Dusheti (Kartli) dhe Telavi (Kaheti) kaluan te Rusia.", "f5e0d5d5"]},
"OLAYLAR_EK5:1801-10-09:0":{"b": ["Evakuimi i Egjiptit nga francezët", "00cfdc8c"], "d": ["Si rezultat i operacionit të përbashkët të forcave osmane dhe angleze nga toka e nga deti, u morën në dorëzim fillimisht Kajroja, pastaj Aleksandria dhe forcat franceze u dërguan me anije në vendin e tyre. Ndërsa përfundonte pushtimi trevjeçar, Egjipti në letër u kthye nën administrimin osman, por lufta për sundim mes bejlerëve kölemenë dhe njësive shqiptare e çoi vendin në kaos. Ky vakuum do të përgatiste brenda pak vitesh terrenin për ngritjen e Mehmet Ali Pashës së Kavallës.", "acaf7e40"]},
"OLAYLAR_EK5:1802-06-25:0":{"b": ["Traktati i Parisit — rivendosja e paqes me Francën", "1b76991f"], "d": ["Me traktatin e nënshkruar pas evakuimit të Egjiptit, gjendja e luftës mes Shtetit Osman dhe Francës përfundoi zyrtarisht dhe u ripërtërinë kapitulacionet e vjetra. Anijeve tregtare franceze iu lejua të hynin në Detin e Zi; në këmbim, Franca njohu integritetin territorial osman. Vendosja e paqes i ktheu politikës së jashtme të Selimit III, e ngujuar pranë Rusisë dhe Anglisë, përsëri hapësirë manovrimi.", "367c616e"]},
"OLAYLAR_EK5:1803-02-01:0":{"b": ["Pushtimi i Taifit nga vehabitët", "7b791359"], "d": ["Forcat vehabite nën komandën e Suud b. Abdulazizit, në hapin e parë drejt Hixhazit, rrethuan dhe plaçkitën Taifin; qyteti ra si porta e parë që hapej drejt tokave të shenjta. Për padishahun osman, që mbante titullin e mbrojtësit të dy vendeve të shenjta (Haremejn), kjo ishte një goditje që tronditte drejtpërdrejt legjitimitetin e sundimit. Dy muaj e gjysmë më vonë e njëjta ushtri do të marshonte mbi Mekë.", "289d52ef"]},
"OLAYLAR_EK5:1803-04-30:0":{"b": ["Vehabitët shtien në dorë Mekën për herë të parë", "21157c05"], "d": ["Dy muaj e gjysmë pas rënies së Taifit, forcat vehabite hynë në Mekë, shembën tyrbet dhe vendosën një rend sipas kuptimit të tyre; Sherif Galibi u detyrua të tërhiqej në Xheda. Mbyllja e rrugëve të haxhit pati jehonë në gjithë botën islame dhe e detyroi Stambollin të kërkonte ndihmë ushtarake nga valiu i Egjiptit, Mehmet Aliu. Ky sundim i parë do të zgjaste vetëm tre muaj.", "7194e460"]},
"OLAYLAR_EK5:1803-08-06:0":{"b": ["Sherif Galibi rimerr Mekën", "83d08dff"], "d": ["Sherif Galibi, që ishte tërhequr në Xheda, me forcat që mblodhi rrethoi Mekën dhe pas një rrethimi njëzet e pesëditor ua rimori qytetin vehabitëve; hytbeja u lexua përsëri në emër të osmanëve. As ky sundim i dytë nuk do të ishte i qëndrueshëm; forcat saudite do ta merrnin përsëri qytetin më 1806.", "8c15c19e"]},
"OLAYLAR_EK5:1804-02-14:0":{"b": ["Fillimi i Kryengritjes së Parë Serbe", "0f6e8767"], "d": ["Pas masakrës masive të parisë serbe nga dahijtë rebelë jeniçerë që kishin marrë pushtetin në Beograd, nën udhëheqjen e Karagjorgjit filloi një rezistencë e armatosur. Lëvizja, që në fillim mbeti besnike ndaj padishahut dhe u drejtua vetëm kundër dahijve, brenda pak kohe u shndërrua në një kryengritje kombëtare që kërkonte autonomi dhe pavarësi. Forcat serbe shtinë në dorë Beogradin më 1806; kjo kryengritje u bë hallka e parë e lëvizjeve nacionaliste për pavarësi në Ballkan.", "07d5d6c6"]},
"OLAYLAR_EK5:1805-06-01:0":{"b": ["Pushtimi i Medinës nga vehabitët", "84e310d7"], "d": ["Pas Mekës, edhe Medina ra në duart e forcave vehabite; thesari i Ravdai Mutahheras u shpërnda dhe tyrbet me kube në qytet u shembën. Kështu të dy qytetet e shenjta dolën njëherësh nga kontrolli osman dhe karvanet e haxhit që vinin nga Damasku dhe Egjipti për vite me radhë nuk mundën të niseshin. Medina mundi të rimerrej vetëm shtatë vjet më vonë, më 1812, nga ushtria egjiptiane nën komandën e Tosun Pashës, birit të Mehmet Ali Pashës.", "b8d034e6"]},
"OLAYLAR_EK5:1806-12-22:0":{"b": ["Fillimi i luftës me Rusinë (lufta osmano-ruse e viteve 1806-1812) dhe mbyllja e ngushticave", "ea170804"], "d": ["Kur Selimi III, që pas fitores së Napoleonit në Austerlitz u afrua me Francën, i shkarkoi vojvodat e Vllahisë dhe Moldavisë megjithë trysninë ruse, ushtritë ruse i pushtuan të dy principatat dhe filloi lufta. Shteti Osman ia mbylli ngushticat flotës ruse; në përgjigje, edhe Anglia u rreshtua përkrah Rusisë dhe dërgoi një flotë në Stamboll. Kjo luftë që do të zgjaste gjashtë vjet, e ndërthurur me kryengritjen e Kabakçiut dhe me rrëzimin e Selimit III nga froni, do të përfundonte me humbjen e Besarabisë në Traktatin e Bukureshtit të vitit 1812.", "901537a4"]},
"OLAYLAR_EK5:1807-02-20:0":{"b": ["Ardhja e flotës angleze para Stambollit (operacioni Duckworth)", "195bb58f"], "d": ["Anglia, duke dashur ta detyronte Shtetin Osman të këpuste lidhjen me Francën, e kaloi nëpër Dardanele flotën nën komandën e admiralit Duckworth dhe e ankoroi para Stambollit. Edhe me udhëzimet e ambasadorit francez Sébastiani, populli i Stambollit u mobilizua, bateritë bregdetare u përforcuan brenda pak ditësh dhe flota u detyrua të tërhiqej pa mundur ta bombardonte qytetin; gjatë kthimit pësoi humbje të rënda në Dardanele. Kërcënimi për herë të parë kaq nga afër i kryeqytetit nga një flotë e huaj e vendosi çështjen e ngushticave në qendër të diplomacisë evropiane.", "bf71116c"]},
"OLAYLAR_EK5:1808-11-17:0":{"b": ["Vrasja me mbytje e Mustafait IV", "eeb75c20"], "d": ["Pasi Alemdar Mustafa Pasha pësoi sulm të befasishëm e vdiq dhe rebelët deshën të marshonin mbi saraj, Mustafai IV, i rrëzuar nga froni, u vra me mbytje me urdhër të vëllait të tij Mahmudit II. Xhenazja u varros në tyrben e të atit, Abdylhamidit I, në Bahçekapë; mes rebelëve u përhap fjala se arkivoli ishte bosh.", "8a944508"]},
"OLAYLAR_EK5:1809-01-05:0":{"b": ["Traktati i Dardaneleve (Kala-i Sultanije) — paqja me Anglinë dhe rregulli i ngushticave", "fe282117"], "d": ["Me traktatin e nënshkruar me Anglinë pas dështimit të operacionit Duckworth, lufta mes dy shteteve përfundoi dhe tregtarëve anglezë iu kthyen privilegjet e vjetra. Dispozita në tekst, e njohur si 'rregulli i lashtë', përcaktonte se në kohë paqeje asnjë anije lufte e huaj nuk mund të kalonte nëpër ngushtica. Ky parim u bë baza juridike e të gjitha rregullimeve ndërkombëtare që do t'i jepnin formë regjimit të ngushticave gjatë gjithë shekullit XIX.", "7ef33a02"]},
"OLAYLAR_EK5:1811-10-14:0":{"b": ["Disfata e Slobozias — rrethimi i ushtrisë së Danubit", "54b60fd1"], "d": ["Pjesa më e madhe e ushtrisë osmane që kaloi Danubin para Rusçukut, me manovrën rrethuese që Kutuzovi bëri nga bregu tjetër i lumit, u ngujua në Slobozia dhe u la në uri. Mijëra ushtarë u detyruan të dorëzoheshin; forca në dorë të vezirit të madh u shkri faktikisht dhe Porta e Lartë një muaj më vonë u detyrua të kërkonte armëpushim. Kjo disfatë është shkaku i drejtpërdrejtë i pranimit të dhënies së Besarabisë në Traktatin e Bukureshtit të vitit 1812.", "d9da91c7"]},
"OLAYLAR_EK5:1813-10-05:0":{"b": ["Rimarrja e Beogradit dhe shtypja e Kryengritjes së Parë Serbe", "06f56f52"], "d": ["Kryengritësit serbë, që me Traktatin e Bukureshtit mbetën pa mbështetjen ruse, nuk mundën t'i rezistonin operacionit të përbashkët të forcave të ardhura nga Bosnja dhe Rumelia; Hurshid Ahmet Pasha hyri në Beograd dhe kryengritja nëntëvjeçare u shtyp plotësisht. Karagjorgji iku në Austri dhe sanxhaku i Smederevës u lidh sërish drejtpërdrejt me administrimin osman. Megjithatë, masat e ashpra të zbatuara dy vjet më vonë do të ndiznin, nën udhëheqjen e Millosh Obrenoviqit, një kryengritje të dytë dhe të qëndrueshme.", "1f0a751b"]},
"OLAYLAR_EK5:1815-04-23:0":{"b": ["Kryengritja e Dytë Serbe dhe titulli i kryeknezit për Miloš Obrenovićin", "e6e82ad2"], "d": ["Kundër masave të rënda të zbatuara pas shtypjes së kryengritjes së parë, nën udhëheqjen e Miloš Obrenovićit shpërtheu një kryengritje e re; kësaj radhe Porta e Lartë, në vend të forcës, parapëlqeu marrëveshjen. Me marrëveshjen e arritur, Miloši u njoh me titullin 'kryeknez' dhe kompetenca për mbledhjen e taksave e drejtimin e punëve të brendshme iu la knezëve serbë. Kjo bërthamë e parë e autonomisë faktike u bë pikënisja e procesit që shkoi deri te fermani i vitit 1830 dhe pavarësia e vitit 1878.", "bf6041bb"]},
"OLAYLAR_EK5:1821-02-22:0":{"b": ["Kryengritja e Vllahisë — kalimi i Prutit nga Ypsilanti dhe ngritja e Vladimirescut", "67d46a98"], "d": ["Aleksandër Ypsilanti, gjeneral në ushtrinë ruse, duke kaluar Prutin në emër të Filiki Eterisë, u përpoq të niste një kryengritje të përgjithshme greke në Vllahi dhe Moldavi; po në ato ditë edhe Tudor Vladimirescu vuri në lëvizje fshatarët vendës. Të dy lëvizjet nuk mundën të bashkoheshin: thirrjes së Ypsilantit për të luftuar bashkë kundër turqve, Vladimirescu iu përgjigj 'Unë u ngrita jo kundër turqve, por kundër grekëve' dhe pas pak kohe u vra nga njerëzit e Ypsilantit. Kryengritja u shtyp nga forcat osmane në maj, por rendi i vojvodëve fanariotë mori fund dhe zjarri i kryengritjes u hodh në More.", "64b96ac8"]},
"OLAYLAR_EK5:1824-06-01:0":{"b": ["Themelimi i Shtetit të Dytë Saudit në Rijad", "34dad3bd"], "d": ["Gjashtë vjet pas rënies së Dirijes më 1818 dhe shembjes së shtetit të parë saudit, Turki b. Abdullah i nxori garnizonet egjiptiane nga Nexhdi dhe themeloi një emirat të ri saudit me qendër në Rijad. Struktura e re parapëlqeu të qëndronte në Nexhd duke iu shmangur shtrirjes drejt Hixhazit dhe u mbajt larg përplasjes së drejtpërdrejtë me forcat osmano-egjiptiane. Ky shtet i dytë do të zgjaste deri në fund të shekullit dhe do të përbënte hallkën e dytë të zinxhirit që çoi në themelimin e Arabisë Saudite të sotme. Vendbanimet e tjera që dolën nga dora në të njëjtën datë: Dirija (Nexhd).", "72b5fd29"]},
"OLAYLAR_EK5:1826-10-07:0":{"b": ["Traktati i Akermanit — lëshime për Serbinë dhe principatat", "c75f15d0"], "d": ["Shteti Osman, i mbetur pa ushtri menjëherë pas shfuqizimit të odxhakut të jeniçerëve, përballë ultimatumit rus u detyrua të pranonte një traktat me kushte të rënda. U konfirmua autonomia e premtuar për Serbinë, u pranua që vojvodat e Vllahisë dhe Moldavisë nuk mund të shkarkoheshin pa miratimin rus dhe anijeve tregtare ruse iu njoh liri e plotë në ngushtica. Kur dy vjet më vonë Porta e Lartë, për shkak të çështjes greke, shpalli se nuk e njihte traktatin, Rusia do ta konsideronte këtë shkak lufte.", "a7de6cda"]},
"OLAYLAR_EK5:1827-02-01:0":{"b": ["Likuidimi i sistemit të timarit", "84d5d1d6"], "d": ["Një vit pas shfuqizimit të odxhakut të jeniçerëve, rreth 5.200 spahinj me timar në pesëdhjetë e tre sanxhakë të Rumelisë dhe Anadollit, bashkë me të ardhurat e timareve, u shndërruan në kalorësi të Asakir-i Mansures. Kështu regjimi i timarit, shtylla kurrizore katërshekullore e rendit osman të tokës, taksave dhe ushtrisë, mori fund faktikisht. Timaret e liruara iu kaluan thesarit dhe u hap rruga për kalimin te ushtria me rrogë qendrore dhe te sistemi i taksave në para.", "077ea4ea"]},
"OLAYLAR_EK5:1827-03-14:0":{"b": ["Themelimi i Shkollës Perandorake të Mjekësisë (Tiphane-i Amire) — fillimi i arsimit modern mjekësor", "ac3e57c0"], "d": ["Për të përgatitur mjekë dhe kirurgë për ushtrinë e sapokrijuar të Asakir-i Mansures, me propozimin e kryemjekut Mustafa Behçet Efendi, në Shehzadebashi u hap Tiphane-i Amire. Mësimet u rregulluan sipas programit mësimor të Evropës dhe në fillim mësimdhënia bëhej në frëngjisht; pak vjet më vonë u themelua edhe Xherrahhane-i Amire (shkolla e kirurgjisë) dhe të dy institucionet u bashkuan. Kjo shkollë, e konsideruar fillimi i arsimit modern mjekësor në Turqi, pranohet si origjina e Fakultetit të sotëm të Mjekësisë së Stambollit.", "54a2ed54"]},
"OLAYLAR_EK5:1828-04-26:0":{"b": ["Fillimi i luftës osmano-ruse të viteve 1828-1829", "9dff4e05"], "d": ["Pas djegies së flotës në Navarin dhe shpalljes së Portës së Lartë se nuk e njihte Traktatin e Akermanit, Rusia hapi luftë njëherësh në dy fronte. Meqë odxhaku i jeniçerëve sapo ishte shfuqizuar dhe ushtria e re ishte ende në fazën e krijimit, mbrojtja osmane ishte e dobët që në fillim; rusët, teksa kalonin Danubin, në lindje morën Karsin dhe Ahëskën (Akhaltsikhen). Ushtria ruse, që brenda një viti përparoi deri në Edrene, do të impononte kushtet e rënda të Traktatit të Edrenesë të vitit 1829 dhe pavarësinë e Greqisë.", "9491c932"]},
"OLAYLAR_EK5:1830-05-07:0":{"b": ["Traktati i parë me Shtetet e Bashkuara të Amerikës", "d737516f"], "d": ["Me traktatin e tregtisë dhe lundrimit të nënshkruar pas kontakteve shumëvjeçare, SHBA fitoi në vendin osman statusin e kombit më të favorizuar dhe të drejtën e kalimit tregtar nëpër ngushtica. Një nen i fshehtë i veçantë parashikonte që osmanët, kur të donin, mund të porositnin anije në kantieret amerikane dhe të blinin anije të gatshme e lëndë drusore; Senati i SHBA e ratifikoi traktatin, por e hodhi poshtë këtë nen të fshehtë me 27 vota kundër 18. Megjithatë, rruga e anijeve nuk u mbyll: Henry Eckford ua shiti osmanëve anijen që solli më 1831, dhe mjeshtrat amerikanë që punonin në Ajnallëkavak i sollën flotës anije të llojit të ri. Ky traktat u bë dëshmia e marrëdhënies së parë gjithëpërfshirëse që Shteti Osman vendosi me një shtet jashtë Evropës.", "c87615ca"]},
"OLAYLAR_EK5:1831-09-14:0":{"b": ["Fundi i administrimit kölemen në Bagdad", "7e1d38a3"], "d": ["Mahmudi II, që ndiqte politikën e centralizimit, e shpalli rebel valiun e Bagdadit Davud Pasha, i cili nuk dërgonte paratë e kërkuara dhe kishte urdhëruar vrasjen e nëpunësit të ardhur nga qendra. Forca nën komandën e Ali Rëza Pashës shtiu në dorë qytetin pas një rrethimi nëntëdhjetëditor dhe pothuajse të gjithë kölemenët u likuiduan. Kështu mori fund sundimi gjysmë i pavarur kölemen që vazhdonte që nga viti 1704 dhe Iraku u lidh përsëri drejtpërdrejt me qendrën.", "676f3744"]},
"OLAYLAR_EK5:1834-07-01:0":{"b": ["Themelimi i Shkollës Ushtarake (Mekteb-i Harbije) në Kazermën e Maçkës", "bf31c7d9"], "d": ["Për t'i siguruar Asakir-i Mansure-i Muhamedijes oficerë të përgatitur sipas mënyrës evropiane, në Kazermën e Maçkës u hap Mekteb-i Fünûn-ı Harbiyye. Nxënësve u mësoheshin matematika, hartografia, fortifikimet dhe gjuhët e huaja; pas pak kohe kuadri u përforcua duke dërguar nxënës në Vjenë dhe Paris. Kjo shkollë u bë vendi ku lindi tradita e oficerëve të shkolluar në ushtrinë osmane dhe, rrjedhimisht, brezi i ri i ushtarakëve intelektualë që do të shfaqej në fund të shekullit XIX.", "1d64a30c"]},
"OLAYLAR_EK5:1835-05-26:0":{"b": ["Lidhja e drejtpërdrejtë e Tripolit me qendrën — fundi i dinastisë Karamanli", "faabcb96"], "d": ["Për shkak të luftërave për fron brenda familjes Karamanli dhe trysnisë evropiane që u rrit pas pushtimit të Algjerisë nga Franca më 1830, Porta e Lartë ndërhyri drejtpërdrejt në Tripoli. Flota e dërguar nga Stambolli hyri në qytet, beu i fundit Karamanli u shkarkua dhe u soll në Stamboll, dhe ejaleti iu dorëzua një valiu të emëruar nga qendra. Ndërsa mbyllej periudha dinastike 124-vjeçare, u përforcua pjesa e fundit e tokës që Shteti Osman e drejtonte drejtpërdrejt në Afrikën Veriore.", "71104846"]},
"OLAYLAR_EK5:1838-02-28:0":{"b": ["Shfuqizimi i defterdarllëkut dhe krijimi i Ministrisë së Financave", "89f8125e"], "d": ["Posti i defterdarit, kreu i rendit financiar klasik osman, u shfuqizua dhe u krijua Ministria e Financave (Maliye Nezareti), një ministri sipas modelit evropian, ndërsa thesaret e shpërndara u mblodhën në një dorë. Po atë vit edhe njësitë e tjera të Portës së Lartë u riorganizuan me emrin nezaret (ministri), duke kaluar në një strukturë moderne të këshillit të ministrave. Ky rregullim ishte një nga hapat më të rëndësishëm që përgatiti infrastrukturën administrative të Fermanit të Tanzimatit, që do të shpallej një vit më vonë.", "46962eda"]},
"OLAYLAR_EK5:1839-01-19:0":{"b": ["Vendosja e anglezëve në Aden", "ddbd556b"], "d": ["Anglia, duke u mbështetur në marrëveshjen e tregtisë dhe miqësisë që kishte nënshkruar më 1802 me sulltanin e Lahixhit, Ahmed b. Abdulkerim, zbarkoi ushtarë në portin e Adenit dhe vuri qytetin nën kontroll. Ky port, që ruante grykën e Detit të Kuq, u shndërrua, si bazë furnizimi me qymyr e rrugës së Indisë, në pikën kyçe të strategjisë së perandorisë britanike. Edhe pse pretendimi osman mbi Jemenin vazhdoi në letër, sundimi faktik në bregdetin jugor pas kësaj date nuk u kthye më.", "731b896d"]},
"OLAYLAR_EK5:1849-01-01:0":{"b": ["Kthimi në bregdetin e Tihames: marrja e Hudejdës, Zebidit dhe Mokës", "353982d2"], "d": ["Në bregdetin e Jemenit, i mbetur pa zot me tërheqjen e ushtrisë egjiptiane më 1840, forcat nën komandën e Tevfik Pashës zbarkuan nën mbikëqyrjen e sherifit të Mekës dhe i lidhën portet Hudejda, Zebid dhe Moka me administrimin osman. Ndonëse u synua të përparohej deri në Sana, për shkak të rezistencës së popullsisë u kthyen në Hudejda; kështu trojet e larta mbetën në duart e imamëve zejditë dhe sundimi osman për njëzet e tre vjet vazhdoi vetëm në rripin e Tihames. Jemeni i brendshëm do të rimerrej vetëm më 1872 me fushatën e Ahmet Muhtar Pashës.", "7a30c1f9"]},
"OLAYLAR_EK5:1849-05-01:0":{"b": ["Konventa e Baltalimanit: protektorati i përbashkët osmano-rus në Vllahi dhe Moldavi", "d3bb22e9"], "d": ["Kur revolucionet e vitit 1848 u shtrinë në Vllahi dhe Moldavi, forcat osmane dhe ruse i kishin pushtuar së bashku principatat. Me konventën e nënshkruar në Baltaliman u vendos që vojvodat të mos zgjidheshin, por të emëroheshin nga padishahu për shtatë vjet dhe që të dy shtetet të ushtronin kontroll të përbashkët në rajon. Marrëveshja ruante sovranitetin osman në letër, por i njihte Rusisë të drejtën e një bashkëpjesëmarrjeje faktike dhe e përshpejtoi shkëputjen e principatave danubiane nga osmanët.", "b343f446"]},
"OLAYLAR_EK5:1849-08-16:0":{"b": ["Çështja e refugjatëve hungarezë: strehimi i Kossuthit dhe shokëve të tij te osmanët", "1c7d7ef4"], "d": ["Pas shtypjes së revolucionit hungarez të viteve 1848-1849 me ndërhyrjen ruso-austriake, Lajos Kossuth dhe mijëra refugjatë hungarezë e polakë u strehuan në tokat osmane. Austria dhe Rusia kërkuan ashpër kthimin e refugjatëve; Porta e Lartë, me mbështetjen e Anglisë dhe Francës, e refuzoi dorëzimin dhe e vendosi grupin në Kutahja. Rrethi i Kossuthit qëndroi këtu rreth tetëmbëdhjetë muaj dhe qindra refugjatë u bënë myslimanë e hynë në shërbim osman. Ngjarja u konsiderua një nga fitoret e rralla diplomatike që e rriti prestigjin e osmanëve të Tanzimatit në opinionin evropian.", "07b6d020"]},
"OLAYLAR_EK5:1851-02-11:0":{"b": ["Themelimi i Encümen-i Danishit: akademia e parë osmane në Stamboll", "6fda1365"], "d": ["Encümen-i Danishi, i krijuar me vendim të Këshillit të Përgjithshëm të Arsimit, është akademia e parë shkencore osmane, e ngritur për të përgatitur në turqisht libra shkencorë dhe tekste mësimore. U hap me ceremoni më 18 korrik 1851 në ndërtesën e Darulmaarifit; mes anëtarëve vendës dhe të huaj ishte edhe Ahmet Xhevdet Pasha. Ndonëse jetëshkurtër, vepra si Historia e Xhevdet Pashës dhe Kavaid-i Osmanije ishin prodhim i këtij institucioni dhe ai u konsiderua gur themeli në shndërrimin e turqishtes në gjuhë të shkencës.", "7eebb193"]},
"OLAYLAR_EK5:1853-11-11:0":{"b": ["Fitorja e Oltenicës: suksesi i parë osman në frontin e Danubit", "a660ad2f"], "d": ["Në fazën hapëse të Luftës së Krimesë, serdari ekrem Omer Lutfi Pasha kaloi Danubin dhe në Oltenicë i zmbrapsi forcat ruse me humbje të rënda. Fitorja, duke ndalur që në fillim të luftës përparimin rus, i tregoi Evropës fuqinë që ushtria osmane kishte fituar me stërvitjen pas Tanzimatit. Ky sukses përgatiti terrenin psikologjik që e lehtësoi vendimin e Anglisë dhe Francës për të hyrë në luftë përkrah osmanëve.", "a0e5e8fb"]},
"OLAYLAR_EK5:1854-03-12:0":{"b": ["Traktati i aleancës me Anglinë dhe Francën në Stamboll", "04809278"], "d": ["Traktati i aleancës i nënshkruar në Luftën e Krimesë kundër Rusisë mes Shtetit Osman, Anglisë dhe Francës përcaktoi që të tre shtetet të zhvillonin operacione të përbashkëta dhe që aleatët të mos bënin paqe më vete para përfundimit të luftës. Kështu Shteti Osman për herë të parë në historinë e vet hyri në një aleancë ushtarake me fuqitë e mëdha evropiane si palë e barabartë. Ky traktat përbëri edhe bazën juridike për pranimin zyrtar të osmanëve në sistemin e shteteve evropiane dy vjet më vonë në Paris.", "1899331b"]},
"OLAYLAR_EK5:1855-08-16:0":{"b": ["Krijimi i Shehremanetit të Stambollit: organizata e parë moderne bashkiake", "be4af27f"], "d": ["Ushtarët aleatë të grumbulluar në Stamboll gjatë Luftës së Krimesë dhe kriza e infrastrukturës që shkaktoi popullsia në rritje nxorën në pah pamjaftueshmërinë e administrimit klasik të qytetit me qendër kadiun. Me Shehremanetin, të krijuar sipas shembujve evropianë, pastërtia, çmimet e caktuara (narhi), kontrolli i tregut dhe punët e ndërtimit u mblodhën në një dorë; vitin pasues në Bejogllu-Galata u organizua si zonë pilot Dairja e Gjashtë Bashkiake. Ky hap pranohet si fillimi i bashkiakëzimit modern te osmanët.", "23959c70"]},
"OLAYLAR_EK5:1856-03-30:0":{"b": ["Traktati i Parisit: fundi i Luftës së Krimesë dhe pranimi i osmanëve në sistemin e shteteve evropiane", "4aee0e2a"], "d": ["Me Traktatin e Parisit, që i dha fund Luftës së Krimesë, Shteti Osman u shpall anëtar i barabartë i së drejtës publike të shteteve evropiane dhe integriteti i tij territorial u vu nën garancinë e përbashkët të fuqive të mëdha. Deti i Zi u neutralizua, pretendimi i Rusisë për mbrojtje mbi nënshtetasit ortodoksë, i fituar që nga Kyçyk-Kajnarxha, u bë i pavlefshëm dhe jugu i Besarabisë (kazatë e Kilisë, Kahulit, Ismailit dhe Bolgradit) iu dha Moldavisë. Megjithatë, i njëjti traktat, duke e shndërruar Fermanin e Reformave (Islahat) në zotim ndërkombëtar, i hapi derën edhe ndërhyrjes në punët e brendshme.", "42c5d63d"]},
"OLAYLAR_EK5:1856-06-07:0":{"b": ["Hapja e Sarajit Dollmabahçe: zhvendosja e qendrës së administrimit nga Topkapia", "71ad26d0"], "d": ["Saraji që Abdylmexhidi ia kishte porositur familjes Baljan më 1842, u hap pas një ndërtimi katërmbëdhjetëvjeçar dhe qendra e administrimit të shtetit u zhvendos nga Topkapia katërshekullore në bregun e Bosforit. Me stilin evropian, shkallën prej kristali dhe Sallonin e Pritjeve (Muayede), saraji u bë shprehja në gur e pretendimit të Tanzimatit për perëndimizim. Ndërsa kostoja e tij kolosale u bë një nga zërat më të kritikuar të viteve kur financat osmane hynë në spiralen e borxhit të jashtëm.", "bb3cd1c8"]},
"OLAYLAR_EK5:1859-02-05:0":{"b": ["Bashkimi i Vllahisë dhe Moldavisë nën drejtimin e Cuzës: lindja e Rumanisë", "baef4da5"], "d": ["Në zgjedhjet e organizuara pas Traktatit të Parisit, të dy principatat zgjodhën vojvodë kolonelin Alexandru Ioan Cuza, duke realizuar bashkimin faktik. Ndonëse Porta e Lartë dhe Austria e kundërshtuan, fakti i kryer i mbështetur nga Franca u desh të pranohej. Ky bashkim, që në letër mbeti i lidhur me osmanët, do të merrte më 1862 emrin Rumani dhe më 1877 do të shpallte njëanshëm pavarësinë; ai është pikë kthese në shpërbërjen e sundimit osman përgjatë Danubit.", "83e52b52"]},
"OLAYLAR_EK5:1859-09-14:0":{"b": ["Ngjarja e Kulelisë: përpjekja e parë për grusht shteti kundër Abdylmexhidit në Stamboll", "e3653b21"], "d": ["Një shoqëri e fshehtë e përzier ushtarakësh e civilësh, që reagonte ndaj politikës së Tanzimatit dhe barazisë që Fermani i Reformave u njihte jomyslimanëve, ndërsa planifikonte rrëzimin e padishahut, u zbulua gjatë një mbledhjeje në xhaminë Këlëç Ali Pasha. Ngaqë të pandehurit u gjykuan në Kazermën e Kulelisë, ngjarja mori këtë emër; dënimet me vdekje u kthyen në internim. Pranohet si përpjekja e parë për grusht shteti pallati në historinë osmane, e ndërmarrë nga një organizatë e krijuar me motive ideologjike.", "4e9e2296"]},
"OLAYLAR_EK5:1860-05-30:0":{"b": ["Lufta civile druzo-maronite në Malin e Libanit dhe ngjarjet e Damaskut", "5595fdd6"], "d": ["Përplasjet që shpërthyen në maj 1860 me vrasjen e dy druzëve pranë Sidonit u shndërruan në luftën civile druzo-maronite më të përgjakshme të malit dhe në korrik u hodhën në Damask, duke përfunduar me vdekjen e mijëra të krishterëve. Pas zbarkimit të ushtarëve nga Franca, Porta e Lartë dërgoi në rajon Fuad Pashën me kompetenca të jashtëzakonshme; u zhvillua një operacion i ashpër shtypës. Ngjarjet përbënë pretekst për ndërhyrjen evropiane dhe u bënë shkaku i drejtpërdrejtë që Libani të fitonte status të veçantë.", "511709b3"]},
"OLAYLAR_EK5:1860-10-22:0":{"b": ["Fillimi i botimit të Tercüman-ı Ahval: gazeta e parë private turke në Stamboll", "24792957"], "d": ["Tercüman-ı Ahval, që e nxirrte Agâh Efendiu dhe redaksinë e të cilës e mori përsipër Shinasiu, është gazeta e parë turke e botuar pa mbështetje shtetërore. Në parathënien e numrit të parë u mbrojt e drejta e popullit për të folur për çështjet e veta, dhe gazeta, duke botuar në vazhdime veprën e Shinasiut 'Martesa e poetit' (Şair Evlenmesi), i hapi derën edhe letërsisë moderne turke. Lindja e konceptit të opinionit publik dhe e shtypit opozitar te osmanët lidhet me këtë datë.", "cc4ba4a5"]},
"OLAYLAR_EK5:1861-06-09:0":{"b": ["Rregullorja e Malit të Libanit: statusi i privilegjuar i mutesarrifllëkut për Libanin", "bf375603"], "d": ["Rregullorja, e përgatitur pas masakrave të vitit 1860 nën trysninë e fuqive të mëdha, e shndërroi Malin e Libanit në mutesarrifllëk të privilegjuar, të lidhur drejtpërdrejt me Portën e Lartë dhe të drejtuar me një këshill administrativ të krijuar sipas ekuilibrit mes besimeve. U kërkua që mutesarrifi të ishte nënshtetas osman i krishterë katolik dhe që emërimi i tij t'u paraqitej për miratim fuqive të mëdha; mutesarrifi i parë ishte Davud Pasha. Ky rend do të zgjaste deri në vitin 1915 dhe do të përbënte bërthamën e shtetit modern libanez.", "1b56a9d5"]},
"OLAYLAR_EK5:1861-06-25:0":{"b": ["Vdekja e Abdylmexhidit dhe hipja në fron e Sulltan Abdylazizit", "27204d7c"], "d": ["Pasi Abdylmexhidi, që gjatë sundimit njëzet e dyvjeçar nënshkroi fermanet e Tanzimatit dhe të Reformave, u mund nga tuberkulozi, në fron hipi vëllai i tij Abdylazizi. Padishahu i ri në vitet e para ngjalli shpresë me masat e kursimit dhe jetesën e thjeshtë; flotën e bëri një nga fuqitë e pakta të rëndësishme në botë. Megjithatë, në fund të sundimit, borxhi i rëndë i jashtëm, falimentimi i vitit 1875 dhe kryengritjet ballkanike u grumbulluan dhe përgatitën terrenin për lëvizjen e rrëzimit të vitit 1876.", "1c2db3f9"]},
"OLAYLAR_EK5:1862-02-21:0":{"b": ["Principatat e bashkuara marrin emrin Rumani", "d960e3fc"], "d": ["Vllahia dhe Moldavia, të bashkuara faktikisht me zgjedhjen e dyfishtë të Cuzës më 1859, më 1862 i bashkuan parlamentet dhe qeveritë e tyre nën një çati në Bukuresht dhe morën zyrtarisht emrin Rumani. Ndonëse Shteti Osman ruajti juridikisht cilësinë e sovranit dhe taksën vjetore, faktikisht e humbi kontrollin mbi principatën. Me këtë datë simbolizohet fundi i ndikimit osman katërshekullor në veri të Danubit.", "1693f20f"]},
"OLAYLAR_EK5:1865-01-01:0":{"b": ["Lidhja e Suakinit, Massauas dhe Dahlakut me Egjiptin", "a0924860"], "d": ["Massaua, që më 1846 Sulltan Abdylmexhidi ia kishte dhënë hedivit të Egjiptit Mehmet Ali Pasha si salyane (ndarje të ardhurash) bashkë me Suakinin, në kohën e Hediv Ismail Pashës u përfshi me Dahlakun dhe Suakinin në pronat e Egjiptit dhe u organizua me statusin e kajmekamllëkut. Kështu këto tri porte në bregun afrikan të Detit të Kuq, ndonëse juridikisht mbetën tokë osmane, administrativisht kaluan nga Porta e Lartë drejtpërdrejt te Kajroja — hynë në të njëjtën shtresë vartëse me fqinjët e tyre, Egjiptin dhe Sudanin.", "782199b7"]},
"OLAYLAR_EK5:1866-08-21:0":{"b": ["Fillimi i kryengritjes së Kretës (1866-1869)", "3679b861"], "d": ["Kryengritja e gjerë që shpërtheu në ishull me mbështetjen e hapur të Greqisë, për herë të parë e bëri çështje ndërkombëtare kërkesën e grekëve të Kretës për enosis (bashkim me Greqinë). Lufta e ashpër malore trevjeçare i shkaktoi ushtrisë osmane humbje të rënda dhe pati jehonë të madhe në opinionin evropian. Kryengritja mundi të shuhej vetëm kur më 1868 Ali Pasha shkoi në ishull dhe vuri në fuqi rregulloren që njihte privilegje të gjera.", "eba163ff"]},
"OLAYLAR_EK5:1867-04-18:0":{"b": ["Tërheqja e garnizoneve të fundit osmane nga Beogradi dhe kështjellat e Serbisë", "b34217db"], "d": ["Nën trysninë e fuqive të mëdha dhe me kërkesën këmbëngulëse të princit Mihailo, Porta e Lartë pranoi të boshatiste bazat e fundit ushtarake që i kishin mbetur në Serbi; më 18 prill 1867 sanxhaku (flamuri) osman në kështjellën e Beogradit u ul dhe çelësat iu dorëzuan princit. Kështu mori fund prania ushtarake faktike osmane që vazhdonte nga viti 1521 dhe u hoq pengesa e fundit e madhe në rrugën e Serbisë drejt pavarësisë. Sovraniteti i padishahut u reduktua vetëm në çështjen simbolike të flamurit dhe të taksës.", "875dbecb"]},
"OLAYLAR_EK5:1867-06-08:0":{"b": ["Dhënia e titullit hediv valinjve të Egjiptit", "09e10c12"], "d": ["Si pasojë e lobimit të dendur të Ismail Pashës, nga brezi i tretë i dinastisë Kavalali, dhe të parave që ai derdhi në Stamboll, valiut të Egjiptit iu dha titulli hediv, që theksonte epërsinë e tij mbi valinjtë e tjerë. Po në ato vite u ndryshua edhe rendi i trashëgimisë që të kalonte nga babai te i biri dhe Egjiptit iu njohën kompetenca me natyrë sovrane, si marrja e borxheve të jashtme, dhënia e dekoratave dhe mbajtja e konsullatave. Këto hapa janë hallka e parë e zinxhirit që e përshpejtoi shkëputjen juridike të Egjiptit nga osmanët.", "38a9a00f"]},
"OLAYLAR_EK5:1868-01-04:0":{"b": ["Rregullorja e Kretës: privilegje të gjera administrative për ishullin", "12052262"], "d": ["Për t'i dhënë fund kryengritjes trevjeçare, veziri i madh Ali Pasha kaloi vetë në ishull dhe me rregulloren e botuar me miratimin e padishahut kretasve iu njohën këshilla administrativë të përzier, gjykata vendore, përdorimi i greqishtes në veprimet zyrtare dhe lehtësime tatimore. Ky rregullim e mbajti më këmbë sundimin osman në ishull edhe tridhjetë vjet. Megjithatë, privilegjet e njohura popullsisë së krishterë e dobësuan pozitën e kretasve myslimanë dhe mbollën farat e krizës së viteve 1896-1898.", "9cce04af"]},
"OLAYLAR_EK5:1868-05-10:0":{"b": ["Hapja e Shura-i Devletit: themelimi i Këshillit të Shtetit osman", "70b16497"], "d": ["Me iradenë e datës 5 mars 1868, Mexhlisi-i Ahkjam-i Adlije u nda në dysh: punët administrativo-legjislative iu lanë Shura-i Devletit, punët gjyqësore Divan-i Ahkjam-i Adlijes; institucioni u hap me ceremoni në Portën e Lartë dhe kryetar i tij i parë u caktua Midhat Pasha. U ngarkua me përgatitjen e projektligjeve, zgjidhjen e mosmarrëveshjeve administrative dhe zhvillimin e gjyqeve ndaj nëpunësve. Me përbërjen e përzier të anëtarëve myslimanë e jomyslimanë, konsiderohet zbatimi i parë institucional i idesë së ndarjes së pushteteve te osmanët.", "c85741e0"]},
"OLAYLAR_EK5:1869-11-17:0":{"b": ["Hapja e Kanalit të Suezit: shkurtimi i rrugës së Indisë përmes Egjiptit", "377ccd04"], "d": ["Ndërtimi i nisur më 1859 zgjati dhjetë vjet dhe kanali 163 kilometra i gjatë, që lidhte Mesdheun me Detin e Kuq, hyri në shërbim me një ceremoni madhështore. Kur rruga që lidhte Evropën me Indinë u shkurtua me mijëra milje, Egjipti u bë befas pika kyçe e tregtisë botërore. Kjo vlerë gjeostrategjike do të ishte shkaku kryesor që Anglia, trembëdhjetë vjet pas hapjes së kanalit, të pushtonte Egjiptin; ndërsa borxhi që kanali i ngarkoi Egjiptit do ta çonte hedivllëkun në falimentim.", "ccff3d4b"]},
"OLAYLAR_EK5:1870-03-11:0":{"b": ["Krijimi i Ekzarkatit Bullgar: shkëputja e kishës bullgare nga Fanari", "33a8272c"], "d": ["Me ferman të padishahut u krijua një kishë bullgare e pavarur (ekzarkat), e ndarë nga Patriarkana Greke, dhe iu la votimit popullor se cilat kaza do t'i lidheshin ekzarkatit. Ndonëse Porta e Lartë e hodhi këtë hap për të thyer ndikimin grek, rezultati doli i kundërt: kisha u shndërrua në qendrën e organizuar të identitetit kombëtar bullgar dhe të pretendimit bullgar për Maqedoninë. Kështu u hodhën themelet institucionale të rivalitetit bullgaro-greko-serb në Ballkan dhe të kryengritjeve të vitit 1876.", "ce8f108b"]},
"OLAYLAR_EK5:1871-01-01:0":{"b": ["Marrja e Asirit nën administrimin e drejtpërdrejtë", "4559e099"], "d": ["Kur me hapjen e Kanalit të Suezit u rrit vlera strategjike e Detit të Kuq, u pa se malet e Asirit, në mes të rrugës tokësore për në Jemen, nuk mund të liheshin pa kontroll. Forcat e Redif Pashës, që doli në fushatë për në Jemen, hynë në Abha, e lidhën rajonin drejtpërdrejt me administrimin osman dhe u krijua sanxhaku i Asirit. Për shkak të gjeografisë malore dhe ndikimit idrisid, ky sundim nuk u rrënjos kurrë plotësisht.", "eb2bbdad"]},
"OLAYLAR_EK5:1871-04-20:0":{"b": ["Fushata e Midhat Pashës në Nexhd: rivendosja e sundimit osman në Lahsa", "7db51461"], "d": ["Valiu i Bagdadit, Midhat Pasha, duke përfituar nga lufta për fron brenda familjes saudite, dërgoi ushtarë në bregun perëndimor të Gjirit të Basrës dhe krahinën e Lahsës ia lidhi vilajetit të Basrës me emrin sanxhaku i Nexhdit. Abdullah b. Faisali u emërua mutesarrif dhe sundimi osman u vendos në letër. Fushata synonte të ndalte përhapjen e ndikimit anglez në gji dhe po atë vit çoi në hyrjen nën kontrollin osman edhe të Katarit.", "fbc6819e"]},
"OLAYLAR_EK5:1871-09-07:0":{"b": ["Vdekja e vezirit të madh Ali Pasha: fundi i kuadrit të Tanzimatit", "1cf0141c"], "d": ["Me vdekjen e Ali Pashës, që pas vdekjes së Fuad Pashës më 1869 e kishte mbajtur i vetëm mbi supe politikën e Tanzimatit, u shua brezi i diplomatëve mjeshtërorë që drejtuan politikën e jashtme të shtetit për tridhjetë vjet. Administrimi arbitrar e proruse i Mahmud Nedim Pashës, që erdhi në vendin e tij, e forcoi sundimin personal të Abdylazizit. Brenda pesë vjetëve pas vdekjes së Ali Pashës, financat falimentuan, Ballkani u ngrit në kryengritje dhe ndryshimi në fron u bë i pashmangshëm.", "c4954cff"]},
"OLAYLAR_EK5:1871-09-20:0":{"b": ["Vendosja e kontrollit osman në Katar", "3b453165"], "d": ["Me ftesën e sheikut Kasim b. Thani, që ishte nën trysninë angleze, forcat osmane dolën në gadishullin e Katarit dhe në vjeshtën e vitit 1871 u sigurua kontrolli osman në rajon. Katari u organizua si kaza e lidhur me sanxhakun e Nexhdit dhe sheiku u emërua kajmekam. Ky veprim u bë fitimi më konkret i politikës përparimtare që Midhat Pasha ndiqte në gji kundër Anglisë; flamuri osman valoi mbi gadishull deri më 1913.", "823711c3"]},
"OLAYLAR_EK5:1871-10-24:0":{"b": ["Fermani i trashëgimisë për Tunizinë — bejllëku familjes së Mehmet Sadik Pashës", "1509ebb0"], "d": ["Me fermanin që doli me përpjekjet e Hajredin Pashës, të cilin beu i Tunizisë Mehmet Sadik Pasha e dërgoi në Stamboll duke shfrytëzuar disfatën e Francës përballë Prusisë, Tunizia, duke mbetur e lidhur drejtpërdrejt me Stambollin, iu dha Mehmet Sadik Pashës dhe pasardhësve të tij me të drejtë trashëgimie. Pa lejen e padishahut nuk do të zhvilloheshin bisedime për luftë e paqe, asnjë tokë e vendit nuk do t'i jepej tjetrit dhe do të plotësohej kërkesa osmane për ushtarë. Franca nuk e njohu fermanin; dhjetë vjet më vonë pushtoi Tunizinë.", "b72eabcc"]},
"OLAYLAR_EK5:1872-04-01:0":{"b": ["Marrja e Sanasë: rivendosja e autoritetit osman në Jemen", "978e20a0"], "d": ["Kur me hapjen e Kanalit të Suezit u rrit vlera strategjike e Detit të Kuq, Porta e Lartë dërgoi në Jemen ushtrinë e divizionit rezervë (fırka-i ihtiyatiye) nën komandën e Ahmet Muhtar Pashës. Me marrjen e Sanasë, autoriteti shtetëror u rivendos në Jemenin e brendshëm, të humbur faktikisht prej dy shekujsh, dhe rajoni u bë vilajet. Megjithatë, lufta me imamët zejditë nuk mori kurrë fund; kryengritjet e viteve 1891, 1898 dhe 1904 përbënë frontin e brendshëm më të shtrenjtë dhe më të gjatë osman. Vendet e tjera që u bashkuan në të njëjtën datë: Sana, Taizi.", "2173d1a2"]},
"OLAYLAR_EK5:1875-06-19:0":{"b": ["Fillimi i kryengritjes së Hercegovinës: ndezja e re e Çështjes së Lindjes", "571b18ec"], "d": ["Ngritja e fshatarëve të krishterë përreth Nevesinjes, për shkak të taksave të rënda dhe trysnisë së ajanëve, brenda pak kohe u përhap në gjithë Hercegovinën dhe u ushqye nga vullnetarë të ardhur nga Serbia e Mali i Zi. Kryengritja, që çoi në imponimet e reformave nga Austria dhe Rusia, vitin pasues shkaktoi kryengritjet bullgare dhe shpalljet e luftës nga Serbia e Mali i Zi. Kështu u këput hallka e parë e zinxhirit të madh që çoi në Luftën e '93-shit dhe në humbjen e Ballkanit me Traktatin e Berlinit.", "b697eb06"]},
"OLAYLAR_EK5:1875-10-06:0":{"b": ["Falimentimi i financave osmane: përgjysmimi i pagesave të borxhit të jashtëm", "2cac2fa5"], "d": ["Huatë e marra njëra pas tjetrës që nga viti 1854, shpenzimet e Luftës së Krimesë, ndërtimet e sarajeve dhe zija e bukës në Anadoll në vitet 1873-74 e shndërruan deficitin buxhetor në një humnerë mbi pesë milionë lira. Qeveria e Mahmud Nedim Pashës, duke shpallur se pagesat e interesave e të principalit të borxhit do të përgjysmoheshin për pesë vjet, shpalli faktikisht moratorium. Ky vendim, që ngjalli reagim të madh në bursat evropiane, nisi procesin që gjashtë vjet më vonë do të përfundonte me Dekretin e Muharremit dhe krijimin e Administratës së Borxhit Publik Osman (Düyun-u Umumiye).", "a6706632"]},
"OLAYLAR_EK5:1876-08-31:0":{"b": ["Rrëzimi i Muratit V dhe hipja në fron e Abdylhamidit II", "cffb2271"], "d": ["Murati V, që hipi në fron pas rrëzimit të Abdylazizit, për shkak të shëndetit mendor të tronditur nga vdekja e xhaxhait dhe ngjarja e Hasan Çerkezit, u bë i paaftë për detyrë; nga nëntëdhjetë e tri ditët e sundimit vetëm në shtatë pati gjykim të shëndoshë. Me fetvanë e shejhulislamit u rrëzua dhe në vend të tij u soll vëllai i tij Abdylhamidi II. Padishahu i ri hipi në fron duke i premtuar Midhat Pashës se do të shpallte regjimin kushtetues; fillonte një epokë që do të zgjaste tridhjetë e tre vjet.", "9904ab70"]},
"OLAYLAR_EK5:1876-12-23:0":{"b": ["Konferenca e Tersanesë: imponimi i reformave për Ballkanin nga fuqitë e mëdha", "b5006a2c"], "d": ["Konferenca, që fuqitë e mëdha mblodhën në Stamboll për të zgjidhur krizën ballkanike, kërkoi ndarjen e Bullgarisë në dy vilajete autonome dhe zbatimin në Bosnjë-Hercegovinë të reformave me kontroll ndërkombëtar. Porta e Lartë, ditën e hapjes së konferencës, duke njoftuar me të shtëna topash shpalljen e Ligjit Themelor (Kanun-i Esasi), u përpoq t'u përgjigjej imponimeve me reformë kushtetuese. Delegatët e konsideruan këtë shtyrje dhe më 20 janar 1877 u shpërndanë; katër muaj më vonë Rusia shpalli luftë.", "8149c00f"]},
"OLAYLAR_EK5:1877-03-19:0":{"b": ["Hapja e Parlamentit të parë (Mexhlisi i Mebusanëve) në Dollmabahçe", "429bb279"], "d": ["115 deputetët e zgjedhur sipas Ligjit Themelor u mblodhën për herë të parë më 19 mars 1877 me ceremoni në Sallonin e Pritjeve të Sarajit Dollmabahçe; kështu në historinë osmane filloi periudha e parlamentit përfaqësues. Deputetët myslimanë dhe jomyslimanë e pyetën ashpër qeverinë, diskutuan drejtimin e luftës dhe përgjegjësinë e ministrave. Kjo opozitë guximtare do të ishte shkaku kryesor që do ta shkurtonte jetën e parlamentit.", "df95fa07"]},
"OLAYLAR_EK5:1877-07-19:0":{"b": ["Fillimi i mbrojtjes së Plevnës: qëndresa e Gazi Osman Pashës", "0e04a878"], "d": ["Për t'i prerë rrugën për në Stamboll ushtrisë ruse që kaloi Danubin në Luftën e '93-shit, Osman Pasha marshoi nga Vidini në Plevnë, e fortifikoi qytezën me reduta e llogore dhe nisi një mbrojtje legjendare pesëmujore. Tri sulme të mëdha ruso-rumune njëra pas tjetrës u zmbrapsën me humbje të rënda dhe ushtria e drejtuar personalisht nga cari Aleksandër II u detyrua të kalonte në rrethim. Plevna hyri në histori si suksesi më i shkëlqyer mbrojtës i ushtrisë osmane në shekullin XIX.", "5a86466f"]},
"OLAYLAR_EK5:1877-12-10:0":{"b": ["Rënia e Plevnës: shembja e frontit të Danubit", "185e7602"], "d": ["Osman Pasha, që gjatë rrethimit pesëmujor i mbaruan rezervat, ndërmori një dalje sulmuese përtej lumit Vit; pasi u plagos e ra rob, qyteti u dorëzua. Komandantët rusë e përshëndetën pashain e zënë rob duke i kthyer shpatën dhe Osman Pashës iu dha titulli 'Gazi'. Me rënien e Plevnës, ushtrisë ruse iu hap rruga; brenda dy muajsh ranë Sofja, Filipopoja (Plovdivi) dhe Edreneja, dhe pararojat ruse arritën në Jeshilkëj.", "fc075756"]},
"OLAYLAR_EK5:1878-01-04:0":{"b": ["Pushtimi i Sofjes nga forcat ruse", "ef369d22"], "d": ["Ushtria ruse, që pas rënies së Plevnës kapërceu Ballkanin, hyri në Sofjen e pambrojtur. Qyteti nuk do të kthehej më nën administrimin osman; në fund të vitit 1878 do të bëhej pjesë e Principatës autonome të Bullgarisë dhe më 1879 faktikisht kryeqyteti i saj. Në hartë, Sofja nga kjo datë del nga administrimi i drejtpërdrejtë osman, kalon nën pushtimin e përkohshëm rus dhe më pas nën administrimin autonom bullgar.", "66b1da91"]},
"OLAYLAR_EK5:1878-01-31:0":{"b": ["Armëpushimi i Edrenesë: heshtja e armëve në Luftën e '93-shit", "1f899180"], "d": ["Pas rënies njëra pas tjetrës të Sofjes, Filipopojës dhe Edrenesë dhe arritjes së ushtrisë ruse në brigjet e Marmarasë, Porta e Lartë u detyrua të kërkonte armëpushim. Armëpushimi i nënshkruar në Edrene i detyroi osmanët të pranonin kushtet paraprake të paqes, si autonomia e Bullgarisë, pavarësia e Malit të Zi, Serbisë e Rumanisë dhe dëmshpërblimi i rëndë i luftës. Një muaj më vonë, në Shën Stefan, këto kushte do të shndërroheshin në tekst traktati.", "49d61081"]},
"OLAYLAR_EK5:1878-02-13:0":{"b": ["Pezullimi pa afat i Parlamentit nga Abdylhamidi II", "e770b540"], "d": ["Për shkak të kritikave të ashpra të deputetëve, që për përfundimin katastrofik të luftës fajësonin qeverinë dhe sarajin, Abdylhamidi II, duke u mbështetur në kompetencën që i njihte Ligji Themelor, e pezulloi parlamentin pa afat. Kështu u mbyll parlamenti i parë osman, që kishte punuar rreth njëmbëdhjetë muaj, dhe filloi epoka e absolutizmit që do të zgjaste tridhjetë vjet. Parlamenti mundi të mblidhej përsëri vetëm pas revolucionit të vitit 1908.", "dd2e6d60"]},
"OLAYLAR_EK5:1878-03-03:0":{"b": ["Traktati i Shën Stefanit: projekti i Bullgarisë së Madhe", "2c7cc611"], "d": ["Traktati i Shën Stefanit, që i dha fund Luftës së '93-shit, krijonte një Bullgari autonome gjigante që shtrihej deri në Egje dhe përfshinte Maqedoninë; njihte pavarësinë e Serbisë, Malit të Zi dhe Rumanisë; ia linte Rusisë Karsin, Ardahanin, Batumin dhe Dogubajazitin dhe, veç kësaj, ngarkonte një dëmshpërblim lufte të pamundur për t'u paguar. Ky tekst, që e zbriste Rusinë në Mesdhe, ngjalli reagim të ashpër të Anglisë dhe Austrisë. Pa u zbatuar, brenda katër muajsh u rirregullua me Kongresin e Berlinit; megjithatë mbeti dokumenti që shpalli fundin e Rumelisë osmane.", "dfd3e7f4"]},
"OLAYLAR_EK5:1878-07-13:0":{"b": ["Karsi, Ardahani dhe Batumi iu lanë Rusisë — Elviye-i Selase", "99bdfad2"], "d": ["Me Traktatin e Berlinit, Shteti Osman ia la Rusisë Karsin, Ardahanin dhe Batumin në këmbim të një pjese të dëmshpërblimit të luftës; ndërsa Dogubajaziti dhe lugina e Eleshkirtit, që në Shën Stefan i ishin dhënë Rusisë, mbetën te osmanët. Ndonëse Batumi u dha si port i lirë, këtë status mundi ta ruante vetëm deri më 1886. Rusët e bënë Karsin vilajet të lidhur me guvernatorinë e përgjithshme të Transkaukazisë me qendër në Tiflis; një popullsi që nga tri sanxhaqet arrinte deri në 100.000 veta u detyrua të emigronte në anën e Erzurumit. Me të njëjtin traktat, Besarabia Jugore (Kilia, Kahuli, Bolgradi) iu kthye Rusisë nga Rumania.", "867dda58"]},
"OLAYLAR_EK5:1878-07-29:0":{"b": ["Pushtimi i Bosnjë-Hercegovinës dhe i Pazarit të Ri nga Austro-Hungaria", "e5f901df"], "d": ["Duke u mbështetur në autorizimin e dhënë nga Traktati i Berlinit, ushtritë austro-hungareze hynë në Bosnjë; ndonëse qeveria osmane pranoi të mos rezistonte, popullsia vendëse myslimane dhe ortodokse në Sarajevë dhe Mostar rroku armët dhe për tre muaj bëri një qëndresë të ashpër. Pushtimi mundi të përfundonte vetëm më 20 tetor 1878. Sovraniteti juridik i padishahut vazhdoi në letër deri në vitin 1908, por Bosnja osmane katërshekullore humbi faktikisht dhe filloi një valë e madhe emigrimi të myslimanëve. Vendbanimet e tjera që dolën nga dora në të njëjtën datë: Banja Lluka.", "9d6a9e57"]},
"OLAYLAR_EK5:1881-12-20:0":{"b": ["Dekreti i Muharremit dhe krijimi i Administratës së Borxhit Publik Osman (Düyun-u Umumiye)", "02b7cc03"], "d": ["Bisedimet që pas falimentimit të vitit 1875 u zhvilluan me përfaqësuesit e shteteve kreditore përfunduan me dekretin e datës 28 muharrem 1299 (20 dhjetor 1881): principali i borxhit u ul me më shumë se gjysmën, kurse në këmbim zërat më fitimprurës të të ardhurave, si taksat e kripës, duhanit, mëndafshit, pullës dhe peshkut, iu kaluan drejtpërdrejt Administratës së Borxhit Publik Osman, të drejtuar nga kreditorët. Kjo administratë, që punësonte mijëra nëpunës, u shndërrua në një organizatë financiare më vete brenda shtetit. Konsiderohet data kur pavarësia financiare osmane mori fund faktikisht.", "3cb26eeb"]},
"OLAYLAR_EK5:1884-02-01:0":{"b": ["Suakini — porti i vetëm që nuk ra në duart e Mehdiut", "5a37b198"], "d": ["Ndërsa që nga shkurti 1884 të gjitha zonat e Sudanit lindor, me përjashtim të Suakinit, kaluan nën sundimin e Muhammed Ahmed el-Mehdiut, porti u mbajt më këmbë me mbrojtjen ushtarake të forcës angleze prej tri batalionesh nën komandën e gjeneralit Graham. Ky ishte fillimi i një periudhe në të cilën gjendja faktike dhe ajo juridike u ndanë: edhe pse bregdeti ishte faktikisht nën kontrollin ushtarak anglez, lidhja administrative do t'i merrej Egjiptit më 1885 dhe do t'i lidhej drejtpërdrejt vilajetit të Jemenit, pra Portës së Lartë — ky rend vazhdoi derisa mori fund më 1888 me pushtimin francez të Zejlës.", "343c16cf"]},
"OLAYLAR_EK5:1884-05-08:0":{"b": ["Vrasja e Midhat Pashës në burgun e Taifit", "f4562261"], "d": ["Midhat Pasha, arkitekti i Ligjit Themelor dhe emri simbol i Regjimit të Parë Kushtetues, ishte shpallur fajtor në Gjyqin e Jëlldëzit për vdekjen e Abdylazizit, dënimi me vdekje iu kthye në internim dhe u dërgua në Taif. Sipas shënimit të TDV-së, natën e 7-8 majit 1884 u vra me mbytje në qelinë e tij, ndërsa si shkak zyrtar u shpall sëmundja 'şirpençe' (karbunkul). Vdekja e tij u bë simbol i likuidimit të opozitës kushtetuese në kohën e Abdylhamidit II.", "06cc8d1c"]},
"OLAYLAR_EK5:1888-09-24:0":{"b": ["Dhënia gjermanëve e koncesionit të hekurudhës Hajdarpasha-Ankara", "5705b163"], "d": ["Me iradenë e padishahut, koncesioni për ndërtimin dhe shfrytëzimin e linjës Hajdarpasha-Ankara iu dha bankierit Alfred von Kaulla, që përfaqësonte Deutsche Bank, dhe u krijua Shoqëria e Hekurudhave të Anadollit. Ky koncesion u bë pikë kthese që theu monopolin anglo-francez në transportin dhe politikën e jashtme osmane dhe vendosi ndikimin gjerman. Bashkë me koncesionin e linjës së Bagdadit, që njëmbëdhjetë vjet më vonë do t'i jepej së njëjtës shoqëri, do të lindte ëndrra 'Berlin-Bagdad', dhe kjo do të bëhej një nga boshtet kryesore të rivalitetit të fuqive të mëdha para Luftës së Parë Botërore.", "9974f219"]},
"OLAYLAR_EK5:1889-06-02:0":{"b": ["Themelimi i Shoqërisë Bashkimi Osman (İttihad-ı Osmani) në Stamboll", "b7187939"], "d": ["Katër studentë të Shkollës Ushtarake të Mjekësisë themeluan Shoqërinë Bashkimi Osman si organizatë të fshehtë kundër regjimit absolutist; kjo strukturë brenda pak kohe u shndërrua në Komitetin Bashkim e Përparim, që do të mblidhte nën çatinë e vet të gjithë elementët opozitarë të lëvizjes xhonturke. Organizimi i bazuar në celula u bashkua me të mërguarit në Evropë dhe me oficerët në Selanik. Kuadri që më 1908 do ta detyronte shpalljen e Regjimit të Dytë Kushtetues dhe pas vitit 1913 do ta drejtonte shtetin i vetëm doli nga kjo celulë e vogël studentësh.", "f2417434"]},
"OLAYLAR_EK5:1896-08-26:0":{"b": ["Sulmi mbi Bankën Osmane: aksioni i militantëve dashnakë në Galata", "08b3095f"], "d": ["Një grup i armatosur i organizatës armene Dashnakcutjun, me synim të tërhiqte vëmendjen e Evropës ndaj çështjes armene, sulmoi selinë qendrore të Bankës Osmane në Galata, mori pengje dhe kërcënoi se do ta hidhte ndërtesën në erë. Kriza përfundoi me ndërmjetësimin e ambasadorëve, në këmbim të nxjerrjes së militantëve nga vendi me një anije. Ngjarjet e përgjakshme që ndodhën në Stamboll në ditët pas sulmit ishin vendimtare në shndërrimin e çështjes armene në mjet presioni për ndërhyrje ndërkombëtare.", "8fb5eb98"]},
"OLAYLAR_EK5:1897-04-17:0":{"b": ["Fillimi i luftës osmano-greke të vitit 1897: fronti i Thesalisë", "33e490ab"], "d": ["Për shkak se Greqia nxori flotë dhe ushtarë në Kretë dhe për sulmet e çetave në kufirin e Rumelisë, Shteti Osman shpalli luftë. Ushtria osmane, e stërvitur nga misioni gjerman i reformave, përparoi shpejt në Thesali dhe brenda një muaji mori Larisën (Yenişehir), Farsalën (Çatalca) dhe Domokon (Dömeke); ushtria greke u shpërnda. Me ndërhyrjen e fuqive të mëdha, tokat e fituara u kthyen, por lufta mbeti e vetmja fitore ushtarake e prerë e kohës së Abdylhamidit II dhe nuk mundi ta pengonte humbjen faktike të Kretës.", "405fd8a7"]},
"OLAYLAR_EK5:1899-11-27:0":{"b": ["Dhënia gjermanëve e koncesionit të linjës Konja-Bagdad", "fd8b6cbd"], "d": ["Pas vizitës së kajzerit Vilhelm II në Stamboll dhe Damask më 1898, Shoqërisë së Hekurudhave të Anadollit iu dha koncesioni paraprak i linjës që do të shtrihej nga Konja në Bagdad dhe Basra. Projekti i Hekurudhës së Bagdadit për osmanët nënkuptonte forcimin e kontrollit qendror mbi vilajetet arabe, ndërsa për Gjermaninë arritjen në Gjirin e Basrës. Ky projekt, të cilin Anglia dhe Rusia e kundërshtuan ashpër, u bë një nga dosjet më të diskutuara të rivalitetit imperialist që çoi në Luftën e Parë Botërore.", "0de9d1cf"]},
"OLAYLAR_EK5:1900-09-01:0":{"b": ["Fillimi i ndërtimit të Hekurudhës së Hixhazit në Damask", "62f58f68"], "d": ["Linja, që Abdylhamidi II e urdhëroi me iradenë e datës 2 maj 1900, filloi të ndërtohej më 1 shtator 1900 me ceremoni zyrtare në Damask. Projekti, i realizuar tërësisht me donacione të mbledhura nga bota islame dhe me punën e inxhinierëve dhe ushtarëve osmanë, e shkurtoi udhëtimin e haxhilerëve Damask-Medinë nga dyzet ditë në pesë. Ishte njëkohësisht vepër prestigji që forconte autoritetin shpirtëror të hilafetit dhe investim strategjik që përforconte kontrollin ushtarak mbi Hixhazin.", "5dedd229"]},
"OLAYLAR_EK5:1903-10-02:0":{"b": ["Programi i Mürzstegut: mbikëqyrja ndërkombëtare e reformave në Maqedoni", "4c7464da"], "d": ["Pas kryengritjes së Ilindenit, perandorët rus dhe austriak u takuan në Mürzsteg dhe përgatitën një paketë të re reformash për Maqedoninë. Programi parashikonte vendosjen pranë inspektorit të përgjithshëm osman të dy agjentëve civilë të huaj, riorganizimin e xhandarmërisë nga oficerë evropianë dhe ndryshimin e kufijve administrativë sipas parimit të kombësisë. Ndonëse Porta e Lartë rezistoi me arsyetimin se cenoheshin të drejtat sovrane, nën trysninë e përbashkët u detyrua ta pranonte; programi u bë një nga faktorët themelorë që e përshpejtuan organizimin ittihadist mes oficerëve të rinj.", "b56ab15c"]},
"OLAYLAR_EK5:1904-08-29:0":{"b": ["Vdekja e Muratit V", "396659a7"], "d": ["Murati V, që më 1876 qëndroi në fron rreth tre muaj dhe u rrëzua, pas përpjekjeve për ta rikthyer në fron jetoi i burgosur nën ruajtje të rreptë njëzet e tetë vjet dhe vdiq nga sëmundja e sheqerit. U varros pranë së ëmës në Tyrben e Zonjave të Reja (Cedid Havatin) në xhaminë Jeni. Hyri në histori si padishahu osman që qëndroi më pak në fron.", "8558c1b8"]},
"OLAYLAR_EK5:1905-04-01:0":{"b": ["Humbja e Sanasë nga imam Jahja", "e7f876cb"], "d": ["Kryengritja e nisur më 1904 nga imami zejdit Jahja Hamidudin përfundoi në prill 1905 me rënien e Sanasë pas rrethimit; qyteti doli nga administrimi osman dhe gjatë rrethimit shpërthyen uria dhe epidemitë. Gjeografia malore e Jemenit, gjatësia e linjave të furnizimit dhe legjitimiteti vendor i imamatit zejdit e bënin sundimin osman këtu të brishtë që nga themelimi i tij. Qyteti do të rimerrej pesë muaj më vonë me humbje të rënda, por çështja e Jemenit nuk do të mbyllej deri në vitin 1918.", "702b0ff5"]},
"OLAYLAR_EK5:1905-07-21:0":{"b": ["Atentati i Jëlldëzit: sulm me bombë ndaj Abdylhamidit II", "1ee2e1a6"], "d": ["Organizata Dashnakcutjun organizoi atentatin duke shpërthyer një karrocë (lando) me bombë me sahat pranë karrocës së padishahut që po dilte nga ceremonia e xhumasë; vonesa e Abdylhamidit për disa minuta, teksa bisedonte me shejhulislamin, i shpëtoi jetën. Në shpërthim vdiqën njëzet e gjashtë veta dhe u plagosën më shumë se pesëdhjetë. Ngjarja e ashpërsoi edhe më shumë obsesionin e padishahut për sigurinë dhe sundimin absolutist të mbështetur në organizatën e spiunëve; u bë edhe temë e poezisë së Tevfik Fikretit 'Një çast vonese' (Bir Lahza-i Taahhur).", "d4f10280"]},
"OLAYLAR_EK5:1905-09-01:0":{"b": ["Rimarrja e Sanasë: shtypja e kryengritjes së imam Jahjasë", "dec3b8f9"], "d": ["Kryengritja që filloi më 1904 nën udhëheqjen e imamit zejdit Jahja përfundoi në prill 1905 me rënien e Sanasë dhe në qytet shpërthyen uria dhe epidemitë. Ushtritë përforcuese nën komandën e Ali Rëza Pashës dhe Ahmet Fejzi Pashës, me operacionin që zhvilluan mes 15 korrikut dhe 1 shtatorit 1905, të mbështetur edhe nga forcat në Taiz, e rimorën qytetin me humbje të rënda dhe kryengritja u shtyp. Operacioni i Jemenit i solli ushtrisë osmane dhjetëra mijëra humbje dhe një barrë kolosale financiare; mes oficerëve në Rumeli frika e 'internimit në Jemen' ishte ndër ankesat kryesore që ushqenin organizimin ittihadist.", "667bb98c"]},
"OLAYLAR_EK5:1908-12-17:0":{"b": ["Mbledhja e parlamentit të parë të Regjimit të Dytë Kushtetues", "e7fd2716"], "d": ["Parlamenti, i formuar me zgjedhje dyshkallëshe të mbajtura pas një ndërprerjeje tridhjetëvjeçare, u hap më 17 dhjetor 1908 me fjalimin e padishahut dhe kryetar i tij u zgjodh Ahmet Rëza Beu, udhëheqës i lëvizjes xhonturke. Parlamenti, i përbërë nga deputetë turq, arabë, shqiptarë, grekë, armenë e hebrenj, ishte prova e fundit e madhe e idealit të osmanizmit. Megjithatë, pavarësia e Bullgarisë, aneksimi i Bosnjës dhe shpallja e bashkimit të Kretës me Greqinë e kishin errësuar këtë optimizëm ende pa u hapur parlamenti.", "b408f232"]},
"OLAYLAR_EK5:1909-04-27:0":{"b": ["Ushtria e Veprimit dhe rrëzimi i Abdylhamidit II: hipja në fron e Mehmetit V Reshad", "6a65a704"], "d": ["Ushtria e Veprimit (Hareket Ordusu), e nisur nga Selaniku pas Ngjarjes së 31 Marsit, natën e 22-23 prillit hyri në Stamboll nga katër drejtime dhe më 24 prill u dorëzua Saraji i Jëlldëzit. Kuvendi i Përgjithshëm Kombëtar më 27 prill vendosi rrëzimin e Abdylhamidit II; padishahu u dërgua në Selanik dhe në fron u ngrit vëllai i tij Mehmeti V Reshad. Kështu mori fund sundimi personal tridhjetë e trevjeçar, por vendin e tij e zuri një periudhë e re, në të cilën padishahu u bë simbolik dhe Komiteti Bashkim e Përparim drejtonte me mbështetjen e ushtrisë.", "496ff2f2"]},
"OLAYLAR_EK5:1910-04-01:0":{"b": ["Kryengritja shqiptare: qëndresë e armatosur në Kosovë dhe Shkodër", "93ed30c6"], "d": ["Politika centralizuese tatimore e qeverisë ittihadiste, fushata e mbledhjes së armëve dhe debati për alfabetin latin i ngritën në kryengritje fiset shqiptare, që deri atëherë konsideroheshin ndër elementët më besnikë të shtetit. Ndonëse ushtria nën komandën e Mahmud Shefqet Pashës e shtypi ashpër kryengritjen, pakënaqësia u ndez përsëri më 1911 dhe 1912. Këto kryengritje e rraskapitën ushtrinë osmane në prag të Luftës Ballkanike dhe e përshpejtuan lindjen e lëvizjes kombëtare shqiptare.", "18d0ffb5"]},
"OLAYLAR_EK5:1912-10-18:0":{"b": ["Traktati i Ouchyt: lëshimi i Tripolit dhe Bengazit Italisë", "4ffa1fd2"], "d": ["Porta e Lartë, që përballë përgatitjeve për luftë të shteteve ballkanike nuk guxoi të rrezikonte një konflikt në dy fronte, në qytezën zvicerane Ouchy nënshkroi me Italinë një paqe të fshehtë dhe hoqi dorë nga Tripoli dhe Bengazi. Kështu Shteti Osman humbi tokën e fundit në Afrikë; në këmbim u premtua kthimi i Rodosit dhe i Dymbëdhjetë Ishujve të pushtuar nga Italia, por ky premtim nuk u mbajt kurrë. Kur u nënshkrua traktati, Lufta Ballkanike kishte filluar prej kohësh. Me këtë ngjarje, Murzuku (Fezzani), Gati, Sebha, Ubari, Traghani, Zawila dhe el-Katruni (sanxhaku i Fezzanit i vilajetit të Tripolit) kaluan nën administrimin italian.", "5896634d"]},
"OLAYLAR_EK5:1912-10-21:0":{"b": ["Pushtimi grek i Lemnosit", "9555af1d"], "d": ["Në Luftën e Parë Ballkanike, flota greke pushtoi Lemnosin; porti Mudros i ishullit u bë bazë për bllokadën e ngushticës së Dardaneleve. Ishulli në Lozanë (24 korrik 1923) iu la Greqisë.", "61677826"]},
"OLAYLAR_EK5:1912-10-30:0":{"b": ["Pushtimi grek i Tasosit", "6c03c7f0"], "d": ["Në Luftën e Parë Ballkanike, Greqia pushtoi Tasosin dhe Samotrakën.", "b0695c7a"]},
"OLAYLAR_EK5:1912-11-01:0":{"b": ["Pushtimi grek i Samotrakës", "911e82a3"], "d": ["Në Luftën e Parë Ballkanike, Greqia pushtoi Samotrakën.", "0e592cf7"]},
"OLAYLAR_EK5:1912-11-21:0":{"b": ["Pushtimi grek i Mitilenës (Lesbos)", "6b2b07ba"], "d": ["Flota greke zbarkoi në Lesbos; ishulli në fund të Luftës së Parë Ballkanike u shtie në dorë nga ushtria dhe flota greke. Konferenca e Londrës (maj 1913) e konfirmoi gjendjen.", "a07eeadb"]},
"OLAYLAR_EK5:1912-11-25:0":{"b": ["Zbarkimi grek në Kios", "901c6539"], "d": ["Në Kios, të bombarduar më 7 prill 1912 gjatë Luftës së Parë Ballkanike, grekët bënë zbarkim; garnizoni osman u dorëzua më 3 janar 1913. Ishulli me Traktatin e Lozanës (24 korrik 1923) iu la Greqisë.", "d9fc9f4b"]},
"OLAYLAR_EK5:1913-06-11:0":{"b": ["Vrasja me atentat në Stamboll e vezirit të madh Mahmud Shefqet Pasha", "68e60e63"], "d": ["Mahmud Shefqet Pasha, i emëruar vezir i madh pas Sulmit mbi Portën e Lartë, teksa shkonte në Ministrinë e Luftës, u vra pranë Çarshikapisë nga të shtënat mbi karrocën e tij. Komiteti Bashkim e Përparim, duke ia hedhur fajin e atentatit opozitës, nisi një valë të gjerë arrestimesh e ekzekutimesh dhe Partia Liri e Marrëveshje (Hürriyet ve İtilaf) u likuidua faktikisht. Me këtë ngjarje u vendos përfundimisht diktatura njëpartiake e ittihadistëve, e mbështetur në treshen Enver-Talat-Xhemal.", "203085f0"]},
"OLAYLAR_EK5:1913-06-29:0":{"b": ["Fillimi i Luftës së Dytë Ballkanike: grindja e aleatëve për ndarjen", "48d088a2"], "d": ["Aleatët ballkanikë, që nuk mundën të ndanin mes tyre tokat që u kishin marrë osmanëve me Traktatin e Londrës, ranë në konflikt me njëri-tjetrin; me sulmin e Bullgarisë mbi pozicionet serbe e greke filloi lufta e dytë. Kur edhe Rumania dhe Mali i Zi hynë në front kundër Bullgarisë, ushtria bullgare u shemb. Shteti Osman, duke e shfrytëzuar këtë rast, e kaloi vijën Midje-Enez të caktuar nga Traktati i Londrës dhe rimori Trakinë Lindore bashkë me Edrenenë.", "33183400"]},
"OLAYLAR_EK5:1913-09-29:0":{"b": ["Traktati i Stambollit: paqja me Bullgarinë dhe konfirmimi i Edrenesë", "c8c18b2d"], "d": ["Traktati i nënshkruar pas Luftës së Dytë Ballkanike mes Shtetit Osman dhe Bullgarisë, duke pranuar lumin Marica si kufi, konfirmoi juridikisht që Edreneja, Kërklarelia, Dimotika dhe Trakia Lindore të mbeteshin te osmanët. Dedeagaçi iu la Bullgarisë (ndërsa Kavalla, pas pushtimit bullgar të vjeshtës 1912, në korrik 1913 kishte kaluar te Greqia dhe me Traktatin e Bukureshtit të 10 gushtit 1913 ishte konfirmuar si pjesë e Greqisë); u rregulluan shkëmbimi reciprok i popullsisë mes dy vendeve dhe të drejtat e myslimanëve në Bullgari. Ky tekst është garancia e së vetmes pjesë toke që mundi të rimerrej nga katastrofa ballkanike. Vendet e tjera që u bashkuan në të njëjtën datë: Gjumulxhina.", "1fe8a2f6"]},
"OLAYLAR_EK5:1913-11-01:0":{"b": ["Rimarrja e Tenedosit dhe Imbrosit — Traktati i Athinës", "ec084d09"], "d": ["Nga ishujt e Egjeut Verior të pushtuar nga Greqia në Luftën Ballkanike, Tenedosi dhe Imbrosi, që zotëronin grykën e ngushticës, në bisedimet e Traktatit të Athinës u konsideruan të domosdoshëm për mbrojtjen e Çanakkalesë dhe iu kthyen osmanëve. Ishujt e tjerë mbetën te Greqia. Këta dy ishuj u bënë tokat e fundit që perandoria mbajti në Egje dhe edhe në Lozanë iu lanë Turqisë.", "bc1961ea"]},
"OLAYLAR_EK5:1913-11-14:0":{"b": ["Traktati i Athinës: paqja me Greqinë dhe kalimi i Selanikut dhe Janinës", "8e94def7"], "d": ["Traktati i nënshkruar mes Shtetit Osman dhe Greqisë e njohu zyrtarisht kalimin te Greqia të Selanikut, Janinës dhe Maqedonisë Jugore, të humbura në Luftën Ballkanike, dhe u hoq dorë nga të drejtat osmane mbi Kretën. Të drejtat fetare e pronësore të myslimanëve të mbetur në Greqi, statusi i vakëfeve dhe emërimi i myftinjve u rregulluan hollësisht. Ndërsa statusi i ishujve të Egjeut u la i pazgjidhur dhe mbeti burim i përhershëm tensioni mes dy shteteve.", "a5ae7115"]},
"OLAYLAR_EK5:1914-08-02:0":{"b": ["Nënshkrimi në Stamboll i traktatit të fshehtë të aleancës osmano-gjermane", "0472efb3"], "d": ["Sapo shpërtheu lufta në Evropë, në konakun e vezirit të madh Said Halim Pasha u nënshkrua një traktat i fshehtë aleance mes Shtetit Osman dhe Gjermanisë; teksti parashikonte që, nëse Rusia hynte në luftë kundër Gjermanisë, edhe osmanët të rreshtoheshin përkrah Gjermanisë. Traktati u mbajt i fshehtë edhe nga kabineti; për të dinin vetëm katër veta. Tre muaj më vonë, me sulmin në Detin e Zi, Shteti Osman do të tërhiqej faktikisht në luftë dhe fati i perandorisë do të lidhej me këtë dokument.", "063ef809"]},
"OLAYLAR_EK5:1914-09-09:0":{"b": ["Heqja e njëanshme e kapitulacioneve", "ec773d18"], "d": ["Qeveria osmane, në një çast kur Evropa ishte e zënë me luftë, shpalli se që nga 1 tetori 1914 i hiqte njëanshëm kapitulacionet, që u njihnin të huajve privilegje gjyqësore, financiare dhe doganore. Fundi i këtij rendi privilegjesh katërshekullor u prit brenda vendit me një entuziazëm të madh pavarësie dhe në Stamboll u bënë festime. Të gjitha shtetet, përfshirë aleaten Gjermani, protestuan kundër vendimit; kapitulacionet do të hynin përfundimisht në histori vetëm më 1923 në Lozanë.", "b30c11aa"]},
"OLAYLAR_EK5:1914-10-29:0":{"b": ["Sulmi në Detin e Zi: flota osmane bombardon portet ruse", "8ad4ef61"], "d": ["Goebeni dhe Breslau (Yavuz dhe Midilli), që ikën nga Gjermania dhe iu bashkuan flotës osmane si të 'blera', nën komandën e admiralit Souchon dolën në Detin e Zi, goditën me topa portet ruse dhe fundosën anije. Ky urdhër, që Enver Pasha e dha fshehurazi nga kabineti, i dha fund faktikisht neutralitetit. Brenda një jave Rusia, Anglia dhe Franca shpallën luftë dhe Shteti Osman hyri pakthyeshëm në Luftën e Parë Botërore.", "bdd1c93a"]},
"OLAYLAR_EK5:1914-11-06:0":{"b": ["Shtënia në dorë e Faos nga forcat britaniko-indiane — hapja e frontit të Irakut", "08663813"], "d": ["Mëngjesin pas ditës kur shtetet e Antantës i shpallën luftë Shtetit Osman, brigada britaniko-indiane që priste në Bahrein zbarkoi në Fao, në grykën e Shatt-el-Arabit. Njësia e vogël osmane në kështjellën e rrënuar të Faos u tërhoq nën zjarrin e anijeve luftarake dhe stacioni i linjës telegrafike të Indisë ra në duart e anglezëve. Kështu u hap fronti i Irakut.", "7da97cb0"]},
"OLAYLAR_EK5:1914-11-14:0":{"b": ["Shpallja e Xhihadit të Madh: leximi i fetvasë së xhihadit në xhaminë Fatih", "2a6174e8"], "d": ["Pesë fetvatë e dhëna nga shejhulislami Ürgüplü Hajri Efendi u lexuan në xhaminë Fatih në emër të halif-padishahut dhe të gjithë myslimanët u thirrën në xhihad kundër shteteve të Antantës. Ky veprim, ku Gjermania mbështeste shpresa të mëdha, synonte të ngrinte në kryengritje myslimanët në kolonitë angleze e franceze. Ngritja e përgjithshme e pritur nuk ndodhi; përkundrazi, kryengritja dy vjet më vonë e emirit të Mekës, Sherif Husein, me mbështetjen angleze, tregoi në mënyrë të hidhur kufijtë e ndikimit politik të hilafetit.", "e5a86763"]},
"OLAYLAR_EK5:1914-12-09:0":{"b": ["Dorëzimi i Kurnës te anglezët", "621d36b0"], "d": ["Forcat e valiut të Basrës, Subhi Beut, që pas rënies së Basrës u tërhoqën në Kurnë, ku bashkohen Tigri dhe Eufrati, pas përleshjeve të 4-8 dhjetorit, u dorëzuan mëngjesin e 9 dhjetorit 1914.", "ff45626a"]},
"OLAYLAR_EK5:1914-12-22:0":{"b": ["Operacioni i Sarëkamëshit: katastrofë në frontin e Kaukazit", "5cbde7f0"], "d": ["Enver Pasha, me synim të rimerrte Karsin, Ardahanin dhe Batumin e humbur më 1878 dhe të ngrinte turqit në Kaukaz, e hodhi Armatën III në mes të dimrit në një manovër për të rrethuar forcat ruse përmes maleve Allahuekber. Për shkak të pajisjeve dimërore të pamjaftueshme, furnizimit të mbaruar dhe stuhisë së borës me tridhjetë gradë nën zero, ushtria u shkri ende pa hyrë në betejë; dhjetëra mijëra ushtarë vdiqën nga ngrirja. Operacioni u bë një nga katastrofat më të rënda osmane në luftë dhe e la frontin lindor të pambrojtur për dy vjet.", "f5289317"]},
"OLAYLAR_EK5:1915-01-14:0":{"b": ["Operacioni i Parë i Kanalit: sulm mbi Suez përmes shkretëtirës së Sinait", "02dd72f5"], "d": ["Komandanti i Armatës IV, Xhemal Pasha, me synim të çlironte Egjiptin nga pushtimi anglez dhe të mbyllte Kanalin e Suezit për lundrimin, organizoi një sulm përmes shkretëtirës së Sinait. Ndonëse njësitë osmane arritën në bregun lindor të kanalit dhe një pjesë e tyre kaloi përtej, për shkak të epërsisë angleze dhe mosrealizimit të kryengritjes së pritur të popullit egjiptian u tërhoqën. Operacioni nuk e arriti objektivin, por, duke e detyruar Anglinë të mbante forca të mëdha në Egjipt, krijoi një efekt strategjik të tërthortë.", "d9d0152c"]},
"OLAYLAR_EK5:1915-05-27:0":{"b": ["Miratimi i Ligjit të Dërgimit dhe Vendosjes (Tehxhirit)", "2f2bc22c"], "d": ["Pas kryengritjes së Vanit dhe përparimit rus, qeveria nxori ligjin e përkohshëm që lejonte komandantët e ushtrisë të shpërngulnin në zona të tjera popullsinë që vlerësohej se prishte sigurinë në prapavijë, dhe padishahu e miratoi më 27 maj 1915. Si pasojë e zbatimit, pjesa më e madhe e popullsisë armene në vilajetet lindore dhe jugore të Anadollit u dërgua në drejtim të Sirisë dhe Mosulit; gjatë dërgimit, për shkak të sëmundjeve, urisë dhe sulmeve, pati humbje shumë të mëdha jetësh. Vendimi mbetet çështja më e rëndë e viteve të fundit osmane dhe edhe sot më e debatueshmja.", "e8af8dee"]},
"OLAYLAR_EK5:1916-08-07:0":{"b": ["Njësitë osmane rimorën Mushin nga pushtimi rus", "fb1be113"], "d": ["Gjashtë muaj pas pushtimit të parë rus të Mushit, Korpusi i 16-të osman, në kundërsulmin Bitlis-Mush, hyri në qytezë.", "c235eed5"]},
"OLAYLAR_EK5:1916-08-25:0":{"b": ["Mushi kaloi përsëri në duart ruse", "43ad8a03"], "d": ["Për shkak të kundërsulmit rus, detashmenti osman e boshatisi Mushin; qyteza mes 22 dhe 25 gushtit 1916 u pushtua përsëri nga rusët dhe mbeti në duart e tyre deri në pranverën e vitit 1917.", "db39e054"]},
"OLAYLAR_EK5:1917-05-01:0":{"b": ["Mushi u çlirua përfundimisht nga pushtimi rus", "f0e89703"], "d": ["Mushi, që në Luftën e Parë Botërore ra nën pushtimin rus, u rimor përfundimisht nga forcat osmane më 1 maj 1917.", "f2406306"]},
"OLAYLAR_EK5:1918-02-10:0":{"b": ["Vdekja e Abdylhamidit II në Sarajin Bejlerbej", "c9662582"], "d": ["Vdiq Abdylhamidi II, i rrëzuar nga froni më 1909, i dërguar fillimisht në Selanik, pastaj, kur qyteti humbi në Luftën Ballkanike, i sjellë në Stamboll dhe i mbajtur nën vëzhgim në Sarajin Bejlerbej. Gjatë sundimit tridhjetë e trevjeçar ishte përpjekur të fitonte kohë duke e mbajtur shtetin larg luftërave, por u kujtua edhe për regjimin absolutist. Xhenazja e tij, me një turmë të madhe, u varros në Tyrben e Mahmudit I në Divanjolu; vdekja e tij përkoi me një vit lufte, kur rendi që ai kishte ndërtuar ishte likuiduar prej kohësh.", "241489b4"]},
"OLAYLAR_EK5:1918-03-03:0":{"b": ["Traktati i Brest-Litovskut: rimarrja e Karsit, Ardahanit dhe Batumit", "da82636f"], "d": ["Traktati i nënshkruar mes shteteve të Aleancës Qendrore dhe Rusisë, që pas revolucionit bolshevik u tërhoq nga lufta, e mbylli frontin lindor dhe ia riktheu Shtetit Osman Karsin, Ardahanin dhe Batumin (Elviye-i Selase — tri sanxhaqet), të humbura me Traktatin e Berlinit të vitit 1878. Ky ishte i vetmi fitim territorial i arritur në historinë osmane pas dyzet vjetësh. Megjithatë, pas Armëpushimit të Mudrosit rajoni do të humbiste përsëri dhe zgjidhja përfundimtare do të vinte me Traktatin e Karsit të vitit 1921.", "f6f15123"]},
"OLAYLAR_EK5:1918-03-28:0":{"b": ["Njësitë osmane hynë në Artvin", "ca7d1778"], "d": ["Njësitë osmane që më 25 mars kapërcyen kufirin e vitit 1914 marshuan mbi Elviye-i Selase, ku Brest-Litovsku kthente kufirin e para vitit 1878, dhe hynë në Artvin më 28 mars 1918. Artvini, si pjesë e sanxhakut të Batumit, i ishte lënë Rusisë më 1878; zëri 'Artvin' i TDV-së për kthimin shkruan vetëm 'mars 1918', ndërsa ditën e jep Mustafa Sarı.", "7c7f5573"]},
"OLAYLAR_EK5:1918-04-03:0":{"b": ["Ardahani kaloi në duart e ushtrisë turke", "7fd9e3db"], "d": ["Në operacionin e Elviye-i Selases, ushtria osmane pas Artvinit mori Ardahanin më 3 prill 1918; Ardahani kishte rënë në Luftën e '93-shit më 1877 dhe më 1878 i ishte lënë Rusisë. Karsi do të merrej një muaj më vonë, më 25 prill.", "76d4ba84"]},
"OLAYLAR_EK5:1918-04-14:0":{"b": ["Rimarrja e Batumit", "d37a1a0d"], "d": ["Pas tërheqjes së Rusisë nga lufta me Traktatin e Brest-Litovskut, ushtria osmane që përparoi drejt lindjes rimori pas dyzet vjetësh portin e Batumit, të humbur më 1878. Ky port në skajin lindor të Detit të Zi ishte dalja detare e naftës së Bakusë. Fitimi zgjati vetëm shtatë muaj; pas Armëpushimit të Mudrosit rajoni do të boshatisej.", "877ec7ee"]},
"OLAYLAR_EK5:1918-04-25:0":{"b": ["Elviye-i Selase: Karsi hyri nën administrimin osman", "02cbf0b3"], "d": ["Në Brest-Litovsk ishte vendosur kthimi i tri sanxhaqeve të humbura me Traktatin e Berlinit të vitit 1878 — Karsit, Ardahanit dhe Batumit; ushtria osmane hyri në Ardahan më 3 prill, në Batum më 14 prill dhe në Kars më 25 prill 1918 dhe administrimi u vendos faktikisht. Këto toka, të njohura me emrin 'Elviye-i Selase', u konsideruan kompensim i humbjes që vazhdonte që nga Lufta e '93-shit. Pas armëpushimit do të dilnin përsëri nga dora dhe do t'i lidheshin përfundimisht Turqisë vetëm me Traktatin e Karsit të vitit 1921.", "83a69417"]},
"OLAYLAR_EK5:1918-05-20:0":{"b": ["U pushtua Igdiri — përparimi në luginën e Araksit", "87ebf4d3"], "d": ["Në kuadër të ofensivës së nisur në shkurt 1918, njësitë turke i mundën njësitë armene në Serdarabad, në veri të Araksit, dhe më 20 maj 1918 pushtuan Igdirin. Igdiri nuk bënte pjesë te Elviye-i Selaseja, por ishte kazaja Surmeli e gubernisë së Jerevanit; pas rreth 180 vjetësh, në rajon u vendos për herë të parë administrimi osman.", "f50c4b56"]},
"OLAYLAR_EK5:1918-07-03:0":{"b": ["Vdekja e Mehmetit V Reshad dhe hipja në fron e Mehmetit VI Vahideddin", "d302ba07"], "d": ["Mehmeti V Reshad, sundimi nëntëvjeçar i të cilit kaloi me luftërat e Tripolit, të Ballkanit dhe Botërore, vdiq në periudhën më kritike të luftës dhe në vend të tij hipi në fron vëllai i tij Vahideddini me emrin Mehmeti VI. Padishahu i ri u përpoq të shpëtonte nga kujdestaria e kuadrit ittihadist; kur katër muaj më vonë u nënshkrua armëpushimi, do të detyrohej të drejtonte likuidimin e perandorisë. Ishte padishahu i tridhjetë e gjashtë dhe i fundit i dinastisë osmane.", "2d9306b3"]},
"OLAYLAR_EK5:1918-11-13:0":{"b": ["Ardhja e flotës së Antantës para Stambollit dhe pushtimi faktik i qytetit", "d10cb14d"], "d": ["Pas Armëpushimit të Mudrosit, flota aleate prej mbi gjashtëdhjetë anijesh angleze, franceze, italiane dhe greke u ankorua para Dollmabahçes dhe Stambolli kaloi faktikisht nën pushtim. Pas katërqind e gjashtëdhjetë e pesë vjetësh, kryeqyteti kaloi për herë të parë nën kontrollin e ushtarëve të huaj. Po atë ditë, fjala 'Siç erdhën, ashtu do të ikin', që tregohet se e tha Mustafa Kemal Pasha kur zbriti në Hajdarpasha dhe e pa pamjen, do të bëhej një nga fjalitë simbol të Luftës Kombëtare.", "30db4974"]},
"OLAYLAR_EK5:1918-12-04:0":{"b": ["Tërheqja në zonën e Araksit: u boshatis Igdiri", "57572ab4"], "d": ["Sipas dispozitës së Armëpushimit të Mudrosit për tërheqjen prapa kufirit të vitit 1914, Jakup Shevki Pasha me urdhëresën e 21 nëntorit urdhëroi tërheqjen deri më 4 dhjetor të njësive jashtë kufirit të Brest-Litovskut; Igdiri dhe rrethinat u boshatisën plotësisht në atë datë. Më pas, Qeveria Arasito-Turke u shemb nga armenët në fund të dhjetorit 1918.", "68b8ff9a"]},
"OLAYLAR_EK5:1918-12-17:0":{"b": ["Anglezët u vendosën në Artvin", "e2cb3153"], "d": ["Meqë Armëpushimi i Mudrosit i 30 tetorit 1918 kushtëzonte tërheqjen e ushtrisë osmane prapa kufirit të vitit 1914, Artvini u boshatis dhe më 17 dhjetor 1918 u pushtua nga anglezët. Sipas zërit 'Artvin' të TDV-së, pushtimi anglez zgjati deri në prill 1920.", "5b9a237d"]},
"OLAYLAR_EK5:1918-12-24:0":{"b": ["Administrimi britanik në Batum pas Mudrosit", "9dd768fc"], "d": ["Sipas Armëpushimit të Mudrosit të 30 tetorit 1918, Shteti Osman u detyrua të tërhiqej nga Batumi; më 24 dhjetor 1918 qytetin e zunë njësitë britanike. Batumi, i bërë në prill 1918 qendër sanxhaku më vete, nga kjo datë deri në korrik 1920 mbeti nën kontrollin anglez.", "d172259b"]},
"OLAYLAR_EK5:1919-04-20:0":{"b": ["Ardahani kaloi nën sundimin gjeorgjian", "97cf47f6"], "d": ["Ardahanin, të boshatisur pas Mudrosit, forcat gjeorgjiane e pushtuan më 20 prill 1919, në ditët kur Qeveria e Kaukazit Jugperëndimor u shpërnda nga anglezët. Sundimi gjeorgjian do të zgjaste deri më 23 shkurt 1921.", "6027a645"]},
"OLAYLAR_EK5:1919-04-30:0":{"b": ["Prestoni ia dorëzoi administrimin e Karsit guvernatorit armen", "efa81cb0"], "d": ["Komandanti anglez Preston, që më 12-13 prill 1919 shpërndau Qeverinë e Kaukazit Jugperëndimor, më 30 prill 1919 e shfuqizoi qeverinë e përkohshme të këshillit dhe ia dorëzoi administrimin e qytetit armenit Karganov, të emëruar guvernator i Karsit; në Kars filloi periudha e administrimit armen, që zgjati deri në fitoren e Kazëm Karabekirit më 30 tetor 1920.", "ffa3989a"]},
"OLAYLAR_EK5:1919-07-23:0":{"b": ["Kongresi i Erzurumit: vendimi për qëndresë kombëtare i vilajeteve lindore", "41ef0457"], "d": ["Kongresi, i mbledhur nga Shoqëria për Mbrojtjen e të Drejtave të Anadollit Lindor, pasi u shty për shkak të trysnisë angleze, u hap me pesëdhjetë e gjashtë delegatë dhe kryetar u zgjodh Mustafa Kemal Pasha, që kishte dhënë dorëheqjen nga ushtria. Kongresi shpalli se brenda kufijve kombëtarë atdheu është një i tërë, se mandati dhe protektorati nuk mund të pranohen dhe se, nëse qeveria shpërndahet, kombi do ta marrë fatin e vet në dorë. Këto vendime gjashtë muaj më vonë do të përbënin bërthamën e tekstit të Paktit Kombëtar (Misak-ı Milli).", "925ca450"]},
"OLAYLAR_EK5:1919-09-04:0":{"b": ["Kongresi i Sivasit: bashkimi i qëndresës kombëtare nën një çati", "0e9ad36b"], "d": ["Kongresi, që i filloi punimet më 4 shtator 1919 në Gjimnazin (Sultani) e Sivasit, bashkoi shoqëritë për mbrojtjen e të drejtave nga të katër anët e vendit nën emrin Shoqëria për Mbrojtjen e të Drejtave të Anadollit dhe Rumelisë dhe zgjodhi një Komitet Përfaqësues (Heyet-i Temsiliyye). Propozimi për mandat amerikan u hodh poshtë pas diskutimeve të gjata. Me deklaratën e botuar më 11 shtator, Lufta Kombëtare u bë një lëvizje politike legjitime me një qendër dhe filloi një përplasje e hapur për pushtet me qeverinë e Stambollit.", "9e4ba0a0"]},
"OLAYLAR_EK5:1919-10-22:0":{"b": ["Protokolli i Amasjas: bisedimet mes qeverisë së Stambollit dhe Komitetit Përfaqësues", "40e6a6ab"], "d": ["Pas rënies së Damat Feridit dhe formimit të qeverisë së Ali Rëza Pashës, ministri i Marinës, Salih Pasha, u dërgua në Amasja për të biseduar me Komitetin Përfaqësues. Me protokollet e arritura, qeveria e Stambollit e njohu faktikisht ekzistencën e lëvizjes së Anadollit; u pranua mbledhja e Parlamentit, mbajtja e lirë e zgjedhjeve dhe ruajtja e kufijve kombëtarë. Ky është fitimi i parë zyrtar politik që Lufta Kombëtare arriti përballë Stambollit.", "721d202a"]},
"OLAYLAR_EK5:1920-01-28:0":{"b": ["Miratimi i Paktit Kombëtar nga parlamenti i fundit osman", "6322865e"], "d": ["Teksti i Betimit Kombëtar (Ahd-i Milli), i nënshkruar nga 121 deputetë në Parlamentin e fundit Osman, kërkonte si kushte integritetin e pandashëm të tokave brenda vijës së Mudrosit të banuara me shumicë myslimano-turke, plebishit në vilajetet arabe dhe në Trakinë Perëndimore, heqjen e kapitulacioneve dhe pavarësi të plotë politiko-financiare. Teksti u miratua njëzëri më 17 shkurt 1920 dhe iu shpall botës. Kjo deklaratë ishte njëkohësisht programi politik i Luftës Kombëtare dhe harta e kufijve që do të mbroheshin në Lozanë; u bë shkaku i drejtpërdrejtë i pushtimit zyrtar të Stambollit nga shtetet e Antantës më 16 mars.", "576d2af5"]},
"OLAYLAR_EK5:1920-04-01:0":{"b": ["Ndërsa anglezët tërhiqeshin, Artvini i mbeti Gjeorgjisë", "6d086b06"], "d": ["Sipas zërit 'Artvin' të TDV-së, pushtimi anglez zgjati deri në prill 1920; ndërsa tërhiqeshin, anglezët ia lanë qytetin Gjeorgjisë. Artvini mbeti në duart e Gjeorgjisë deri në ultimatumin e Asamblesë së Madhe Kombëtare Turke më 23 shkurt 1921.", "20ff63b0"]},
"OLAYLAR_EK5:1920-07-07:0":{"b": ["Batumi iu dorëzua administratës gjeorgjiane", "6523d095"], "d": ["Dorëzim-marrja zyrtare e Batumit nga anglezët te gjeorgjianët u realizua më 7 korrik 1920 (zëri 'Batum' i TDV-së shkruan vetëm 'korrik 1920'). Qeveria e Ankarasë më 25 korrik protestoi kundër dorëzimit duke e quajtur 'pushtim'.", "99c9bfc8"]},
"OLAYLAR_EK5:1920-12-03:0":{"b": ["Traktati i Gjymrisë: traktati i parë ndërkombëtar i qeverisë së Asamblesë së Madhe Kombëtare", "9232c690"], "d": ["Pasi ushtria e frontit lindor nën komandën e Kazëm Karabekirit rimori Sarëkamëshin dhe Karsin, Armenia kërkoi paqe dhe me traktatin e nënshkruar në Gjymri pranoi se nuk e njihte Sevrin dhe hiqte dorë nga kërkesat territoriale në lindje. Ky traktat i parë që nënshkroi qeveria e Ankarasë u bë dokumenti i parë ndërkombëtar që e refuzonte faktikisht Sevrin dhe i hapi Asamblesë së Madhe Kombëtare Turke rrugën drejt njohjes juridike. Kështu u sigurua kufiri lindor dhe u bë i mundur zhvendosja e forcave në frontin perëndimor.", "c41c725d"]},
"OLAYLAR_EK5:1921-01-10:0":{"b": ["Beteja e Parë e Inonysë: fitorja e parë e ushtrisë së rregullt", "4add3719"], "d": ["Ushtria e rregullt e sapokrijuar i ndali në pozicionet e Inonysë forcat greke që përparonin nga drejtimi i Bursës dhe i detyroi të tërhiqeshin. Ky sukses, me përmasa të kufizuara nga ana ushtarake, ishte shumë i madh për nga pasojat politike: qeveria e Ankarasë u ftua në Konferencën e Londrës, u hap rruga e Traktatit të Moskës me Rusinë Sovjetike dhe u miratua Ligji i Organizimit Themelor (Teşkilat-ı Esasiye). Me këtë fitore u forcua edhe besimi i opinionit të brendshëm te ushtria e rregullt.", "13509273"]},
"OLAYLAR_EK5:1921-04-01:0":{"b": ["Beteja e Dytë e Inonysë: thyerja për herë të dytë e ofensivës greke", "a974521c"], "d": ["Ushtria greke, që nuk arriti rezultat në Konferencën e Londrës, nisi një ofensivë të re nga drejtimet e Bursës dhe Ushakut, por u ndal përsëri në kodrat e Inonysë dhe u detyrua të tërhiqej. Telegrami i Mustafa Kemal Pashës drejtuar Ismet Pashës, 'Ju atje nuk mundët vetëm armikun, por edhe fatin e mbrapshtë të kombit', u shkrua pas kësaj fitoreje. Beteja e ngriti prestigjin ndërkombëtar të Luftës Kombëtare dhe e përshpejtoi procesin e tërheqjes së Italisë nga Anadolli.", "639e964d"]},
"OLAYLAR_EK5:1921-10-20:0":{"b": ["Marrëveshja e Ankarasë: paqja me Francën dhe mbyllja e frontit jugor", "35fc32db"], "d": ["Me marrëveshjen e nënshkruar në Ankara me Francën pas fitores së Sakarjas përfundoi lufta në frontin jugor; forcat franceze boshatisën Çukurovën dhe Juglindjen, përfshirë Adanën, Antepin, Marashin dhe Urfën, dhe u tërhoqën në kufirin sirian. Kështu njëri prej shteteve të Antantës e njohu faktikisht qeverinë e Ankarasë dhe u hap e çara e parë në frontin e Sevrit. Armët e marra nga zonat e boshatisura dhe njësitë e liruara luajtën rol kritik në përgatitjen e Ofensivës së Madhe.", "7e088769"]},
"OLAYLAR_EK5:1922-10-11:0":{"b": ["Armëpushimi i Mudanjas: dorëzimi pa luftë i Stambollit dhe ngushticave", "ac0d9baf"], "d": ["Pasi pas Ofensivës së Madhe ushtria turke u përball me forcat angleze në Çanakkale dhe Izmit, konferenca e mbledhur në Mudanja, pas njëmbëdhjetë ditësh pazaresh të ashpra, përfundoi me armëpushim. U pranua që Trakia Lindore deri në lumin Marica të boshatisej nga Greqia brenda pesëmbëdhjetë ditëve dhe t'i dorëzohej administratës turke, e po ashtu që Stambolli dhe ngushticat të dorëzoheshin me traktatin e paqes. Kështu faza e armatosur e Luftës Kombëtare u mbyll me një fitore diplomatike të arritur pa u shtënë asnjë plumb dhe u hap dera e Lozanës.", "79b94dfb"]},
"OLAYLAR_EK5:1922-11-17:0":{"b": ["Largimi i Mehmetit VI Vahideddin nga Stambolli dhe zgjedhja e Abdylmexhid Efendiut halif", "8ab0e847"], "d": ["Padishahu i fundit, Mehmeti VI Vahideddin, pozita e të cilit u bë e diskutueshme pas shfuqizimit të sulltanatit, mëngjesin e së premtes më 17 nëntor 1922 u largua nga Stambolli me luftanijen angleze Malaya dhe shkoi në Maltë. Asambleja e Madhe Kombëtare Turke, dy ditë më vonë, më 19 nëntor, zgjodhi Abdylmexhid Efendiun si halif pa kompetenca politike. Kështu mori fund faktikisht sundimi gjashtëqind e njëzet e trevjeçar i dinastisë osmane; ndërsa hilafeti do të vazhdonte simbolikisht edhe pesëmbëdhjetë muaj. Vahideddini, që kaloi në Maltë e pastaj në Itali, u vendos në Villa Nobel në San Remo; nuk mori rezultat nga kërkesat që bëri për t'u pranuar në një vend mysliman dhe vdiq atje më 16 maj 1926, duke përsëritur se kurrë nuk kishte hequr dorë nga të drejtat e sulltanatit dhe hilafetit.", "86831a04"]},
"OLAYLAR_EK5:1926-05-16:0":{"b": ["Vdekja në San Remo e padishahut të fundit, Mehmetit VI Vahideddin", "7149ed0e"], "d": ["Padishahu i fundit osman, Mehmed Vahideddini, që pas largimit nga Stambolli u vendos në qytetin italian San Remo, vdiq më 16 maj 1926, pa marrë lajmin se ishte mbledhur kongresi i hilafetit (13 maj 1926), të cilit i kishte njoftuar se kurrë nuk kishte hequr dorë nga të drejtat e sulltanatit dhe hilafetit. Ishte në vështirësi të rënda financiare; u kishte borxh 60.000 lireta tregtarëve të San Remos dhe kreditorët, kur mësuan për vdekjen, vunë sekuestro mbi sendet e shtëpisë së tij.", "0864312a"]},
"OLAYLAR_EK6:1325-01-01:0":{"b": ["Konuralpi pushton viset e Bolusë — Mudurnu, Konurapa dhe Bolu", "e245cd27"], "d": ["Konuralpi, një nga komandantët e Orhan Gaziut, duke u drejtuar nga zona malore në lindje të Sakarjas, ia lidhi administrimit osman viset e Mudurnusë, Konurapës dhe Bolusë; qyteza në fushën e Dyzxhes u quajt me emrin e tij. Data e saktë e pushtimit nuk dihet; rrëfimi mbështetet në tregimin e Ashikpashazades. Rajoni atëherë ishte një zonë kufitare që ndërronte duar mes Xhandarogullëve dhe Bizantit; pushtimi i afroi osmanët për herë të parë me bregun perëndimor të Detit të Zi. Pas Betejës së Ankarasë viset do të kalonin përsëri te Xhandarogullët, por në kohën e Fatihut do të rimerreshin përfundimisht.", "d7b58190"]},
"OLAYLAR_EK6:1334-01-01:0":{"b": ["Marrja e qytezave bizantine në jug të Marmarasë — Mihaliçi, Kirmasti, Gölyazı", "9c61b8d4"], "d": ["Pas marrjes së Nikeas dhe Nikomedisë, qytezat që i kishin mbetur Bizantit në perëndim të fushës së Bursës hynë njëra pas tjetrës nën administrimin osman. Gölyazı rreth liqenit të Uluabatit, Kirmasti dhe Mihaliçi përgjatë lumit Susurluk plotësuan korridorin që lidhte bregun jugor të Marmarasë me tokat e Karesit. Këto qyteza për një kohë të gjatë nuk panë rrethim, por u dorëzuan me prerjen e rrethinave; kështu prania bizantine në rajon u ngjesh në gjirin e Gemlikut.", "bd729343"]},
"OLAYLAR_EK6:1395-01-01:0":{"b": ["Korinti kaloi te Despotati i Moresë", "392495eb"], "d": ["Korinti, që prej vitit 1358 ishte feud i principatës së Akesë të familjes fiorentine Acciajuoli, më 1395 kaloi në duart e despotit bizantin të Moresë, Teodorit. Pas kësaj qyteti mbeti nën administrimin e despotatit deri në pushtimin osman.", "1803a03a"]},
"OLAYLAR_EK6:1427-06-01:0":{"b": ["Aneksimi i bejllëkut të Haxhiemirogullëve — Ordu dhe Ünye", "c064f07f"], "d": ["Bejllëku turkmen, që Bajram Beu themeloi rreth Ordusë dhe i biri, Haxhi Emiri, e zgjeroi në vitet 1350, ishte një shtet bregdetar i vogël, por strategjik, me qendër në Eskipazarin e sotëm: ishte e vetmja zonë sundimi e pavarur mes Samsunit dhe Trapezundit. Emir Sulejmani më 1398 i shprehu besnikërinë Bajazitit Rrufe gjatë operacionit të Xhanikut; pas Betejës së Ankarasë bejllëku u lirua përsëri. Në kohën e Muratit II, në të njëjtat vite me likuidimin e Taxhedinogullëve, tokat e bejllëkut iu lidhën drejtpërdrejt administrimit osman dhe bregu i Detit të Zi nga Samsuni deri në Giresun u bashkua në një dorë.", "d5caa358"]},
"OLAYLAR_EK6:1458-08-06:0":{"b": ["Pushtimi i Korintit", "87a2bc59"], "d": ["Në fushatën e Moresë të Fatihut, kështjella e Akrokorintit u rrethua për tre muaj dhe në fund u mor në dorëzim me rrugë paqësore. Kështu istmi i Korintit, i konsideruar porta e Moresë, kaloi te osmanët.", "b2be3a05"]},
"OLAYLAR_EK6:1499-01-01:0":{"b": ["Lidhja e Malit të Zi me administrimin osman — Cetinja", "7fdb7cc8"], "d": ["Kur dinastia Crnojević, që drejtonte Zetën, më 1496 hoqi dorë nga sundimi, zona malore e Malit të Zi, oborri i prapmë i Shkodrës, u mor drejtpërdrejt nën administrimin osman dhe u organizua fillimisht si sanxhak më vete, pastaj si pjesë e sanxhakut të Shkodrës. Manastiri i Cetinjës u la në vend si qendra fetare e rajonit. Për shkak të ashpërsisë së gjeografisë, administrimi këtu nuk funksionoi kurrë aq rreptë sa në fusha; dy shekuj më vonë, sundimi i vladikës që lindi nga po ky manastir do të bëhej bërthama e pavarësisë faktike.", "e8356eb2"]},
"OLAYLAR_EK6:1534-06-23:0":{"b": ["Pranimi i sundimit osman nga kështjella e Bajazitit gjatë Fushatës së Irakejnit", "f29e2e17"], "d": ["Kur veziri i madh Ibrahim Pasha gjatë Fushatës së Irakejnit arriti në rrethinat e Bingölit, bashkë me shumë fise kurde të rajonit, kështjellat e Vanit, Toprakkalesë, Avnikut dhe Bajazitit pranuan të hynin nën sundimin osman. Bajaziti ishte bashkuar me osmanët më 1514 gjatë fushatës së Javuzit, por kur ushtria u kthye, safavidët e rimorën rajonin.", "14640206"]},
"OLAYLAR_EK6:1535-06-01:0":{"b": ["Kalimi i Tabrizit përsëri te safavidët — kthimi nga Irakejni", "80b8b761"], "d": ["Në Fushatën e Irakejnit ushtria hyri në Tabriz, por meqë objektivi kryesor ishte Bagdadi, në qytet nuk u la garnizon i përhershëm. Ndërsa ushtria që e kaloi dimrin në Bagdad kthehej drejt perëndimit, Shah Tahmaspi hyri përsëri në Azerbajxhanin e boshatisur dhe e rimori Tabrizin. Ky ishte modeli i përsëritur i luftërave osmano-safavide: Tabrizi u mor pesë herë dhe të pesë herët nuk mundi të mbahej; qyteti do të kishte një garnizon osman afatgjatë vetëm më 1585.", "f60ea64f"]},
"OLAYLAR_EK6:1535-09-22:0":{"b": ["Rënia e Vanit dhe Erxhishit në duart e Tahmaspit (qëndrimi osman mori fund më 1534-35)", "cb93d561"], "d": ["Në rajonin që më 1534 ia kaloi Vanin sundimit osman, Ulama Pasha rezistoi në kështjellën e Vanit ndaj rrethimit safavid; kështjella ra në duart e safavidëve, kurse forcat safavide që rrethonin Erxhishin ishin tërhequr me ndihmën osmane. Kur Sulejmani Ligjvënës arriti në Ahlat (23 shtator 1535), Vani ishte tashmë në duart e Tahmaspit. Vani mbeti safavid deri më 1548.", "eb576b34"]},
"OLAYLAR_EK6:1547-01-01:0":{"b": ["Kalimi i sanxhakut të Bajazitit nën sundimin safavid (Vani dhe Erxhishi ishin safavidë qysh më 1535)", "806a2cf1"], "d": ["Sanxhaku i Bajazitit, në mes të kufirit osmano-safavid, kaloi përsëri në duart e Iranit (Kaya 2017 e përmend këtë si 'bashkë me Vanin dhe Erxhishin'; por sipas Karataş 2025 dhe TDV, Vani dhe Erxhishi u ishin kthyer safavidëve më 22 shtator 1535 — shih zërin e mëparshëm); në këtë ndërrim dore disa vende të sanxhakut u rrënuan. Sanxhaku deri në çerekun e fundit të shekullit XVI ndërroi shumë herë duar mes dy shteteve.", "28cb6e07"]},
"OLAYLAR_EK6:1553-08-01:0":{"b": ["Kalimi i sanxhakut të Bajazitit përsëri te osmanët gjatë Fushatës së Nahiçevanit", "cf0171fa"], "d": ["Gjatë fushatës së tretë iraniane (të Nahiçevanit) të Sulejmanit Ligjvënës, sanxhaku i Bajazitit u mor përsëri nën administrimin osman. Në fushatën e vitit 1554 Bajaziti u bë bazë e rëndësishme për ushtrinë; sanxhaku hyri përfundimisht nën sundimin osman më 1578.", "a6c619eb"]},
"OLAYLAR_EK6:1604-06-08:0":{"b": ["Humbja e Jerevanit nga Shah Abasi", "34413cf2"], "d": ["Kur në vitet kur kryengritjet xhelali bllokonin Anadollin fronti lindor mbeti i pambrojtur, Shah Abasi, që e kishte riorganizuar ushtrinë sipas mënyrës evropiane, kaloi në ofensivë. Kështjella e Jerevanit, që Ferhat Pasha e kishte urdhëruar të ndërtohej më 1583, u dorëzua pas një rrethimi shtatëmujor. U këput hallka e parë e vijës së Kaukazit të fituar me Traktatin e Ferhat Pashës; brenda tre vjetëve pasues do të humbiste i gjithë Kaukazi Jugor.", "b5f54d9c"]},
"OLAYLAR_EK6:1606-01-01:0":{"b": ["Humbja e Tiflisit dhe Gjanxhës", "3fb51753"], "d": ["Pas rënies së Jerevanit, ushtria safavide përparoi përgjatë luginës së Kurës; Gjanxha, qendra e Karabakut, dhe Tiflisi, kryeqyteti i Gjeorgjisë, humbën njëri pas tjetrit. Shteti Osman në të njëjtën kohë zhvillonte në frontin austriak luftën e gjatë trembëdhjetëvjeçare dhe në Anadoll merrej me xhelalinjtë; nuk kishte forcë për t'u dërguar në lindje. Kështu rendi i ejaleteve të gjera kaukaziane, i ngritur me Traktatin e Ferhat Pashës të vitit 1590, mori fund faktikisht.", "c80d75b7"]},
"OLAYLAR_EK6:1607-01-01:0":{"b": ["Humbja e Shirvanit — Shamahia, Bakuja dhe Derbendi", "81beab11"], "d": ["Ejaleti i Shirvanit në bregun e Kaspikut ishte fituar me fushatat e Ozdemiroglu Osman Pashës të viteve 1578-1585 dhe, si burim kryesor i tregtisë së mëndafshit, u siguronte financave osmane të ardhura të rëndësishme. Operacioni i Shah Abasit i drejtuar nga veriu, duke marrë njëra pas tjetrës Shamahinë, Bakunë dhe Derbendin, e likuidoi këtë ejalet. Humbja nuk ishte vetëm tokë: edhe rruga nëpër të cilën mëndafshi iranian shkonte përmes osmanëve në Evropë doli nga kontrolli dhe shteti safavid filloi ta tregtonte mëndafshin përmes Oqeanit Indian.", "f85d7f97"]},
"OLAYLAR_EK6:1629-01-01:0":{"b": ["Humbja e Taizit", "65f20d53"], "d": ["Osmanët në vitin 1038 (1629), bashkë me sundimin e Jemenit që iu la administratës kasimite në Sana, braktisën edhe Taizin — hapi i parë i madh i procesit me të cilin imamët zejditë rimorën Jemenin e brendshëm.", "72344627"]},
"OLAYLAR_EK6:1635-01-01:0":{"b": ["Humbja e Jemenit — sundimi i imamëve kasimitë", "49e83e3c"], "d": ["Jemeni nga viti 1538 ishte ejalet osman; por rezistenca e imamëve zejditë nuk u ndal kurrë. Kryengritja e nisur nga imam Kasimi në kohën e të birit, el-Muejjed Muhammed, u përhap në gjithë vendin dhe garnizonet osmane u rrethuan me radhë. Në vitet kur Murati IV përqendrohej te Bagdadi dhe Jerevani nuk mundën të dërgoheshin përforcime; Taizi kishte humbur më 1629, kurse Moka ishte evakuuar më 22 tetor 1635 në fazën e fundit të së njëjtës shembje. Më 1635 edhe njësitë e fundit në Sana dhe Zebid e evakuuan Jemenin. Kështu bregu lindor i Detit të Kuq për dyqind e tridhjetë e shtatë vjet mbeti jashtë perandorisë dhe mundi të rimerrej vetëm më 1872. Lahixhi (el-Havta), sipas Enciklopedisë së Islamit të TDV-së, deri më 1635 ishte në duart e osmanëve; që nga ajo datë ndikimin e patën imamët zejditë.", "e966b559"]},
"OLAYLAR_EK6:1635-10-22:0":{"b": ["Evakuimi i Mokës", "c6b3061a"], "d": ["Mustafa Beu, më 10 xhumadelula 1045 (22 tetor 1635), e evakuoi Mokën me forcat dhe armët e mbetura; pastaj Hasan b. Kasimi, i biri i imam Kasimit, emëroi në Zebid dhe Mokë njerëzit e vet dhe vendosi kontrollin kasimit edhe në bregdetin e Tihames.", "04e81711"]},
"OLAYLAR_EK6:1670-01-01:0":{"b": ["Humbja e Lahsës nga Emirati i Beni Halidit", "a9b6131a"], "d": ["Lahsa ishte një ejalet i krijuar më 1550 për t'ia mbyllur Portugalisë bregun perëndimor të Gjirit të Basrës; por ishte shumë larg Stambollit, në fund të një rruge të vetme shkretëtire. Në vitet kur rrethimi i Kretës po shteronte burimet, fisi Beni Halid i rajonit, nën udhëheqjen e Berrak b. Gurejrit, e dëboi garnizonin osman dhe themeloi emiratin e vet. Bregu perëndimor i gjirit mbeti për një shekull e gjysmë në emiratet fisnore; më 1795 do të kalonte te saudët dhe më 1871 përsëri te osmanët.", "f3749775"]},
"OLAYLAR_EK6:1684-09-29:0":{"b": ["Humbja e Prevezës dhe Vonitsës nga Venediku — hapja e bregdetit të Epirit", "1201204c"], "d": ["Venediku, që iu bashkua Lidhjes së Shenjtë, para se të niste fushatën e Moresë mori dy kështjellat që zotëronin grykën e gjirit të Ambrakisë: Prevezën dhe Vonitsën në bregun përballë. Po atë verë kishte rënë edhe Ajamavra (Lefkada). Këto tri pozicione i mundësuan flotës të depërtonte me siguri nga Deti Jon në brendësi të Greqisë dhe u bënë bazë e operacionit të Moresë që do të fillonte vitin pasues. Preveza dhe Vonitsa edhe në Pasarofçë iu lanë Venedikut; nën administrimin osman do të ktheheshin vetëm më 1798.", "1de80a4b"]},
"OLAYLAR_EK6:1685-10-12:0":{"b": ["Humbja e Szolnokut — shpërbërja e vijës së Tisës", "51c2c8ef"], "d": ["Pas rënies së Ujvarit në gusht, ushtria habsburge u kthye drejt jugut dhe mori Szolnokun, kryeurën mbi lumin Tisa. Qyteti ishte i vetmi kalim i sigurt mes Budinit dhe Transilvanisë; humbja e tij do të thoshte se kështjellat osmane në gjysmën lindore të Hungarisë këputeshin nga njëra-tjetra. Vitin pasues, prerja e rrugës së furnizimit u bë vendimtare gjatë rrethimit të Budinit.", "a0595e94"]},
"OLAYLAR_EK6:1686-07-10:0":{"b": ["Humbja e Modonit nga Venediku", "114c9cc0"], "d": ["Modoni, në skajin jugperëndimor të gadishullit të Moresë, ishte porti që Venediku e kishte humbur tri shekuj më parë dhe e quante 'njëri nga dy sytë e shtetit'. Kështjella, e rrethuar pas rënies së Koronit, u mor në dorëzim pasi u godit njëkohësisht nga toka dhe deti. Kështu operacioni i Morosinit në More shtiu në dorë gjithë bregun perëndimor të gadishullit dhe u hap rruga drejt brendësisë.", "df990436"]},
"OLAYLAR_EK6:1686-10-20:0":{"b": ["Humbja e Pecsit", "99d54cf4"], "d": ["Pas rënies së Budinit në shtator, forcat habsburge zbritën drejt jugut në perëndim të Danubit dhe morën Pecsin, osman që nga koha e Sulejmanit Ligjvënës. Qyteti, i njohur për xhaminë e Gazi Kasim Pashës, ishte një nga qendrat më të zhvilluara të sanxhakëve të ejaletit të Budinit. Humbja e tij do të thoshte hapjen e rrugës që zbriste në fushën e Mohaçit; vitin pasues disfata e Mohaçit të Dytë do të ndodhte pikërisht këtu.", "10e39af1"]},
"OLAYLAR_EK6:1686-10-23:0":{"b": ["Humbja e Szegedit", "9fbee1b2"], "d": ["Szegedi, në pikën ku bashkohen lumenjtë Tisa dhe Maros, ishte porta jugore e fushës hungareze dhe zotëronte rrugën për në ejaletin e Temeshvarit. Kështjella, e rrethuar pas rënies së Budinit dhe Pecsit në të njëjtën vjeshtë, u dorëzua pas pak kohe. Humbja e tri kështjellave brenda një stine ishte shenja se struktura administrative osmane në Hungari, e ngritur që nga viti 1541, kishte filluar të shembej. Atlasi e konsideron se edhe Zenta përgjatë Tisës kalon po atë ditë nga ana osmane në atë habsburge (dita e veçantë e dorëzimit të Zentës nuk u lexua në burim, dita u mor nga Szegedi; TDV zenta: nga tetori 1686 filluan përleshjet mes osmanëve dhe aleatëve nën udhëheqjen habsburge — përafrim i deklaruar).", "2450ee08"]},
"OLAYLAR_EK6:1687-08-01:0":{"b": ["Humbja e Patrës (Balyabadra) — porta veriore e Moresë", "b9cff63c"], "d": ["Patra, në grykën e gjirit të Korintit, ishte porti që kontrollonte kalimin mes Moresë dhe Rumelisë. Pasi ushtria venedikase mori qytetin, edhe kështjellat në të dy brigjet e gjirit ranë njëra pas tjetrës dhe gadishulli u izolua tërësisht nga toka. Në fund të këtij operacioni e gjithë Morea kaloi te Venediku; rajoni deri më 1715 do të drejtohej me emrin 'Regno di Morea'.", "3b3ca389"]},
"OLAYLAR_EK6:1687-08-01:1":{"b": ["Lënia e Korintit Venedikut", "9a25b6b9"], "d": ["Pas rënies së Patrës, Korinti iu la venedikasve me rrugë paqësore dhe popullsia myslimane e braktisi qytetin. Në gusht 1687 ushtria e Morosinit po grumbullohej në Korint për fushatën e Athinës.", "d92bcf7d"]},
"OLAYLAR_EK6:1687-12-17:0":{"b": ["Humbja e Egerit", "983391aa"], "d": ["Egeri ishte marrë më 1596 me fushatën në të cilën mori pjesë personalisht Mehmeti III dhe ishte bërë qendra e një ejaleti me emrin e vet. Kjo kështjellë e fundit e madhe osmane në Hungarinë Veriore, e rrethuar tërësisht pas disfatës së Mohaçit të Dytë, rezistoi një vit dhe u dorëzua për shkak të urisë. Me humbjen e saj, krahu verior i Shtetit Osman në Hungari u likuidua tërësisht.", "ced01ee7"]},
"OLAYLAR_EK6:1688-05-19:0":{"b": ["Humbja e Székesfehérvárit (İstolni Belgrad) — qyteti i kurorëzimit të mbretërve hungarezë", "c6147255"], "d": ["Qyteti ku mbretërit hungarezë për shekuj me radhë kurorëzoheshin dhe varroseshin ishte marrë më 1543 nga Sulejmani Ligjvënës dhe ishte bërë një nga qendrat më të rëndësishme të sanxhakëve të ejaletit të Budinit. Rreth dy vjet pas rënies së Budinit, kështjella, rrethinat e së cilës ishin prerë plotësisht, u dorëzua. Me këtë humbje, prania osmane në perëndim të Danubit u ngjesh në rrethinat e Sremit dhe Osijekut.", "245ff91b"]},
"OLAYLAR_EK6:1689-02-03:0":{"b": ["Humbja e Sigetit", "834910a7"], "d": ["Sigeti ishte kështjella ku Sulltan Sulejman Kanuniu, në fushatën e tij të trembëdhjetë dhe të fundit, vdiq më 1566 ndërsa vazhdonte rrethimi; prandaj kishte një vend simbolik në kujtesën osmane. Njëqind e njëzet e tre vjet më pas, pasi ranë të gjitha kështjellat përreth, u dorëzua edhe kështjella e mbrojtur nga moçalet. Tyrbeja ku ishin varrosur organet e brendshme të Kanuniut dhe qyteza përreth saj u shembën pasi kaluan nën administrimin habsburg. Vendbanimi tjetër që në atlas kalon po atë datë nga osmanët te habsburgët: Barcsi — ndjek zinxhirin e qendrës mëmë të Sigetit (Bánlaky 0017/1449; përafrim i deklaruar).", "12bc4465"]},
"OLAYLAR_EK6:1692-06-05:0":{"b": ["Humbja e Varadit", "6cce360d"], "d": ["Varadi ishte kështjella kyçe që hapej drejt Transilvanisë, të cilën Mehmet Pashë Qyprilliu e mori më 1660 dhe e bëri qendër të një ejaleti me emrin e vet. Kështjella, e mbetur krejt e vetme pas disfatës së Slankamenit, pas një bllokade që zgjati gati dy vjet u dorëzua nga uria. Me humbjen e saj, ndikimi osman mbi Transilvaninë mori fund faktikisht dhe sundimi habsburg u vendos në lindje të Tisës.", "72d9fcc0"]},
"OLAYLAR_EK6:1693-05-27:0":{"b": ["Humbja e Janovës — mbyllja e rrugës së Transilvanisë", "4b5e30d8"], "d": ["Janova ishte një kështjellë e marrë më 1658 që mbante lidhjen mes Varadit dhe Temeshvarit. Menjëherë pas rënies së Varadit, kur iu prenë rrethinat, edhe ajo doli nga dora. Kështu ejaleti i Temeshvarit u izolua tërësisht nga veriu dhe vazhdoi të ekzistonte si e vetmja tokë hungareze që mbeti në duart osmane deri në Karllofçë.", "67168a2e"]},
"OLAYLAR_EK6:1697-01-01:0":{"b": ["Vendosja e sundimit të vladikës në Mal të Zi — shkëputja faktike e Cetinjës", "a924b778"], "d": ["Në vitet kur Lufta e Lidhjes së Shenjtë e lironte kontrollin osman në Ballkan, mitropolia në krye të manastirit të Cetinjës u bë në familjen Petroviq një post që kalonte nga babai te i biri dhe rajoni faktikisht fitoi një administrim më vete. Falë paarritshmërisë së maleve, ky vladikat për dy shekuj vazhdoi të ekzistonte në një pozitë as krejt të pavarur, as krejt të lidhur; juridikisht pavarësia do t'i njihej vetëm me Traktatin e Berlinit të vitit 1878.", "104e26b1"]},
"OLAYLAR_EK6:1715-06-01:0":{"b": ["Rimarrja e Korintit", "26f53e3a"], "d": ["Ndalesa e parë e madhe e fushatës së Moresë të Damad Ali Pashës ishte Korinti; osmanët në qershor 1715 ua rimorën qytetin venedikasve dhe prej këtej përparuan drejt pjesës tjetër të gadishullit.", "82e2e719"]},
"OLAYLAR_EK6:1730-08-12:0":{"b": ["Ofensiva e Nadirit: humbja e Tabrizit, Nahiçevanit, Hamadanit, Kermanshahut, Maragës dhe Kasr-i Shirinit", "d95efd59"], "d": ["Qytetet e Iranit Perëndimor, të marra në vitet 1723-1727 duke përfituar nga shembja e shtetit safavid, dolën nga dora njëri pas tjetrit me ofensivën e Nadir Hanit, që kishte shtënë faktikisht në dorë pushtetin në Iran. Në Azerbajxhan, edhe Ardebili dhe Halhali kaluan në duart e Nadirit. Humbja e Hamadanit, Kermanshahut dhe Kasr-i Shirinit pati jehonë të rëndë në Stamboll; fakti që ushtria nuk doli në fushatë, por priti në Yskydar, dhe përpjekja për ta mbuluar humbjen u bënë një nga shkaqet e drejtpërdrejta të kryengritjes së Patrona Halilit, që shpërtheu gjashtë javë më vonë. Atlasi e konsideron se edhe Koturi, që ndjek zinxhirin e Hoit, kalon po atë ditë nga osmanët te safavidët (Uluerler 2015, Turkish Studies 10/5, f. 6; për Koturin nuk ka ditë të veçantë në burim — përafrim i deklaruar).", "412bd324"]},
"OLAYLAR_EK6:1735-06-19:0":{"b": ["Disfata e Baghavardit (Arpaçajit) — humbja e Kaukazit nga Nadir Hani", "4262f54c"], "d": ["Ejaletet e Kaukazit, të marra në vitet 1723-1725 duke përfituar nga shembja e shtetit safavid, mundën të mbaheshin dhjetë vjet. Nadir Hani, që shtiu faktikisht në dorë pushtetin në Iran, në Baghavard pranë Jerevanit i shkaktoi ushtrisë osmane një disfatë të rëndë; serdari Abdullah Pashë Qyprilliu humbi jetën në fushën e betejës. Pas disfatës, Jerevani, Tiflisi, Gjanxha dhe Shirvani u boshatisën brenda pak muajsh. Kufiri lindor u kthye në vijën e Kasr-i Shirinit të vitit 1639, siç do të konfirmohej më 1746.", "f123b2d9"]},
"OLAYLAR_EK6:1770-09-27:0":{"b": ["Humbja e Benderit nga rusët", "0daca453"], "d": ["Pas disfatës së fushës së Kagulit, ushtria osmane ishte tërhequr në jug të Danubit dhe kështjellat mes Moldavisë dhe Ozit kishin mbetur të vetme. Benderi, që zotëronte vendkalimin e lumit Dnjestër, u mor me sulm pas një rrethimi dymujor; qyteti u plaçkit. Humbja e kështjellës e këputi hallkën e mesme të vijës mbrojtëse të Detit të Zi Verior dhe pas saj ranë edhe Akermani e Kilia. Në Kyçyk-Kajnarxhë Benderi do të kthehej, por më 1806 do të humbiste edhe një herë.", "483d1fad"]},
"OLAYLAR_EK6:1795-04-01:0":{"b": ["Hyrja e emiratit Sabah në Kuvajt nën mbrojtjen osmane", "3584dba0"], "d": ["Sipas zërit 'Kuvajt' të TDV-së, skelën e kishte ngritur në fillim të shekullit XVIII fisi Utub i ardhur nga Nexhdi, kurse familja Sabah e kishte marrë administrimin nga fundi i shekullit. Në të njëjtat vite kur Lahsa kaloi në duart e saudëve, emirati, të cilit përballë trysnisë vehabite nuk i mbeti zgjidhje tjetër veçse të mbështetej te Basra, hyri nën mbrojtjen osmane. Lidhja do të zyrtarizohej më 1871 me rregullimin e Midhat Pashës për Basrën dhe Kuvajti do të konsiderohej një nga tri kazatë e sanxhakut të Basrës; edhe pretendimi i mëvonshëm territorial i Irakut mbështetet në këtë shënim.", "c084f05f"]},
"OLAYLAR_EK6:1806-01-01:0":{"b": ["Humbja e Mekës nga vehabitët", "2da23acd"], "d": ["Lëvizja vehabite, e lindur në Nexhd, në kohën e Suud b. Abdulazizit u drejtua nga Hixhazi; pas Taifit dhe Medinës u mor për herë të dytë edhe Meka — emiri i Mekës, Sherif Galibi, ua dorëzoi qytetin vehabitëve me kushtin që të mbetej në emirat. Tyrbet u shembën dhe u pre rruga e karvaneve të haxhit që vinin nga Damasku dhe Kajroja; edhe surreja që padishahu dërgonte çdo vit në Haremejn u ndërpre në këto vite — e vetmja përjashtim i kësaj ndarjeje, që vazhdoi pandërprerë deri më 1915, është periudha e sundimit vehabit. Meqë cilësia e mbrojtësit të dy vendeve të shenjta ishte një nga shtyllat themelore të legjitimitetit të padishahut, kjo humbje, përtej humbjes së tokës, ishte një goditje e rëndë politike; rimarrja do të zgjaste shtatë vjet dhe do të bëhej e mundur me ushtrinë e Mehmet Ali Pashës së Kavallës.", "888df9e3"]},
"OLAYLAR_EK6:1806-05-27:0":{"b": ["Fundi i Republikës së Dubrovnikut — pushtimi francez", "f8e27bf1"], "d": ["Francezët, që me Traktatin e Campo Formios (1797) u vendosën në bregdetin dalmat, më 27 maj 1806 shtinë në dorë Dubrovnikun dhe i dhanë fund republikës së vogël të tregtarëve. Kështu mori fund statusi vartës tre shekuj e gjysmë i Dubrovnikut, që nga viti 1458, duke u paguar haraç osmanëve, kishte ruajtur autonominë dhe privilegjet tregtare; qyteti dhe ishulli Mljet i republikës kalojnë në hartë nën administrimin e drejtpërdrejtë francez.", "720631c0"]},
"OLAYLAR_EK6:1810-07-11:0":{"b": ["Humbja e Suhumit nga rusët — hapja e bregdetit të Detit të Zi Lindor", "adc96bd4"], "d": ["Në luftën osmano-ruse të viteve 1806-1812, flota ruse u drejtua nga bregu i Detit të Zi Lindor dhe mori kështjellën e Suhumit (Sohumkale), mbi të cilën mbështetej sundimi osman në Abhazi. Kështjella ishte qendra e lidhjes me fiset kaukaziane dhe e tregtisë bregdetare. Me humbjen e saj, Rusia për herë të parë u vendos përgjithmonë në bregun lindor të Detit të Zi; ndikimi osman në Kaukaz u ngjesh në rrethinat e Anapës dhe Potit.", "77af92b7"]},
"OLAYLAR_EK6:1819-05-10:0":{"b": ["Lënia e Pargës nën administrimin osman", "66e0cc5d"], "d": ["Parga që nga viti 1401 ishte në duart e Venedikut dhe nuk kishte hyrë kurrë nën administrimin osman; pas shembjes së Venedikut kaloi me radhë te Franca dhe Anglia. Zëri 'Ali Pashë Tepelena' i TDV-së e përmbledh gjendjen kështu: qyteti iu dorëzua anglezëve dhe nën administrimin e Ali Pashës u lëshua vetëm më 1819. Dorëzimi përfundoi me emigrimin e pjesës më të madhe të popullsisë në ishujt e Jonit. Kështu edhe e fundit nga treshja Prevezë-Pargë-Vonitsa, e lënë Venedikut në Pasarofçë, iu bashkua perandorisë; Parga do të mbetej osmane nëntëdhjetë e katër vjet.", "555a1119"]},
"OLAYLAR_EK6:1821-01-01:0":{"b": ["Kalimi i Argosit në duart e kryengritësve grekë", "be66a696"], "d": ["Në muajt e parë të kryengritjes së Moresë, Argosi dhe rrethinat dolën nga administrimi osman dhe kaluan në duart e kryengritësve grekë; qyteti në maj 1821 do të bëhej skenë e kundërofensivës së forcave osmane.", "c3ea2041"]},
"OLAYLAR_EK6:1821-05-05:0":{"b": ["Ahmet Qehaja mori Argosin, qyteti u plaçkit dhe u dogj", "d6d3ac7b"], "d": ["Forcat e Ahmet Qehajait i mundën grekët në Argos, e plaçkitën dhe e dogjën qytetin; qyteti për pak kohë u kthye nën kontrollin osman.", "316a51a8"]},
"OLAYLAR_EK6:1821-05-15:0":{"b": ["Ahmet Qehaja u bashkua në Argos me myslimanët e Tripolicës dhe marshoi drejt Tripolicës", "9d679fd5"], "d": ["Ahmet Qehaja, duke u bashkuar në Argos me myslimanët e Tripolicës, marshoi drejt Tripolicës; Argosi kaloi përsëri nën kontrollin e kryengritësve grekë.", "596502da"]},
"OLAYLAR_EK6:1822-01-01:0":{"b": ["Kalimi i Korintit te kryengritësit grekë", "892dcdc6"], "d": ["Gjatë luftës së pavarësisë greke, Akrokorinti kaloi në duart e kryengritësve dhe komandanti i kështjellës, Kamil Beu, u zu rob.", "a7cb2c26"]},
"OLAYLAR_EK6:1822-07-24:0":{"b": ["Dramalë Mahmud Pasha e vendosi shtabin në Argos", "c79abbfb"], "d": ["Ushtria e Dramalë Mahmud Pashës hyri në fushën e Argosit dhe pashai e vendosi shtabin në qytezën e Argosit; qyteti kaloi përsëri nën kontrollin osman.", "d931b635"]},
"OLAYLAR_EK6:1822-08-06:0":{"b": ["Dramalë Mahmud Pasha filloi të tërhiqej nga Argosi", "5e5afb74"], "d": ["Dramalë Mahmud Pasha, i detyruar të tërhiqej para se të mbusheshin dy javë nga pushtimi i Argosit, filloi të tërhiqte divizionin e parë të ushtrisë drejt Korintit; Argosi kaloi përsëri në duart e kryengritësve grekë.", "9c49ab0c"]},
"OLAYLAR_EK6:1822-12-12:0":{"b": ["Humbja e Nauplias (Anabolu) nga kryengritësit", "1a67fa50"], "d": ["Nauplia, porti me fortifikimet më të forta në More, pas një bllokade që zgjati mbi një vit u dorëzua nga uria. Kështjella ishte që nga fillimi i kryengritjes mbështetja e fundit e madhe e kontrollit osman në gadishull; me humbjen e saj e gjithë Morea kaloi në duart e kryengritësve. Qyteti pas pak kohe do të bëhej kryeqyteti i parë i shtetit të ri grek.", "f5a972d7"]},
"OLAYLAR_EK6:1829-04-30:0":{"b": ["Kalimi i Naupaktit (İnebahtı) nën administrimin grek", "c9d19d4b"], "d": ["Naupakti në bregun verior të gjirit të Korintit, që mbeti në duart osmane deri në kryengritjen greke, doli nga dora në prill 1829 dhe hyri nën administrimin grek; emri i qytezës u kthye në Navpaktos, si në lashtësi. Popullsia myslimane dhe hebraike e qytetit u zhduk plotësisht dhe vendi u shndërrua në një qytezë të vogël.", "b354fb47"]},
"OLAYLAR_EK6:1830-07-05:0":{"b": ["Pushtimi francez i Algjerisë — fundi i odxhakut treqindvjeçar", "0be8f568"], "d": ["Duke marrë si pretekst ngjarjen e freskores, të lindur nga një mosmarrëveshje për një borxh, Franca e mbajti bregun e Algjerisë nën bllokadë për tre vjet, pastaj zbarkoi ushtarë në Sidi Ferruxh. Në fund të operacionit trejavor, Husein Dajiu u dorëzua dhe Odxhaku osman i Algjerisë, që vazhdonte nga viti 1516, mori fund. Pushtimi nuk u kufizua te kryeqyteti; edhe Tlemseni, Shershali dhe Medea në brendësi dolën nga dora po atë verë. Që i gjithë bregdeti të hynte nën kontrollin francez do të duheshin edhe njëzet e katër vjet.", "a19df96b"]},
"OLAYLAR_EK6:1831-01-01:0":{"b": ["Dhënia e Eubesë Greqisë — bashkë me ishullin (Karistos, Oreoi)", "7b524aa4"], "d": ["Eubea, që gjatë gjithë luftës së pavarësisë greke ishte skenë përleshjesh të dendura, por mbeti në duart osmane, pas hyrjes në fuqi të traktatit të paqes iu dha grekëve më 1831. Popullsia myslimane e qytetit, që që nga viti 1470 ishte bazë e rëndësishme detare, i shiti të gjitha pasuritë me çmime shumë të lira dhe emigroi masivisht në tokat osmane; qyteti për një kohë të gjatë mbeti bosh dhe udhëtari gjerman Fallmerayer më 1842 e cilësoi si qytet fantazmë.", "313e4745"]},
"OLAYLAR_EK6:1831-01-04:0":{"b": ["Pushtimi i Oranit (Vahran) nga francezët", "a8415d66"], "d": ["Orani, që Spanja e dorëzoi pa luftë më 1792, ishte porti më i madh në perëndim të Algjerisë. Gjashtë muaj pas rënies së kryeqytetit, njësitë franceze hynë në qytet. Operacioni perëndimor që nisi këtu pas pak kohe do të përballej me rezistencën pesëmbëdhjetëvjeçare të emirit Abdulkadir.", "e1913ae8"]},
"OLAYLAR_EK6:1832-03-01:0":{"b": ["Pushtimi i Annabasë (Bône)", "21f37fb1"], "d": ["Annaba, port i Algjerisë Lindore pranë kufirit tunizian, u mor nga forcat franceze dhe u bë bazë e marshimit drejt Konstantinës. Qyteti ishte njëkohësisht porti afrikan më i afërt përballë ishullit të Sardenjës.", "1ca5b213"]},
"OLAYLAR_EK6:1833-04-12:0":{"b": ["Lënia e Athinës shtetit të ri grek (dita kur njësitë bavareze e morën në dorëzim Akropolin)", "deee4d37"], "d": ["Athina, osmane që nga viti 1456, gjatë luftës së pavarësisë greke ndërroi disa herë duar dhe garnizoni në Akropol më 1827 kishte kaluar përsëri nën kontrollin osman. Meqë mbeti në veri të kufirit të vizatuar me Protokollin e Londrës, qyteti iu dorëzua mbretërisë së re dhe garnizoni e evakuoi Akropolin. Dita e atlasit është dita kur njësitë bavareze e morën në dorëzim Akropolin; dalja faktike e garnizonit osman u bë pak ditë më vonë (St Clair, Who Saved the Parthenon?, Open Book Publishers, 2022, kap. 13; Finlay, Journals and Letters, vëll. I, f. 67). Vitin pasues Athina u shpall kryeqytet i Greqisë në vend të Nauplias.", "378db620"]},
"OLAYLAR_EK6:1833-09-29:0":{"b": ["Pushtimi i Bexhajas (Bougie)", "a8927e00"], "d": ["Porti i Bexhajas, ku malet e Kabilisë hapen drejt detit, ishte hallka e fundit e pavarur e vijës bregdetare mes Algjerit dhe Annabasë. U mor me mbështetjen e artilerisë detare; por zona malore prapa tij nuk do të hynte nën kontrollin francez edhe tridhjetë vjet. Këto pushtime përgjatë bregdetit përbëjnë shkrirjen vit pas viti të Algjerisë osmane në hartë.", "af6938db"]},
"OLAYLAR_EK6:1838-10-13:0":{"b": ["Pushtimi i Setifit", "2073731a"], "d": ["Pas rënies së Konstantinës një vit më parë, forcat franceze dolën në rrafshnaltë, morën Setifin, qytet i vjetër romak, dhe ngritën aty një garnizon të përhershëm. Setifi ishte pika ku kryqëzoheshin rrugët e karvaneve mes bregdetit dhe Saharasë; pushtimi i tij tregoi se Franca nuk kontrollonte më vetëm portet, por edhe rrjetin e brendshëm tregtar.", "c20b8b14"]},
"OLAYLAR_EK6:1844-03-04:0":{"b": ["Pushtimi i Biskrës — humbja e portës së Saharasë", "d895cad0"], "d": ["Biskra, në rrëzë jugore të maleve Atlas, ishte porta që hapej drejt Saharasë dhe qendra e oazeve të hurmave. Me marrjen e saj në vitet kur filloi të thyhej rezistenca e emirit Abdulkadir, kontrolli francez për herë të parë arriti bregun verior të shkretëtirës. Pas kësaj do të vinte një operacion shkretëtire që përparonte oaz pas oazi.", "46486fff"]},
"OLAYLAR_EK6:1854-12-02:0":{"b": ["Pushtimi i Tugurtit — dalja e gjithë Algjerisë nga dora", "33c056e2"], "d": ["Me marrjen e Tugurtit, qytet oazi në veri të Saharasë, pushtimi i nisur më 1830 u plotësua në gjysmën veriore të Algjerisë së sotme. Shteti Osman në ato vite po luftonte në Luftën e Krimesë në të njëjtin krah me Francën; ndonëse kurrë nuk hoqi dorë zyrtarisht nga pretendimi juridik mbi Algjerinë, faktikisht nuk mundi të hidhte asnjë hap. Toka e vetme që i mbeti në Afrikën Veriore ishte Tripoli.", "0eaa89a0"]},
"OLAYLAR_EK6:1883-01-19:0":{"b": ["Rënia e el-Ubejdit — kalimi i Kordofanit te forcat e Mehdiut", "58299f62"], "d": ["Lëvizja e nisur nga Muhammed Ahmedi, që u shpall mehdi, u përhap shpejt kundër administrimit egjiptian në Sudan. El-Ubejdi, qendra e Kordofanit, ra pas një rrethimi katërmujor dhe u bë kryeqytet i kryengritjes; thesari dhe depot e armëve në qytet i mundësuan lëvizjes të bëhej ushtri. Sudani juridikisht ishte ende tokë e hedivllëkut të Egjiptit, të lidhur me osmanët, prandaj humbja në hartë zbritet nga trupi i perandorisë.", "200e1799"]},
"OLAYLAR_EK6:1885-01-26:0":{"b": ["Rënia e Hartumit — humbja e gjithë Sudanit", "d4b98464"], "d": ["Pas rrethimit dhjetëmujor, forcat e Mehdiut hynë në Hartum, në pikën ku bashkohen Nili Blu dhe Nili i Bardhë; guvernatori i qytetit, Gordoni, u vra, dhe kolona angleze e dërguar për ndihmë u vonua dy ditë. Pas kësaj date i gjithë Sudani, përfshirë Senarin, Dongolën dhe Kordofanin, mbeti katërmbëdhjetë vjet nën administrimin e shtetit të Mehdiut. Rajoni vetëm më 1899, me lidhjen osmane të këputur krejtësisht, do të hynte nën administrimin e përbashkët anglo-egjiptian.", "39a0a2c0"]},
"OLAYLAR_EK6:1885-02-05:0":{"b": ["Pushtimi italian i Massauas — humbja e bregut perëndimor të Detit të Kuq", "c333b95b"], "d": ["Porti i Massauas, qendra e ejaletit të Habeshit, u pushtua nga Italia, që përfitoi nga rrëmuja kur kryengritja e Mehdiut mbuloi Sudanin; kjo përbëri bërthamën e Eritresë italiane. Në të njëjtin proces dolën nga dora edhe Suakini në veri dhe arkipelagu Dahlak në det të hapur. Kështu sundimi osman në bregun perëndimor të Detit të Kuq, që vazhdonte nga koha e Javuz Sulltan Selimit, mori fund dhe deti u bë tashmë ujë me të dy brigjet të huaja.", "8cf1ab7a"]},
"OLAYLAR_EK6:1912-05-04:0":{"b": ["Pushtimi italian i Rodosit", "e08662c5"], "d": ["Italia, duke dashur ta ulte Shtetin Osman në tryezë gjatë Luftës së Tripolit, e shtriu luftën në Mesdhe dhe zbarkoi ushtarë në Rodos. Ishulli u mor në dorëzim brenda pak ditësh. Rodosi, që Sulejmani Ligjvënës e mori më 1522 pas një rrethimi të gjatë dhe u mbajt treqind e nëntëdhjetë vjet, kështu pushoi së qeni baza më e madhe ishullore e perandorisë në Mesdheun Lindor; ndonëse në Traktatin e Ouchyt u konsiderua pushtim i përkohshëm, nuk u rimor më kurrë.", "f3823a2e"]},
"OLAYLAR_EK6:1912-05-12:0":{"b": ["Pushtimi italian i Dymbëdhjetë Ishujve", "200aacf2"], "d": ["Brenda një jave pas marrjes së Rodosit, flota italiane pushtoi edhe ishujt përreth; ky arkipelag më vonë do të merrte emrin 'Dymbëdhjetë Ishujt' (Dodekanez). Shumica e ishujve ishin vetëm pak milje larg bregut anadollak dhe kontrollonin kalimin juglindor të Egjeut. Pushtimi në Traktatin e Ouchyt u konsiderua i përkohshëm në këmbim të lënies së Tripolit, por Italia nuk i boshatisi kurrë ishujt; më 1947 do t'i dorëzoheshin Greqisë.", "01ceef5f"]},
"OLAYLAR_EK6:1912-05-20:0":{"b": ["Pushtimi i Kosit", "ab246c62"], "d": ["Kosi, hallka e fundit e operacionit në Dymbëdhjetë Ishujt, ishte ishulli pjellor e i populluar përballë gadishullit të Bodrumit. Me pushtimin, të gjithë ishujt në qoshen juglindore të Egjeut hynë nën kontrollin italian dhe bregu jugperëndimor i Anadollit u rrethua anembanë nga një zinxhir ishujsh të huaj.", "5a6552a9"]},
"OLAYLAR_EK6:1912-07-17:0":{"b": ["Shpallja e pavarësisë së Nikarias", "c4452033"], "d": ["Në ishullin e vogël të Nikarias, mes Samosit dhe Kiosit, populli, në klimën e pasigurisë që krijuan pushtimet italiane, u ngrit në kryengritje, e nxori xhandarmërinë osmane nga ishulli dhe shpalli një 'shtet të lirë' me flamurin, pullën dhe parlamentin e vet, që zgjati pesë muaj. Në nëntor 1912 ishulli iu bashkua Greqisë. Megjithë vogëlsinë e saj, kjo ngjarje është tregues i qartë se si po shpërbëhej administrimi qendror në Egje.", "bf892a96"]},
"OLAYLAR_EK6:1912-11-11:0":{"b": ["Dalja e Samosit nga administrimi osman", "3a862f2b"], "d": ["Samosi që nga viti 1832 ishte një emirat autonom që u paguante taksë osmanëve dhe drejtohej nga një bej i emëruar nga Stambolli. Në boshllëkun që krijoi Lufta e Tripolit, lëvizja pro bashkimit në ishull mori administrimin dhe rendi i emiratit autonom mori fund faktikisht; ishulli po atë vit shpalli se i bashkohej Greqisë. Ky ishull, dy kilometra larg bregut anadollak, u bë një nga tokat e para të humbura në Egje.", "3b6eafda"]},
"OLAYLAR_EK6:1913-03-06:0":{"b": ["Rënia e Janinës — humbja e Epirit dhe Pargës", "d42fce18"], "d": ["Janina, e rrethuar për pesë muaj në Luftën Ballkanike, u dorëzua pas rënies së pozicioneve të Bizanit; bashkë me qytetin, i gjithë Epiri kaloi te Greqia. Edhe Parga, e lidhur me sanxhakun e Janinës, doli nga dora në këtë datë dhe administrimi osman nëntëdhjetë e katërvjeçar mori fund. Humbja e Janinës do të thoshte mbyllja e dritares së fundit të perandorisë drejt Adriatikut.", "faa4893b"]},
"OLAYLAR_EK6:1913-03-26:0":{"b": ["Rënia e Edrenesë në duart bullgare", "459d2e56"], "d": ["Pas rrethimit pesë muaj e gjysmë, Edreneja, së cilës i mbaruan municioni dhe rezervat, u dorëzua; Shykrü Pasha u zu rob. Rënia e qytetit, osman që nga viti 1361 dhe kryeqytet për nëntëdhjetë e dy vjet, u konsiderua goditja më e rëndë e Luftës Ballkanike. Edreneja do të rimerrej katër muaj më vonë, duke përfituar nga shembja e Bullgarisë në frontet e tjera gjatë Luftës së Dytë Ballkanike.", "4b63fb0d"]},
"OLAYLAR_EK6:1916-07-27:0":{"b": ["Humbja e Janbusë nga forcat e Sherif Huseinit", "e291c816"], "d": ["Kryengritja që Sherif Huseini nisi në qershor u përhap në bregdetin e Detit të Kuq; Janbuja, porti i Medinës, me mbështetjen e flotës angleze kaloi në duart e kryengritësve. Porti u bë dera kryesore e rrjedhës së armëve dhe parave që i vinin kryengritjes nga jashtë. Kështu u pre lidhja detare e forcave të Fahredin Pashës në Medinë dhe qyteti mbeti i vetëm në skajin e hekurudhës së Hixhazit.", "83cc4dbb"]},
"OLAYLAR_EK6:1917-11-07:0":{"b": ["Beteja e Tretë e Gazës — humbja e Gazës dhe Han Junusit", "c142a069"], "d": ["Pas dy përpjekjeve të pasuksesshme, Allenby në sulmin e tretë e çau frontin duke e anashkaluar nga Beersheba dhe vija e Gazës, e mbajtur për gjashtë muaj, u shemb. Gaza dhe Han Junusi në jug të saj u boshatisën po atë ditë. Ky depërtim ishte fillimi i shpërbërjes së frontit të Palestinës; Jerusalemi do të binte pesë javë më pas.", "a6efff96"]},
"OLAYLAR_EK6:1920-05-27:0":{"b": ["Pushtimi i Gjumulxhinës — humbja e Trakisë Perëndimore", "904d813c"], "d": ["Trakia Perëndimore, që pas Mudrosit fillimisht hyri nën kontrollin e njësive të Antantës, me vendimin e konferencës së San Remos iu la Greqisë dhe ushtria greke hyri në Gjumulxhinë. Rajoni, i rimarrë nga Bullgaria më 1913, u bë toka e fundit që perandoria humbi në Rumeli. Statusi i popullsisë turke në rajon tre vjet më vonë do të rregullohej në Lozanë me regjimin e pakicave. Me këtë pushtim, kazatë e Gjumulxhinës, Ksanthit (İskeçe), Dedeagaçit dhe Sofllisë të Trakisë Perëndimore kaluan te Greqia.", "ef0aeba3"]},
"OLAYLAR_EK7:1335-12-01:0":{"b": ["Shpërbërja e Shtetit Ilhanid: vdekja e Ebu Said Bahadur Hanit", "0f187469"], "d": ["Sipas zërit për ilhanidët në Enciklopedinë Islame të TDV-së, vdekja e Ebu Saidit pa lënë trashëgimtar shkaktoi copëtimin e Shtetit Ilhanid, që prej një shekulli sundonte Iranin; emirët, duke përfituar nga luftërat për fron, themeluan dinasti vendore si xhelajiridët, karakojunlutë, muzaferidët, serbedarët e Horasanit dhe eretnidët. Kjo shpërbërje e ndau rajonin në një mozaik bejliqesh që do të zgjaste një shekull; përfundimisht ai do të bashkohej sërish me fushatat e Timurit.", "ebf54b53"]},
"OLAYLAR_EK7:1387-01-01:0":{"b": ["Timuri vendos sundimin mbi pjesën më të madhe të Iranit", "1cee2b82"], "d": ["Sipas zërit për Timurin në Enciklopedinë Islame të TDV-së, që nga fillimi i viteve 1380 Timuri i likuidoi një nga një dinastitë vendore pas-ilhanide, si serbedarët, kertët dhe muzaferidët, dhe gjatë 'fushatës trevjeçare' të viteve 1386-1388 vendosi faktikisht sundimin mbi pjesën më të madhe të Iranit; dinastisë muzaferide goditja përfundimtare do t'i jepej më 1393. Kështu rajoni, pas një shekulli copëtimi, u lidh sërish me një autoritet të vetëm qendror.", "aaab87fe"]},
"OLAYLAR_EK7:1406-10-15:0":{"b": ["Fitorja në Aras: Kara Jusufi mundi timuridin Ebu Bekr Mirza", "4b61a75a"], "d": ["Pas vdekjes së Timurit më 1405, beu karakojunlu Kara Jusufi, i kthyer nga internimi, mori Avnikun, rifitoi tokat e veta në Anadollin Lindor, pastaj marshoi kundër nipit të Timurit, Ebu Bekr Mirzës, që konsiderohej zot i Azerbajxhanit dhe i dy Irakëve, dhe e mundi në brigjet e Arasit. Kjo fitore nuk ua dha Tabrizin karakojunluve: zëri `tebriz` i TDV-së shkruan se më 1408 qyteti ishte në duart e Ebu Bekr Mirzës; beteja që u solli Azerbajxhanin është ajo e Serdrudit, më 13 prill 1408.", "38fdfcfd"]},
"OLAYLAR_EK7:1408-04-13:0":{"b": ["Fitorja në Serdrud: Tabrizi dhe Azerbajxhani u kaluan karakojunluve", "1f0a429d"], "d": ["Kara Jusufi e mundi timuridin Ebu Bekr Mirza për herë të dytë pas Arasit, në Serdrud afër Tabrizit; kjo fitore u solli karakojunluve Azerbajxhanin. Pastaj Kara Jusufi e ngarkoi Bistam Beun me pushtimin e Irakut Axhem;", "10fb176b"]}
});
